insert into public.legal_provisions (
    version_id, provision_key, sequence, heading_path, heading, label, content
)
select
    '21000000-0000-4000-8000-000000000006', item.chave, item.sequencia, item.caminho, item.titulo, item.rotulo, item.conteudo
from jsonb_to_recordset($dados$[{"chave":"art-1","sequencia":1,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 1º","conteudo":"O processo penal reger-se-á, em todo o território brasileiro, por este Código, ressalvados:\n\nI - os tratados, as convenções e regras de direito internacional;\n\nII - as prerrogativas constitucionais do Presidente da República, dos ministros de Estado, nos crimes conexos com os do Presidente da República, e dos ministros do Supremo Tribunal Federal, nos crimes de responsabilidade ( Constituição, arts. 86 , 89 , § 2º , e 100 );\n\nIII - os processos da competência da Justiça Militar;\n\nIV - os processos da competência do tribunal especial ( Constituição, art. 122, n o 17 );\n\nV - os processos por crimes de imprensa. (Vide ADPF nº 130)\n\nParágrafo único. Aplicar-se-á, entretanto, este Código aos processos referidos nos n o s. IV e V, quando as leis especiais que os regulam não dispuserem de modo diverso."},{"chave":"art-2","sequencia":2,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 2º","conteudo":"A lei processual penal aplicar-se-á desde logo, sem prejuízo da validade dos atos realizados sob a vigência da lei anterior."},{"chave":"art-3","sequencia":3,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 3º","conteudo":"A lei processual penal admitirá interpretação extensiva e aplicação analógica, bem como o suplemento dos princípios gerais de direito."},{"chave":"art-3-a","sequencia":4,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"Juiz das Garantias","rotulo":"Art. 3º-A","conteudo":"O processo penal terá estrutura acusatória, vedadas a iniciativa do juiz na fase de investigação e a substituição da atuação probatória do órgão de acusação. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298) (Vide ADI 6.300) (Vide ADI 6.305)"},{"chave":"art-3-b","sequencia":5,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 3º-B","conteudo":"O juiz das garantias é responsável pelo controle da legalidade da investigação criminal e pela salvaguarda dos direitos individuais cuja franquia tenha sido reservada à autorização prévia do Poder Judiciário, competindo-lhe especialmente: (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298) (Vide ADI 6.299) (Vide ADI 6.300) (Vide ADI 6.305)\n\nI - receber a comunicação imediata da prisão, nos termos do inciso LXII do caput do art. 5º da Constituição Federal; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nII - receber o auto da prisão em flagrante para o controle da legalidade da prisão, observado o disposto no art. 310 deste Código; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nIII - zelar pela observância dos direitos do preso, podendo determinar que este seja conduzido à sua presença, a qualquer tempo; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nIV - ser informado sobre a instauração de qualquer investigação criminal; (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\nV - decidir sobre o requerimento de prisão provisória ou outra medida cautelar, observado o disposto no § 1º deste artigo; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nVI - prorrogar a prisão provisória ou outra medida cautelar, bem como substituí-las ou revogá-las, assegurado, no primeiro caso, o exercício do contraditório em audiência pública e oral, na forma do disposto neste Código ou em legislação especial pertinente; (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\nVII - decidir sobre o requerimento de produção antecipada de provas consideradas urgentes e não repetíveis, assegurados o contraditório e a ampla defesa em audiência pública e oral; (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\nVIII - prorrogar o prazo de duração do inquérito, estando o investigado preso, em vista das razões apresentadas pela autoridade policial e observado o disposto no § 2º deste artigo; (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\nIX - determinar o trancamento do inquérito policial quando não houver fundamento razoável para sua instauração ou prosseguimento; (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\nX - requisitar documentos, laudos e informações ao delegado de polícia sobre o andamento da investigação; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nXI - decidir sobre os requerimentos de: (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\na) interceptação telefônica, do fluxo de comunicações em sistemas de informática e telemática ou de outras formas de comunicação; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nb) afastamento dos sigilos fiscal, bancário, de dados e telefônico; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nc) busca e apreensão domiciliar; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nd) acesso a informações sigilosas; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\ne) outros meios de obtenção da prova que restrinjam direitos fundamentais do investigado; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nXII - julgar o habeas corpus impetrado antes do oferecimento da denúncia; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nXIII - determinar a instauração de incidente de insanidade mental; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nXIV - decidir sobre o recebimento da denúncia ou queixa, nos termos do art. 399 deste Código; (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\nXV - assegurar prontamente, quando se fizer necessário, o direito outorgado ao investigado e ao seu defensor de acesso a todos os elementos informativos e provas produzidos no âmbito da investigação criminal, salvo no que concerne, estritamente, às diligências em andamento; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nXVI - deferir pedido de admissão de assistente técnico para acompanhar a produção da perícia; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nXVII - decidir sobre a homologação de acordo de não persecução penal ou os de colaboração premiada, quando formalizados durante a investigação; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nXVIII - outras matérias inerentes às atribuições definidas no caput deste artigo. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 1º O preso em flagrante ou por força de mandado de prisão provisória será encaminhado à presença do juiz competente para celebração da audiência de custódia no prazo de 24 (vinte e quatro) horas, momento em que se realizará, por videoconferência, audiência com a presença do Ministério Público e da Defensoria Pública ou de advogado constituído, na forma estabelecida no art. 310 deste Código. (Redação dada pela Lei nº 15.358, de 2026)\n\n§ 2º Se o investigado estiver preso, o juiz das garantias poderá, mediante representação da autoridade policial e ouvido o Ministério Público, prorrogar, uma única vez, a duração do inquérito por até 15 (quinze) dias, após o que, se ainda assim a investigação não for concluída, a prisão será imediatamente relaxada. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)"},{"chave":"art-3-c","sequencia":6,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 3º-C","conteudo":"A competência do juiz das garantias abrange todas as infrações penais, exceto as de menor potencial ofensivo, e cessa com o recebimento da denúncia ou queixa na forma do art. 399 deste Código. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298) (Vide ADI 6.299) (Vide ADI 6.300 ) (Vide ADI 6.305)\n\n§ 1º Recebida a denúncia ou queixa, as questões pendentes serão decididas pelo juiz da instrução e julgamento. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\n§ 2º As decisões proferidas pelo juiz das garantias não vinculam o juiz da instrução e julgamento, que, após o recebimento da denúncia ou queixa, deverá reexaminar a necessidade das medidas cautelares em curso, no prazo máximo de 10 (dez) dias. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\n§ 3º Os autos que compõem as matérias de competência do juiz das garantias ficarão acautelados na secretaria desse juízo, à disposição do Ministério Público e da defesa, e não serão apensados aos autos do processo enviados ao juiz da instrução e julgamento, ressalvados os documentos relativos às provas irrepetíveis, medidas de obtenção de provas ou de antecipação de provas, que deverão ser remetidos para apensamento em apartado. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\n§ 4º Fica assegurado às partes o amplo acesso aos autos acautelados na secretaria do juízo das garantias. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)"},{"chave":"art-3-d","sequencia":7,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 3º-D","conteudo":"O juiz que, na fase de investigação, praticar qualquer ato incluído nas competências dos arts. 4º e 5º deste Código ficará impedido de funcionar no processo. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298) (Vide ADI 6.299) (Vide ADI 6.300 ) (Vide ADI 6.305)\n\nParágrafo único. Nas comarcas em que funcionar apenas um juiz, os tribunais criarão um sistema de rodízio de magistrados, a fim de atender às disposições deste Capítulo. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298) (Vide ADI 6.299)"},{"chave":"art-3-e","sequencia":8,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 3º-E","conteudo":"O juiz das garantias será designado conforme as normas de organização judiciária da União, dos Estados e do Distrito Federal, observando critérios objetivos a serem periodicamente divulgados pelo respectivo tribunal. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298) (Vide ADI 6.299) (Vide ADI 6.300 ) (Vide ADI 6.305)"},{"chave":"art-3-f","sequencia":9,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 3º-F","conteudo":"O juiz das garantias deverá assegurar o cumprimento das regras para o tratamento dos presos, impedindo o acordo ou ajuste de qualquer autoridade com órgãos da imprensa para explorar a imagem da pessoa submetida à prisão, sob pena de responsabilidade civil, administrativa e penal. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298) (Vide ADI 6.299) (Vide ADI 6.300 ) (Vide ADI 6.305)\n\nParágrafo único. Por meio de regulamento, as autoridades deverão disciplinar, em 180 (cento e oitenta) dias, o modo pelo qual as informações sobre a realização da prisão e a identidade do preso serão, de modo padronizado e respeitada a programação normativa aludida no caput deste artigo, transmitidas à imprensa, assegurados a efetividade da persecução penal, o direito à informação e a dignidade da pessoa submetida à prisão. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)"},{"chave":"art-4","sequencia":10,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 4º","conteudo":"A polícia judiciária será exercida pelas autoridades policiais no território de suas respectivas circunscrições e terá por fim a apuração das infrações penais e da sua autoria. (Redação dada pela Lei nº 9.043, de 9.5.1995)\n\nParágrafo único. A competência definida neste artigo não excluirá a de autoridades administrativas, a quem por lei seja cometida a mesma função."},{"chave":"art-5","sequencia":11,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 5º","conteudo":"Nos crimes de ação pública o inquérito policial será iniciado:\n\nI - de ofício;\n\nII - mediante requisição da autoridade judiciária ou do Ministério Público, ou a requerimento do ofendido ou de quem tiver qualidade para representá-lo.\n\n§ 1 o O requerimento a que se refere o n o II conterá sempre que possível:\n\na) a narração do fato, com todas as circunstâncias;\n\nb) a individualização do indiciado ou seus sinais característicos e as razões de convicção ou de presunção de ser ele o autor da infração, ou os motivos de impossibilidade de o fazer;\n\nc) a nomeação das testemunhas, com indicação de sua profissão e residência.\n\n§ 2 o Do despacho que indeferir o requerimento de abertura de inquérito caberá recurso para o chefe de Polícia.\n\n§ 3 o Qualquer pessoa do povo que tiver conhecimento da existência de infração penal em que caiba ação pública poderá, verbalmente ou por escrito, comunicá-la à autoridade policial, e esta, verificada a procedência das informações, mandará instaurar inquérito.\n\n§ 4 o O inquérito, nos crimes em que a ação pública depender de representação, não poderá sem ela ser iniciado.\n\n§ 5 o Nos crimes de ação privada, a autoridade policial somente poderá proceder a inquérito a requerimento de quem tenha qualidade para intentá-la."},{"chave":"art-6","sequencia":12,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 6º","conteudo":"Logo que tiver conhecimento da prática da infração penal, a autoridade policial deverá:\n\nI - dirigir-se ao local, providenciando para que não se alterem o estado e conservação das coisas, até a chegada dos peritos criminais; (Redação dada pela Lei nº 8.862, de 28.3.1994)\n\nII - apreender os objetos que tiverem relação com o fato, após liberados pelos peritos criminais; (Redação dada pela Lei nº 8.862, de 28.3.1994)\n\nIII - colher todas as provas que servirem para o esclarecimento do fato e suas circunstâncias;\n\nIV - ouvir o ofendido;\n\nV - ouvir o indiciado, com observância, no que for aplicável, do disposto no Capítulo III do Título Vll, deste Livro , devendo o respectivo termo ser assinado por duas testemunhas que Ihe tenham ouvido a leitura;\n\nVI - proceder a reconhecimento de pessoas e coisas e a acareações;\n\nVII - determinar, se for caso, que se proceda a exame de corpo de delito e a quaisquer outras perícias;\n\nVIII - ordenar a identificação do indiciado pelo processo datiloscópico, se possível, e fazer juntar aos autos sua folha de antecedentes;\n\nIX - averiguar a vida pregressa do indiciado, sob o ponto de vista individual, familiar e social, sua condição econômica, sua atitude e estado de ânimo antes e depois do crime e durante ele, e quaisquer outros elementos que contribuírem para a apreciação do seu temperamento e caráter.\n\nX - colher informações sobre a existência de filhos, respectivas idades e se possuem alguma deficiência e o nome e o contato de eventual responsável pelos cuidados dos filhos, indicado pela pessoa presa. (Incluído pela Lei nº 13.257, de 2016)"},{"chave":"art-7","sequencia":13,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 7º","conteudo":"Para verificar a possibilidade de haver a infração sido praticada de determinado modo, a autoridade policial poderá proceder à reprodução simulada dos fatos, desde que esta não contrarie a moralidade ou a ordem pública."},{"chave":"art-8","sequencia":14,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 8º","conteudo":"Havendo prisão em flagrante, será observado o disposto no Capítulo II do Título IX deste Livro ."},{"chave":"art-9","sequencia":15,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 9º","conteudo":"Todas as peças do inquérito policial serão, num só processado, reduzidas a escrito ou datilografadas e, neste caso, rubricadas pela autoridade."},{"chave":"art-10","sequencia":16,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 10.","conteudo":"O inquérito deverá terminar no prazo de 10 dias, se o indiciado tiver sido preso em flagrante, ou estiver preso preventivamente, contado o prazo, nesta hipótese, a partir do dia em que se executar a ordem de prisão, ou no prazo de 30 dias, quando estiver solto, mediante fiança ou sem ela.\n\n§ 1 o A autoridade fará minucioso relatório do que tiver sido apurado e enviará os autos ao juiz competente.\n\n§ 2 o No relatório poderá a autoridade indicar testemunhas que não tiverem sido inquiridas, mencionando o lugar onde possam ser encontradas.\n\n§ 3 o Quando o fato for de difícil elucidação, e o indiciado estiver solto, a autoridade poderá requerer ao juiz a devolução dos autos, para ulteriores diligências, que serão realizadas no prazo marcado pelo juiz."},{"chave":"art-11","sequencia":17,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 11.","conteudo":"Os instrumentos do crime, bem como os objetos que interessarem à prova, acompanharão os autos do inquérito."},{"chave":"art-12","sequencia":18,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 12.","conteudo":"O inquérito policial acompanhará a denúncia ou queixa, sempre que servir de base a uma ou outra."},{"chave":"art-13","sequencia":19,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 13.","conteudo":"Incumbirá ainda à autoridade policial:\n\nI - fornecer às autoridades judiciárias as informações necessárias à instrução e julgamento dos processos;\n\nII - realizar as diligências requisitadas pelo juiz ou pelo Ministério Público;\n\nIII - cumprir os mandados de prisão expedidos pelas autoridades judiciárias;\n\nIV - representar acerca da prisão preventiva."},{"chave":"art-13-a","sequencia":20,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 13º-A","conteudo":"Nos crimes previstos nos arts. 148 , 149 e 149-A , no § 3º do art. 158 e no art. 159 do Decreto-Lei no 2.848, de 7 de dezembro de 1940 (Código Penal) , e no art. 239 da Lei n o 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente) , o membro do Ministério Público ou o delegado de polícia poderá requisitar, de quaisquer órgãos do poder público ou de empresas da iniciativa privada, dados e informações cadastrais da vítima ou de suspeitos. (Incluído pela Lei nº 13.344, de 2016) (Vigência)\n\nParágrafo único. A requisição, que será atendida no prazo de 24 (vinte e quatro) horas, conterá: (Incluído pela Lei nº 13.344, de 2016) (Vigência)\n\nI - o nome da autoridade requisitante; (Incluído pela Lei nº 13.344, de 2016) (Vigência)\n\nII - o número do inquérito policial; e (Incluído pela Lei nº 13.344, de 2016) (Vigência)\n\nIII - a identificação da unidade de polícia judiciária responsável pela investigação. (Incluído pela Lei nº 13.344, de 2016) (Vigência)"},{"chave":"art-13-b","sequencia":21,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 13º-B","conteudo":"Se necessário à prevenção e à repressão dos crimes relacionados ao tráfico de pessoas, o membro do Ministério Público ou o delegado de polícia poderão requisitar, mediante autorização judicial, às empresas prestadoras de serviço de telecomunicações e/ou telemática que disponibilizem imediatamente os meios técnicos adequados – como sinais, informações e outros – que permitam a localização da vítima ou dos suspeitos do delito em curso. (Incluído pela Lei nº 13.344, de 2016) (Vigência)\n\n§ 1 o Para os efeitos deste artigo, sinal significa posicionamento da estação de cobertura, setorização e intensidade de radiofrequência. (Incluído pela Lei nº 13.344, de 2016) (Vigência)\n\n§ 2 o Na hipótese de que trata o caput , o sinal: (Incluído pela Lei nº 13.344, de 2016) (Vigência)\n\nI - não permitirá acesso ao conteúdo da comunicação de qualquer natureza, que dependerá de autorização judicial, conforme disposto em lei; (Incluído pela Lei nº 13.344, de 2016) (Vigência)\n\nII - deverá ser fornecido pela prestadora de telefonia móvel celular por período não superior a 30 (trinta) dias, renovável por uma única vez, por igual período; (Incluído pela Lei nº 13.344, de 2016) (Vigência)\n\nIII - para períodos superiores àquele de que trata o inciso II, será necessária a apresentação de ordem judicial. (Incluído pela Lei nº 13.344, de 2016) (Vigência)\n\n§ 3 o Na hipótese prevista neste artigo, o inquérito policial deverá ser instaurado no prazo máximo de 72 (setenta e duas) horas, contado do registro da respectiva ocorrência policial. (Incluído pela Lei nº 13.344, de 2016) (Vigência)\n\n§ 4 o Não havendo manifestação judicial no prazo de 12 (doze) horas, a autoridade competente requisitará às empresas prestadoras de serviço de telecomunicações e/ou telemática que disponibilizem imediatamente os meios técnicos adequados – como sinais, informações e outros – que permitam a localização da vítima ou dos suspeitos do delito em curso, com imediata comunicação ao juiz. (Incluído pela Lei nº 13.344, de 2016) (Vigência)"},{"chave":"art-14","sequencia":22,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 14.","conteudo":"O ofendido, ou seu representante legal, e o indiciado poderão requerer qualquer diligência, que será realizada, ou não, a juízo da autoridade."},{"chave":"art-14-a","sequencia":23,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 14º-A","conteudo":"Nos casos em que servidores vinculados às instituições dispostas no art. 144 da Constituição Federal figurarem como investigados em inquéritos policiais, inquéritos policiais militares e demais procedimentos extrajudiciais, cujo objeto for a investigação de fatos relacionados ao uso da força letal praticados no exercício profissional, de forma consumada ou tentada, incluindo as situações dispostas no art. 23 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal) , o indiciado poderá constituir defensor. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 1º Para os casos previstos no caput deste artigo, o investigado deverá ser citado da instauração do procedimento investigatório, podendo constituir defensor no prazo de até 48 (quarenta e oito) horas a contar do recebimento da citação. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 2º Esgotado o prazo disposto no § 1º deste artigo com ausência de nomeação de defensor pelo investigado, a autoridade responsável pela investigação deverá intimar a instituição a que estava vinculado o investigado à época da ocorrência dos fatos, para que essa, no prazo de 48 (quarenta e oito) horas, indique defensor para a representação do investigado. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 3º Havendo necessidade de indicação de defensor nos termos do § 2º deste artigo, a defesa caberá preferencialmente à Defensoria Pública, e, nos locais em que ela não estiver instalada, a União ou a Unidade da Federação correspondente à respectiva competência territorial do procedimento instaurado deverá disponibilizar profissional para acompanhamento e realização de todos os atos relacionados à defesa administrativa do investigado. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 4º A indicação do profissional a que se refere o § 3º deste artigo deverá ser precedida de manifestação de que não existe defensor público lotado na área territorial onde tramita o inquérito e com atribuição para nele atuar, hipótese em que poderá ser indicado profissional que não integre os quadros próprios da Administração. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 5º Na hipótese de não atuação da Defensoria Pública, os custos com o patrocínio dos interesses dos investigados nos procedimentos de que trata este artigo correrão por conta do orçamento próprio da instituição a que este esteja vinculado à época da ocorrência dos fatos investigados. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 6º As disposições constantes deste artigo se aplicam aos servidores militares vinculados às instituições dispostas no art. 142 da Constituição Federal, desde que os fatos investigados digam respeito a missões para a Garantia da Lei e da Ordem. (Incluído pela Lei nº 13.964, de 2019) (Vigência)"},{"chave":"art-15","sequencia":24,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 15.","conteudo":"Se o indiciado for menor, ser-lhe-á nomeado curador pela autoridade policial."},{"chave":"art-16","sequencia":25,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 16.","conteudo":"O Ministério Público não poderá requerer a devolução do inquérito à autoridade policial, senão para novas diligências, imprescindíveis ao oferecimento da denúncia."},{"chave":"art-17","sequencia":26,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 17.","conteudo":"A autoridade policial não poderá mandar arquivar autos de inquérito."},{"chave":"art-18","sequencia":27,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 18.","conteudo":"Depois de ordenado o arquivamento do inquérito pela autoridade judiciária, por falta de base para a denúncia, a autoridade policial poderá proceder a novas pesquisas, se de outras provas tiver notícia."},{"chave":"art-19","sequencia":28,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 19.","conteudo":"Nos crimes em que não couber ação pública, os autos do inquérito serão remetidos ao juízo competente, onde aguardarão a iniciativa do ofendido ou de seu representante legal, ou serão entregues ao requerente, se o pedir, mediante traslado."},{"chave":"art-20","sequencia":29,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 20.","conteudo":"A autoridade assegurará no inquérito o sigilo necessário à elucidação do fato ou exigido pelo interesse da sociedade.\n\nParágrafo único. Nos atestados de antecedentes que lhe forem solicitados, a autoridade policial não poderá mencionar quaisquer anotações referentes a instauração de inquérito contra os requerentes. (Redação dada pela Lei nº 12.681, de 2012)"},{"chave":"art-21","sequencia":30,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 21.","conteudo":"A incomunicabilidade do indiciado dependerá sempre de despacho nos autos e somente será permitida quando o interesse da sociedade ou a conveniência da investigação o exigir.\n\nParágrafo único. A incomunicabilidade, que não excederá de três dias, será decretada por despacho fundamentado do Juiz, a requerimento da autoridade policial, ou do órgão do Ministério Público, respeitado, em qualquer hipótese, o disposto no artigo 89, inciso III, do Estatuto da Ordem dos Advogados do Brasil (Lei n. 4.215, de 27 de abril de 1963) (Redação dada pela Lei nº 5.010, de 30.5.1966)"},{"chave":"art-22","sequencia":31,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 22.","conteudo":"No Distrito Federal e nas comarcas em que houver mais de uma circunscrição policial, a autoridade com exercício em uma delas poderá, nos inquéritos a que esteja procedendo, ordenar diligências em circunscrição de outra, independentemente de precatórias ou requisições, e bem assim providenciará, até que compareça a autoridade competente, sobre qualquer fato que ocorra em sua presença, noutra circunscrição."},{"chave":"art-23","sequencia":32,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO II — DO INQUÉRITO POLICIAL"],"titulo":"TÍTULO II — DO INQUÉRITO POLICIAL","rotulo":"Art. 23.","conteudo":"Ao fazer a remessa dos autos do inquérito ao juiz competente, a autoridade policial oficiará ao Instituto de Identificação e Estatística, ou repartição congênere, mencionando o juízo a que tiverem sido distribuídos, e os dados relativos à infração penal e à pessoa do indiciado."},{"chave":"art-24","sequencia":33,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 24.","conteudo":"Nos crimes de ação pública, esta será promovida por denúncia do Ministério Público, mas dependerá, quando a lei o exigir, de requisição do Ministro da Justiça, ou de representação do ofendido ou de quem tiver qualidade para representá-lo.\n\n§ 1 o No caso de morte do ofendido ou quando declarado ausente por decisão judicial, o direito de representação passará ao cônjuge, ascendente, descendente ou irmão. (Parágrafo único renumerado pela Lei nº 8.699, de 27.8.1993)\n\n§ 2 o Seja qual for o crime, quando praticado em detrimento do patrimônio ou interesse da União, Estado e Município, a ação penal será pública. (Incluído pela Lei nº 8.699, de 27.8.1993)"},{"chave":"art-25","sequencia":34,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 25.","conteudo":"A representação será irretratável, depois de oferecida a denúncia."},{"chave":"art-26","sequencia":35,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 26.","conteudo":"A ação penal, nas contravenções, será iniciada com o auto de prisão em flagrante ou por meio de portaria expedida pela autoridade judiciária ou policial."},{"chave":"art-27","sequencia":36,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 27.","conteudo":"Qualquer pessoa do povo poderá provocar a iniciativa do Ministério Público, nos casos em que caiba a ação pública, fornecendo-lhe, por escrito, informações sobre o fato e a autoria e indicando o tempo, o lugar e os elementos de convicção."},{"chave":"art-28","sequencia":37,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 28.","conteudo":"Ordenado o arquivamento do inquérito policial ou de quaisquer elementos informativos da mesma natureza, o órgão do Ministério Público comunicará à vítima, ao investigado e à autoridade policial e encaminhará os autos para a instância de revisão ministerial para fins de homologação, na forma da lei. (Redação dada pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298) (Vide ADI 6.300 ) (Vide ADI 6.305)\n\n§ 1º Se a vítima, ou seu representante legal, não concordar com o arquivamento do inquérito policial, poderá, no prazo de 30 (trinta) dias do recebimento da comunicação, submeter a matéria à revisão da instância competente do órgão ministerial, conforme dispuser a respectiva lei orgânica. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\n§ 2º Nas ações penais relativas a crimes praticados em detrimento da União, Estados e Municípios, a revisão do arquivamento do inquérito policial poderá ser provocada pela chefia do órgão a quem couber a sua representação judicial. (Incluído pela Lei nº 13.964, de 2019) (Vigência)"},{"chave":"art-28-a","sequencia":38,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 28º-A","conteudo":"Não sendo caso de arquivamento e tendo o investigado confessado formal e circunstancialmente a prática de infração penal sem violência ou grave ameaça e com pena mínima inferior a 4 (quatro) anos, o Ministério Público poderá propor acordo de não persecução penal, desde que necessário e suficiente para reprovação e prevenção do crime, mediante as seguintes condições ajustadas cumulativa e alternativamente: (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\nI - reparar o dano ou restituir a coisa à vítima, exceto na impossibilidade de fazê-lo; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nII - renunciar voluntariamente a bens e direitos indicados pelo Ministério Público como instrumentos, produto ou proveito do crime; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nIII - prestar serviço à comunidade ou a entidades públicas por período correspondente à pena mínima cominada ao delito diminuída de um a dois terços, em local a ser indicado pelo juízo da execução, na forma do art. 46 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal) ; (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\nIV - pagar prestação pecuniária, a ser estipulada nos termos do art. 45 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), a entidade pública ou de interesse social, a ser indicada pelo juízo da execução, que tenha, preferencialmente, como função proteger bens jurídicos iguais ou semelhantes aos aparentemente lesados pelo delito; ou (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\nV - cumprir, por prazo determinado, outra condição indicada pelo Ministério Público, desde que proporcional e compatível com a infração penal imputada. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 1º Para aferição da pena mínima cominada ao delito a que se refere o caput deste artigo, serão consideradas as causas de aumento e diminuição aplicáveis ao caso concreto. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 2º O disposto no caput deste artigo não se aplica nas seguintes hipóteses: (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nI - se for cabível transação penal de competência dos Juizados Especiais Criminais, nos termos da lei; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nII - se o investigado for reincidente ou se houver elementos probatórios que indiquem conduta criminal habitual, reiterada ou profissional, exceto se insignificantes as infrações penais pretéritas; (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nIII - ter sido o agente beneficiado nos 5 (cinco) anos anteriores ao cometimento da infração, em acordo de não persecução penal, transação penal ou suspensão condicional do processo; e (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\nIV - nos crimes praticados no âmbito de violência doméstica ou familiar, ou praticados contra a mulher por razões da condição de sexo feminino, em favor do agressor. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 3º O acordo de não persecução penal será formalizado por escrito e será firmado pelo membro do Ministério Público, pelo investigado e por seu defensor. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 4º Para a homologação do acordo de não persecução penal, será realizada audiência na qual o juiz deverá verificar a sua voluntariedade, por meio da oitiva do investigado na presença do seu defensor, e sua legalidade. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 5º Se o juiz considerar inadequadas, insuficientes ou abusivas as condições dispostas no acordo de não persecução penal, devolverá os autos ao Ministério Público para que seja reformulada a proposta de acordo, com concordância do investigado e seu defensor. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\n§ 6º Homologado judicialmente o acordo de não persecução penal, o juiz devolverá os autos ao Ministério Público para que inicie sua execução perante o juízo de execução penal. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 7º O juiz poderá recusar homologação à proposta que não atender aos requisitos legais ou quando não for realizada a adequação a que se refere o § 5º deste artigo. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\n§ 8º Recusada a homologação, o juiz devolverá os autos ao Ministério Público para a análise da necessidade de complementação das investigações ou o oferecimento da denúncia. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298)\n\n§ 9º A vítima será intimada da homologação do acordo de não persecução penal e de seu descumprimento. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 10. Descumpridas quaisquer das condições estipuladas no acordo de não persecução penal, o Ministério Público deverá comunicar ao juízo, para fins de sua rescisão e posterior oferecimento de denúncia. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 11. O descumprimento do acordo de não persecução penal pelo investigado também poderá ser utilizado pelo Ministério Público como justificativa para o eventual não oferecimento de suspensão condicional do processo. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 12. A celebração e o cumprimento do acordo de não persecução penal não constarão de certidão de antecedentes criminais, exceto para os fins previstos no inciso III do § 2º deste artigo. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 13. Cumprido integralmente o acordo de não persecução penal, o juízo competente decretará a extinção de punibilidade. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 14. No caso de recusa, por parte do Ministério Público, em propor o acordo de não persecução penal, o investigado poderá requerer a remessa dos autos a órgão superior, na forma do art. 28 deste Código. (Incluído pela Lei nº 13.964, de 2019) (Vigência)"},{"chave":"art-29","sequencia":39,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 29.","conteudo":"Será admitida ação privada nos crimes de ação pública, se esta não for intentada no prazo legal, cabendo ao Ministério Público aditar a queixa, repudiá-la e oferecer denúncia substitutiva, intervir em todos os termos do processo, fornecer elementos de prova, interpor recurso e, a todo tempo, no caso de negligência do querelante, retomar a ação como parte principal."},{"chave":"art-30","sequencia":40,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 30.","conteudo":"Ao ofendido ou a quem tenha qualidade para representá-lo caberá intentar a ação privada."},{"chave":"art-31","sequencia":41,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 31.","conteudo":"No caso de morte do ofendido ou quando declarado ausente por decisão judicial, o direito de oferecer queixa ou prosseguir na ação passará ao cônjuge, ascendente, descendente ou irmão."},{"chave":"art-32","sequencia":42,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 32.","conteudo":"Nos crimes de ação privada, o juiz, a requerimento da parte que comprovar a sua pobreza, nomeará advogado para promover a ação penal.\n\n§ 1 o Considerar-se-á pobre a pessoa que não puder prover às despesas do processo, sem privar-se dos recursos indispensáveis ao próprio sustento ou da família.\n\n§ 2 o Será prova suficiente de pobreza o atestado da autoridade policial em cuja circunscrição residir o ofendido."},{"chave":"art-33","sequencia":43,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 33.","conteudo":"Se o ofendido for menor de 18 anos, ou mentalmente enfermo, ou retardado mental, e não tiver representante legal, ou colidirem os interesses deste com os daquele, o direito de queixa poderá ser exercido por curador especial, nomeado, de ofício ou a requerimento do Ministério Público, pelo juiz competente para o processo penal."},{"chave":"art-34","sequencia":44,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 34.","conteudo":"Se o ofendido for menor de 21 e maior de 18 anos, o direito de queixa poderá ser exercido por ele ou por seu representante legal."},{"chave":"art-35","sequencia":45,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 35.","conteudo":"(Revogado pela Lei nº 9.520, de 27.11.1997)"},{"chave":"art-36","sequencia":46,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 36.","conteudo":"Se comparecer mais de uma pessoa com direito de queixa, terá preferência o cônjuge, e, em seguida, o parente mais próximo na ordem de enumeração constante do art. 31 , podendo, entretanto, qualquer delas prosseguir na ação, caso o querelante desista da instância ou a abandone."},{"chave":"art-37","sequencia":47,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 37.","conteudo":"As fundações, associações ou sociedades legalmente constituídas poderão exercer a ação penal, devendo ser representadas por quem os respectivos contratos ou estatutos designarem ou, no silêncio destes, pelos seus diretores ou sócios-gerentes."},{"chave":"art-38","sequencia":48,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 38.","conteudo":"Salvo disposição em contrário, o ofendido, ou seu representante legal, decairá no direito de queixa ou de representação, se não o exercer dentro do prazo de seis meses, contado do dia em que vier a saber quem é o autor do crime, ou, no caso do art. 29 , do dia em que se esgotar o prazo para o oferecimento da denúncia.\n\n§ 1º Verificar-se-á a decadência do direito de queixa ou representação, dentro do mesmo prazo, nos casos dos arts. 24 , parágrafo único, e 31 . (Redação dada pela Lei nº 15.438, de 2026)\n\n§ 2º Nos crimes praticados no âmbito de violência doméstica e familiar contra a mulher, a ofendida decairá do direito de queixa ou de representação se não o exercer no prazo de 12 (doze) meses, contado do dia em que vier a saber quem é o autor do crime, ou, no caso do art. 29 deste Código, do dia em que se esgotar o prazo para o oferecimento de denúncia. (Incluído pela Lei nº 15.438, de 2026)"},{"chave":"art-39","sequencia":49,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 39.","conteudo":"O direito de representação poderá ser exercido, pessoalmente ou por procurador com poderes especiais, mediante declaração, escrita ou oral, feita ao juiz, ao órgão do Ministério Público, ou à autoridade policial.\n\n§ 1 o A representação feita oralmente ou por escrito, sem assinatura devidamente autenticada do ofendido, de seu representante legal ou procurador, será reduzida a termo, perante o juiz ou autoridade policial, presente o órgão do Ministério Público, quando a este houver sido dirigida.\n\n§ 2 o A representação conterá todas as informações que possam servir à apuração do fato e da autoria.\n\n§ 3 o Oferecida ou reduzida a termo a representação, a autoridade policial procederá a inquérito, ou, não sendo competente, remetê-lo-á à autoridade que o for.\n\n§ 4 o A representação, quando feita ao juiz ou perante este reduzida a termo, será remetida à autoridade policial para que esta proceda a inquérito.\n\n§ 5 o O órgão do Ministério Público dispensará o inquérito, se com a representação forem oferecidos elementos que o habilitem a promover a ação penal, e, neste caso, oferecerá a denúncia no prazo de quinze dias."},{"chave":"art-40","sequencia":50,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 40.","conteudo":"Quando, em autos ou papéis de que conhecerem, os juízes ou tribunais verificarem a existência de crime de ação pública, remeterão ao Ministério Público as cópias e os documentos necessários ao oferecimento da denúncia."},{"chave":"art-41","sequencia":51,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 41.","conteudo":"A denúncia ou queixa conterá a exposição do fato criminoso, com todas as suas circunstâncias, a qualificação do acusado ou esclarecimentos pelos quais se possa identificá-lo, a classificação do crime e, quando necessário, o rol das testemunhas."},{"chave":"art-42","sequencia":52,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 42.","conteudo":"O Ministério Público não poderá desistir da ação penal."},{"chave":"art-43","sequencia":53,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 43.","conteudo":"(Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-44","sequencia":54,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 44.","conteudo":"A queixa poderá ser dada por procurador com poderes especiais, devendo constar do instrumento do mandato o nome do querelante e a menção do fato criminoso, salvo quando tais esclarecimentos dependerem de diligências que devem ser previamente requeridas no juízo criminal."},{"chave":"art-45","sequencia":55,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 45.","conteudo":"A queixa, ainda quando a ação penal for privativa do ofendido, poderá ser aditada pelo Ministério Público, a quem caberá intervir em todos os termos subseqüentes do processo."},{"chave":"art-46","sequencia":56,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 46.","conteudo":"O prazo para oferecimento da denúncia, estando o réu preso, será de 5 dias, contado da data em que o órgão do Ministério Público receber os autos do inquérito policial, e de 15 dias, se o réu estiver solto ou afiançado. No último caso, se houver devolução do inquérito à autoridade policial ( art. 16 ), contar-se-á o prazo da data em que o órgão do Ministério Público receber novamente os autos.\n\n§ 1 o Quando o Ministério Público dispensar o inquérito policial, o prazo para o oferecimento da denúncia contar-se-á da data em que tiver recebido as peças de informações ou a representação\n\n§ 2 o O prazo para o aditamento da queixa será de 3 dias, contado da data em que o órgão do Ministério Público receber os autos, e, se este não se pronunciar dentro do tríduo, entender-se-á que não tem o que aditar, prosseguindo-se nos demais termos do processo."},{"chave":"art-47","sequencia":57,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 47.","conteudo":"Se o Ministério Público julgar necessários maiores esclarecimentos e documentos complementares ou novos elementos de convicção, deverá requisitá-los, diretamente, de quaisquer autoridades ou funcionários que devam ou possam fornecê-los."},{"chave":"art-48","sequencia":58,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 48.","conteudo":"A queixa contra qualquer dos autores do crime obrigará ao processo de todos, e o Ministério Público velará pela sua indivisibilidade."},{"chave":"art-49","sequencia":59,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 49.","conteudo":"A renúncia ao exercício do direito de queixa, em relação a um dos autores do crime, a todos se estenderá."},{"chave":"art-50","sequencia":60,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 50.","conteudo":"A renúncia expressa constará de declaração assinada pelo ofendido, por seu representante legal ou procurador com poderes especiais.\n\nParágrafo único. A renúncia do representante legal do menor que houver completado 18 (dezoito) anos não privará este do direito de queixa, nem a renúncia do último excluirá o direito do primeiro."},{"chave":"art-51","sequencia":61,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 51.","conteudo":"O perdão concedido a um dos querelados aproveitará a todos, sem que produza, todavia, efeito em relação ao que o recusar."},{"chave":"art-52","sequencia":62,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 52.","conteudo":"Se o querelante for menor de 21 e maior de 18 anos, o direito de perdão poderá ser exercido por ele ou por seu representante legal, mas o perdão concedido por um, havendo oposição do outro, não produzirá efeito."},{"chave":"art-53","sequencia":63,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 53.","conteudo":"Se o querelado for mentalmente enfermo ou retardado mental e não tiver representante legal, ou colidirem os interesses deste com os do querelado, a aceitação do perdão caberá ao curador que o juiz Ihe nomear."},{"chave":"art-54","sequencia":64,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 54.","conteudo":"Se o querelado for menor de 21 anos, observar-se-á, quanto à aceitação do perdão, o disposto no art. 52 ."},{"chave":"art-55","sequencia":65,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 55.","conteudo":"O perdão poderá ser aceito por procurador com poderes especiais."},{"chave":"art-56","sequencia":66,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 56.","conteudo":"Aplicar-se-á ao perdão extraprocessual expresso o disposto no art. 50 ."},{"chave":"art-57","sequencia":67,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 57.","conteudo":"A renúncia tácita e o perdão tácito admitirão todos os meios de prova."},{"chave":"art-58","sequencia":68,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 58.","conteudo":"Concedido o perdão, mediante declaração expressa nos autos, o querelado será intimado a dizer, dentro de três dias, se o aceita, devendo, ao mesmo tempo, ser cientificado de que o seu silêncio importará aceitação.\n\nParágrafo único. Aceito o perdão, o juiz julgará extinta a punibilidade."},{"chave":"art-59","sequencia":69,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 59.","conteudo":"A aceitação do perdão fora do processo constará de declaração assinada pelo querelado, por seu representante legal ou procurador com poderes especiais."},{"chave":"art-60","sequencia":70,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 60.","conteudo":"Nos casos em que somente se procede mediante queixa, considerar-se-á perempta a ação penal:\n\nI - quando, iniciada esta, o querelante deixar de promover o andamento do processo durante 30 dias seguidos;\n\nII - quando, falecendo o querelante, ou sobrevindo sua incapacidade, não comparecer em juízo, para prosseguir no processo, dentro do prazo de 60 (sessenta) dias, qualquer das pessoas a quem couber fazê-lo, ressalvado o disposto no art. 36 ;\n\nIII - quando o querelante deixar de comparecer, sem motivo justificado, a qualquer ato do processo a que deva estar presente, ou deixar de formular o pedido de condenação nas alegações finais;\n\nIV - quando, sendo o querelante pessoa jurídica, esta se extinguir sem deixar sucessor."},{"chave":"art-61","sequencia":71,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 61.","conteudo":"Em qualquer fase do processo, o juiz, se reconhecer extinta a punibilidade, deverá declará-lo de ofício.\n\nParágrafo único. No caso de requerimento do Ministério Público, do querelante ou do réu, o juiz mandará autuá-lo em apartado, ouvirá a parte contrária e, se o julgar conveniente, concederá o prazo de cinco dias para a prova, proferindo a decisão dentro de cinco dias ou reservando-se para apreciar a matéria na sentença final."},{"chave":"art-62","sequencia":72,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO III — DA AÇÃO PENAL"],"titulo":"TÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 62.","conteudo":"No caso de morte do acusado, o juiz somente à vista da certidão de óbito, e depois de ouvido o Ministério Público, declarará extinta a punibilidade."},{"chave":"art-63","sequencia":73,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IV — DA AÇÃO CIVIL"],"titulo":"TÍTULO IV — DA AÇÃO CIVIL","rotulo":"Art. 63.","conteudo":"Transitada em julgado a sentença condenatória, poderão promover-lhe a execução, no juízo cível, para o efeito da reparação do dano, o ofendido, seu representante legal ou seus herdeiros.\n\nParágrafo único. Transitada em julgado a sentença condenatória, a execução poderá ser efetuada pelo valor fixado nos termos do inciso iv do caput do art. 387 deste Código sem prejuízo da liquidação para a apuração do dano efetivamente sofrido. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-64","sequencia":74,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IV — DA AÇÃO CIVIL"],"titulo":"TÍTULO IV — DA AÇÃO CIVIL","rotulo":"Art. 64.","conteudo":"Sem prejuízo do disposto no artigo anterior, a ação para ressarcimento do dano poderá ser proposta no juízo cível, contra o autor do crime e, se for caso, contra o responsável civil. (Vide Lei nº 5.970, de 1973)\n\nParágrafo único. Intentada a ação penal, o juiz da ação civil poderá suspender o curso desta, até o julgamento definitivo daquela."},{"chave":"art-65","sequencia":75,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IV — DA AÇÃO CIVIL"],"titulo":"TÍTULO IV — DA AÇÃO CIVIL","rotulo":"Art. 65.","conteudo":"Faz coisa julgada no cível a sentença penal que reconhecer ter sido o ato praticado em estado de necessidade, em legítima defesa, em estrito cumprimento de dever legal ou no exercício regular de direito. (Vide ADPF 779)"},{"chave":"art-66","sequencia":76,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IV — DA AÇÃO CIVIL"],"titulo":"TÍTULO IV — DA AÇÃO CIVIL","rotulo":"Art. 66.","conteudo":"Não obstante a sentença absolutória no juízo criminal, a ação civil poderá ser proposta quando não tiver sido, categoricamente, reconhecida a inexistência material do fato."},{"chave":"art-67","sequencia":77,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IV — DA AÇÃO CIVIL"],"titulo":"TÍTULO IV — DA AÇÃO CIVIL","rotulo":"Art. 67.","conteudo":"Não impedirão igualmente a propositura da ação civil:\n\nI - o despacho de arquivamento do inquérito ou das peças de informação;\n\nII - a decisão que julgar extinta a punibilidade;\n\nIII - a sentença absolutória que decidir que o fato imputado não constitui crime."},{"chave":"art-68","sequencia":78,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IV — DA AÇÃO CIVIL"],"titulo":"TÍTULO IV — DA AÇÃO CIVIL","rotulo":"Art. 68.","conteudo":"Quando o titular do direito à reparação do dano for pobre ( art. 32, §§ 1 o e 2 o ), a execução da sentença condenatória ( art. 63 ) ou a ação civil ( art. 64 ) será promovida, a seu requerimento, pelo Ministério Público."},{"chave":"art-69","sequencia":79,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA"],"titulo":"TÍTULO V — DA COMPETÊNCIA","rotulo":"Art. 69.","conteudo":"Determinará a competência jurisdicional:\n\nI - o lugar da infração:\n\nII - o domicílio ou residência do réu;\n\nIII - a natureza da infração;\n\nIV - a distribuição;\n\nV - a conexão ou continência;\n\nVI - a prevenção;\n\nVII - a prerrogativa de função."},{"chave":"art-70","sequencia":80,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO I — DA COMPETÊNCIA PELO LUGAR DA INFRAÇÃO"],"titulo":"CAPÍTULO I — DA COMPETÊNCIA PELO LUGAR DA INFRAÇÃO","rotulo":"Art. 70.","conteudo":"A competência será, de regra, determinada pelo lugar em que se consumar a infração, ou, no caso de tentativa, pelo lugar em que for praticado o último ato de execução.\n\n§ 1 o Se, iniciada a execução no território nacional, a infração se consumar fora dele, a competência será determinada pelo lugar em que tiver sido praticado, no Brasil, o último ato de execução.\n\n§ 2 o Quando o último ato de execução for praticado fora do território nacional, será competente o juiz do lugar em que o crime, embora parcialmente, tenha produzido ou devia produzir seu resultado.\n\n§ 3 o Quando incerto o limite territorial entre duas ou mais jurisdições, ou quando incerta a jurisdição por ter sido a infração consumada ou tentada nas divisas de duas ou mais jurisdições, a competência firmar-se-á pela prevenção.\n\n§ 4º Nos crimes previstos no art. 171 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), quando praticados mediante depósito, mediante emissão de cheques sem suficiente provisão de fundos em poder do sacado ou com o pagamento frustrado ou mediante transferência de valores, a competência será definida pelo local do domicílio da vítima, e, em caso de pluralidade de vítimas, a competência firmar-se-á pela prevenção. (Incluído pela Lei nº 14.155, de 2021)"},{"chave":"art-71","sequencia":81,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO I — DA COMPETÊNCIA PELO LUGAR DA INFRAÇÃO"],"titulo":"CAPÍTULO I — DA COMPETÊNCIA PELO LUGAR DA INFRAÇÃO","rotulo":"Art. 71.","conteudo":"Tratando-se de infração continuada ou permanente, praticada em território de duas ou mais jurisdições, a competência firmar-se-á pela prevenção."},{"chave":"art-72","sequencia":82,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO II — DA COMPETÊNCIA PELO DOMICÍLIO OU RESIDÊNCIA DO RÉU"],"titulo":"CAPÍTULO II — DA COMPETÊNCIA PELO DOMICÍLIO OU RESIDÊNCIA DO RÉU","rotulo":"Art. 72.","conteudo":"Não sendo conhecido o lugar da infração, a competência regular-se-á pelo domicílio ou residência do réu.\n\n§ 1 o Se o réu tiver mais de uma residência, a competência firmar-se-á pela prevenção.\n\n§ 2 o Se o réu não tiver residência certa ou for ignorado o seu paradeiro, será competente o juiz que primeiro tomar conhecimento do fato."},{"chave":"art-73","sequencia":83,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO II — DA COMPETÊNCIA PELO DOMICÍLIO OU RESIDÊNCIA DO RÉU"],"titulo":"CAPÍTULO II — DA COMPETÊNCIA PELO DOMICÍLIO OU RESIDÊNCIA DO RÉU","rotulo":"Art. 73.","conteudo":"Nos casos de exclusiva ação privada, o querelante poderá preferir o foro de domicílio ou da residência do réu, ainda quando conhecido o lugar da infração."},{"chave":"art-74","sequencia":84,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO III — DA COMPETÊNCIA PELA NATUREZA DA INFRAÇÃO"],"titulo":"CAPÍTULO III — DA COMPETÊNCIA PELA NATUREZA DA INFRAÇÃO","rotulo":"Art. 74.","conteudo":"A competência pela natureza da infração será regulada pelas leis de organização judiciária, salvo a competência privativa do Tribunal do Júri.\n\n§ 1º Compete ao Tribunal do Júri o julgamento dos crimes previstos nos arts. 121, §§ 1º e 2º , 122 , parágrafo único , 123, 124, 125, 126 e 127 do Código Penal , consumados ou tentados. (Redação dada pela Lei nº 263, de 23.2.1948)\n\n§ 2 o Se, iniciado o processo perante um juiz, houver desclassificação para infração da competência de outro, a este será remetido o processo, salvo se mais graduada for a jurisdição do primeiro, que, em tal caso, terá sua competência prorrogada.\n\n§ 3 o Se o juiz da pronúncia desclassificar a infração para outra atribuída à competência de juiz singular, observar-se-á o disposto no art. 410 ; mas, se a desclassificação for feita pelo próprio Tribunal do Júri, a seu presidente caberá proferir a sentença ( art. 492, § 2 o )."},{"chave":"art-75","sequencia":85,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO IV — DA COMPETÊNCIA POR DISTRIBUIÇÃO"],"titulo":"CAPÍTULO IV — DA COMPETÊNCIA POR DISTRIBUIÇÃO","rotulo":"Art. 75.","conteudo":"A precedência da distribuição fixará a competência quando, na mesma circunscrição judiciária, houver mais de um juiz igualmente competente.\n\nParágrafo único. A distribuição realizada para o efeito da concessão de fiança ou da decretação de prisão preventiva ou de qualquer diligência anterior à denúncia ou queixa prevenirá a da ação penal."},{"chave":"art-76","sequencia":86,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA"],"titulo":"CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA","rotulo":"Art. 76.","conteudo":"A competência será determinada pela conexão:\n\nI - se, ocorrendo duas ou mais infrações, houverem sido praticadas, ao mesmo tempo, por várias pessoas reunidas, ou por várias pessoas em concurso, embora diverso o tempo e o lugar, ou por várias pessoas, umas contra as outras;\n\nII - se, no mesmo caso, houverem sido umas praticadas para facilitar ou ocultar as outras, ou para conseguir impunidade ou vantagem em relação a qualquer delas;\n\nIII - quando a prova de uma infração ou de qualquer de suas circunstâncias elementares influir na prova de outra infração."},{"chave":"art-77","sequencia":87,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA"],"titulo":"CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA","rotulo":"Art. 77.","conteudo":"A competência será determinada pela continência quando:\n\nI - duas ou mais pessoas forem acusadas pela mesma infração;\n\nII - no caso de infração cometida nas condições previstas nos arts. 51, § 1 o , 53, segunda parte , e 54 do Código Penal ."},{"chave":"art-78","sequencia":88,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA"],"titulo":"CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA","rotulo":"Art. 78.","conteudo":"Na determinação da competência por conexão ou continência, serão observadas as seguintes regras: (Redação dada pela Lei nº 263, de 23.2.1948)\n\nI - no concurso entre a competência do júri e a de outro órgão da jurisdição comum, prevalecerá a competência do júri, salvo os casos de homicídios cometidos por membros de organizações criminosas ultraviolentas, grupo paramilitar ou milícia privada, ou sua tentativa, na forma do art. 2º da lei que institui o marco legal do combate ao crime organizado no Brasil; (Redação dada pela Lei nº 15.358, de 2026)\n\nIl - no concurso de jurisdições da mesma categoria: (Redação dada pela Lei nº 263, de 23.2.1948)\n\na) preponderará a do lugar da infração, à qual for cominada a pena mais grave; (Redação dada pela Lei nº 263, de 23.2.1948)\n\nb) prevalecerá a do lugar em que houver ocorrido o maior número de infrações, se as respectivas penas forem de igual gravidade; (Redação dada pela Lei nº 263, de 23.2.1948)\n\nc) firmar-se-á a competência pela prevenção, nos outros casos; (Redação dada pela Lei nº 263, de 23.2.1948)\n\nIII - no concurso de jurisdições de diversas categorias, predominará a de maior graduação; (Redação dada pela Lei nº 263, de 23.2.1948)\n\nIV - no concurso entre a jurisdição comum e a especial, prevalecerá esta. (Redação dada pela Lei nº 263, de 23.2.1948)"},{"chave":"art-79","sequencia":89,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA"],"titulo":"CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA","rotulo":"Art. 79.","conteudo":"A conexão e a continência importarão unidade de processo e julgamento, salvo:\n\nI - no concurso entre a jurisdição comum e a militar;\n\nII - no concurso entre a jurisdição comum e a do juízo de menores.\n\n§ 1 o Cessará, em qualquer caso, a unidade do processo, se, em relação a algum co-réu, sobrevier o caso previsto no art. 152 .\n\n§ 2 o A unidade do processo não importará a do julgamento, se houver co-réu foragido que não possa ser julgado à revelia, ou ocorrer a hipótese do art. 461 ."},{"chave":"art-80","sequencia":90,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA"],"titulo":"CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA","rotulo":"Art. 80.","conteudo":"Será facultativa a separação dos processos quando as infrações tiverem sido praticadas em circunstâncias de tempo ou de lugar diferentes, ou, quando pelo excessivo número de acusados e para não Ihes prolongar a prisão provisória, ou por outro motivo relevante, o juiz reputar conveniente a separação."},{"chave":"art-81","sequencia":91,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA"],"titulo":"CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA","rotulo":"Art. 81.","conteudo":"Verificada a reunião dos processos por conexão ou continência, ainda que no processo da sua competência própria venha o juiz ou tribunal a proferir sentença absolutória ou que desclassifique a infração para outra que não se inclua na sua competência, continuará competente em relação aos demais processos.\n\nParágrafo único. Reconhecida inicialmente ao júri a competência por conexão ou continência, o juiz, se vier a desclassificar a infração ou impronunciar ou absolver o acusado, de maneira que exclua a competência do júri, remeterá o processo ao juízo competente."},{"chave":"art-82","sequencia":92,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA"],"titulo":"CAPÍTULO V — DA COMPETÊNCIA POR CONEXÃO OU CONTINÊNCIA","rotulo":"Art. 82.","conteudo":"Se, não obstante a conexão ou continência, forem instaurados processos diferentes, a autoridade de jurisdição prevalente deverá avocar os processos que corram perante os outros juízes, salvo se já estiverem com sentença definitiva. Neste caso, a unidade dos processos só se dará, ulteriormente, para o efeito de soma ou de unificação das penas."},{"chave":"art-83","sequencia":93,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO VI — DA COMPETÊNCIA POR PREVENÇÃO"],"titulo":"CAPÍTULO VI — DA COMPETÊNCIA POR PREVENÇÃO","rotulo":"Art. 83.","conteudo":"Verificar-se-á a competência por prevenção toda vez que, concorrendo dois ou mais juízes igualmente competentes ou com jurisdição cumulativa, um deles tiver antecedido aos outros na prática de algum ato do processo ou de medida a este relativa, ainda que anterior ao oferecimento da denúncia ou da queixa ( arts. 70, § 3 o , 71 , 72, § 2 o , e 78, II, c )."},{"chave":"art-84","sequencia":94,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO VII — DA COMPETÊNCIA PELA PRERROGATIVA DE FUNÇÃO"],"titulo":"CAPÍTULO VII — DA COMPETÊNCIA PELA PRERROGATIVA DE FUNÇÃO","rotulo":"Art. 84.","conteudo":"A competência pela prerrogativa de função é do Supremo Tribunal Federal, do Superior Tribunal de Justiça, dos Tribunais Regionais Federais e Tribunais de Justiça dos Estados e do Distrito Federal, relativamente às pessoas que devam responder perante eles por crimes comuns e de responsabilidade. (Redação dada pela Lei nº 10.628, de 24.12.2002)\n\n§ 1 o (Vide ADIN nº 2797)\n\n§ 2 o (Vide ADIN nº 2797)"},{"chave":"art-85","sequencia":95,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO VII — DA COMPETÊNCIA PELA PRERROGATIVA DE FUNÇÃO"],"titulo":"CAPÍTULO VII — DA COMPETÊNCIA PELA PRERROGATIVA DE FUNÇÃO","rotulo":"Art. 85.","conteudo":"Nos processos por crime contra a honra, em que forem querelantes as pessoas que a Constituição sujeita à jurisdição do Supremo Tribunal Federal e dos Tribunais de Apelação, àquele ou a estes caberá o julgamento, quando oposta e admitida a exceção da verdade."},{"chave":"art-86","sequencia":96,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO VII — DA COMPETÊNCIA PELA PRERROGATIVA DE FUNÇÃO"],"titulo":"CAPÍTULO VII — DA COMPETÊNCIA PELA PRERROGATIVA DE FUNÇÃO","rotulo":"Art. 86.","conteudo":"Ao Supremo Tribunal Federal competirá, privativamente, processar e julgar:\n\nI - os seus ministros, nos crimes comuns;\n\nII - os ministros de Estado, salvo nos crimes conexos com os do Presidente da República;\n\nIII - o procurador-geral da República, os desembargadores dos Tribunais de Apelação, os ministros do Tribunal de Contas e os embaixadores e ministros diplomáticos, nos crimes comuns e de responsabilidade."},{"chave":"art-87","sequencia":97,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO VII — DA COMPETÊNCIA PELA PRERROGATIVA DE FUNÇÃO"],"titulo":"CAPÍTULO VII — DA COMPETÊNCIA PELA PRERROGATIVA DE FUNÇÃO","rotulo":"Art. 87.","conteudo":"Competirá, originariamente, aos Tribunais de Apelação o julgamento dos governadores ou interventores nos Estados ou Territórios, e prefeito do Distrito Federal, seus respectivos secretários e chefes de Polícia, juízes de instância inferior e órgãos do Ministério Público."},{"chave":"art-88","sequencia":98,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO VIII — DISPOSIÇÕES ESPECIAIS"],"titulo":"CAPÍTULO VIII — DISPOSIÇÕES ESPECIAIS","rotulo":"Art. 88.","conteudo":"No processo por crimes praticados fora do território brasileiro, será competente o juízo da Capital do Estado onde houver por último residido o acusado. Se este nunca tiver residido no Brasil, será competente o juízo da Capital da República."},{"chave":"art-89","sequencia":99,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO VIII — DISPOSIÇÕES ESPECIAIS"],"titulo":"CAPÍTULO VIII — DISPOSIÇÕES ESPECIAIS","rotulo":"Art. 89.","conteudo":"Os crimes cometidos em qualquer embarcação nas águas territoriais da República, ou nos rios e lagos fronteiriços, bem como a bordo de embarcações nacionais, em alto-mar, serão processados e julgados pela justiça do primeiro porto brasileiro em que tocar a embarcação, após o crime, ou, quando se afastar do País, pela do último em que houver tocado."},{"chave":"art-90","sequencia":100,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO VIII — DISPOSIÇÕES ESPECIAIS"],"titulo":"CAPÍTULO VIII — DISPOSIÇÕES ESPECIAIS","rotulo":"Art. 90.","conteudo":"Os crimes praticados a bordo de aeronave nacional, dentro do espaço aéreo correspondente ao território brasileiro, ou ao alto-mar, ou a bordo de aeronave estrangeira, dentro do espaço aéreo correspondente ao território nacional, serão processados e julgados pela justiça da comarca em cujo território se verificar o pouso após o crime, ou pela da comarca de onde houver partido a aeronave."},{"chave":"art-91","sequencia":101,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO V — DA COMPETÊNCIA","CAPÍTULO VIII — DISPOSIÇÕES ESPECIAIS"],"titulo":"CAPÍTULO VIII — DISPOSIÇÕES ESPECIAIS","rotulo":"Art. 91.","conteudo":"Quando incerta e não se determinar de acordo com as normas estabelecidas nos arts. 89 e 90 , a competência se firmará pela prevenção. (Redação dada pela Lei nº 4.893, de 9.12.1965)"},{"chave":"art-92","sequencia":102,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO I — DAS QUESTÕES PREJUDICIAIS"],"titulo":"CAPÍTULO I — DAS QUESTÕES PREJUDICIAIS","rotulo":"Art. 92.","conteudo":"Se a decisão sobre a existência da infração depender da solução de controvérsia, que o juiz repute séria e fundada, sobre o estado civil das pessoas, o curso da ação penal ficará suspenso até que no juízo cível seja a controvérsia dirimida por sentença passada em julgado, sem prejuízo, entretanto, da inquirição das testemunhas e de outras provas de natureza urgente.\n\nParágrafo único. Se for o crime de ação pública, o Ministério Público, quando necessário, promoverá a ação civil ou prosseguirá na que tiver sido iniciada, com a citação dos interessados."},{"chave":"art-93","sequencia":103,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO I — DAS QUESTÕES PREJUDICIAIS"],"titulo":"CAPÍTULO I — DAS QUESTÕES PREJUDICIAIS","rotulo":"Art. 93.","conteudo":"Se o reconhecimento da existência da infração penal depender de decisão sobre questão diversa da prevista no artigo anterior, da competência do juízo cível, e se neste houver sido proposta ação para resolvê-la, o juiz criminal poderá, desde que essa questão seja de difícil solução e não verse sobre direito cuja prova a lei civil limite, suspender o curso do processo, após a inquirição das testemunhas e realização das outras provas de natureza urgente.\n\n§ 1 o O juiz marcará o prazo da suspensão, que poderá ser razoavelmente prorrogado, se a demora não for imputável à parte. Expirado o prazo, sem que o juiz cível tenha proferido decisão, o juiz criminal fará prosseguir o processo, retomando sua competência para resolver, de fato e de direito, toda a matéria da acusação ou da defesa.\n\n§ 2 o Do despacho que denegar a suspensão não caberá recurso.\n\n§ 3 o Suspenso o processo, e tratando-se de crime de ação pública, incumbirá ao Ministério Público intervir imediatamente na causa cível, para o fim de promover-lhe o rápido andamento."},{"chave":"art-94","sequencia":104,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO I — DAS QUESTÕES PREJUDICIAIS"],"titulo":"CAPÍTULO I — DAS QUESTÕES PREJUDICIAIS","rotulo":"Art. 94.","conteudo":"A suspensão do curso da ação penal, nos casos dos artigos anteriores, será decretada pelo juiz, de ofício ou a requerimento das partes."},{"chave":"art-95","sequencia":105,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 95.","conteudo":"Poderão ser opostas as exceções de:\n\nI - suspeição;\n\nII - incompetência de juízo;\n\nIII - litispendência;\n\nIV - ilegitimidade de parte;\n\nV - coisa julgada."},{"chave":"art-96","sequencia":106,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 96.","conteudo":"A argüição de suspeição precederá a qualquer outra, salvo quando fundada em motivo superveniente."},{"chave":"art-97","sequencia":107,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 97.","conteudo":"O juiz que espontaneamente afirmar suspeição deverá fazê-lo por escrito, declarando o motivo legal, e remeterá imediatamente o processo ao seu substituto, intimadas as partes."},{"chave":"art-98","sequencia":108,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 98.","conteudo":"Quando qualquer das partes pretender recusar o juiz, deverá fazê-lo em petição assinada por ela própria ou por procurador com poderes especiais, aduzindo as suas razões acompanhadas de prova documental ou do rol de testemunhas."},{"chave":"art-99","sequencia":109,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 99.","conteudo":"Se reconhecer a suspeição, o juiz sustará a marcha do processo, mandará juntar aos autos a petição do recusante com os documentos que a instruam, e por despacho se declarará suspeito, ordenando a remessa dos autos ao substituto."},{"chave":"art-100","sequencia":110,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 100.","conteudo":"Não aceitando a suspeição, o juiz mandará autuar em apartado a petição, dará sua resposta dentro em três dias, podendo instruí-la e oferecer testemunhas, e, em seguida, determinará sejam os autos da exceção remetidos, dentro em 24 vinte e quatro horas, ao juiz ou tribunal a quem competir o julgamento.\n\n§ 1 o Reconhecida, preliminarmente, a relevância da argüição, o juiz ou tribunal, com citação das partes, marcará dia e hora para a inquirição das testemunhas, seguindo-se o julgamento, independentemente de mais alegações.\n\n§ 2 o Se a suspeição for de manifesta improcedência, o juiz ou relator a rejeitará liminarmente."},{"chave":"art-101","sequencia":111,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 101.","conteudo":"Julgada procedente a suspeição, ficarão nulos os atos do processo principal, pagando o juiz as custas, no caso de erro inescusável; rejeitada, evidenciando-se a malícia do excipiente, a este será imposta a multa de duzentos mil-réis a dois contos de réis."},{"chave":"art-102","sequencia":112,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 102.","conteudo":"Quando a parte contrária reconhecer a procedência da argüição, poderá ser sustado, a seu requerimento, o processo principal, até que se julgue o incidente da suspeição."},{"chave":"art-103","sequencia":113,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 103.","conteudo":"No Supremo Tribunal Federal e nos Tribunais de Apelação, o juiz que se julgar suspeito deverá declará-lo nos autos e, se for revisor, passar o feito ao seu substituto na ordem da precedência, ou, se for relator, apresentar os autos em mesa para nova distribuição.\n\n§ 1 o Se não for relator nem revisor, o juiz que houver de dar-se por suspeito, deverá fazê-lo verbalmente, na sessão de julgamento, registrando-se na ata a declaração.\n\n§ 2 o Se o presidente do tribunal se der por suspeito, competirá ao seu substituto designar dia para o julgamento e presidi-lo.\n\n§ 3 o Observar-se-á, quanto à argüição de suspeição pela parte, o disposto nos arts. 98 a 101 , no que Ihe for aplicável, atendido, se o juiz a reconhecer, o que estabelece este artigo.\n\n§ 4 o A suspeição, não sendo reconhecida, será julgada pelo tribunal pleno, funcionando como relator o presidente.\n\n§ 5 o Se o recusado for o presidente do tribunal, o relator será o vice-presidente."},{"chave":"art-104","sequencia":114,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 104.","conteudo":"Se for argüida a suspeição do órgão do Ministério Público, o juiz, depois de ouvi-lo, decidirá, sem recurso, podendo antes admitir a produção de provas no prazo de três dias."},{"chave":"art-105","sequencia":115,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 105.","conteudo":"As partes poderão também argüir de suspeitos os peritos, os intérpretes e os serventuários ou funcionários de justiça, decidindo o juiz de plano e sem recurso, à vista da matéria alegada e prova imediata."},{"chave":"art-106","sequencia":116,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 106.","conteudo":"A suspeição dos jurados deverá ser argüida oralmente, decidindo de plano do presidente do Tribunal do Júri, que a rejeitará se, negada pelo recusado, não for imediatamente comprovada, o que tudo constará da ata."},{"chave":"art-107","sequencia":117,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 107.","conteudo":"Não se poderá opor suspeição às autoridades policiais nos atos do inquérito, mas deverão elas declarar-se suspeitas, quando ocorrer motivo legal."},{"chave":"art-108","sequencia":118,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 108.","conteudo":"A exceção de incompetência do juízo poderá ser oposta, verbalmente ou por escrito, no prazo de defesa.\n\n§ 1 o Se, ouvido o Ministério Público, for aceita a declinatória, o feito será remetido ao juízo competente, onde, ratificados os atos anteriores, o processo prosseguirá.\n\n§ 2 o Recusada a incompetência, o juiz continuará no feito, fazendo tomar por termo a declinatória, se formulada verbalmente."},{"chave":"art-109","sequencia":119,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 109.","conteudo":"Se em qualquer fase do processo o juiz reconhecer motivo que o torne incompetente, declará-lo-á nos autos, haja ou não alegação da parte, prosseguindo-se na forma do artigo anterior."},{"chave":"art-110","sequencia":120,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 110.","conteudo":"Nas exceções de litispendência, ilegitimidade de parte e coisa julgada, será observado, no que Ihes for aplicável, o disposto sobre a exceção de incompetência do juízo.\n\n§ 1 o Se a parte houver de opor mais de uma dessas exceções, deverá fazê-lo numa só petição ou articulado.\n\n§ 2 o A exceção de coisa julgada somente poderá ser oposta em relação ao fato principal, que tiver sido objeto da sentença."},{"chave":"art-111","sequencia":121,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO II — DAS EXCEÇÕES"],"titulo":"CAPÍTULO II — DAS EXCEÇÕES","rotulo":"Art. 111.","conteudo":"As exceções serão processadas em autos apartados e não suspenderão, em regra, o andamento da ação penal."},{"chave":"art-112","sequencia":122,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO III — DAS INCOMPATIBILIDADES E IMPEDIMENTOS"],"titulo":"CAPÍTULO III — DAS INCOMPATIBILIDADES E IMPEDIMENTOS","rotulo":"Art. 112.","conteudo":"O juiz, o órgão do Ministério Público, os serventuários ou funcionários de justiça e os peritos ou intérpretes abster-se-ão de servir no processo, quando houver incompatibilidade ou impedimento legal, que declararão nos autos. Se não se der a abstenção, a incompatibilidade ou impedimento poderá ser argüido pelas partes, seguindo-se o processo estabelecido para a exceção de suspeição."},{"chave":"art-113","sequencia":123,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO IV — DO CONFLITO DE JURISDIÇÃO"],"titulo":"CAPÍTULO IV — DO CONFLITO DE JURISDIÇÃO","rotulo":"Art. 113.","conteudo":"As questões atinentes à competência resolver-se-ão não só pela exceção própria, como também pelo conflito positivo ou negativo de jurisdição."},{"chave":"art-114","sequencia":124,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO IV — DO CONFLITO DE JURISDIÇÃO"],"titulo":"CAPÍTULO IV — DO CONFLITO DE JURISDIÇÃO","rotulo":"Art. 114.","conteudo":"Haverá conflito de jurisdição:\n\nI - quando duas ou mais autoridades judiciárias se considerarem competentes, ou incompetentes, para conhecer do mesmo fato criminoso;\n\nII - quando entre elas surgir controvérsia sobre unidade de juízo, junção ou separação de processos."},{"chave":"art-115","sequencia":125,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO IV — DO CONFLITO DE JURISDIÇÃO"],"titulo":"CAPÍTULO IV — DO CONFLITO DE JURISDIÇÃO","rotulo":"Art. 115.","conteudo":"O conflito poderá ser suscitado:\n\nI - pela parte interessada;\n\nII - pelos órgãos do Ministério Público junto a qualquer dos juízos em dissídio;\n\nIII - por qualquer dos juízes ou tribunais em causa."},{"chave":"art-116","sequencia":126,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO IV — DO CONFLITO DE JURISDIÇÃO"],"titulo":"CAPÍTULO IV — DO CONFLITO DE JURISDIÇÃO","rotulo":"Art. 116.","conteudo":"Os juízes e tribunais, sob a forma de representação, e a parte interessada, sob a de requerimento, darão parte escrita e circunstanciada do conflito, perante o tribunal competente, expondo os fundamentos e juntando os documentos comprobatórios.\n\n§ 1 o Quando negativo o conflito, os juízes e tribunais poderão suscitá-lo nos próprios autos do processo.\n\n§ 2 o Distribuído o feito, se o conflito for positivo, o relator poderá determinar imediatamente que se suspenda o andamento do processo.\n\n§ 3 o Expedida ou não a ordem de suspensão, o relator requisitará informações às autoridades em conflito, remetendo-lhes cópia do requerimento ou representação.\n\n§ 4 o As informações serão prestadas no prazo marcado pelo relator.\n\n§ 5 o Recebidas as informações, e depois de ouvido o procurador-geral, o conflito será decidido na primeira sessão, salvo se a instrução do feito depender de diligência.\n\n§ 6 o Proferida a decisão, as cópias necessárias serão remetidas, para a sua execução, às autoridades contra as quais tiver sido levantado o conflito ou que o houverem suscitado."},{"chave":"art-117","sequencia":127,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO IV — DO CONFLITO DE JURISDIÇÃO"],"titulo":"CAPÍTULO IV — DO CONFLITO DE JURISDIÇÃO","rotulo":"Art. 117.","conteudo":"O Supremo Tribunal Federal, mediante avocatória, restabelecerá a sua jurisdição, sempre que exercida por qualquer dos juízes ou tribunais inferiores."},{"chave":"art-118","sequencia":128,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS"],"titulo":"CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS","rotulo":"Art. 118.","conteudo":"Antes de transitar em julgado a sentença final, as coisas apreendidas não poderão ser restituídas enquanto interessarem ao processo."},{"chave":"art-119","sequencia":129,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS"],"titulo":"CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS","rotulo":"Art. 119.","conteudo":"As coisas a que se referem os arts. 74 e 100 do Código Penal não poderão ser restituídas, mesmo depois de transitar em julgado a sentença final, salvo se pertencerem ao lesado ou a terceiro de boa-fé."},{"chave":"art-120","sequencia":130,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS"],"titulo":"CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS","rotulo":"Art. 120.","conteudo":"A restituição, quando cabível, poderá ser ordenada pela autoridade policial ou juiz, mediante termo nos autos, desde que não exista dúvida quanto ao direito do reclamante.\n\n§ 1 o Se duvidoso esse direito, o pedido de restituição autuar-se-á em apartado, assinando-se ao requerente o prazo de 5 (cinco) dias para a prova. Em tal caso, só o juiz criminal poderá decidir o incidente.\n\n§ 2 o O incidente autuar-se-á também em apartado e só a autoridade judicial o resolverá, se as coisas forem apreendidas em poder de terceiro de boa-fé, que será intimado para alegar e provar o seu direito, em prazo igual e sucessivo ao do reclamante, tendo um e outro dois dias para arrazoar.\n\n§ 3 o Sobre o pedido de restituição será sempre ouvido o Ministério Público.\n\n§ 4 o Em caso de dúvida sobre quem seja o verdadeiro dono, o juiz remeterá as partes para o juízo cível, ordenando o depósito das coisas em mãos de depositário ou do próprio terceiro que as detinha, se for pessoa idônea.\n\n§ 5 o Tratando-se de coisas facilmente deterioráveis, serão avaliadas e levadas a leilão público, depositando-se o dinheiro apurado, ou entregues ao terceiro que as detinha, se este for pessoa idônea e assinar termo de responsabilidade."},{"chave":"art-121","sequencia":131,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS"],"titulo":"CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS","rotulo":"Art. 121.","conteudo":"No caso de apreensão de coisa adquirida com os proventos da infração, aplica-se o disposto no art. 133 e seu parágrafo ."},{"chave":"art-122","sequencia":132,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS"],"titulo":"CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS","rotulo":"Art. 122.","conteudo":"Sem prejuízo do disposto no art. 120, as coisas apreendidas serão alienadas nos termos do disposto no art. 133 deste Código. (Redação dada pela Lei nº 13.964, de 2019)\n\nParágrafo único. (Revogado). (Redação dada pela Lei nº 13.964, de 2019)"},{"chave":"art-123","sequencia":133,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS"],"titulo":"CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS","rotulo":"Art. 123.","conteudo":"Fora dos casos previstos nos artigos anteriores, se dentro no prazo de 90 dias, a contar da data em que transitar em julgado a sentença final, condenatória ou absolutória, os objetos apreendidos não forem reclamados ou não pertencerem ao réu, serão vendidos em leilão, depositando-se o saldo à disposição do juízo de ausentes."},{"chave":"art-124","sequencia":134,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS"],"titulo":"CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS","rotulo":"Art. 124.","conteudo":"Os instrumentos do crime, cuja perda em favor da União for decretada, e as coisas confiscadas, de acordo com o disposto no art. 100 do Código Penal , serão inutilizados ou recolhidos a museu criminal, se houver interesse na sua conservação."},{"chave":"art-124-a","sequencia":135,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS"],"titulo":"CAPÍTULO V — DA RESTITUIÇÃO DAS COISAS APREENDIDAS","rotulo":"Art. 124º-A","conteudo":"Na hipótese de decretação de perdimento de obras de arte ou de outros bens de relevante valor cultural ou artístico, se o crime não tiver vítima determinada, poderá haver destinação dos bens a museus públicos. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-125","sequencia":136,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 125.","conteudo":"Caberá o seqüestro dos bens imóveis, adquiridos pelo indiciado com os proventos da infração, ainda que já tenham sido transferidos a terceiro."},{"chave":"art-126","sequencia":137,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 126.","conteudo":"Para a decretação do seqüestro, bastará a existência de indícios veementes da proveniência ilícita dos bens."},{"chave":"art-127","sequencia":138,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 127.","conteudo":"O juiz, de ofício, a requerimento do Ministério Público ou do ofendido, ou mediante representação da autoridade policial, poderá ordenar o seqüestro, em qualquer fase do processo ou ainda antes de oferecida a denúncia ou queixa."},{"chave":"art-128","sequencia":139,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 128.","conteudo":"Realizado o seqüestro, o juiz ordenará a sua inscrição no Registro de Imóveis."},{"chave":"art-129","sequencia":140,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 129.","conteudo":"O seqüestro autuar-se-á em apartado e admitirá embargos de terceiro."},{"chave":"art-130","sequencia":141,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 130.","conteudo":"O seqüestro poderá ainda ser embargado:\n\nI - pelo acusado, sob o fundamento de não terem os bens sido adquiridos com os proventos da infração;\n\nII - pelo terceiro, a quem houverem os bens sido transferidos a título oneroso, sob o fundamento de tê-los adquirido de boa-fé.\n\nParágrafo único. Não poderá ser pronunciada decisão nesses embargos antes de passar em julgado a sentença condenatória."},{"chave":"art-131","sequencia":142,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 131.","conteudo":"O seqüestro será levantado:\n\nI - se a ação penal não for intentada no prazo de sessenta dias, contado da data em que ficar concluída a diligência;\n\nII - se o terceiro, a quem tiverem sido transferidos os bens, prestar caução que assegure a aplicação do disposto no art. 74, II, b , segunda parte, do Código Penal ;\n\nIII - se for julgada extinta a punibilidade ou absolvido o réu, por sentença transitada em julgado."},{"chave":"art-132","sequencia":143,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 132.","conteudo":"Proceder-se-á ao seqüestro dos bens móveis se, verificadas as condições previstas no art. 126 , não for cabível a medida regulada no Capítulo Xl do Título Vll deste Livro ."},{"chave":"art-133","sequencia":144,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 133.","conteudo":"Transitada em julgado a sentença condenatória, o juiz, de ofício ou a requerimento do interessado ou do Ministério Público, determinará a avaliação e a venda dos bens em leilão público cujo perdimento tenha sido decretado. (Redação dada pela Lei nº 13.964, de 2019)\n\n§ 1º Do dinheiro apurado, será recolhido aos cofres públicos o que não couber ao lesado ou a terceiro de boa-fé. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 2º O valor apurado deverá ser recolhido ao Fundo Penitenciário Nacional, exceto se houver previsão diversa em lei especial. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-133-a","sequencia":145,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 133º-A","conteudo":"O juiz poderá autorizar, constatado o interesse público, a utilização de bem sequestrado, apreendido ou sujeito a qualquer medida assecuratória pelos órgãos de segurança pública previstos no art. 144 da Constituição Federal, do sistema prisional, do sistema socioeducativo, da Força Nacional de Segurança Pública e do Instituto Geral de Perícia, para o desempenho de suas atividades. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 1º O órgão de segurança pública participante das ações de investigação ou repressão da infração penal que ensejou a constrição do bem terá prioridade na sua utilização. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 2º Fora das hipóteses anteriores, demonstrado o interesse público, o juiz poderá autorizar o uso do bem pelos demais órgãos públicos. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 3º Se o bem a que se refere o caput deste artigo for veículo, embarcação ou aeronave, o juiz ordenará à autoridade de trânsito ou ao órgão de registro e controle a expedição de certificado provisório de registro e licenciamento em favor do órgão público beneficiário, o qual estará isento do pagamento de multas, encargos e tributos anteriores à disponibilização do bem para a sua utilização, que deverão ser cobrados de seu responsável. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 4º Transitada em julgado a sentença penal condenatória com a decretação de perdimento dos bens, ressalvado o direito do lesado ou terceiro de boa-fé, o juiz poderá determinar a transferência definitiva da propriedade ao órgão público beneficiário ao qual foi custodiado o bem. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-134","sequencia":146,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 134.","conteudo":"A hipoteca legal sobre os imóveis do indiciado poderá ser requerida pelo ofendido em qualquer fase do processo, desde que haja certeza da infração e indícios suficientes da autoria."},{"chave":"art-135","sequencia":147,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 135.","conteudo":"Pedida a especialização mediante requerimento, em que a parte estimará o valor da responsabilidade civil, e designará e estimará o imóvel ou imóveis que terão de ficar especialmente hipotecados, o juiz mandará logo proceder ao arbitramento do valor da responsabilidade e à avaliação do imóvel ou imóveis.\n\n§ 1 o A petição será instruída com as provas ou indicação das provas em que se fundar a estimação da responsabilidade, com a relação dos imóveis que o responsável possuir, se outros tiver, além dos indicados no requerimento, e com os documentos comprobatórios do domínio.\n\n§ 2 o O arbitramento do valor da responsabilidade e a avaliação dos imóveis designados far-se-ão por perito nomeado pelo juiz, onde não houver avaliador judicial, sendo-lhe facultada a consulta dos autos do processo respectivo.\n\n§ 3 o O juiz, ouvidas as partes no prazo de dois dias, que correrá em cartório, poderá corrigir o arbitramento do valor da responsabilidade, se Ihe parecer excessivo ou deficiente.\n\n§ 4 o O juiz autorizará somente a inscrição da hipoteca do imóvel ou imóveis necessários à garantia da responsabilidade.\n\n§ 5 o O valor da responsabilidade será liquidado definitivamente após a condenação, podendo ser requerido novo arbitramento se qualquer das partes não se conformar com o arbitramento anterior à sentença condenatória.\n\n§ 6 o Se o réu oferecer caução suficiente, em dinheiro ou em títulos de dívida pública, pelo valor de sua cotação em Bolsa, o juiz poderá deixar de mandar proceder à inscrição da hipoteca legal."},{"chave":"art-136","sequencia":148,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 136.","conteudo":"O arresto do imóvel poderá ser decretado de início, revogando-se, porém, se no prazo de 15 (quinze) dias não for promovido o processo de inscrição da hipoteca legal. (Redação dada pela Lei nº 11.435, de 2006)"},{"chave":"art-137","sequencia":149,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 137.","conteudo":"Se o responsável não possuir bens imóveis ou os possuir de valor insuficiente, poderão ser arrestados bens móveis suscetíveis de penhora, nos termos em que é facultada a hipoteca legal dos imóveis. (Redação dada pela Lei nº 11.435, de 2006).\n\n§ 1 o Se esses bens forem coisas fungíveis e facilmente deterioráveis, proceder-se-á na forma do § 5 o do art. 120 .\n\n§ 2 o Das rendas dos bens móveis poderão ser fornecidos recursos arbitrados pelo juiz, para a manutenção do indiciado e de sua família."},{"chave":"art-138","sequencia":150,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 138.","conteudo":"O processo de especialização da hipoteca e do arresto correrão em auto apartado. (Redação dada pela Lei nº 11.435, de 2006)."},{"chave":"art-139","sequencia":151,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 139.","conteudo":"O depósito e a administração dos bens arrestados ficarão sujeitos ao regime do processo civil. (Redação dada pela Lei nº 11.435, de 2006)."},{"chave":"art-140","sequencia":152,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 140.","conteudo":"As garantias do ressarcimento do dano alcançarão também as despesas processuais e as penas pecuniárias, tendo preferência sobre estas a reparação do dano ao ofendido."},{"chave":"art-141","sequencia":153,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 141.","conteudo":"O arresto será levantado ou cancelada a hipoteca, se, por sentença irrecorrível, o réu for absolvido ou julgada extinta a punibilidade. (Redação dada pela Lei nº 11.435, de 2006)."},{"chave":"art-142","sequencia":154,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 142.","conteudo":"Caberá ao Ministério Público promover as medidas estabelecidas nos arts. 134 e 137 , se houver interesse da Fazenda Pública, ou se o ofendido for pobre e o requerer."},{"chave":"art-143","sequencia":155,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 143.","conteudo":"Passando em julgado a sentença condenatória, serão os autos de hipoteca ou arresto remetidos ao juiz do cível (art. 63). (Redação dada pela Lei nº 11.435, de 2006)."},{"chave":"art-144","sequencia":156,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 144.","conteudo":"Os interessados ou, nos casos do art. 142 , o Ministério Público poderão requerer no juízo cível, contra o responsável civil, as medidas previstas nos arts. 134 , 136 e 137 ."},{"chave":"art-144-a","sequencia":157,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS"],"titulo":"CAPÍTULO VI — DAS MEDIDAS ASSECURATÓRIAS","rotulo":"Art. 144º-A","conteudo":"O juiz determinará a alienação antecipada para preservação do valor dos bens sempre que estiverem sujeitos a qualquer grau de deterioração ou depreciação, ou quando houver dificuldade para sua manutenção. (Incluído pela Lei nº 12.694, de 2012)\n\n§ 1 o O leilão far-se-á preferencialmente por meio eletrônico. (Incluído pela Lei nº 12.694, de 2012)\n\n§ 2 o Os bens deverão ser vendidos pelo valor fixado na avaliação judicial ou por valor maior. Não alcançado o valor estipulado pela administração judicial, será realizado novo leilão, em até 10 (dez) dias contados da realização do primeiro, podendo os bens ser alienados por valor não inferior a 80% (oitenta por cento) do estipulado na avaliação judicial. (Incluído pela Lei nº 12.694, de 2012)\n\n§ 3 o O produto da alienação ficará depositado em conta vinculada ao juízo até a decisão final do processo, procedendo-se à sua conversão em renda para a União, Estado ou Distrito Federal, no caso de condenação, ou, no caso de absolvição, à sua devolução ao acusado. (Incluído pela Lei nº 12.694, de 2012)\n\n§ 4 o Quando a indisponibilidade recair sobre dinheiro, inclusive moeda estrangeira, títulos, valores mobiliários ou cheques emitidos como ordem de pagamento, o juízo determinará a conversão do numerário apreendido em moeda nacional corrente e o depósito das correspondentes quantias em conta judicial. (Incluído pela Lei nº 12.694, de 2012)\n\n§ 5 o No caso da alienação de veículos, embarcações ou aeronaves, o juiz ordenará à autoridade de trânsito ou ao equivalente órgão de registro e controle a expedição de certificado de registro e licenciamento em favor do arrematante, ficando este livre do pagamento de multas, encargos e tributos anteriores, sem prejuízo de execução fiscal em relação ao antigo proprietário. (Incluído pela Lei nº 12.694, de 2012)\n\n§ 6 o O valor dos títulos da dívida pública, das ações das sociedades e dos títulos de crédito negociáveis em bolsa será o da cotação oficial do dia, provada por certidão ou publicação no órgão oficial. (Incluído pela Lei nº 12.694, de 2012)\n\n§ 7 o (VETADO). (Incluído pela Lei nº 12.694, de 2012)"},{"chave":"art-145","sequencia":158,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VII — DO INCIDENTE DE FALSIDADE"],"titulo":"CAPÍTULO VII — DO INCIDENTE DE FALSIDADE","rotulo":"Art. 145.","conteudo":"Argüida, por escrito, a falsidade de documento constante dos autos, o juiz observará o seguinte processo:\n\nI - mandará autuar em apartado a impugnação, e em seguida ouvirá a parte contrária, que, no prazo de 48 horas, oferecerá resposta;\n\nII - assinará o prazo de três dias, sucessivamente, a cada uma das partes, para prova de suas alegações;\n\nIII - conclusos os autos, poderá ordenar as diligências que entender necessárias;\n\nIV - se reconhecida a falsidade por decisão irrecorrível, mandará desentranhar o documento e remetê-lo, com os autos do processo incidente, ao Ministério Público."},{"chave":"art-146","sequencia":159,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VII — DO INCIDENTE DE FALSIDADE"],"titulo":"CAPÍTULO VII — DO INCIDENTE DE FALSIDADE","rotulo":"Art. 146.","conteudo":"A argüição de falsidade, feita por procurador, exige poderes especiais."},{"chave":"art-147","sequencia":160,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VII — DO INCIDENTE DE FALSIDADE"],"titulo":"CAPÍTULO VII — DO INCIDENTE DE FALSIDADE","rotulo":"Art. 147.","conteudo":"O juiz poderá, de ofício, proceder à verificação da falsidade."},{"chave":"art-148","sequencia":161,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VII — DO INCIDENTE DE FALSIDADE"],"titulo":"CAPÍTULO VII — DO INCIDENTE DE FALSIDADE","rotulo":"Art. 148.","conteudo":"Qualquer que seja a decisão, não fará coisa julgada em prejuízo de ulterior processo penal ou civil."},{"chave":"art-149","sequencia":162,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VIII — DA INSANIDADE MENTAL DO ACUSADO"],"titulo":"CAPÍTULO VIII — DA INSANIDADE MENTAL DO ACUSADO","rotulo":"Art. 149.","conteudo":"Quando houver dúvida sobre a integridade mental do acusado, o juiz ordenará, de ofício ou a requerimento do Ministério Público, do defensor, do curador, do ascendente, descendente, irmão ou cônjuge do acusado, seja este submetido a exame médico-legal.\n\n§ 1 o O exame poderá ser ordenado ainda na fase do inquérito, mediante representação da autoridade policial ao juiz competente.\n\n§ 2 o O juiz nomeará curador ao acusado, quando determinar o exame, ficando suspenso o processo, se já iniciada a ação penal, salvo quanto às diligências que possam ser prejudicadas pelo adiamento."},{"chave":"art-150","sequencia":163,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VIII — DA INSANIDADE MENTAL DO ACUSADO"],"titulo":"CAPÍTULO VIII — DA INSANIDADE MENTAL DO ACUSADO","rotulo":"Art. 150.","conteudo":"Para o efeito do exame, o acusado, se estiver preso, será internado em manicômio judiciário, onde houver, ou, se estiver solto, e o requererem os peritos, em estabelecimento adequado que o juiz designar.\n\n§ 1 o O exame não durará mais de quarenta e cinco dias, salvo se os peritos demonstrarem a necessidade de maior prazo.\n\n§ 2 o Se não houver prejuízo para a marcha do processo, o juiz poderá autorizar sejam os autos entregues aos peritos, para facilitar o exame."},{"chave":"art-151","sequencia":164,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VIII — DA INSANIDADE MENTAL DO ACUSADO"],"titulo":"CAPÍTULO VIII — DA INSANIDADE MENTAL DO ACUSADO","rotulo":"Art. 151.","conteudo":"Se os peritos concluírem que o acusado era, ao tempo da infração, irresponsável nos termos do art. 22 do Código Penal , o processo prosseguirá, com a presença do curador."},{"chave":"art-152","sequencia":165,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VIII — DA INSANIDADE MENTAL DO ACUSADO"],"titulo":"CAPÍTULO VIII — DA INSANIDADE MENTAL DO ACUSADO","rotulo":"Art. 152.","conteudo":"Se se verificar que a doença mental sobreveio à infração o processo continuará suspenso até que o acusado se restabeleça, observado o § 2 o do art. 149 .\n\n§ 1 o O juiz poderá, nesse caso, ordenar a internação do acusado em manicômio judiciário ou em outro estabelecimento adequado.\n\n§ 2 o O processo retomará o seu curso, desde que se restabeleça o acusado, ficando-lhe assegurada a faculdade de reinquirir as testemunhas que houverem prestado depoimento sem a sua presença."},{"chave":"art-153","sequencia":166,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VIII — DA INSANIDADE MENTAL DO ACUSADO"],"titulo":"CAPÍTULO VIII — DA INSANIDADE MENTAL DO ACUSADO","rotulo":"Art. 153.","conteudo":"O incidente da insanidade mental processar-se-á em auto apartado, que só depois da apresentação do laudo, será apenso ao processo principal."},{"chave":"art-154","sequencia":167,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VI — DAS QUESTÕES E PROCESSOS INCIDENTES","CAPÍTULO VIII — DA INSANIDADE MENTAL DO ACUSADO"],"titulo":"CAPÍTULO VIII — DA INSANIDADE MENTAL DO ACUSADO","rotulo":"Art. 154.","conteudo":"Se a insanidade mental sobrevier no curso da execução da pena, observar-se-á o disposto no art. 682 ."},{"chave":"art-155","sequencia":168,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 155.","conteudo":"O juiz formará sua convicção pela livre apreciação da prova produzida em contraditório judicial, não podendo fundamentar sua decisão exclusivamente nos elementos informativos colhidos na investigação, ressalvadas as provas cautelares, não repetíveis e antecipadas. (Redação dada pela Lei nº 11.690, de 2008)\n\nParágrafo único. Somente quanto ao estado das pessoas serão observadas as restrições estabelecidas na lei civil. (Incluído pela Lei nº 11.690, de 2008)"},{"chave":"art-156","sequencia":169,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 156.","conteudo":"A prova da alegação incumbirá a quem a fizer, sendo, porém, facultado ao juiz de ofício: (Redação dada pela Lei nº 11.690, de 2008)\n\nI – ordenar, mesmo antes de iniciada a ação penal, a produção antecipada de provas consideradas urgentes e relevantes, observando a necessidade, adequação e proporcionalidade da medida; (Incluído pela Lei nº 11.690, de 2008)\n\nII – determinar, no curso da instrução, ou antes de proferir sentença, a realização de diligências para dirimir dúvida sobre ponto relevante. (Incluído pela Lei nº 11.690, de 2008)"},{"chave":"art-157","sequencia":170,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 157.","conteudo":"São inadmissíveis, devendo ser desentranhadas do processo, as provas ilícitas, assim entendidas as obtidas em violação a normas constitucionais ou legais. (Redação dada pela Lei nº 11.690, de 2008)\n\n§ 1 o São também inadmissíveis as provas derivadas das ilícitas, salvo quando não evidenciado o nexo de causalidade entre umas e outras, ou quando as derivadas puderem ser obtidas por uma fonte independente das primeiras. (Incluído pela Lei nº 11.690, de 2008)\n\n§ 2 o Considera-se fonte independente aquela que por si só, seguindo os trâmites típicos e de praxe, próprios da investigação ou instrução criminal, seria capaz de conduzir ao fato objeto da prova. (Incluído pela Lei nº 11.690, de 2008)\n\n§ 3 o Preclusa a decisão de desentranhamento da prova declarada inadmissível, esta será inutilizada por decisão judicial, facultado às partes acompanhar o incidente. (Incluído pela Lei nº 11.690, de 2008)\n\n§ 4 o (VETADO) (Incluído pela Lei nº 11.690, de 2008)\n\n§ 5º O juiz que conhecer do conteúdo da prova declarada inadmissível não poderá proferir a sentença ou acórdão. (Incluído pela Lei nº 13.964, de 2019) (Vide ADI 6.298) (Vide ADI 6.299) (Vide ADI 6.300 ) (Vide ADI 6.305)"},{"chave":"art-158","sequencia":171,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 158.","conteudo":"Quando a infração deixar vestígios, será indispensável o exame de corpo de delito, direto ou indireto, não podendo supri-lo a confissão do acusado.\n\nParágrafo único. Dar-se-á prioridade à realização do exame de corpo de delito quando se tratar de crime que envolva: (Incluído dada pela Lei nº 13.721, de 2018)\n\nI - violência doméstica e familiar contra mulher; (Incluído dada pela Lei nº 13.721, de 2018)\n\nII - violência contra criança, adolescente, idoso ou pessoa com deficiência. (Incluído dada pela Lei nº 13.721, de 2018)"},{"chave":"art-158-a","sequencia":172,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 158º-A","conteudo":"Considera-se cadeia de custódia o conjunto de todos os procedimentos utilizados para manter e documentar a história cronológica do vestígio coletado em locais ou em vítimas de crimes, para rastrear sua posse e manuseio a partir de seu reconhecimento até o descarte. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 1º O início da cadeia de custódia dá-se com a preservação do local de crime ou com procedimentos policiais ou periciais nos quais seja detectada a existência de vestígio. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 2º O agente público que reconhecer um elemento como de potencial interesse para a produção da prova pericial fica responsável por sua preservação. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 3º Vestígio é todo objeto ou material bruto, visível ou latente, constatado ou recolhido, que se relaciona à infração penal. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-158-b","sequencia":173,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 158º-B","conteudo":"A cadeia de custódia compreende o rastreamento do vestígio nas seguintes etapas: (Incluído pela Lei nº 13.964, de 2019)\n\nI - reconhecimento: ato de distinguir um elemento como de potencial interesse para a produção da prova pericial; (Incluído pela Lei nº 13.964, de 2019)\n\nII - isolamento: ato de evitar que se altere o estado das coisas, devendo isolar e preservar o ambiente imediato, mediato e relacionado aos vestígios e local de crime; (Incluído pela Lei nº 13.964, de 2019)\n\nIII - fixação: descrição detalhada do vestígio conforme se encontra no local de crime ou no corpo de delito, e a sua posição na área de exames, podendo ser ilustrada por fotografias, filmagens ou croqui, sendo indispensável a sua descrição no laudo pericial produzido pelo perito responsável pelo atendimento; (Incluído pela Lei nº 13.964, de 2019)\n\nIV - coleta: ato de recolher o vestígio que será submetido à análise pericial, respeitando suas características e natureza; (Incluído pela Lei nº 13.964, de 2019)\n\nV - acondicionamento: procedimento por meio do qual cada vestígio coletado é embalado de forma individualizada, de acordo com suas características físicas, químicas e biológicas, para posterior análise, com anotação da data, hora e nome de quem realizou a coleta e o acondicionamento; (Incluído pela Lei nº 13.964, de 2019)\n\nVI - transporte: ato de transferir o vestígio de um local para o outro, utilizando as condições adequadas (embalagens, veículos, temperatura, entre outras), de modo a garantir a manutenção de suas características originais, bem como o controle de sua posse; (Incluído pela Lei nº 13.964, de 2019)\n\nVII - recebimento: ato formal de transferência da posse do vestígio, que deve ser documentado com, no mínimo, informações referentes ao número de procedimento e unidade de polícia judiciária relacionada, local de origem, nome de quem transportou o vestígio, código de rastreamento, natureza do exame, tipo do vestígio, protocolo, assinatura e identificação de quem o recebeu; (Incluído pela Lei nº 13.964, de 2019)\n\nVIII - processamento: exame pericial em si, manipulação do vestígio de acordo com a metodologia adequada às suas características biológicas, físicas e químicas, a fim de se obter o resultado desejado, que deverá ser formalizado em laudo produzido por perito; (Incluído pela Lei nº 13.964, de 2019)\n\nIX - armazenamento: procedimento referente à guarda, em condições adequadas, do material a ser processado, guardado para realização de contraperícia, descartado ou transportado, com vinculação ao número do laudo correspondente; (Incluído pela Lei nº 13.964, de 2019)\n\nX - descarte: procedimento referente à liberação do vestígio, respeitando a legislação vigente e, quando pertinente, mediante autorização judicial. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-158-c","sequencia":174,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 158º-C","conteudo":"A coleta dos vestígios deverá ser realizada preferencialmente por perito oficial, que dará o encaminhamento necessário para a central de custódia, mesmo quando for necessária a realização de exames complementares. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 1º Todos vestígios coletados no decurso do inquérito ou processo devem ser tratados como descrito nesta Lei, ficando órgão central de perícia oficial de natureza criminal responsável por detalhar a forma do seu cumprimento. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 2º É proibida a entrada em locais isolados bem como a remoção de quaisquer vestígios de locais de crime antes da liberação por parte do perito responsável, sendo tipificada como fraude processual a sua realização. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-158-d","sequencia":175,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 158º-D","conteudo":"O recipiente para acondicionamento do vestígio será determinado pela natureza do material. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 1º Todos os recipientes deverão ser selados com lacres, com numeração individualizada, de forma a garantir a inviolabilidade e a idoneidade do vestígio durante o transporte. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 2º O recipiente deverá individualizar o vestígio, preservar suas características, impedir contaminação e vazamento, ter grau de resistência adequado e espaço para registro de informações sobre seu conteúdo. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 3º O recipiente só poderá ser aberto pelo perito que vai proceder à análise e, motivadamente, por pessoa autorizada. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 4º Após cada rompimento de lacre, deve se fazer constar na ficha de acompanhamento de vestígio o nome e a matrícula do responsável, a data, o local, a finalidade, bem como as informações referentes ao novo lacre utilizado. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 5º O lacre rompido deverá ser acondicionado no interior do novo recipiente. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-158-e","sequencia":176,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 158º-E","conteudo":"Todos os Institutos de Criminalística deverão ter uma central de custódia destinada à guarda e controle dos vestígios, e sua gestão deve ser vinculada diretamente ao órgão central de perícia oficial de natureza criminal. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 1º Toda central de custódia deve possuir os serviços de protocolo, com local para conferência, recepção, devolução de materiais e documentos, possibilitando a seleção, a classificação e a distribuição de materiais, devendo ser um espaço seguro e apresentar condições ambientais que não interfiram nas características do vestígio. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 2º Na central de custódia, a entrada e a saída de vestígio deverão ser protocoladas, consignando-se informações sobre a ocorrência no inquérito que a eles se relacionam. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 3º Todas as pessoas que tiverem acesso ao vestígio armazenado deverão ser identificadas e deverão ser registradas a data e a hora do acesso. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 4º Por ocasião da tramitação do vestígio armazenado, todas as ações deverão ser registradas, consignando-se a identificação do responsável pela tramitação, a destinação, a data e horário da ação. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-158-f","sequencia":177,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 158º-F","conteudo":"Após a realização da perícia, o material deverá ser devolvido à central de custódia, devendo nela permanecer. (Incluído pela Lei nº 13.964, de 2019)\n\nParágrafo único. Caso a central de custódia não possua espaço ou condições de armazenar determinado material, deverá a autoridade policial ou judiciária determinar as condições de depósito do referido material em local diverso, mediante requerimento do diretor do órgão central de perícia oficial de natureza criminal. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-159","sequencia":178,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 159.","conteudo":"O exame de corpo de delito e outras perícias serão realizados por perito oficial, portador de diploma de curso superior. (Redação dada pela Lei nº 11.690, de 2008)\n\n§ 1 o Na falta de perito oficial, o exame será realizado por 2 (duas) pessoas idôneas, portadoras de diploma de curso superior preferencialmente na área específica, dentre as que tiverem habilitação técnica relacionada com a natureza do exame. (Redação dada pela Lei nº 11.690, de 2008)\n\n§ 2 o Os peritos não oficiais prestarão o compromisso de bem e fielmente desempenhar o encargo. (Redação dada pela Lei nº 11.690, de 2008)\n\n§ 3 o Serão facultadas ao Ministério Público, ao assistente de acusação, ao ofendido, ao querelante e ao acusado a formulação de quesitos e indicação de assistente técnico. (Incluído pela Lei nº 11.690, de 2008)\n\n§ 4 o O assistente técnico atuará a partir de sua admissão pelo juiz e após a conclusão dos exames e elaboração do laudo pelos peritos oficiais, sendo as partes intimadas desta decisão. (Incluído pela Lei nº 11.690, de 2008)\n\n§ 5 o Durante o curso do processo judicial, é permitido às partes, quanto à perícia: (Incluído pela Lei nº 11.690, de 2008)\n\nI – requerer a oitiva dos peritos para esclarecerem a prova ou para responderem a quesitos, desde que o mandado de intimação e os quesitos ou questões a serem esclarecidas sejam encaminhados com antecedência mínima de 10 (dez) dias, podendo apresentar as respostas em laudo complementar; (Incluído pela Lei nº 11.690, de 2008)\n\nII – indicar assistentes técnicos que poderão apresentar pareceres em prazo a ser fixado pelo juiz ou ser inquiridos em audiência. (Incluído pela Lei nº 11.690, de 2008)\n\n§ 6 o Havendo requerimento das partes, o material probatório que serviu de base à perícia será disponibilizado no ambiente do órgão oficial, que manterá sempre sua guarda, e na presença de perito oficial, para exame pelos assistentes, salvo se for impossível a sua conservação. (Incluído pela Lei nº 11.690, de 2008)\n\n§ 7 o Tratando-se de perícia complexa que abranja mais de uma área de conhecimento especializado, poder-se-á designar a atuação de mais de um perito oficial, e a parte indicar mais de um assistente técnico. (Incluído pela Lei nº 11.690, de 2008)"},{"chave":"art-160","sequencia":179,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 160.","conteudo":"Os peritos elaborarão o laudo pericial, onde descreverão minuciosamente o que examinarem, e responderão aos quesitos formulados. (Redação dada pela Lei nº 8.862, de 28.3.1994)\n\nParágrafo único. O laudo pericial será elaborado no prazo máximo de 10 dias, podendo este prazo ser prorrogado, em casos excepcionais, a requerimento dos peritos. (Redação dada pela Lei nº 8.862, de 28.3.1994)"},{"chave":"art-161","sequencia":180,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 161.","conteudo":"O exame de corpo de delito poderá ser feito em qualquer dia e a qualquer hora."},{"chave":"art-162","sequencia":181,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 162.","conteudo":"A autópsia será feita pelo menos seis horas depois do óbito, salvo se os peritos, pela evidência dos sinais de morte, julgarem que possa ser feita antes daquele prazo, o que declararão no auto.\n\nParágrafo único. Nos casos de morte violenta, bastará o simples exame externo do cadáver, quando não houver infração penal que apurar, ou quando as lesões externas permitirem precisar a causa da morte e não houver necessidade de exame interno para a verificação de alguma circunstância relevante."},{"chave":"art-163","sequencia":182,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 163.","conteudo":"Em caso de exumação para exame cadavérico, a autoridade providenciará para que, em dia e hora previamente marcados, se realize a diligência, da qual se lavrará auto circunstanciado.\n\nParágrafo único. O administrador de cemitério público ou particular indicará o lugar da sepultura, sob pena de desobediência. No caso de recusa ou de falta de quem indique a sepultura, ou de encontrar-se o cadáver em lugar não destinado a inumações, a autoridade procederá às pesquisas necessárias, o que tudo constará do auto."},{"chave":"art-164","sequencia":183,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 164.","conteudo":"Os cadáveres serão sempre fotografados na posição em que forem encontrados, bem como, na medida do possível, todas as lesões externas e vestígios deixados no local do crime. (Redação dada pela Lei nº 8.862, de 28.3.1994)"},{"chave":"art-165","sequencia":184,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 165.","conteudo":"Para representar as lesões encontradas no cadáver, os peritos, quando possível, juntarão ao laudo do exame provas fotográficas, esquemas ou desenhos, devidamente rubricados."},{"chave":"art-166","sequencia":185,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 166.","conteudo":"Havendo dúvida sobre a identidade do cadáver exumado, proceder-se-á ao reconhecimento pelo Instituto de Identificação e Estatística ou repartição congênere ou pela inquirição de testemunhas, lavrando-se auto de reconhecimento e de identidade, no qual se descreverá o cadáver, com todos os sinais e indicações.\n\nParágrafo único. Em qualquer caso, serão arrecadados e autenticados todos os objetos encontrados, que possam ser úteis para a identificação do cadáver."},{"chave":"art-167","sequencia":186,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 167.","conteudo":"Não sendo possível o exame de corpo de delito, por haverem desaparecido os vestígios, a prova testemunhal poderá suprir-lhe a falta."},{"chave":"art-168","sequencia":187,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 168.","conteudo":"Em caso de lesões corporais, se o primeiro exame pericial tiver sido incompleto, proceder-se-á a exame complementar por determinação da autoridade policial ou judiciária, de ofício, ou a requerimento do Ministério Público, do ofendido ou do acusado, ou de seu defensor.\n\n§ 1 o No exame complementar, os peritos terão presente o auto de corpo de delito, a fim de suprir-lhe a deficiência ou retificá-lo.\n\n§ 2 o Se o exame tiver por fim precisar a classificação do delito no art. 129, § 1 o , I, do Código Penal , deverá ser feito logo que decorra o prazo de 30 dias, contado da data do crime.\n\n§ 3 o A falta de exame complementar poderá ser suprida pela prova testemunhal."},{"chave":"art-169","sequencia":188,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 169.","conteudo":"Para o efeito de exame do local onde houver sido praticada a infração, a autoridade providenciará imediatamente para que não se altere o estado das coisas até a chegada dos peritos, que poderão instruir seus laudos com fotografias, desenhos ou esquemas elucidativos. (Vide Lei nº 5.970, de 1973)\n\nParágrafo único. Os peritos registrarão, no laudo, as alterações do estado das coisas e discutirão, no relatório, as conseqüências dessas alterações na dinâmica dos fatos. (Incluído pela Lei nº 8.862, de 28.3.1994)"},{"chave":"art-170","sequencia":189,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 170.","conteudo":"Nas perícias de laboratório, os peritos guardarão material suficiente para a eventualidade de nova perícia. Sempre que conveniente, os laudos serão ilustrados com provas fotográficas, ou microfotográficas, desenhos ou esquemas."},{"chave":"art-171","sequencia":190,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 171.","conteudo":"Nos crimes cometidos com destruição ou rompimento de obstáculo a subtração da coisa, ou por meio de escalada, os peritos, além de descrever os vestígios, indicarão com que instrumentos, por que meios e em que época presumem ter sido o fato praticado."},{"chave":"art-172","sequencia":191,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 172.","conteudo":"Proceder-se-á, quando necessário, à avaliação de coisas destruídas, deterioradas ou que constituam produto do crime.\n\nParágrafo único. Se impossível a avaliação direta, os peritos procederão à avaliação por meio dos elementos existentes nos autos e dos que resultarem de diligências."},{"chave":"art-173","sequencia":192,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 173.","conteudo":"No caso de incêndio, os peritos verificarão a causa e o lugar em que houver começado, o perigo que dele tiver resultado para a vida ou para o patrimônio alheio, a extensão do dano e o seu valor e as demais circunstâncias que interessarem à elucidação do fato."},{"chave":"art-174","sequencia":193,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 174.","conteudo":"No exame para o reconhecimento de escritos, por comparação de letra, observar-se-á o seguinte:\n\nI - a pessoa a quem se atribua ou se possa atribuir o escrito será intimada para o ato, se for encontrada;\n\nII - para a comparação, poderão servir quaisquer documentos que a dita pessoa reconhecer ou já tiverem sido judicialmente reconhecidos como de seu punho, ou sobre cuja autenticidade não houver dúvida;\n\nIII - a autoridade, quando necessário, requisitará, para o exame, os documentos que existirem em arquivos ou estabelecimentos públicos, ou nestes realizará a diligência, se daí não puderem ser retirados;\n\nIV - quando não houver escritos para a comparação ou forem insuficientes os exibidos, a autoridade mandará que a pessoa escreva o que Ihe for ditado. Se estiver ausente a pessoa, mas em lugar certo, esta última diligência poderá ser feita por precatória, em que se consignarão as palavras que a pessoa será intimada a escrever."},{"chave":"art-175","sequencia":194,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 175.","conteudo":"Serão sujeitos a exame os instrumentos empregados para a prática da infração, a fim de se Ihes verificar a natureza e a eficiência."},{"chave":"art-176","sequencia":195,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 176.","conteudo":"A autoridade e as partes poderão formular quesitos até o ato da diligência."},{"chave":"art-177","sequencia":196,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 177.","conteudo":"No exame por precatória, a nomeação dos peritos far-se-á no juízo deprecado. Havendo, porém, no caso de ação privada, acordo das partes, essa nomeação poderá ser feita pelo juiz deprecante.\n\nParágrafo único. Os quesitos do juiz e das partes serão transcritos na precatória."},{"chave":"art-178","sequencia":197,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 178.","conteudo":"No caso do art. 159 , o exame será requisitado pela autoridade ao diretor da repartição, juntando-se ao processo o laudo assinado pelos peritos."},{"chave":"art-179","sequencia":198,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 179.","conteudo":"No caso do § 1 o do art. 159 , o escrivão lavrará o auto respectivo, que será assinado pelos peritos e, se presente ao exame, também pela autoridade.\n\nParágrafo único. No caso do art. 160 , parágrafo único, o laudo, que poderá ser datilografado, será subscrito e rubricado em suas folhas por todos os peritos."},{"chave":"art-180","sequencia":199,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 180.","conteudo":"Se houver divergência entre os peritos, serão consignadas no auto do exame as declarações e respostas de um e de outro, ou cada um redigirá separadamente o seu laudo, e a autoridade nomeará um terceiro; se este divergir de ambos, a autoridade poderá mandar proceder a novo exame por outros peritos."},{"chave":"art-181","sequencia":200,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 181.","conteudo":"No caso de inobservância de formalidades, ou no caso de omissões, obscuridades ou contradições, a autoridade judiciária mandará suprir a formalidade, complementar ou esclarecer o laudo. (Redação dada pela Lei nº 8.862, de 28.3.1994)\n\nParágrafo único. A autoridade poderá também ordenar que se proceda a novo exame, por outros peritos, se julgar conveniente."},{"chave":"art-182","sequencia":201,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 182.","conteudo":"O juiz não ficará adstrito ao laudo, podendo aceitá-lo ou rejeitá-lo, no todo ou em parte."},{"chave":"art-183","sequencia":202,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 183.","conteudo":"Nos crimes em que não couber ação pública, observar-se-á o disposto no art. 19 ."},{"chave":"art-184","sequencia":203,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL"],"titulo":"CAPÍTULO II — DO EXAME DE CORPO DE DELITO, DA CADEIA DE CUSTÓDIA E DAS PERÍCIAS EM GERAL","rotulo":"Art. 184.","conteudo":"Salvo o caso de exame de corpo de delito, o juiz ou a autoridade policial negará a perícia requerida pelas partes, quando não for necessária ao esclarecimento da verdade."},{"chave":"art-185","sequencia":204,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO"],"titulo":"CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO","rotulo":"Art. 185.","conteudo":"O acusado que comparecer perante a autoridade judiciária, no curso do processo penal, será qualificado e interrogado na presença de seu defensor, constituído ou nomeado. (Redação dada pela Lei nº 10.792, de 1º.12.2003)\n\n§ 1 o O interrogatório do réu preso será realizado, em sala própria, no estabelecimento em que estiver recolhido, desde que estejam garantidas a segurança do juiz, do membro do Ministério Público e dos auxiliares bem como a presença do defensor e a publicidade do ato. (Redação dada pela Lei nº 11.900, de 2009)\n\n§ 2 o Excepcionalmente, o juiz, por decisão fundamentada, de ofício ou a requerimento das partes, poderá realizar o interrogatório do réu preso por sistema de videoconferência ou outro recurso tecnológico de transmissão de sons e imagens em tempo real, desde que a medida seja necessária para atender a uma das seguintes finalidades: (Redação dada pela Lei nº 11.900, de 2009)\n\nI - prevenir risco à segurança pública, quando exista fundada suspeita de que o preso integre organização criminosa ou de que, por outra razão, possa fugir durante o deslocamento; (Incluído pela Lei nº 11.900, de 2009)\n\nII - viabilizar a participação do réu no referido ato processual, quando haja relevante dificuldade para seu comparecimento em juízo, por enfermidade ou outra circunstância pessoal; (Incluído pela Lei nº 11.900, de 2009)\n\nIII - impedir a influência do réu no ânimo de testemunha ou da vítima, desde que não seja possível colher o depoimento destas por videoconferência, nos termos do art. 217 deste Código ; (Incluído pela Lei nº 11.900, de 2009)\n\nIV - responder à gravíssima questão de ordem pública. (Incluído pela Lei nº 11.900, de 2009)\n\n§ 3 o Da decisão que determinar a realização de interrogatório por videoconferência, as partes serão intimadas com 10 (dez) dias de antecedência. (Incluído pela Lei nº 11.900, de 2009)\n\n§ 4 o Antes do interrogatório por videoconferência, o preso poderá acompanhar, pelo mesmo sistema tecnológico, a realização de todos os atos da audiência única de instrução e julgamento de que tratam os arts. 400 , 411 e 531 deste Código . (Incluído pela Lei nº 11.900, de 2009)\n\n§ 5 o Em qualquer modalidade de interrogatório, o juiz garantirá ao réu o direito de entrevista prévia e reservada com o seu defensor; se realizado por videoconferência, fica também garantido o acesso a canais telefônicos reservados para comunicação entre o defensor que esteja no presídio e o advogado presente na sala de audiência do Fórum, e entre este e o preso. (Incluído pela Lei nº 11.900, de 2009)\n\n§ 6 o A sala reservada no estabelecimento prisional para a realização de atos processuais por sistema de videoconferência será fiscalizada pelos corregedores e pelo juiz de cada causa, como também pelo Ministério Público e pela Ordem dos Advogados do Brasil. (Incluído pela Lei nº 11.900, de 2009)\n\n§ 7 o Será requisitada a apresentação do réu preso em juízo nas hipóteses em que o interrogatório não se realizar na forma prevista nos §§ 1 o e 2 o deste artigo. (Incluído pela Lei nº 11.900, de 2009)\n\n§ 8 o Aplica-se o disposto nos §§ 2 o , 3 o , 4 o e 5 o deste artigo, no que couber, à realização de outros atos processuais que dependam da participação de pessoa que esteja presa, como acareação, reconhecimento de pessoas e coisas, e inquirição de testemunha ou tomada de declarações do ofendido. (Incluído pela Lei nº 11.900, de 2009)\n\n§ 9 o Na hipótese do § 8 o deste artigo, fica garantido o acompanhamento do ato processual pelo acusado e seu defensor. (Incluído pela Lei nº 11.900, de 2009)\n\n§ 10. Do interrogatório deverá constar a informação sobre a existência de filhos, respectivas idades e se possuem alguma deficiência e o nome e o contato de eventual responsável pelos cuidados dos filhos, indicado pela pessoa presa (Incluído pela Lei nº 13.257, de 2016)"},{"chave":"art-186","sequencia":205,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO"],"titulo":"CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO","rotulo":"Art. 186.","conteudo":"Depois de devidamente qualificado e cientificado do inteiro teor da acusação, o acusado será informado pelo juiz, antes de iniciar o interrogatório, do seu direito de permanecer calado e de não responder perguntas que lhe forem formuladas. (Redação dada pela Lei nº 10.792, de 1º.12.2003)\n\nParágrafo único. O silêncio, que não importará em confissão, não poderá ser interpretado em prejuízo da defesa. (Incluído pela Lei nº 10.792, de 1º.12.2003)"},{"chave":"art-187","sequencia":206,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO"],"titulo":"CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO","rotulo":"Art. 187.","conteudo":"O interrogatório será constituído de duas partes: sobre a pessoa do acusado e sobre os fatos. (Redação dada pela Lei nº 10.792, de 1º.12.2003)\n\n§ 1 o Na primeira parte o interrogando será perguntado sobre a residência, meios de vida ou profissão, oportunidades sociais, lugar onde exerce a sua atividade, vida pregressa, notadamente se foi preso ou processado alguma vez e, em caso afirmativo, qual o juízo do processo, se houve suspensão condicional ou condenação, qual a pena imposta, se a cumpriu e outros dados familiares e sociais. (Incluído pela Lei nº 10.792, de 1º.12.2003)\n\n§ 2 o Na segunda parte será perguntado sobre: (Incluído pela Lei nº 10.792, de 1º.12.2003)\n\nI - ser verdadeira a acusação que lhe é feita; (Incluído pela Lei nº 10.792, de 1º.12.2003)\n\nII - não sendo verdadeira a acusação, se tem algum motivo particular a que atribuí-la, se conhece a pessoa ou pessoas a quem deva ser imputada a prática do crime, e quais sejam, e se com elas esteve antes da prática da infração ou depois dela; (Incluído pela Lei nº 10.792, de 1º.12.2003)\n\nIII - onde estava ao tempo em que foi cometida a infração e se teve notícia desta; (Incluído pela Lei nº 10.792, de 1º.12.2003)\n\nIV - as provas já apuradas; (Incluído pela Lei nº 10.792, de 1º.12.2003)\n\nV - se conhece as vítimas e testemunhas já inquiridas ou por inquirir, e desde quando, e se tem o que alegar contra elas; (Incluído pela Lei nº 10.792, de 1º.12.2003)\n\nVI - se conhece o instrumento com que foi praticada a infração, ou qualquer objeto que com esta se relacione e tenha sido apreendido; (Incluído pela Lei nº 10.792, de 1º.12.2003)\n\nVII - todos os demais fatos e pormenores que conduzam à elucidação dos antecedentes e circunstâncias da infração; (Incluído pela Lei nº 10.792, de 1º.12.2003)\n\nVIII - se tem algo mais a alegar em sua defesa. (Incluído pela Lei nº 10.792, de 1º.12.2003)"},{"chave":"art-188","sequencia":207,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO"],"titulo":"CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO","rotulo":"Art. 188.","conteudo":"Após proceder ao interrogatório, o juiz indagará das partes se restou algum fato para ser esclarecido, formulando as perguntas correspondentes se o entender pertinente e relevante. (Redação dada pela Lei nº 10.792, de 1º.12.2003)"},{"chave":"art-189","sequencia":208,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO"],"titulo":"CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO","rotulo":"Art. 189.","conteudo":"Se o interrogando negar a acusação, no todo ou em parte, poderá prestar esclarecimentos e indicar provas. (Redação dada pela Lei nº 10.792, de 1º.12.2003)"},{"chave":"art-190","sequencia":209,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO"],"titulo":"CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO","rotulo":"Art. 190.","conteudo":"Se confessar a autoria, será perguntado sobre os motivos e circunstâncias do fato e se outras pessoas concorreram para a infração, e quais sejam. (Redação dada pela Lei nº 10.792, de 1º.12.2003)"},{"chave":"art-191","sequencia":210,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO"],"titulo":"CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO","rotulo":"Art. 191.","conteudo":"Havendo mais de um acusado, serão interrogados separadamente. (Redação dada pela Lei nº 10.792, de 1º.12.2003)"},{"chave":"art-192","sequencia":211,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO"],"titulo":"CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO","rotulo":"Art. 192.","conteudo":"O interrogatório do mudo, do surdo ou do surdo-mudo será feito pela forma seguinte: (Redação dada pela Lei nº 10.792, de 1º.12.2003)\n\nI - ao surdo serão apresentadas por escrito as perguntas, que ele responderá oralmente; (Redação dada pela Lei nº 10.792, de 1º.12.2003)\n\nII - ao mudo as perguntas serão feitas oralmente, respondendo-as por escrito; (Redação dada pela Lei nº 10.792, de 1º.12.2003)\n\nIII - ao surdo-mudo as perguntas serão formuladas por escrito e do mesmo modo dará as respostas. (Redação dada pela Lei nº 10.792, de 1º.12.2003)\n\nParágrafo único. Caso o interrogando não saiba ler ou escrever, intervirá no ato, como intérprete e sob compromisso, pessoa habilitada a entendê-lo. (Redação dada pela Lei nº 10.792, de 1º.12.2003)"},{"chave":"art-193","sequencia":212,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO"],"titulo":"CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO","rotulo":"Art. 193.","conteudo":"Quando o interrogando não falar a língua nacional, o interrogatório será feito por meio de intérprete. (Redação dada pela Lei nº 10.792, de 1º.12.2003)"},{"chave":"art-195","sequencia":213,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO"],"titulo":"CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO","rotulo":"Art. 195.","conteudo":"Se o interrogado não souber escrever, não puder ou não quiser assinar, tal fato será consignado no termo. (Redação dada pela Lei nº 10.792, de 1º.12.2003)"},{"chave":"art-196","sequencia":214,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO"],"titulo":"CAPÍTULO III — DO INTERROGATÓRIO DO ACUSADO","rotulo":"Art. 196.","conteudo":"A todo tempo o juiz poderá proceder a novo interrogatório de ofício ou a pedido fundamentado de qualquer das partes. (Redação dada pela Lei nº 10.792, de 1º.12.2003)"},{"chave":"art-197","sequencia":215,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO IV — DA CONFISSÃO"],"titulo":"CAPÍTULO IV — DA CONFISSÃO","rotulo":"Art. 197.","conteudo":"O valor da confissão se aferirá pelos critérios adotados para os outros elementos de prova, e para a sua apreciação o juiz deverá confrontá-la com as demais provas do processo, verificando se entre ela e estas existe compatibilidade ou concordância."},{"chave":"art-198","sequencia":216,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO IV — DA CONFISSÃO"],"titulo":"CAPÍTULO IV — DA CONFISSÃO","rotulo":"Art. 198.","conteudo":"O silêncio do acusado não importará confissão, mas poderá constituir elemento para a formação do convencimento do juiz."},{"chave":"art-199","sequencia":217,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO IV — DA CONFISSÃO"],"titulo":"CAPÍTULO IV — DA CONFISSÃO","rotulo":"Art. 199.","conteudo":"A confissão, quando feita fora do interrogatório, será tomada por termo nos autos, observado o disposto no art. 195 ."},{"chave":"art-200","sequencia":218,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO IV — DA CONFISSÃO"],"titulo":"CAPÍTULO IV — DA CONFISSÃO","rotulo":"Art. 200.","conteudo":"A confissão será divisível e retratável, sem prejuízo do livre convencimento do juiz, fundado no exame das provas em conjunto."},{"chave":"art-201","sequencia":219,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO V — DO OFENDIDO"],"titulo":"CAPÍTULO V — DO OFENDIDO","rotulo":"Art. 201.","conteudo":"Sempre que possível, o ofendido será qualificado e perguntado sobre as circunstâncias da infração, quem seja ou presuma ser o seu autor, as provas que possa indicar, tomando-se por termo as suas declarações. (Redação dada pela Lei nº 11.690, de 2008)\n\n§ 1 o Se, intimado para esse fim, deixar de comparecer sem motivo justo, o ofendido poderá ser conduzido à presença da autoridade. (Incluído pela Lei nº 11.690, de 2008)\n\n§ 2 o O ofendido será comunicado dos atos processuais relativos ao ingresso e à saída do acusado da prisão, à designação de data para audiência e à sentença e respectivos acórdãos que a mantenham ou modifiquem. (Incluído pela Lei nº 11.690, de 2008)\n\n§ 3 o As comunicações ao ofendido deverão ser feitas no endereço por ele indicado, admitindo-se, por opção do ofendido, o uso de meio eletrônico. (Incluído pela Lei nº 11.690, de 2008)\n\n§ 4 o Antes do início da audiência e durante a sua realização, será reservado espaço separado para o ofendido. (Incluído pela Lei nº 11.690, de 2008)\n\n§ 5 o Se o juiz entender necessário, poderá encaminhar o ofendido para atendimento multidisciplinar, especialmente nas áreas psicossocial, de assistência jurídica e de saúde, a expensas do ofensor ou do Estado. (Incluído pela Lei nº 11.690, de 2008)\n\n§ 6 o O juiz tomará as providências necessárias à preservação da intimidade, vida privada, honra e imagem do ofendido, podendo, inclusive, determinar o segredo de justiça em relação aos dados, depoimentos e outras informações constantes dos autos a seu respeito para evitar sua exposição aos meios de comunicação. (Incluído pela Lei nº 11.690, de 2008)"},{"chave":"art-202","sequencia":220,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 202.","conteudo":"Toda pessoa poderá ser testemunha."},{"chave":"art-203","sequencia":221,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 203.","conteudo":"A testemunha fará, sob palavra de honra, a promessa de dizer a verdade do que souber e Ihe for perguntado, devendo declarar seu nome, sua idade, seu estado e sua residência, sua profissão, lugar onde exerce sua atividade, se é parente, e em que grau, de alguma das partes, ou quais suas relações com qualquer delas, e relatar o que souber, explicando sempre as razões de sua ciência ou as circunstâncias pelas quais possa avaliar-se de sua credibilidade."},{"chave":"art-204","sequencia":222,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 204.","conteudo":"O depoimento será prestado oralmente, não sendo permitido à testemunha trazê-lo por escrito.\n\nParágrafo único. Não será vedada à testemunha, entretanto, breve consulta a apontamentos."},{"chave":"art-205","sequencia":223,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 205.","conteudo":"Se ocorrer dúvida sobre a identidade da testemunha, o juiz procederá à verificação pelos meios ao seu alcance, podendo, entretanto, tomar-lhe o depoimento desde logo."},{"chave":"art-206","sequencia":224,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 206.","conteudo":"A testemunha não poderá eximir-se da obrigação de depor. Poderão, entretanto, recusar-se a fazê-lo o ascendente ou descendente, o afim em linha reta, o cônjuge, ainda que desquitado, o irmão e o pai, a mãe, ou o filho adotivo do acusado, salvo quando não for possível, por outro modo, obter-se ou integrar-se a prova do fato e de suas circunstâncias."},{"chave":"art-207","sequencia":225,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 207.","conteudo":"São proibidas de depor as pessoas que, em razão de função, ministério, ofício ou profissão, devam guardar segredo, salvo se, desobrigadas pela parte interessada, quiserem dar o seu testemunho."},{"chave":"art-208","sequencia":226,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 208.","conteudo":"Não se deferirá o compromisso a que alude o art. 203 aos doentes e deficientes mentais e aos menores de 14 (quatorze) anos, nem às pessoas a que se refere o art. 206 ."},{"chave":"art-209","sequencia":227,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 209.","conteudo":"O juiz, quando julgar necessário, poderá ouvir outras testemunhas, além das indicadas pelas partes.\n\n§ 1 o Se ao juiz parecer conveniente, serão ouvidas as pessoas a que as testemunhas se referirem.\n\n§ 2 o Não será computada como testemunha a pessoa que nada souber que interesse à decisão da causa."},{"chave":"art-210","sequencia":228,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 210.","conteudo":"As testemunhas serão inquiridas cada uma de per si, de modo que umas não saibam nem ouçam os depoimentos das outras, devendo o juiz adverti-las das penas cominadas ao falso testemunho. (Redação dada pela Lei nº 11.690, de 2008)\n\nParágrafo único. Antes do início da audiência e durante a sua realização, serão reservados espaços separados para a garantia da incomunicabilidade das testemunhas. (Incluído pela Lei nº 11.690, de 2008)"},{"chave":"art-211","sequencia":229,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 211.","conteudo":"Se o juiz, ao pronunciar sentença final, reconhecer que alguma testemunha fez afirmação falsa, calou ou negou a verdade, remeterá cópia do depoimento à autoridade policial para a instauração de inquérito.\n\nParágrafo único. Tendo o depoimento sido prestado em plenário de julgamento, o juiz, no caso de proferir decisão na audiência ( art. 538, § 2 o ), o tribunal ( art. 561 ), ou o conselho de sentença, após a votação dos quesitos, poderão fazer apresentar imediatamente a testemunha à autoridade policial."},{"chave":"art-212","sequencia":230,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 212.","conteudo":"As perguntas serão formuladas pelas partes diretamente à testemunha, não admitindo o juiz aquelas que puderem induzir a resposta, não tiverem relação com a causa ou importarem na repetição de outra já respondida. (Redação dada pela Lei nº 11.690, de 2008)\n\nParágrafo único. Sobre os pontos não esclarecidos, o juiz poderá complementar a inquirição. (Incluído pela Lei nº 11.690, de 2008)"},{"chave":"art-213","sequencia":231,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 213.","conteudo":"O juiz não permitirá que a testemunha manifeste suas apreciações pessoais, salvo quando inseparáveis da narrativa do fato."},{"chave":"art-214","sequencia":232,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 214.","conteudo":"Antes de iniciado o depoimento, as partes poderão contraditar a testemunha ou argüir circunstâncias ou defeitos, que a tornem suspeita de parcialidade, ou indigna de fé. O juiz fará consignar a contradita ou argüição e a resposta da testemunha, mas só excluirá a testemunha ou não Ihe deferirá compromisso nos casos previstos nos arts. 207 e 208 ."},{"chave":"art-215","sequencia":233,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 215.","conteudo":"Na redação do depoimento, o juiz deverá cingir-se, tanto quanto possível, às expressões usadas pelas testemunhas, reproduzindo fielmente as suas frases."},{"chave":"art-216","sequencia":234,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 216.","conteudo":"O depoimento da testemunha será reduzido a termo, assinado por ela, pelo juiz e pelas partes. Se a testemunha não souber assinar, ou não puder fazê-lo, pedirá a alguém que o faça por ela, depois de lido na presença de ambos."},{"chave":"art-217","sequencia":235,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 217.","conteudo":"Se o juiz verificar que a presença do réu poderá causar humilhação, temor, ou sério constrangimento à testemunha ou ao ofendido, de modo que prejudique a verdade do depoimento, fará a inquirição por videoconferência e, somente na impossibilidade dessa forma, determinará a retirada do réu, prosseguindo na inquirição, com a presença do seu defensor. (Redação dada pela Lei nº 11.690, de 2008)\n\nParágrafo único. A adoção de qualquer das medidas previstas no caput deste artigo deverá constar do termo, assim como os motivos que a determinaram. (Incluído pela Lei nº 11.690, de 2008)"},{"chave":"art-218","sequencia":236,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 218.","conteudo":"Se, regularmente intimada, a testemunha deixar de comparecer sem motivo justificado, o juiz poderá requisitar à autoridade policial a sua apresentação ou determinar seja conduzida por oficial de justiça, que poderá solicitar o auxílio da força pública."},{"chave":"art-219","sequencia":237,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 219.","conteudo":"O juiz poderá aplicar à testemunha faltosa a multa prevista no art. 453 , sem prejuízo do processo penal por crime de desobediência, e condená-la ao pagamento das custas da diligência. (Redação dada pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-220","sequencia":238,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 220.","conteudo":"As pessoas impossibilitadas, por enfermidade ou por velhice, de comparecer para depor, serão inquiridas onde estiverem."},{"chave":"art-221","sequencia":239,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 221.","conteudo":"O Presidente e o Vice-Presidente da República, os senadores e deputados federais, os ministros de Estado, os governadores de Estados e Territórios, os secretários de Estado, os prefeitos do Distrito Federal e dos Municípios, os deputados às Assembléias Legislativas Estaduais, os membros do Poder Judiciário, os ministros e juízes dos Tribunais de Contas da União, dos Estados, do Distrito Federal, bem como os do Tribunal Marítimo serão inquiridos em local, dia e hora previamente ajustados entre eles e o juiz. ( Redação dada pela Lei nº 3.653, de 4.11.1959)\n\n§ 1 o O Presidente e o Vice-Presidente da República, os presidentes do Senado Federal, da Câmara dos Deputados e do Supremo Tribunal Federal poderão optar pela prestação de depoimento por escrito, caso em que as perguntas, formuladas pelas partes e deferidas pelo juiz, Ihes serão transmitidas por ofício. (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\n§ 2 o Os militares deverão ser requisitados à autoridade superior. (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\n§ 3 o Aos funcionários públicos aplicar-se-á o disposto no art. 218 , devendo, porém, a expedição do mandado ser imediatamente comunicada ao chefe da repartição em que servirem, com indicação do dia e da hora marcados. (Incluído pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-222","sequencia":240,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 222.","conteudo":"A testemunha que morar fora da jurisdição do juiz será inquirida pelo juiz do lugar de sua residência, expedindo-se, para esse fim, carta precatória, com prazo razoável, intimadas as partes.\n\n§ 1 o A expedição da precatória não suspenderá a instrução criminal.\n\n§ 2 o Findo o prazo marcado, poderá realizar-se o julgamento, mas, a todo tempo, a precatória, uma vez devolvida, será junta aos autos.\n\n§ 3 o Na hipótese prevista no caput deste artigo, a oitiva de testemunha poderá ser realizada por meio de videoconferência ou outro recurso tecnológico de transmissão de sons e imagens em tempo real, permitida a presença do defensor e podendo ser realizada, inclusive, durante a realização da audiência de instrução e julgamento. (Incluído pela Lei nº 11.900, de 2009)"},{"chave":"art-222-a","sequencia":241,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 222º-A","conteudo":"As cartas rogatórias só serão expedidas se demonstrada previamente a sua imprescindibilidade, arcando a parte requerente com os custos de envio. (Incluído pela Lei nº 11.900, de 2009)\n\nParágrafo único. Aplica-se às cartas rogatórias o disposto nos §§ 1 o e 2 o do art. 222 deste Código . (Incluído pela Lei nº 11.900, de 2009)"},{"chave":"art-223","sequencia":242,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 223.","conteudo":"Quando a testemunha não conhecer a língua nacional, será nomeado intérprete para traduzir as perguntas e respostas.\n\nParágrafo único. Tratando-se de mudo, surdo ou surdo-mudo, proceder-se-á na conformidade do art. 192 ."},{"chave":"art-224","sequencia":243,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 224.","conteudo":"As testemunhas comunicarão ao juiz, dentro de um ano, qualquer mudança de residência, sujeitando-se, pela simples omissão, às penas do não-comparecimento."},{"chave":"art-225","sequencia":244,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VI — DAS TESTEMUNHAS"],"titulo":"CAPÍTULO VI — DAS TESTEMUNHAS","rotulo":"Art. 225.","conteudo":"Se qualquer testemunha houver de ausentar-se, ou, por enfermidade ou por velhice, inspirar receio de que ao tempo da instrução criminal já não exista, o juiz poderá, de ofício ou a requerimento de qualquer das partes, tomar-lhe antecipadamente o depoimento."},{"chave":"art-226","sequencia":245,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VII — DO RECONHECIMENTO DE PESSOAS E COISAS"],"titulo":"CAPÍTULO VII — DO RECONHECIMENTO DE PESSOAS E COISAS","rotulo":"Art. 226.","conteudo":"Quando houver necessidade de fazer-se o reconhecimento de pessoa, proceder-se-á pela seguinte forma:\n\nI - a pessoa que tiver de fazer o reconhecimento será convidada a descrever a pessoa que deva ser reconhecida;\n\nIl - a pessoa, cujo reconhecimento se pretender, será colocada, se possível, ao lado de outras que com ela tiverem qualquer semelhança, convidando-se quem tiver de fazer o reconhecimento a apontá-la;\n\nIII - se houver razão para recear que a pessoa chamada para o reconhecimento, por efeito de intimidação ou outra influência, não diga a verdade em face da pessoa que deve ser reconhecida, a autoridade providenciará para que esta não veja aquela;\n\nIV - do ato de reconhecimento lavrar-se-á auto pormenorizado, subscrito pela autoridade, pela pessoa chamada para proceder ao reconhecimento e por duas testemunhas presenciais.\n\nParágrafo único. O disposto no n o III deste artigo não terá aplicação na fase da instrução criminal ou em plenário de julgamento."},{"chave":"art-227","sequencia":246,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VII — DO RECONHECIMENTO DE PESSOAS E COISAS"],"titulo":"CAPÍTULO VII — DO RECONHECIMENTO DE PESSOAS E COISAS","rotulo":"Art. 227.","conteudo":"No reconhecimento de objeto, proceder-se-á com as cautelas estabelecidas no artigo anterior, no que for aplicável."},{"chave":"art-228","sequencia":247,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VII — DO RECONHECIMENTO DE PESSOAS E COISAS"],"titulo":"CAPÍTULO VII — DO RECONHECIMENTO DE PESSOAS E COISAS","rotulo":"Art. 228.","conteudo":"Se várias forem as pessoas chamadas a efetuar o reconhecimento de pessoa ou de objeto, cada uma fará a prova em separado, evitando-se qualquer comunicação entre elas."},{"chave":"art-229","sequencia":248,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VIII — DA ACAREAÇÃO"],"titulo":"CAPÍTULO VIII — DA ACAREAÇÃO","rotulo":"Art. 229.","conteudo":"A acareação será admitida entre acusados, entre acusado e testemunha, entre testemunhas, entre acusado ou testemunha e a pessoa ofendida, e entre as pessoas ofendidas, sempre que divergirem, em suas declarações, sobre fatos ou circunstâncias relevantes.\n\nParágrafo único. Os acareados serão reperguntados, para que expliquem os pontos de divergências, reduzindo-se a termo o ato de acareação."},{"chave":"art-230","sequencia":249,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO VIII — DA ACAREAÇÃO"],"titulo":"CAPÍTULO VIII — DA ACAREAÇÃO","rotulo":"Art. 230.","conteudo":"Se ausente alguma testemunha, cujas declarações divirjam das de outra, que esteja presente, a esta se darão a conhecer os pontos da divergência, consignando-se no auto o que explicar ou observar. Se subsistir a discordância, expedir-se-á precatória à autoridade do lugar onde resida a testemunha ausente, transcrevendo-se as declarações desta e as da testemunha presente, nos pontos em que divergirem, bem como o texto do referido auto, a fim de que se complete a diligência, ouvindo-se a testemunha ausente, pela mesma forma estabelecida para a testemunha presente. Esta diligência só se realizará quando não importe demora prejudicial ao processo e o juiz a entenda conveniente."},{"chave":"art-231","sequencia":250,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO IX — DOS DOCUMENTOS"],"titulo":"CAPÍTULO IX — DOS DOCUMENTOS","rotulo":"Art. 231.","conteudo":"Salvo os casos expressos em lei, as partes poderão apresentar documentos em qualquer fase do processo."},{"chave":"art-232","sequencia":251,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO IX — DOS DOCUMENTOS"],"titulo":"CAPÍTULO IX — DOS DOCUMENTOS","rotulo":"Art. 232.","conteudo":"Consideram-se documentos quaisquer escritos, instrumentos ou papéis, públicos ou particulares.\n\nParágrafo único. À fotografia do documento, devidamente autenticada, se dará o mesmo valor do original."},{"chave":"art-233","sequencia":252,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO IX — DOS DOCUMENTOS"],"titulo":"CAPÍTULO IX — DOS DOCUMENTOS","rotulo":"Art. 233.","conteudo":"As cartas particulares, interceptadas ou obtidas por meios criminosos, não serão admitidas em juízo.\n\nParágrafo único. As cartas poderão ser exibidas em juízo pelo respectivo destinatário, para a defesa de seu direito, ainda que não haja consentimento do signatário."},{"chave":"art-234","sequencia":253,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO IX — DOS DOCUMENTOS"],"titulo":"CAPÍTULO IX — DOS DOCUMENTOS","rotulo":"Art. 234.","conteudo":"Se o juiz tiver notícia da existência de documento relativo a ponto relevante da acusação ou da defesa, providenciará, independentemente de requerimento de qualquer das partes, para sua juntada aos autos, se possível."},{"chave":"art-235","sequencia":254,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO IX — DOS DOCUMENTOS"],"titulo":"CAPÍTULO IX — DOS DOCUMENTOS","rotulo":"Art. 235.","conteudo":"A letra e firma dos documentos particulares serão submetidas a exame pericial, quando contestada a sua autenticidade."},{"chave":"art-236","sequencia":255,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO IX — DOS DOCUMENTOS"],"titulo":"CAPÍTULO IX — DOS DOCUMENTOS","rotulo":"Art. 236.","conteudo":"Os documentos em língua estrangeira, sem prejuízo de sua juntada imediata, serão, se necessário, traduzidos por tradutor público, ou, na falta, por pessoa idônea nomeada pela autoridade."},{"chave":"art-237","sequencia":256,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO IX — DOS DOCUMENTOS"],"titulo":"CAPÍTULO IX — DOS DOCUMENTOS","rotulo":"Art. 237.","conteudo":"As públicas-formas só terão valor quando conferidas com o original, em presença da autoridade."},{"chave":"art-238","sequencia":257,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO IX — DOS DOCUMENTOS"],"titulo":"CAPÍTULO IX — DOS DOCUMENTOS","rotulo":"Art. 238.","conteudo":"Os documentos originais, juntos a processo findo, quando não exista motivo relevante que justifique a sua conservação nos autos, poderão, mediante requerimento, e ouvido o Ministério Público, ser entregues à parte que os produziu, ficando traslado nos autos."},{"chave":"art-239","sequencia":258,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO X — DOS INDÍCIOS"],"titulo":"CAPÍTULO X — DOS INDÍCIOS","rotulo":"Art. 239.","conteudo":"Considera-se indício a circunstância conhecida e provada, que, tendo relação com o fato, autorize, por indução, concluir-se a existência de outra ou outras circunstâncias."},{"chave":"art-240","sequencia":259,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO XI — DA BUSCA E DA APREENSÃO"],"titulo":"CAPÍTULO XI — DA BUSCA E DA APREENSÃO","rotulo":"Art. 240.","conteudo":"A busca será domiciliar ou pessoal.\n\n§ 1 o Proceder-se-á à busca domiciliar, quando fundadas razões a autorizarem, para:\n\na) prender criminosos;\n\nb) apreender coisas achadas ou obtidas por meios criminosos;\n\nc) apreender instrumentos de falsificação ou de contrafação e objetos falsificados ou contrafeitos;\n\nd) apreender armas e munições, instrumentos utilizados na prática de crime ou destinados a fim delituoso;\n\ne) descobrir objetos necessários à prova de infração ou à defesa do réu;\n\nf) apreender cartas, abertas ou não, destinadas ao acusado ou em seu poder, quando haja suspeita de que o conhecimento do seu conteúdo possa ser útil à elucidação do fato;\n\ng) apreender pessoas vítimas de crimes;\n\nh) colher qualquer elemento de convicção.\n\n§ 2 o Proceder-se-á à busca pessoal quando houver fundada suspeita de que alguém oculte consigo arma proibida ou objetos mencionados nas letras b a f e letra h do parágrafo anterior."},{"chave":"art-241","sequencia":260,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO XI — DA BUSCA E DA APREENSÃO"],"titulo":"CAPÍTULO XI — DA BUSCA E DA APREENSÃO","rotulo":"Art. 241.","conteudo":"Quando a própria autoridade policial ou judiciária não a realizar pessoalmente, a busca domiciliar deverá ser precedida da expedição de mandado."},{"chave":"art-242","sequencia":261,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO XI — DA BUSCA E DA APREENSÃO"],"titulo":"CAPÍTULO XI — DA BUSCA E DA APREENSÃO","rotulo":"Art. 242.","conteudo":"A busca poderá ser determinada de ofício ou a requerimento de qualquer das partes."},{"chave":"art-243","sequencia":262,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO XI — DA BUSCA E DA APREENSÃO"],"titulo":"CAPÍTULO XI — DA BUSCA E DA APREENSÃO","rotulo":"Art. 243.","conteudo":"O mandado de busca deverá:\n\nI - indicar, o mais precisamente possível, a casa em que será realizada a diligência e o nome do respectivo proprietário ou morador; ou, no caso de busca pessoal, o nome da pessoa que terá de sofrê-la ou os sinais que a identifiquem;\n\nII - mencionar o motivo e os fins da diligência;\n\nIII - ser subscrito pelo escrivão e assinado pela autoridade que o fizer expedir.\n\n§ 1 o Se houver ordem de prisão, constará do próprio texto do mandado de busca.\n\n§ 2 o Não será permitida a apreensão de documento em poder do defensor do acusado, salvo quando constituir elemento do corpo de delito."},{"chave":"art-244","sequencia":263,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO XI — DA BUSCA E DA APREENSÃO"],"titulo":"CAPÍTULO XI — DA BUSCA E DA APREENSÃO","rotulo":"Art. 244.","conteudo":"A busca pessoal independerá de mandado, no caso de prisão ou quando houver fundada suspeita de que a pessoa esteja na posse de arma proibida ou de objetos ou papéis que constituam corpo de delito, ou quando a medida for determinada no curso de busca domiciliar."},{"chave":"art-245","sequencia":264,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO XI — DA BUSCA E DA APREENSÃO"],"titulo":"CAPÍTULO XI — DA BUSCA E DA APREENSÃO","rotulo":"Art. 245.","conteudo":"As buscas domiciliares serão executadas de dia, salvo se o morador consentir que se realizem à noite, e, antes de penetrarem na casa, os executores mostrarão e lerão o mandado ao morador, ou a quem o represente, intimando-o, em seguida, a abrir a porta.\n\n§ 1 o Se a própria autoridade der a busca, declarará previamente sua qualidade e o objeto da diligência.\n\n§ 2 o Em caso de desobediência, será arrombada a porta e forçada a entrada.\n\n§ 3 o Recalcitrando o morador, será permitido o emprego de força contra coisas existentes no interior da casa, para o descobrimento do que se procura.\n\n§ 4 o Observar-se-á o disposto nos §§ 2 o e 3 o , quando ausentes os moradores, devendo, neste caso, ser intimado a assistir à diligência qualquer vizinho, se houver e estiver presente.\n\n§ 5 o Se é determinada a pessoa ou coisa que se vai procurar, o morador será intimado a mostrá-la.\n\n§ 6 o Descoberta a pessoa ou coisa que se procura, será imediatamente apreendida e posta sob custódia da autoridade ou de seus agentes.\n\n§ 7 o Finda a diligência, os executores lavrarão auto circunstanciado, assinando-o com duas testemunhas presenciais, sem prejuízo do disposto no § 4 o ."},{"chave":"art-246","sequencia":265,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO XI — DA BUSCA E DA APREENSÃO"],"titulo":"CAPÍTULO XI — DA BUSCA E DA APREENSÃO","rotulo":"Art. 246.","conteudo":"Aplicar-se-á também o disposto no artigo anterior, quando se tiver de proceder a busca em compartimento habitado ou em aposento ocupado de habitação coletiva ou em compartimento não aberto ao público, onde alguém exercer profissão ou atividade."},{"chave":"art-247","sequencia":266,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO XI — DA BUSCA E DA APREENSÃO"],"titulo":"CAPÍTULO XI — DA BUSCA E DA APREENSÃO","rotulo":"Art. 247.","conteudo":"Não sendo encontrada a pessoa ou coisa procurada, os motivos da diligência serão comunicados a quem tiver sofrido a busca, se o requerer."},{"chave":"art-248","sequencia":267,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO XI — DA BUSCA E DA APREENSÃO"],"titulo":"CAPÍTULO XI — DA BUSCA E DA APREENSÃO","rotulo":"Art. 248.","conteudo":"Em casa habitada, a busca será feita de modo que não moleste os moradores mais do que o indispensável para o êxito da diligência."},{"chave":"art-249","sequencia":268,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO XI — DA BUSCA E DA APREENSÃO"],"titulo":"CAPÍTULO XI — DA BUSCA E DA APREENSÃO","rotulo":"Art. 249.","conteudo":"A busca em mulher será feita por outra mulher, se não importar retardamento ou prejuízo da diligência."},{"chave":"art-250","sequencia":269,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VII — DA PROVA","CAPÍTULO XI — DA BUSCA E DA APREENSÃO"],"titulo":"CAPÍTULO XI — DA BUSCA E DA APREENSÃO","rotulo":"Art. 250.","conteudo":"A autoridade ou seus agentes poderão penetrar no território de jurisdição alheia, ainda que de outro Estado, quando, para o fim de apreensão, forem no seguimento de pessoa ou coisa, devendo apresentar-se à competente autoridade local, antes da diligência ou após, conforme a urgência desta.\n\n§ 1 o Entender-se-á que a autoridade ou seus agentes vão em seguimento da pessoa ou coisa, quando:\n\na) tendo conhecimento direto de sua remoção ou transporte, a seguirem sem interrupção, embora depois a percam de vista;\n\nb) ainda que não a tenham avistado, mas sabendo, por informações fidedignas ou circunstâncias indiciárias, que está sendo removida ou transportada em determinada direção, forem ao seu encalço.\n\n§ 2 o Se as autoridades locais tiverem fundadas razões para duvidar da legitimidade das pessoas que, nas referidas diligências, entrarem pelos seus distritos, ou da legalidade dos mandados que apresentarem, poderão exigir as provas dessa legitimidade, mas de modo que não se frustre a diligência."},{"chave":"art-251","sequencia":270,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO I — DO JUIZ"],"titulo":"CAPÍTULO I — DO JUIZ","rotulo":"Art. 251.","conteudo":"Ao juiz incumbirá prover à regularidade do processo e manter a ordem no curso dos respectivos atos, podendo, para tal fim, requisitar a força pública."},{"chave":"art-252","sequencia":271,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO I — DO JUIZ"],"titulo":"CAPÍTULO I — DO JUIZ","rotulo":"Art. 252.","conteudo":"O juiz não poderá exercer jurisdição no processo em que:\n\nI - tiver funcionado seu cônjuge ou parente, consangüíneo ou afim, em linha reta ou colateral até o terceiro grau, inclusive, como defensor ou advogado, órgão do Ministério Público, autoridade policial, auxiliar da justiça ou perito;\n\nII - ele próprio houver desempenhado qualquer dessas funções ou servido como testemunha;\n\nIII - tiver funcionado como juiz de outra instância, pronunciando-se, de fato ou de direito, sobre a questão;\n\nIV - ele próprio ou seu cônjuge ou parente, consangüíneo ou afim em linha reta ou colateral até o terceiro grau, inclusive, for parte ou diretamente interessado no feito."},{"chave":"art-253","sequencia":272,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO I — DO JUIZ"],"titulo":"CAPÍTULO I — DO JUIZ","rotulo":"Art. 253.","conteudo":"Nos juízos coletivos, não poderão servir no mesmo processo os juízes que forem entre si parentes, consangüíneos ou afins, em linha reta ou colateral até o terceiro grau, inclusive."},{"chave":"art-254","sequencia":273,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO I — DO JUIZ"],"titulo":"CAPÍTULO I — DO JUIZ","rotulo":"Art. 254.","conteudo":"O juiz dar-se-á por suspeito, e, se não o fizer, poderá ser recusado por qualquer das partes:\n\nI - se for amigo íntimo ou inimigo capital de qualquer deles;\n\nII - se ele, seu cônjuge, ascendente ou descendente, estiver respondendo a processo por fato análogo, sobre cujo caráter criminoso haja controvérsia;\n\nIII - se ele, seu cônjuge, ou parente, consangüíneo, ou afim, até o terceiro grau, inclusive, sustentar demanda ou responder a processo que tenha de ser julgado por qualquer das partes;\n\nIV - se tiver aconselhado qualquer das partes;\n\nV - se for credor ou devedor, tutor ou curador, de qualquer das partes;\n\nVl - se for sócio, acionista ou administrador de sociedade interessada no processo."},{"chave":"art-255","sequencia":274,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO I — DO JUIZ"],"titulo":"CAPÍTULO I — DO JUIZ","rotulo":"Art. 255.","conteudo":"O impedimento ou suspeição decorrente de parentesco por afinidade cessará pela dissolução do casamento que Ihe tiver dado causa, salvo sobrevindo descendentes; mas, ainda que dissolvido o casamento sem descendentes, não funcionará como juiz o sogro, o padrasto, o cunhado, o genro ou enteado de quem for parte no processo."},{"chave":"art-256","sequencia":275,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO I — DO JUIZ"],"titulo":"CAPÍTULO I — DO JUIZ","rotulo":"Art. 256.","conteudo":"A suspeição não poderá ser declarada nem reconhecida, quando a parte injuriar o juiz ou de propósito der motivo para criá-la."},{"chave":"art-257","sequencia":276,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO II — DO MINISTÉRIO PÚBLICO"],"titulo":"CAPÍTULO II — DO MINISTÉRIO PÚBLICO","rotulo":"Art. 257.","conteudo":"Ao Ministério Público cabe: (Redação dada pela Lei nº 11.719, de 2008).\n\nI - promover, privativamente, a ação penal pública, na forma estabelecida neste Código; e (Incluído pela Lei nº 11.719, de 2008).\n\nII - fiscalizar a execução da lei. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-258","sequencia":277,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO II — DO MINISTÉRIO PÚBLICO"],"titulo":"CAPÍTULO II — DO MINISTÉRIO PÚBLICO","rotulo":"Art. 258.","conteudo":"Os órgãos do Ministério Público não funcionarão nos processos em que o juiz ou qualquer das partes for seu cônjuge, ou parente, consangüíneo ou afim, em linha reta ou colateral, até o terceiro grau, inclusive, e a eles se estendem, no que Ihes for aplicável, as prescrições relativas à suspeição e aos impedimentos dos juízes."},{"chave":"art-259","sequencia":278,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO III — DO ACUSADO E SEU DEFENSOR"],"titulo":"CAPÍTULO III — DO ACUSADO E SEU DEFENSOR","rotulo":"Art. 259.","conteudo":"A impossibilidade de identificação do acusado com o seu verdadeiro nome ou outros qualificativos não retardará a ação penal, quando certa a identidade física. A qualquer tempo, no curso do processo, do julgamento ou da execução da sentença, se for descoberta a sua qualificação, far-se-á a retificação, por termo, nos autos, sem prejuízo da validade dos atos precedentes."},{"chave":"art-260","sequencia":279,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO III — DO ACUSADO E SEU DEFENSOR"],"titulo":"CAPÍTULO III — DO ACUSADO E SEU DEFENSOR","rotulo":"Art. 260.","conteudo":"Se o acusado não atender à intimação para o interrogatório, reconhecimento ou qualquer outro ato que, sem ele, não possa ser realizado, a autoridade poderá mandar conduzi-lo à sua presença. (Vide ADPF 395) (Vide ADPF 444)\n\nParágrafo único. O mandado conterá, além da ordem de condução, os requisitos mencionados no art. 352 , no que Ihe for aplicável."},{"chave":"art-261","sequencia":280,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO III — DO ACUSADO E SEU DEFENSOR"],"titulo":"CAPÍTULO III — DO ACUSADO E SEU DEFENSOR","rotulo":"Art. 261.","conteudo":"Nenhum acusado, ainda que ausente ou foragido, será processado ou julgado sem defensor.\n\nParágrafo único. A defesa técnica, quando realizada por defensor público ou dativo, será sempre exercida através de manifestação fundamentada. (Incluído pela Lei nº 10.792, de 1º.12.2003)"},{"chave":"art-262","sequencia":281,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO III — DO ACUSADO E SEU DEFENSOR"],"titulo":"CAPÍTULO III — DO ACUSADO E SEU DEFENSOR","rotulo":"Art. 262.","conteudo":"Ao acusado menor dar-se-á curador."},{"chave":"art-263","sequencia":282,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO III — DO ACUSADO E SEU DEFENSOR"],"titulo":"CAPÍTULO III — DO ACUSADO E SEU DEFENSOR","rotulo":"Art. 263.","conteudo":"Se o acusado não o tiver, ser-lhe-á nomeado defensor pelo juiz, ressalvado o seu direito de, a todo tempo, nomear outro de sua confiança, ou a si mesmo defender-se, caso tenha habilitação.\n\nParágrafo único. O acusado, que não for pobre, será obrigado a pagar os honorários do defensor dativo, arbitrados pelo juiz."},{"chave":"art-264","sequencia":283,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO III — DO ACUSADO E SEU DEFENSOR"],"titulo":"CAPÍTULO III — DO ACUSADO E SEU DEFENSOR","rotulo":"Art. 264.","conteudo":"Salvo motivo relevante, os advogados e solicitadores serão obrigados, sob pena de multa de cem a quinhentos mil-réis, a prestar seu patrocínio aos acusados, quando nomeados pelo Juiz."},{"chave":"art-265","sequencia":284,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO III — DO ACUSADO E SEU DEFENSOR"],"titulo":"CAPÍTULO III — DO ACUSADO E SEU DEFENSOR","rotulo":"Art. 265.","conteudo":"O defensor não poderá abandonar o processo sem justo motivo, previamente comunicado ao juiz, sob pena de responder por infração disciplinar perante o órgão correicional competente. (Redação dada pela Lei nº 14.752, de 2023)\n\n§ 1 o A audiência poderá ser adiada se, por motivo justificado, o defensor não puder comparecer. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 2 o Incumbe ao defensor provar o impedimento até a abertura da audiência. Não o fazendo, o juiz não determinará o adiamento de ato algum do processo, devendo nomear defensor substituto, ainda que provisoriamente ou só para o efeito do ato. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 3º Em caso de abandono do processo pelo defensor, o acusado será intimado para constituir novo defensor, se assim o quiser, e, na hipótese de não ser localizado, deverá ser nomeado defensor público ou advogado dativo para a sua defesa. (Incluído pela Lei nº 14.752, de 2023)"},{"chave":"art-266","sequencia":285,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO III — DO ACUSADO E SEU DEFENSOR"],"titulo":"CAPÍTULO III — DO ACUSADO E SEU DEFENSOR","rotulo":"Art. 266.","conteudo":"A constituição de defensor independerá de instrumento de mandato, se o acusado o indicar por ocasião do interrogatório."},{"chave":"art-267","sequencia":286,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO III — DO ACUSADO E SEU DEFENSOR"],"titulo":"CAPÍTULO III — DO ACUSADO E SEU DEFENSOR","rotulo":"Art. 267.","conteudo":"Nos termos do art. 252, não funcionarão como defensores os parentes do juiz."},{"chave":"art-268","sequencia":287,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO IV — DOS ASSISTENTES"],"titulo":"CAPÍTULO IV — DOS ASSISTENTES","rotulo":"Art. 268.","conteudo":"Em todos os termos da ação pública, poderá intervir, como assistente do Ministério Público, o ofendido ou seu representante legal, ou, na falta, qualquer das pessoas mencionadas no Art. 31 ."},{"chave":"art-269","sequencia":288,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO IV — DOS ASSISTENTES"],"titulo":"CAPÍTULO IV — DOS ASSISTENTES","rotulo":"Art. 269.","conteudo":"O assistente será admitido enquanto não passar em julgado a sentença e receberá a causa no estado em que se achar."},{"chave":"art-270","sequencia":289,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO IV — DOS ASSISTENTES"],"titulo":"CAPÍTULO IV — DOS ASSISTENTES","rotulo":"Art. 270.","conteudo":"O co-réu no mesmo processo não poderá intervir como assistente do Ministério Público."},{"chave":"art-271","sequencia":290,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO IV — DOS ASSISTENTES"],"titulo":"CAPÍTULO IV — DOS ASSISTENTES","rotulo":"Art. 271.","conteudo":"Ao assistente será permitido propor meios de prova, requerer perguntas às testemunhas, aditar o libelo e os articulados, participar do debate oral e arrazoar os recursos interpostos pelo Ministério Público, ou por ele próprio, nos casos dos arts. 584, § 1º , e 598 .\n\n§ 1 o O juiz, ouvido o Ministério Público, decidirá acerca da realização das provas propostas pelo assistente.\n\n§ 2 o O processo prosseguirá independentemente de nova intimação do assistente, quando este, intimado, deixar de comparecer a qualquer dos atos da instrução ou do julgamento, sem motivo de força maior devidamente comprovado."},{"chave":"art-272","sequencia":291,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO IV — DOS ASSISTENTES"],"titulo":"CAPÍTULO IV — DOS ASSISTENTES","rotulo":"Art. 272.","conteudo":"O Ministério Público será ouvido previamente sobre a admissão do assistente."},{"chave":"art-273","sequencia":292,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO IV — DOS ASSISTENTES"],"titulo":"CAPÍTULO IV — DOS ASSISTENTES","rotulo":"Art. 273.","conteudo":"Do despacho que admitir, ou não, o assistente, não caberá recurso, devendo, entretanto, constar dos autos o pedido e a decisão."},{"chave":"art-274","sequencia":293,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO V — DOS FUNCIONÁRIOS DA JUSTIÇA"],"titulo":"CAPÍTULO V — DOS FUNCIONÁRIOS DA JUSTIÇA","rotulo":"Art. 274.","conteudo":"As prescrições sobre suspeição dos juízes estendem-se aos serventuários e funcionários da justiça, no que Ihes for aplicável."},{"chave":"art-275","sequencia":294,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO VI — DOS PERITOS E INTÉRPRETES"],"titulo":"CAPÍTULO VI — DOS PERITOS E INTÉRPRETES","rotulo":"Art. 275.","conteudo":"O perito, ainda quando não oficial, estará sujeito à disciplina judiciária."},{"chave":"art-276","sequencia":295,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO VI — DOS PERITOS E INTÉRPRETES"],"titulo":"CAPÍTULO VI — DOS PERITOS E INTÉRPRETES","rotulo":"Art. 276.","conteudo":"As partes não intervirão na nomeação do perito."},{"chave":"art-277","sequencia":296,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO VI — DOS PERITOS E INTÉRPRETES"],"titulo":"CAPÍTULO VI — DOS PERITOS E INTÉRPRETES","rotulo":"Art. 277.","conteudo":"O perito nomeado pela autoridade será obrigado a aceitar o encargo, sob pena de multa de cem a quinhentos mil-réis, salvo escusa atendível.\n\nParágrafo único. Incorrerá na mesma multa o perito que, sem justa causa, provada imediatamente:\n\na) deixar de acudir à intimação ou ao chamado da autoridade;\n\nb) não comparecer no dia e local designados para o exame;\n\nc) não der o laudo, ou concorrer para que a perícia não seja feita, nos prazos estabelecidos."},{"chave":"art-278","sequencia":297,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO VI — DOS PERITOS E INTÉRPRETES"],"titulo":"CAPÍTULO VI — DOS PERITOS E INTÉRPRETES","rotulo":"Art. 278.","conteudo":"No caso de não-comparecimento do perito, sem justa causa, a autoridade poderá determinar a sua condução."},{"chave":"art-279","sequencia":298,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO VI — DOS PERITOS E INTÉRPRETES"],"titulo":"CAPÍTULO VI — DOS PERITOS E INTÉRPRETES","rotulo":"Art. 279.","conteudo":"Não poderão ser peritos:\n\nI - os que estiverem sujeitos à interdição de direito mencionada nos ns. I e IV do art. 69 do Código Penal ;\n\nII - os que tiverem prestado depoimento no processo ou opinado anteriormente sobre o objeto da perícia;\n\nIII - os analfabetos e os menores de 21 anos."},{"chave":"art-280","sequencia":299,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO VI — DOS PERITOS E INTÉRPRETES"],"titulo":"CAPÍTULO VI — DOS PERITOS E INTÉRPRETES","rotulo":"Art. 280.","conteudo":"É extensivo aos peritos, no que Ihes for aplicável, o disposto sobre suspeição dos juízes."},{"chave":"art-281","sequencia":300,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO VIII — DO JUIZ, DO MINISTÉRIO PÚBLICO, DO ACUSADO E DEFENSOR, DOS ASSISTENTES E AUXILIARES DA JUSTIÇA","CAPÍTULO VI — DOS PERITOS E INTÉRPRETES"],"titulo":"CAPÍTULO VI — DOS PERITOS E INTÉRPRETES","rotulo":"Art. 281.","conteudo":"Os intérpretes são, para todos os efeitos, equiparados aos peritos."},{"chave":"art-282","sequencia":301,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 282.","conteudo":"As medidas cautelares previstas neste Título deverão ser aplicadas observando-se a: (Redação dada pela Lei nº 12.403, de 2011).\n\nI - necessidade para aplicação da lei penal, para a investigação ou a instrução criminal e, nos casos expressamente previstos, para evitar a prática de infrações penais; (Incluído pela Lei nº 12.403, de 2011).\n\nII - adequação da medida à gravidade do crime, circunstâncias do fato e condições pessoais do indiciado ou acusado. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 1 o As medidas cautelares poderão ser aplicadas isolada ou cumulativamente. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 2º As medidas cautelares serão decretadas pelo juiz a requerimento das partes ou, quando no curso da investigação criminal, por representação da autoridade policial ou mediante requerimento do Ministério Público. (Redação dada pela Lei nº 13.964, de 2019)\n\n§ 3º Ressalvados os casos de urgência ou de perigo de ineficácia da medida, o juiz, ao receber o pedido de medida cautelar, determinará a intimação da parte contrária, para se manifestar no prazo de 5 (cinco) dias, acompanhada de cópia do requerimento e das peças necessárias, permanecendo os autos em juízo, e os casos de urgência ou de perigo deverão ser justificados e fundamentados em decisão que contenha elementos do caso concreto que justifiquem essa medida excepcional. (Redação dada pela Lei nº 13.964, de 2019)\n\n§ 4º No caso de descumprimento de qualquer das obrigações impostas, o juiz, mediante requerimento do Ministério Público, de seu assistente ou do querelante, poderá substituir a medida, impor outra em cumulação, ou, em último caso, decretar a prisão preventiva, nos termos do parágrafo único do art. 312 deste Código. (Redação dada pela Lei nº 13.964, de 2019)\n\n§ 5º O juiz poderá, de ofício ou a pedido das partes, revogar a medida cautelar ou substituí-la quando verificar a falta de motivo para que subsista, bem como voltar a decretá-la, se sobrevierem razões que a justifiquem. (Redação dada pela Lei nº 13.964, de 2019)\n\n§ 6º A prisão preventiva somente será determinada quando não for cabível a sua substituição por outra medida cautelar, observado o art. 319 deste Código, e o não cabimento da substituição por outra medida cautelar deverá ser justificado de forma fundamentada nos elementos presentes do caso concreto, de forma individualizada. (Redação dada pela Lei nº 13.964, de 2019)"},{"chave":"art-283","sequencia":302,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 283.","conteudo":"Ninguém poderá ser preso senão em flagrante delito ou por ordem escrita e fundamentada da autoridade judiciária competente, em decorrência de prisão cautelar ou em virtude de condenação criminal transitada em julgado. (Redação dada pela Lei nº 13.964, de 2019)\n\n§ 1 o As medidas cautelares previstas neste Título não se aplicam à infração a que não for isolada, cumulativa ou alternativamente cominada pena privativa de liberdade. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 2 o A prisão poderá ser efetuada em qualquer dia e a qualquer hora, respeitadas as restrições relativas à inviolabilidade do domicílio. (Incluído pela Lei nº 12.403, de 2011)."},{"chave":"art-284","sequencia":303,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 284.","conteudo":"Não será permitido o emprego de força, salvo a indispensável no caso de resistência ou de tentativa de fuga do preso."},{"chave":"art-285","sequencia":304,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 285.","conteudo":"A autoridade que ordenar a prisão fará expedir o respectivo mandado.\n\nParágrafo único. O mandado de prisão:\n\na) será lavrado pelo escrivão e assinado pela autoridade;\n\nb) designará a pessoa, que tiver de ser presa, por seu nome, alcunha ou sinais característicos;\n\nc) mencionará a infração penal que motivar a prisão;\n\nd) declarará o valor da fiança arbitrada, quando afiançável a infração;\n\ne) será dirigido a quem tiver qualidade para dar-lhe execução."},{"chave":"art-286","sequencia":305,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 286.","conteudo":"O mandado será passado em duplicata, e o executor entregará ao preso, logo depois da prisão, um dos exemplares com declaração do dia, hora e lugar da diligência. Da entrega deverá o preso passar recibo no outro exemplar; se recusar, não souber ou não puder escrever, o fato será mencionado em declaração, assinada por duas testemunhas."},{"chave":"art-287","sequencia":306,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 287.","conteudo":"Se a infração for inafiançável, a falta de exibição do mandado não obstará a prisão, e o preso, em tal caso, será imediatamente apresentado ao juiz que tiver expedido o mandado, para a realização de audiência de custódia. (Redação dada pela Lei nº 13.964, de 2019)"},{"chave":"art-288","sequencia":307,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 288.","conteudo":"Ninguém será recolhido à prisão, sem que seja exibido o mandado ao respectivo diretor ou carcereiro, a quem será entregue cópia assinada pelo executor ou apresentada a guia expedida pela autoridade competente, devendo ser passado recibo da entrega do preso, com declaração de dia e hora.\n\nParágrafo único. O recibo poderá ser passado no próprio exemplar do mandado, se este for o documento exibido."},{"chave":"art-289","sequencia":308,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 289.","conteudo":"Quando o acusado estiver no território nacional, fora da jurisdição do juiz processante, será deprecada a sua prisão, devendo constar da precatória o inteiro teor do mandado. (Redação dada pela Lei nº 12.403, de 2011).\n\n§ 1 o Havendo urgência, o juiz poderá requisitar a prisão por qualquer meio de comunicação, do qual deverá constar o motivo da prisão, bem como o valor da fiança se arbitrada. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 2 o A autoridade a quem se fizer a requisição tomará as precauções necessárias para averiguar a autenticidade da comunicação. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 3 o O juiz processante deverá providenciar a remoção do preso no prazo máximo de 30 (trinta) dias, contados da efetivação da medida. (Incluído pela Lei nº 12.403, de 2011)."},{"chave":"art-289-a","sequencia":309,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 289º-A","conteudo":"O juiz competente providenciará o imediato registro do mandado de prisão em banco de dados mantido pelo Conselho Nacional de Justiça para essa finalidade. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 1 o Qualquer agente policial poderá efetuar a prisão determinada no mandado de prisão registrado no Conselho Nacional de Justiça, ainda que fora da competência territorial do juiz que o expediu. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 2 o Qualquer agente policial poderá efetuar a prisão decretada, ainda que sem registro no Conselho Nacional de Justiça, adotando as precauções necessárias para averiguar a autenticidade do mandado e comunicando ao juiz que a decretou, devendo este providenciar, em seguida, o registro do mandado na forma do caput deste artigo. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 3 o A prisão será imediatamente comunicada ao juiz do local de cumprimento da medida o qual providenciará a certidão extraída do registro do Conselho Nacional de Justiça e informará ao juízo que a decretou. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 4 o O preso será informado de seus direitos, nos termos do inciso LXIII do art. 5 o da Constituição Federal e, caso o autuado não informe o nome de seu advogado, será comunicado à Defensoria Pública. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 5 o Havendo dúvidas das autoridades locais sobre a legitimidade da pessoa do executor ou sobre a identidade do preso, aplica-se o disposto no § 2 o do art. 290 deste Código . (Incluído pela Lei nº 12.403, de 2011).\n\n§ 6 o O Conselho Nacional de Justiça regulamentará o registro do mandado de prisão a que se refere o caput deste artigo. (Incluído pela Lei nº 12.403, de 2011)."},{"chave":"art-290","sequencia":310,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 290.","conteudo":"Se o réu, sendo perseguido, passar ao território de outro município ou comarca, o executor poderá efetuar-lhe a prisão no lugar onde o alcançar, apresentando-o imediatamente à autoridade local, que, depois de lavrado, se for o caso, o auto de flagrante, providenciará para a remoção do preso.\n\n§ 1 o - Entender-se-á que o executor vai em perseguição do réu, quando:\n\na) tendo-o avistado, for perseguindo-o sem interrupção, embora depois o tenha perdido de vista;\n\nb) sabendo, por indícios ou informações fidedignas, que o réu tenha passado, há pouco tempo, em tal ou qual direção, pelo lugar em que o procure, for no seu encalço.\n\n§ 2 o Quando as autoridades locais tiverem fundadas razões para duvidar da legitimidade da pessoa do executor ou da legalidade do mandado que apresentar, poderão pôr em custódia o réu, até que fique esclarecida a dúvida."},{"chave":"art-291","sequencia":311,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 291.","conteudo":"A prisão em virtude de mandado entender-se-á feita desde que o executor, fazendo-se conhecer do réu, Ihe apresente o mandado e o intime a acompanhá-lo."},{"chave":"art-292","sequencia":312,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 292.","conteudo":"Se houver, ainda que por parte de terceiros, resistência à prisão em flagrante ou à determinada por autoridade competente, o executor e as pessoas que o auxiliarem poderão usar dos meios necessários para defender-se ou para vencer a resistência, do que tudo se lavrará auto subscrito também por duas testemunhas.\n\nParágrafo único. É vedado o uso de algemas em mulheres grávidas durante os atos médico-hospitalares preparatórios para a realização do parto e durante o trabalho de parto, bem como em mulheres durante o período de puerpério imediato. (Redação dada pela Lei nº 13.434, de 2017)"},{"chave":"art-293","sequencia":313,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 293.","conteudo":"Se o executor do mandado verificar, com segurança, que o réu entrou ou se encontra em alguma casa, o morador será intimado a entregá-lo, à vista da ordem de prisão. Se não for obedecido imediatamente, o executor convocará duas testemunhas e, sendo dia, entrará à força na casa, arrombando as portas, se preciso; sendo noite, o executor, depois da intimação ao morador, se não for atendido, fará guardar todas as saídas, tornando a casa incomunicável, e, logo que amanheça, arrombará as portas e efetuará a prisão.\n\nParágrafo único. O morador que se recusar a entregar o réu oculto em sua casa será levado à presença da autoridade, para que se proceda contra ele como for de direito."},{"chave":"art-294","sequencia":314,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 294.","conteudo":"No caso de prisão em flagrante, observar-se-á o disposto no artigo anterior, no que for aplicável."},{"chave":"art-295","sequencia":315,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 295.","conteudo":"Serão recolhidos a quartéis ou a prisão especial, à disposição da autoridade competente, quando sujeitos a prisão antes de condenação definitiva:\n\nI - os ministros de Estado;\n\nII - os governadores ou interventores de Estados ou Territórios, o prefeito do Distrito Federal, seus respectivos secretários, os prefeitos municipais, os vereadores e os chefes de Polícia; (Redação dada pela Lei nº 3.181, de 11.6.1957)\n\nIII - os membros do Parlamento Nacional, do Conselho de Economia Nacional e das Assembléias Legislativas dos Estados;\n\nIV - os cidadãos inscritos no \"Livro de Mérito\";\n\nV – os oficiais das Forças Armadas e os militares dos Estados, do Distrito Federal e dos Territórios; (Redação dada pela Lei nº 10.258, de 11.7.2001)\n\nVI - os magistrados;\n\nVII - os diplomados por qualquer das faculdades superiores da República; (Vide ADPF nº 334)\n\nVIII - os ministros de confissão religiosa;\n\nIX - os ministros do Tribunal de Contas;\n\nX - os cidadãos que já tiverem exercido efetivamente a função de jurado, salvo quando excluídos da lista por motivo de incapacidade para o exercício daquela função;\n\nXI - os delegados de polícia e os guardas-civis dos Estados e Territórios, ativos e inativos. (Redação dada pela Lei nº 5.126, de 20.9.1966)\n\n§ 1 o A prisão especial, prevista neste Código ou em outras leis, consiste exclusivamente no recolhimento em local distinto da prisão comum. (Incluído pela Lei nº 10.258, de 11.7.2001)\n\n§ 2 o Não havendo estabelecimento específico para o preso especial, este será recolhido em cela distinta do mesmo estabelecimento. (Incluído pela Lei nº 10.258, de 11.7.2001)\n\n§ 3 o A cela especial poderá consistir em alojamento coletivo, atendidos os requisitos de salubridade do ambiente, pela concorrência dos fatores de aeração, insolação e condicionamento térmico adequados à existência humana. (Incluído pela Lei nº 10.258, de 11.7.2001)\n\n§ 4 o O preso especial não será transportado juntamente com o preso comum. (Incluído pela Lei nº 10.258, de 11.7.2001)\n\n§ 5 o Os demais direitos e deveres do preso especial serão os mesmos do preso comum. (Incluído pela Lei nº 10.258, de 11.7.2001)"},{"chave":"art-296","sequencia":316,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 296.","conteudo":"Os inferiores e praças de pré, onde for possível, serão recolhidos à prisão, em estabelecimentos militares, de acordo com os respectivos regulamentos."},{"chave":"art-297","sequencia":317,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 297.","conteudo":"Para o cumprimento de mandado expedido pela autoridade judiciária, a autoridade policial poderá expedir tantos outros quantos necessários às diligências, devendo neles ser fielmente reproduzido o teor do mandado original."},{"chave":"art-298","sequencia":318,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 298.","conteudo":"(Revogado pela Lei nº 12.403, de 2011)."},{"chave":"art-299","sequencia":319,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 299.","conteudo":"A captura poderá ser requisitada, à vista de mandado judicial, por qualquer meio de comunicação, tomadas pela autoridade, a quem se fizer a requisição, as precauções necessárias para averiguar a autenticidade desta. (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-300","sequencia":320,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 300.","conteudo":"As pessoas presas provisoriamente ficarão separadas das que já estiverem definitivamente condenadas, nos termos da lei de execução penal. (Redação dada pela Lei nº 12.403, de 2011).\n\nParágrafo único. O militar preso em flagrante delito, após a lavratura dos procedimentos legais, será recolhido a quartel da instituição a que pertencer, onde ficará preso à disposição das autoridades competentes. (Incluído pela Lei nº 12.403, de 2011)."},{"chave":"art-300-a","sequencia":321,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 300º-A","conteudo":"O investigado por crimes contra a dignidade sexual, quando preso cautelarmente, e o condenado pelos mesmos crimes deverão ser submetidos obrigatoriamente à identificação do perfil genético, mediante extração de DNA (ácido desoxirribonucleico), por técnica adequada e indolor, por ocasião do ingresso no estabelecimento prisional. (Incluído pela Lei nº 15.280, de 2025)"},{"chave":"art-301","sequencia":322,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO II — DA PRISÃO EM FLAGRANTE"],"titulo":"CAPÍTULO II — DA PRISÃO EM FLAGRANTE","rotulo":"Art. 301.","conteudo":"Qualquer do povo poderá e as autoridades policiais e seus agentes deverão prender quem quer que seja encontrado em flagrante delito."},{"chave":"art-302","sequencia":323,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO II — DA PRISÃO EM FLAGRANTE"],"titulo":"CAPÍTULO II — DA PRISÃO EM FLAGRANTE","rotulo":"Art. 302.","conteudo":"Considera-se em flagrante delito quem:\n\nI - está cometendo a infração penal;\n\nII - acaba de cometê-la;\n\nIII - é perseguido, logo após, pela autoridade, pelo ofendido ou por qualquer pessoa, em situação que faça presumir ser autor da infração;\n\nIV - é encontrado, logo depois, com instrumentos, armas, objetos ou papéis que façam presumir ser ele autor da infração."},{"chave":"art-303","sequencia":324,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO II — DA PRISÃO EM FLAGRANTE"],"titulo":"CAPÍTULO II — DA PRISÃO EM FLAGRANTE","rotulo":"Art. 303.","conteudo":"Nas infrações permanentes, entende-se o agente em flagrante delito enquanto não cessar a permanência."},{"chave":"art-304","sequencia":325,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO II — DA PRISÃO EM FLAGRANTE"],"titulo":"CAPÍTULO II — DA PRISÃO EM FLAGRANTE","rotulo":"Art. 304.","conteudo":"Apresentado o preso à autoridade competente, ouvirá esta o condutor e colherá, desde logo, sua assinatura, entregando a este cópia do termo e recibo de entrega do preso. Em seguida, procederá à oitiva das testemunhas que o acompanharem e ao interrogatório do acusado sobre a imputação que lhe é feita, colhendo, após cada oitiva suas respectivas assinaturas, lavrando, a autoridade, afinal, o auto. (Redação dada pela Lei nº 11.113, de 2005)\n\n§ 1 o Resultando das respostas fundada a suspeita contra o conduzido, a autoridade mandará recolhê-lo à prisão, exceto no caso de livrar-se solto ou de prestar fiança, e prosseguirá nos atos do inquérito ou processo, se para isso for competente; se não o for, enviará os autos à autoridade que o seja.\n\n§ 2 o A falta de testemunhas da infração não impedirá o auto de prisão em flagrante; mas, nesse caso, com o condutor, deverão assiná-lo pelo menos duas pessoas que hajam testemunhado a apresentação do preso à autoridade.\n\n§ 3 o Quando o acusado se recusar a assinar, não souber ou não puder fazê-lo, o auto de prisão em flagrante será assinado por duas testemunhas, que tenham ouvido sua leitura na presença deste. (Redação dada pela Lei nº 11.113, de 2005)\n\n§ 4 o Da lavratura do auto de prisão em flagrante deverá constar a informação sobre a existência de filhos, respectivas idades e se possuem alguma deficiência e o nome e o contato de eventual responsável pelos cuidados dos filhos, indicado pela pessoa presa. (Incluído pela Lei nº 13.257, de 2016)"},{"chave":"art-305","sequencia":326,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO II — DA PRISÃO EM FLAGRANTE"],"titulo":"CAPÍTULO II — DA PRISÃO EM FLAGRANTE","rotulo":"Art. 305.","conteudo":"Na falta ou no impedimento do escrivão, qualquer pessoa designada pela autoridade lavrará o auto, depois de prestado o compromisso legal."},{"chave":"art-306","sequencia":327,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO II — DA PRISÃO EM FLAGRANTE"],"titulo":"CAPÍTULO II — DA PRISÃO EM FLAGRANTE","rotulo":"Art. 306.","conteudo":"A prisão de qualquer pessoa e o local onde se encontre serão comunicados imediatamente ao juiz competente, ao Ministério Público e à família do preso ou à pessoa por ele indicada. (Redação dada pela Lei nº 12.403, de 2011).\n\n§ 1 o Em até 24 (vinte e quatro) horas após a realização da prisão, será encaminhado ao juiz competente o auto de prisão em flagrante e, caso o autuado não informe o nome de seu advogado, cópia integral para a Defensoria Pública. (Redação dada pela Lei nº 12.403, de 2011).\n\n§ 2 o No mesmo prazo, será entregue ao preso, mediante recibo, a nota de culpa, assinada pela autoridade, com o motivo da prisão, o nome do condutor e os das testemunhas. (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-307","sequencia":328,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO II — DA PRISÃO EM FLAGRANTE"],"titulo":"CAPÍTULO II — DA PRISÃO EM FLAGRANTE","rotulo":"Art. 307.","conteudo":"Quando o fato for praticado em presença da autoridade, ou contra esta, no exercício de suas funções, constarão do auto a narração deste fato, a voz de prisão, as declarações que fizer o preso e os depoimentos das testemunhas, sendo tudo assinado pela autoridade, pelo preso e pelas testemunhas e remetido imediatamente ao juiz a quem couber tomar conhecimento do fato delituoso, se não o for a autoridade que houver presidido o auto."},{"chave":"art-308","sequencia":329,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO II — DA PRISÃO EM FLAGRANTE"],"titulo":"CAPÍTULO II — DA PRISÃO EM FLAGRANTE","rotulo":"Art. 308.","conteudo":"Não havendo autoridade no lugar em que se tiver efetuado a prisão, o preso será logo apresentado à do lugar mais próximo."},{"chave":"art-309","sequencia":330,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO II — DA PRISÃO EM FLAGRANTE"],"titulo":"CAPÍTULO II — DA PRISÃO EM FLAGRANTE","rotulo":"Art. 309.","conteudo":"Se o réu se livrar solto, deverá ser posto em liberdade, depois de lavrado o auto de prisão em flagrante."},{"chave":"art-310","sequencia":331,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO II — DA PRISÃO EM FLAGRANTE"],"titulo":"CAPÍTULO II — DA PRISÃO EM FLAGRANTE","rotulo":"Art. 310.","conteudo":"Após receber o auto de prisão em flagrante, no prazo máximo de até 24 (vinte e quatro) horas após a realização da prisão, o juiz deverá promover, por meio de videoconferência em tempo real, audiência de custódia com a presença do acusado, seu advogado constituído ou membro da Defensoria Pública e o membro do Ministério Público, e, nessa audiência, o juiz deverá, fundamentadamente: (Redação dada pela Lei nº 15.358, de 2026)\n\nI - relaxar a prisão ilegal; ou (Incluído pela Lei nº 12.403, de 2011).\n\nII - converter a prisão em flagrante em preventiva, quando presentes os requisitos constantes do art. 312 deste Código , e se revelarem inadequadas ou insuficientes as medidas cautelares diversas da prisão; ou (Incluído pela Lei nº 12.403, de 2011).\n\nIII - conceder liberdade provisória, com ou sem fiança. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 1º Se o juiz verificar, pelo auto de prisão em flagrante, que o agente praticou o fato em qualquer das condições constantes dos incisos I, II ou III do caput do art. 23 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal) , poderá, fundamentadamente, conceder ao acusado liberdade provisória, mediante termo de comparecimento obrigatório a todos os atos processuais, sob pena de revogação. (Renumerado do parágrafo único pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 2º Se o juiz verificar que o agente é reincidente ou que integra organização criminosa armada ou milícia, ou que porta arma de fogo de uso restrito, deverá denegar a liberdade provisória, com ou sem medidas cautelares. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 3º A autoridade que deu causa, sem motivação idônea, à não realização da audiência de custódia no prazo estabelecido no caput deste artigo responderá administrativa, civil e penalmente pela omissão. (Incluído pela Lei nº 13.964, de 2019) (Vigência)\n\n§ 4º Transcorridas 24 (vinte e quatro) horas após o decurso do prazo estabelecido no caput deste artigo, a não realização de audiência de custódia sem motivação idônea ensejará também a ilegalidade da prisão, a ser relaxada pela autoridade competente, sem prejuízo da possibilidade de imediata decretação de prisão preventiva. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6.298) (Vide ADI 6.300 ) (Vide ADI 6.305)\n\n§ 5º São circunstâncias que, sem prejuízo de outras, recomendam a conversão da prisão em flagrante em preventiva: (Incluído pela Leinº 15.272, de 2025)\n\nI – haver provas que indiquem a prática reiterada de infrações penais pelo agente; (Incluído pela Leinº 15.272, de 2025)\n\nII – ter a infração penal sido praticada com violência ou grave ameaça contra a pessoa; (Incluído pela Leinº 15.272, de 2025)\n\nIII – ter o agente já sido liberado em prévia audiência de custódia por outra infração penal, salvo se por ela tiver sido absolvido posteriormente; (Incluído pela Leinº 15.272, de 2025)\n\nIV – ter o agente praticado a infração penal na pendência de inquérito ou ação penal; (Incluído pela Leinº 15.272, de 2025)\n\nV – ter havido fuga ou haver perigo de fuga; ou (Incluído pela Leinº 15.272, de 2025)\n\nVI – haver perigo de perturbação da tramitação e do decurso do inquérito ou da instrução criminal, bem como perigo para a coleta, a conservação ou a incolumidade da prova. (Incluído pela Leinº 15.272, de 2025)\n\n§ 6º A decisão de que trata o caput deste artigo deve ser motivada e fundamentada, sendo obrigatório o exame, pelo juiz, das circunstâncias previstas nos §§ 2º e 5º deste artigo e dos critérios de periculosidade previstos no § 3º do art. 312. (Incluído pela Leinº 15.272, de 2025)\n\n§ 7º Antes do início da audiência de custódia, deverá a serventia judicial conferir os processos criminais a que responde o acusado e, constatada pendência de citação em qualquer deles, informar ao juiz, que certificará a ocorrência e procederá a citação pessoal do acusado, comunicando de imediato o juízo competente. (Incluído pela Lei nº 15.358, de 2026)\n\n§ 8º Na audiência de custódia por videoconferência, serão facultados todos os mecanismos para intervenção da defesa técnica e do Ministério Público, que poderão suscitar questões de ordem. (Incluído pela Lei nº 15.358, de 2026)\n\n§ 9º Será garantido o direito de entrevista prévia, reservada e inviolável entre o preso e o seu defensor, presencialmente, por videoconferência ou por qualquer outro meio de comunicação. (Incluído pela Lei nº 15.358, de 2026)\n\n§ 10. Deverá ser assegurada privacidade ao preso na sala em que se realizar a videoconferência, devendo permanecer sozinho durante a realização de sua oitiva, ressalvada a possibilidade de presença física de seu defensor no ambiente. (Incluído pela Lei nº 15.358, de 2026)\n\n§ 11. No caso de qualquer falha no sistema de comunicações cuja causa seja atribuível ao tribunal, por questões internas ou decorrente dos provedores de serviço que o tribunal tenha contratado, é obrigatória a repetição completa da audiência, sem convalescer qualquer ato incompleto. (Incluído pela Lei nº 15.358, de 2026)\n\n§ 12. Todos os estabelecimentos prisionais terão salas próprias, com disponibilização de mecanismos de videoconferência estáveis, para a realização das audiências de custódia. (Incluído pela Lei nº 15.358, de 2026)\n\n§ 13. Em situações excepcionais decorrentes de força maior, poderá a audiência de custódia ser realizada presencialmente, mediante decisão justificada do juiz competente, vedada a hipótese se o ato se revelar demasiadamente custoso ou trouxer excessivo risco à segurança social ou à segurança física do detido. (Incluído pela Lei nº 15.358, de 2026)"},{"chave":"art-310-a","sequencia":332,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO II — DA PRISÃO EM FLAGRANTE"],"titulo":"CAPÍTULO II — DA PRISÃO EM FLAGRANTE","rotulo":"Art. 310º-A","conteudo":"No caso de prisão em flagrante por crime praticado com violência ou grave ameaça contra a pessoa, por crime contra a dignidade sexual ou por crime praticado por agente em relação ao qual existam elementos probatórios que indiquem integrar organização criminosa que utilize ou tenha à sua disposição armas de fogo ou em relação ao qual seja imputada a prática de crime previsto no art. 1º da Lei nº 8.072, de 25 de julho de 1990 (Lei dos Crimes Hediondos), o Ministério Público ou a autoridade policial deverá requerer ao juiz a coleta de material biológico para obtenção e armazenamento do perfil genético do custodiado, na forma da Lei nº 12.037, de 1º de outubro de 2009. (Incluído pela Leinº 15.272, de 2025)\n\n§ 1º A coleta de material biológico para a obtenção do perfil genético deverá ser feita, preferencialmente, na própria audiência de custódia ou no prazo de 10 (dez) dias, contado de sua realização. (Incluído pela Leinº 15.272, de 2025)\n\n§ 2º A coleta de material biológico será realizada por agente público treinado e respeitará os procedimentos de cadeia de custódia definidos pela legislação em vigor e complementados pelo órgão de perícia oficial de natureza criminal. (Incluído pela Leinº 15.272, de 2025)"},{"chave":"art-311","sequencia":333,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO III — DA PRISÃO PREVENTIVA"],"titulo":"CAPÍTULO III — DA PRISÃO PREVENTIVA","rotulo":"Art. 311.","conteudo":"Em qualquer fase da investigação policial ou do processo penal, caberá a prisão preventiva decretada pelo juiz, a requerimento do Ministério Público, do querelante ou do assistente, ou por representação da autoridade policial. (Redação dada pela Lei nº 13.964, de 2019)"},{"chave":"art-312","sequencia":334,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO III — DA PRISÃO PREVENTIVA"],"titulo":"CAPÍTULO III — DA PRISÃO PREVENTIVA","rotulo":"Art. 312.","conteudo":"A prisão preventiva poderá ser decretada como garantia da ordem pública, da ordem econômica, por conveniência da instrução criminal ou para assegurar a aplicação da lei penal, quando houver prova da existência do crime e indício suficiente de autoria e de perigo gerado pelo estado de liberdade do imputado. (Redação dada pela Lei nº 13.964, de 2019)\n\n§ 1º A prisão preventiva também poderá ser decretada em caso de descumprimento de qualquer das obrigações impostas por força de outras medidas cautelares ( art. 282, § 4 o ). (Redação dada pela Lei nº 13.964, de 2019)\n\n§ 2º A decisão que decretar a prisão preventiva deve ser motivada e fundamentada em receio de perigo e existência concreta de fatos novos ou contemporâneos que justifiquem a aplicação da medida adotada. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 3º Devem ser considerados na aferição da periculosidade do agente, geradora de riscos à ordem pública: (Incluído pela Leinº 15.272, de 2025)\n\nI – o modus operandi , inclusive quanto ao uso reiterado de violência ou grave ameaça à pessoa ou quanto à premeditação do agente para a prática delituosa; (Incluído pela Leinº 15.272, de 2025)\n\nII – a participação em organização criminosa; (Incluído pela Leinº 15.272, de 2025)\n\nIII – a natureza, a quantidade e a variedade de drogas, armas ou munições apreendidas; ou (Incluído pela Leinº 15.272, de 2025)\n\nIV – o fundado receio de reiteração delitiva, inclusive à vista da existência de outros inquéritos e ações penais em curso. (Incluído pela Leinº 15.272, de 2025)\n\n§ 4º É incabível a decretação da prisão preventiva com base em alegações de gravidade abstrata do delito, devendo ser concretamente demonstrados a periculosidade do agente e seu risco à ordem pública, à ordem econômica, à regularidade da instrução criminal e à aplicação da lei penal, conforme o caso. (Incluído pela Leinº 15.272, de 2025)"},{"chave":"art-313","sequencia":335,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO III — DA PRISÃO PREVENTIVA"],"titulo":"CAPÍTULO III — DA PRISÃO PREVENTIVA","rotulo":"Art. 313.","conteudo":"Nos termos do art. 312 deste Código , será admitida a decretação da prisão preventiva: (Redação dada pela Lei nº 12.403, de 2011).\n\nI - nos crimes dolosos punidos com pena privativa de liberdade máxima superior a 4 (quatro) anos; (Redação dada pela Lei nº 12.403, de 2011).\n\nII - se tiver sido condenado por outro crime doloso, em sentença transitada em julgado, ressalvado o disposto no inciso I do caput do art. 64 do Decreto-Lei n o 2.848, de 7 de dezembro de 1940 - Código Penal ; (Redação dada pela Lei nº 12.403, de 2011).\n\nIII - se o crime envolver violência doméstica e familiar contra a mulher, criança, adolescente, idoso, enfermo ou pessoa com deficiência, para garantir a execução das medidas protetivas de urgência; (Redação dada pela Lei nº 12.403, de 2011).\n\nIV - (revogado). (Revogado pela Lei nº 12.403, de 2011).\n\nV - se o crime for cometido por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, no contexto da atuação ou para a consecução das condutas previstas no art. 2º da lei que institui o marco legal do combate ao crime organizado no Brasil. (Incluído pela Lei nº 15.358, de 2026)\n\nVI - nos crimes contra a dignidade sexual praticados contra criança ou adolescente ou os previstos nos arts. 240 a 241-D e 244-A da Lei nº 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente). (Incluído pela Lei nº 15.487, de 2026)\n\n§ 1º Também será admitida a prisão preventiva quando houver dúvida sobre a identidade civil da pessoa ou quando esta não fornecer elementos suficientes para esclarecê-la, devendo o preso ser colocado imediatamente em liberdade após a identificação, salvo se outra hipótese recomendar a manutenção da medida. (Redação dada pela Lei nº 13.964, de 2019)\n\n§ 2º Não será admitida a decretação da prisão preventiva com a finalidade de antecipação de cumprimento de pena ou como decorrência imediata de investigação criminal ou da apresentação ou recebimento de denúncia. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-314","sequencia":336,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO III — DA PRISÃO PREVENTIVA"],"titulo":"CAPÍTULO III — DA PRISÃO PREVENTIVA","rotulo":"Art. 314.","conteudo":"A prisão preventiva em nenhum caso será decretada se o juiz verificar pelas provas constantes dos autos ter o agente praticado o fato nas condições previstas nos incisos I, II e III do caput do art. 23 do Decreto-Lei n o 2.848, de 7 de dezembro de 1940 - Código Penal . (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-315","sequencia":337,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO III — DA PRISÃO PREVENTIVA"],"titulo":"CAPÍTULO III — DA PRISÃO PREVENTIVA","rotulo":"Art. 315.","conteudo":"A decisão que decretar, substituir ou denegar a prisão preventiva será sempre motivada e fundamentada. (Redação dada pela Lei nº 13.964, de 2019)\n\n§ 1º Na motivação da decretação da prisão preventiva ou de qualquer outra cautelar, o juiz deverá indicar concretamente a existência de fatos novos ou contemporâneos que justifiquem a aplicação da medida adotada. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 2º Não se considera fundamentada qualquer decisão judicial, seja ela interlocutória, sentença ou acórdão, que: (Incluído pela Lei nº 13.964, de 2019)\n\nI - limitar-se à indicação, à reprodução ou à paráfrase de ato normativo, sem explicar sua relação com a causa ou a questão decidida; (Incluído pela Lei nº 13.964, de 2019)\n\nII - empregar conceitos jurídicos indeterminados, sem explicar o motivo concreto de sua incidência no caso; (Incluído pela Lei nº 13.964, de 2019)\n\nIII - invocar motivos que se prestariam a justificar qualquer outra decisão; (Incluído pela Lei nº 13.964, de 2019)\n\nIV - não enfrentar todos os argumentos deduzidos no processo capazes de, em tese, infirmar a conclusão adotada pelo julgador; (Incluído pela Lei nº 13.964, de 2019)\n\nV - limitar-se a invocar precedente ou enunciado de súmula, sem identificar seus fundamentos determinantes nem demonstrar que o caso sob julgamento se ajusta àqueles fundamentos; (Incluído pela Lei nº 13.964, de 2019)\n\nVI - deixar de seguir enunciado de súmula, jurisprudência ou precedente invocado pela parte, sem demonstrar a existência de distinção no caso em julgamento ou a superação do entendimento. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-316","sequencia":338,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO III — DA PRISÃO PREVENTIVA"],"titulo":"CAPÍTULO III — DA PRISÃO PREVENTIVA","rotulo":"Art. 316.","conteudo":"O juiz poderá, de ofício ou a pedido das partes, revogar a prisão preventiva se, no correr da investigação ou do processo, verificar a falta de motivo para que ela subsista, bem como novamente decretá-la, se sobrevierem razões que a justifiquem. (Redação dada pela Lei nº 13.964, de 2019) (Vigência)\n\nParágrafo único. Decretada a prisão preventiva, deverá o órgão emissor da decisão revisar a necessidade de sua manutenção a cada 90 (noventa) dias, mediante decisão fundamentada, de ofício, sob pena de tornar a prisão ilegal. (Incluído pela Lei nº 13.964, de 2019) (Vigência) (Vide ADI 6581) (Vide ADI 6582)"},{"chave":"art-317","sequencia":339,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO IV — DA PRISÃO DOMICILIAR"],"titulo":"(Redação dada pela Lei nº 12.403, de 2011).","rotulo":"Art. 317.","conteudo":"A prisão domiciliar consiste no recolhimento do indiciado ou acusado em sua residência, só podendo dela ausentar-se com autorização judicial. (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-318","sequencia":340,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO IV — DA PRISÃO DOMICILIAR"],"titulo":"CAPÍTULO IV — DA PRISÃO DOMICILIAR","rotulo":"Art. 318.","conteudo":"Poderá o juiz substituir a prisão preventiva pela domiciliar quando o agente for: (Redação dada pela Lei nº 12.403, de 2011).\n\nI - maior de 80 (oitenta) anos; (Incluído pela Lei nº 12.403, de 2011).\n\nII - extremamente debilitado por motivo de doença grave; (Incluído pela Lei nº 12.403, de 2011).\n\nIII - imprescindível aos cuidados especiais de pessoa menor de 6 (seis) anos de idade ou com deficiência; (Incluído pela Lei nº 12.403, de 2011).\n\nIV - gestante; (Redação dada pela Lei nº 13.257, de 2016)\n\nV - mulher com filho de até 12 (doze) anos de idade incompletos; (Incluído pela Lei nº 13.257, de 2016)\n\nVI - homem, caso seja o único responsável pelos cuidados do filho de até 12 (doze) anos de idade incompletos. (Incluído pela Lei nº 13.257, de 2016)\n\nParágrafo único. Para a substituição, o juiz exigirá prova idônea dos requisitos estabelecidos neste artigo. (Incluído pela Lei nº 12.403, de 2011)."},{"chave":"art-318-a","sequencia":341,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO IV — DA PRISÃO DOMICILIAR"],"titulo":"CAPÍTULO IV — DA PRISÃO DOMICILIAR","rotulo":"Art. 318º-A","conteudo":"A prisão preventiva imposta à mulher gestante ou que for mãe ou responsável por crianças ou pessoas com deficiência será substituída por prisão domiciliar, desde que: (Incluído pela Lei nº 13.769, de 2018).\n\nI - não tenha cometido crime com violência ou grave ameaça a pessoa; (Incluído pela Lei nº 13.769, de 2018).\n\nII - não tenha cometido o crime contra seu filho ou dependente. (Incluído pela Lei nº 13.769, de 2018)."},{"chave":"art-318-b","sequencia":342,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO IV — DA PRISÃO DOMICILIAR"],"titulo":"CAPÍTULO IV — DA PRISÃO DOMICILIAR","rotulo":"Art. 318º-B","conteudo":"A substituição de que tratam os arts. 318 e 318-A poderá ser efetuada sem prejuízo da aplicação concomitante das medidas alternativas previstas no art. 319 deste Código. (Incluído pela Lei nº 13.769, de 2018)."},{"chave":"art-319","sequencia":343,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO V — DAS OUTRAS MEDIDAS CAUTELARES"],"titulo":"(Redação dada pela Lei nº 12.403, de 2011).","rotulo":"Art. 319.","conteudo":"São medidas cautelares diversas da prisão: (Redação dada pela Lei nº 12.403, de 2011).\n\nI - comparecimento periódico em juízo, no prazo e nas condições fixadas pelo juiz, para informar e justificar atividades; (Redação dada pela Lei nº 12.403, de 2011).\n\nII - proibição de acesso ou frequência a determinados lugares quando, por circunstâncias relacionadas ao fato, deva o indiciado ou acusado permanecer distante desses locais para evitar o risco de novas infrações; (Redação dada pela Lei nº 12.403, de 2011).\n\nIII - proibição de manter contato com pessoa determinada quando, por circunstâncias relacionadas ao fato, deva o indiciado ou acusado dela permanecer distante; (Redação dada pela Lei nº 12.403, de 2011).\n\nIV - proibição de ausentar-se da Comarca quando a permanência seja conveniente ou necessária para a investigação ou instrução; (Incluído pela Lei nº 12.403, de 2011).\n\nV - recolhimento domiciliar no período noturno e nos dias de folga quando o investigado ou acusado tenha residência e trabalho fixos; (Incluído pela Lei nº 12.403, de 2011).\n\nVI - suspensão do exercício de função pública ou de atividade de natureza econômica ou financeira quando houver justo receio de sua utilização para a prática de infrações penais; (Incluído pela Lei nº 12.403, de 2011).\n\nVII - internação provisória do acusado nas hipóteses de crimes praticados com violência ou grave ameaça, quando os peritos concluírem ser inimputável ou semi-imputável (art. 26 do Código Penal) e houver risco de reiteração; (Incluído pela Lei nº 12.403, de 2011).\n\nVIII - fiança, nas infrações que a admitem, para assegurar o comparecimento a atos do processo, evitar a obstrução do seu andamento ou em caso de resistência injustificada à ordem judicial; (Incluído pela Lei nº 12.403, de 2011).\n\nIX - monitoração eletrônica. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 1 o (Revogado). (Revogado pela Lei nº 12.403, de 2011).\n\n§ 2 o (Revogado). (Revogado pela Lei nº 12.403, de 2011).\n\n§ 3 o (Revogado). (Revogado pela Lei nº 12.403, de 2011).\n\n§ 4 o A fiança será aplicada de acordo com as disposições do Capítulo VI deste Título, podendo ser cumulada com outras medidas cautelares. (Incluído pela Lei nº 12.403, de 2011)."},{"chave":"art-320","sequencia":344,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO V — DAS OUTRAS MEDIDAS CAUTELARES"],"titulo":"CAPÍTULO V — DAS OUTRAS MEDIDAS CAUTELARES","rotulo":"Art. 320.","conteudo":"A proibição de ausentar-se do País será comunicada pelo juiz às autoridades encarregadas de fiscalizar as saídas do território nacional, intimando-se o indiciado ou acusado para entregar o passaporte, no prazo de 24 (vinte e quatro) horas. (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-321","sequencia":345,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 321.","conteudo":"Ausentes os requisitos que autorizam a decretação da prisão preventiva, o juiz deverá conceder liberdade provisória, impondo, se for o caso, as medidas cautelares previstas no art. 319 deste Código e observados os critérios constantes do art. 282 deste Código . (Redação dada pela Lei nº 12.403, de 2011).\n\nI - (revogado) (Revogado pela Lei nº 12.403, de 2011).\n\nII - (revogado). (Revogado pela Lei nº 12.403, de 2011)."},{"chave":"art-322","sequencia":346,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 322.","conteudo":"A autoridade policial somente poderá conceder fiança nos casos de infração cuja pena privativa de liberdade máxima não seja superior a 4 (quatro) anos. (Redação dada pela Lei nº 12.403, de 2011).\n\nParágrafo único. Nos demais casos, a fiança será requerida ao juiz, que decidirá em 48 (quarenta e oito) horas. (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-323","sequencia":347,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 323.","conteudo":"Não será concedida fiança: (Redação dada pela Lei nº 12.403, de 2011).\n\nI - nos crimes de racismo; (Redação dada pela Lei nº 12.403, de 2011).\n\nII - nos crimes de tortura, tráfico ilícito de entorpecentes e drogas afins, terrorismo e nos definidos como crimes hediondos; (Redação dada pela Lei nº 12.403, de 2011).\n\nIII - nos crimes cometidos por grupos armados, civis ou militares, contra a ordem constitucional e o Estado Democrático; (Redação dada pela Lei nº 12.403, de 2011).\n\nIV - (revogado); (Revogado pela Lei nº 12.403, de 2011).\n\nV - (revogado). (Revogado pela Lei nº 12.403, de 2011)."},{"chave":"art-324","sequencia":348,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 324.","conteudo":"Não será, igualmente, concedida fiança: (Redação dada pela Lei nº 12.403, de 2011).\n\nI - aos que, no mesmo processo, tiverem quebrado fiança anteriormente concedida ou infringido, sem motivo justo, qualquer das obrigações a que se referem os arts. 327 e 328 deste Código ; (Redação dada pela Lei nº 12.403, de 2011).\n\nII - em caso de prisão civil ou militar; (Redação dada pela Lei nº 12.403, de 2011).\n\nIII - (revogado); (Revogado pela Lei nº 12.403, de 2011).\n\nIV - quando presentes os motivos que autorizam a decretação da prisão preventiva ( art. 312 ). (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-325","sequencia":349,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 325.","conteudo":"O valor da fiança será fixado pela autoridade que a conceder nos seguintes limites: (Redação dada pela Lei nº 12.403, de 2011).\n\na) (revogada); (Redação dada pela Lei nº 12.403, de 2011).\n\nb) (revogada); (Redação dada pela Lei nº 12.403, de 2011).\n\nc) (revogada). (Redação dada pela Lei nº 12.403, de 2011).\n\nI - de 1 (um) a 100 (cem) salários mínimos, quando se tratar de infração cuja pena privativa de liberdade, no grau máximo, não for superior a 4 (quatro) anos; (Incluído pela Lei nº 12.403, de 2011).\n\nII - de 10 (dez) a 200 (duzentos) salários mínimos, quando o máximo da pena privativa de liberdade cominada for superior a 4 (quatro) anos. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 1 o Se assim recomendar a situação econômica do preso, a fiança poderá ser: (Redação dada pela Lei nº 12.403, de 2011).\n\nI - dispensada, na forma do art. 350 deste Código ; (Redação dada pela Lei nº 12.403, de 2011).\n\nII - reduzida até o máximo de 2/3 (dois terços); ou (Redação dada pela Lei nº 12.403, de 2011).\n\nIII - aumentada em até 1.000 (mil) vezes. (Incluído pela Lei nº 12.403, de 2011).\n\n§ 2 o (Revogado): (Revogado pela Lei nº 12.403, de 2011).\n\nI - (revogado); (Revogado pela Lei nº 12.403, de 2011).\n\nII - (revogado); (Revogado pela Lei nº 12.403, de 2011).\n\nIII - (revogado). (Revogado pela Lei nº 12.403, de 2011)."},{"chave":"art-326","sequencia":350,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 326.","conteudo":"Para determinar o valor da fiança, a autoridade terá em consideração a natureza da infração, as condições pessoais de fortuna e vida pregressa do acusado, as circunstâncias indicativas de sua periculosidade, bem como a importância provável das custas do processo, até final julgamento."},{"chave":"art-327","sequencia":351,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 327.","conteudo":"A fiança tomada por termo obrigará o afiançado a comparecer perante a autoridade, todas as vezes que for intimado para atos do inquérito e da instrução criminal e para o julgamento. Quando o réu não comparecer, a fiança será havida como quebrada."},{"chave":"art-328","sequencia":352,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 328.","conteudo":"O réu afiançado não poderá, sob pena de quebramento da fiança, mudar de residência, sem prévia permissão da autoridade processante, ou ausentar-se por mais de 8 (oito) dias de sua residência, sem comunicar àquela autoridade o lugar onde será encontrado."},{"chave":"art-329","sequencia":353,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 329.","conteudo":"Nos juízos criminais e delegacias de polícia, haverá um livro especial, com termos de abertura e de encerramento, numerado e rubricado em todas as suas folhas pela autoridade, destinado especialmente aos termos de fiança. O termo será lavrado pelo escrivão e assinado pela autoridade e por quem prestar a fiança, e dele extrair-se-á certidão para juntar-se aos autos.\n\nParágrafo único. O réu e quem prestar a fiança serão pelo escrivão notificados das obrigações e da sanção previstas nos arts. 327 e 328 , o que constará dos autos."},{"chave":"art-330","sequencia":354,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 330.","conteudo":"A fiança, que será sempre definitiva, consistirá em depósito de dinheiro, pedras, objetos ou metais preciosos, títulos da dívida pública, federal, estadual ou municipal, ou em hipoteca inscrita em primeiro lugar.\n\n§ 1 o A avaliação de imóvel, ou de pedras, objetos ou metais preciosos será feita imediatamente por perito nomeado pela autoridade.\n\n§ 2 o Quando a fiança consistir em caução de títulos da dívida pública, o valor será determinado pela sua cotação em Bolsa, e, sendo nominativos, exigir-se-á prova de que se acham livres de ônus."},{"chave":"art-331","sequencia":355,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 331.","conteudo":"O valor em que consistir a fiança será recolhido à repartição arrecadadora federal ou estadual, ou entregue ao depositário público, juntando-se aos autos os respectivos conhecimentos.\n\nParágrafo único. Nos lugares em que o depósito não se puder fazer de pronto, o valor será entregue ao escrivão ou pessoa abonada, a critério da autoridade, e dentro de três dias dar-se-á ao valor o destino que Ihe assina este artigo, o que tudo constará do termo de fiança."},{"chave":"art-332","sequencia":356,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 332.","conteudo":"Em caso de prisão em flagrante, será competente para conceder a fiança a autoridade que presidir ao respectivo auto, e, em caso de prisão por mandado, o juiz que o houver expedido, ou a autoridade judiciária ou policial a quem tiver sido requisitada a prisão."},{"chave":"art-333","sequencia":357,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 333.","conteudo":"Depois de prestada a fiança, que será concedida independentemente de audiência do Ministério Público, este terá vista do processo a fim de requerer o que julgar conveniente."},{"chave":"art-334","sequencia":358,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 334.","conteudo":"A fiança poderá ser prestada enquanto não transitar em julgado a sentença condenatória. (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-335","sequencia":359,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 335.","conteudo":"Recusando ou retardando a autoridade policial a concessão da fiança, o preso, ou alguém por ele, poderá prestá-la, mediante simples petição, perante o juiz competente, que decidirá em 48 (quarenta e oito) horas. (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-336","sequencia":360,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 336.","conteudo":"O dinheiro ou objetos dados como fiança servirão ao pagamento das custas, da indenização do dano, da prestação pecuniária e da multa, se o réu for condenado. (Redação dada pela Lei nº 12.403, de 2011).\n\nParágrafo único. Este dispositivo terá aplicação ainda no caso da prescrição depois da sentença condenatória ( ). (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-337","sequencia":361,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 337.","conteudo":"Se a fiança for declarada sem efeito ou passar em julgado sentença que houver absolvido o acusado ou declarada extinta a ação penal, o valor que a constituir, atualizado, será restituído sem desconto, salvo o disposto no parágrafo único do art. 336 deste Código . (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-338","sequencia":362,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 338.","conteudo":"A fiança que se reconheça não ser cabível na espécie será cassada em qualquer fase do processo."},{"chave":"art-339","sequencia":363,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 339.","conteudo":"Será também cassada a fiança quando reconhecida a existência de delito inafiançável, no caso de inovação na classificação do delito."},{"chave":"art-340","sequencia":364,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 340.","conteudo":"Será exigido o reforço da fiança:\n\nI - quando a autoridade tomar, por engano, fiança insuficiente;\n\nII - quando houver depreciação material ou perecimento dos bens hipotecados ou caucionados, ou depreciação dos metais ou pedras preciosas;\n\nIII - quando for inovada a classificação do delito.\n\nParágrafo único. A fiança ficará sem efeito e o réu será recolhido à prisão, quando, na conformidade deste artigo, não for reforçada."},{"chave":"art-341","sequencia":365,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 341.","conteudo":"Julgar-se-á quebrada a fiança quando o acusado: (Redação dada pela Lei nº 12.403, de 2011).\n\nI - regularmente intimado para ato do processo, deixar de comparecer, sem motivo justo; (Incluído pela Lei nº 12.403, de 2011).\n\nII - deliberadamente praticar ato de obstrução ao andamento do processo; (Incluído pela Lei nº 12.403, de 2011).\n\nIII - descumprir medida cautelar imposta cumulativamente com a fiança; (Incluído pela Lei nº 12.403, de 2011).\n\nIV - resistir injustificadamente a ordem judicial; (Incluído pela Lei nº 12.403, de 2011).\n\nV - praticar nova infração penal dolosa. (Incluído pela Lei nº 12.403, de 2011)."},{"chave":"art-342","sequencia":366,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 342.","conteudo":"Se vier a ser reformado o julgamento em que se declarou quebrada a fiança, esta subsistirá em todos os seus efeitos"},{"chave":"art-343","sequencia":367,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 343.","conteudo":"O quebramento injustificado da fiança importará na perda de metade do seu valor, cabendo ao juiz decidir sobre a imposição de outras medidas cautelares ou, se for o caso, a decretação da prisão preventiva. (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-344","sequencia":368,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 344.","conteudo":"Entender-se-á perdido, na totalidade, o valor da fiança, se, condenado, o acusado não se apresentar para o início do cumprimento da pena definitivamente imposta. (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-345","sequencia":369,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 345.","conteudo":"No caso de perda da fiança, o seu valor, deduzidas as custas e mais encargos a que o acusado estiver obrigado, será recolhido ao fundo penitenciário, na forma da lei. (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-346","sequencia":370,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 346.","conteudo":"No caso de quebramento de fiança, feitas as deduções previstas no art. 345 deste Código , o valor restante será recolhido ao fundo penitenciário, na forma da lei. (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-347","sequencia":371,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 347.","conteudo":"Não ocorrendo a hipótese do art. 345 , o saldo será entregue a quem houver prestado a fiança, depois de deduzidos os encargos a que o réu estiver obrigado."},{"chave":"art-348","sequencia":372,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 348.","conteudo":"Nos casos em que a fiança tiver sido prestada por meio de hipoteca, a execução será promovida no juízo cível pelo órgão do Ministério Público."},{"chave":"art-349","sequencia":373,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 349.","conteudo":"Se a fiança consistir em pedras, objetos ou metais preciosos, o juiz determinará a venda por leiloeiro ou corretor."},{"chave":"art-350","sequencia":374,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — DA PRISÃO, DAS MEDIDAS CAUTELARES E DA LIBERDADE PROVISÓRIA","CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA"],"titulo":"CAPÍTULO VI — DA LIBERDADE PROVISÓRIA, COM OU SEM FIANÇA","rotulo":"Art. 350.","conteudo":"Nos casos em que couber fiança, o juiz, verificando a situação econômica do preso, poderá conceder-lhe liberdade provisória, sujeitando-o às obrigações constantes dos arts. 327 e 328 deste Código e a outras medidas cautelares, se for o caso. (Redação dada pela Lei nº 12.403, de 2011).\n\nParágrafo único. Se o beneficiado descumprir, sem motivo justo, qualquer das obrigações ou medidas impostas, aplicar-se-á o disposto no § 4 o do art. 282 deste Código . (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-350-a","sequencia":375,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — A"],"titulo":"DAS MEDIDAS PROTETIVAS DE URGÊNCIA”","rotulo":"Art. 350º-A","conteudo":"Constatada a existência de indícios da prática de crime contra a dignidade sexual, o juiz poderá aplicar, de imediato, ao autor, em conjunto ou separadamente, as seguintes medidas protetivas de urgência, entre outras: (Incluído pela Lei nº 15.280, de 2025)\n\nI – suspensão da posse ou restrição do porte de armas, com comunicação ao órgão competente, nos termos da Lei nº 10.826, de 22 de dezembro de 2003 (Estatuto do Desarmamento); (Incluído pela Lei nº 15.280, de 2025)\n\nII – afastamento do lar, domicílio ou local de convivência com a vítima, se aplicável; (Incluído pela Lei nº 15.280, de 2025)\n\nIII – proibição de determinadas condutas, entre as quais: (Incluído pela Lei nº 15.280, de 2025)\n\na) aproximação da vítima, de seus familiares e das testemunhas, fixando o limite mínimo de distância entre esses e o autor; (Incluído pela Lei nº 15.280, de 2025)\n\nb) contato com a vítima, seus familiares e testemunhas por qualquer meio de comunicação; (Incluído pela Lei nº 15.280, de 2025)\n\nc) frequentação de determinados lugares a fim de preservar a integridade física e psicológica da vítima; (Incluído pela Lei nº 15.280, de 2025)\n\nIV – restrição ou suspensão de visitas aos dependentes menores, ouvida a equipe de atendimento multidisciplinar ou serviço similar; (Incluído pela Lei nº 15.280, de 2025)\n\nV – prestação de alimentos provisionais ou provisórios; (Incluído pela Lei nº 15.280, de 2025)\n\nVI – comparecimento do autor a programas de recuperação e reeducação; (Incluído pela Lei nº 15.280, de 2025)\n\nVII – acompanhamento psicossocial do autor, por meio de atendimento individual e/ou em grupo de apoio. (Incluído pela Lei nº 15.280, de 2025)\n\n§ 1º As medidas referidas neste artigo não impedem a aplicação de outras previstas na legislação em vigor, sempre que a segurança da vítima ou as circunstâncias o exigirem, devendo a providência ser comunicada ao Ministério Público. (Incluído pela Lei nº 15.280, de 2025)\n\n§ 2º Na hipótese de aplicação do inciso I do caput deste artigo, encontrando-se o autor nas condições mencionadas no caput e nos incisos do art. 6º da Lei nº 10.826, de 22 de dezembro de 2003 (Estatuto do Desarmamento), o juiz comunicará ao respectivo órgão, corporação ou instituição as medidas protetivas de urgência concedidas e determinará a restrição do porte de armas, ficando o superior imediato do autor responsável pelo cumprimento da determinação judicial, sob pena de incorrer nos crimes de prevaricação ou de desobediência, conforme o caso. (Incluído pela Lei nº 15.280, de 2025)\n\n§ 3º Para garantir a efetividade das medidas protetivas de urgência, poderá o juiz requisitar, a qualquer momento, auxílio da força policial. (Incluído pela Lei nº 15.280, de 2025)\n\n§ 4º Aplica-se às hipóteses previstas neste artigo, no que couber, o disposto na Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil). (Incluído pela Lei nº 15.280, de 2025)\n\n§ 5º Nos casos previstos neste artigo, a medida protetiva de urgência será cumulada com a sujeição do autor a monitoração eletrônica, disponibilizando-se à vítima dispositivo de segurança que alerte sobre sua eventual aproximação. (Incluído pela Lei nº 15.280, de 2025)\n\n§ 6º O disposto neste artigo aplica-se, ainda, aos crimes cuja vítima esteja em situação de vulnerabilidade, como crianças, adolescentes, pessoas com deficiência ou incapazes, qualquer que seja o crime investigado. (Incluído pela Lei nº 15.280, de 2025)"},{"chave":"art-350-b","sequencia":376,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO IX — A"],"titulo":"TÍTULO IX — A","rotulo":"Art. 350º-B","conteudo":"Em qualquer fase da investigação policial ou do processo penal, a pedido da autoridade policial, do Ministério Público ou da vítima, o juiz poderá determinar a proibição do autor de exercer atividades que envolvam contato direto com pessoa em situação de vulnerabilidade, quando houver prova da existência do crime, indício suficiente de autoria e perigo gerado pelo estado de liberdade do imputado. (Incluído pela Lei nº 15.280, de 2025)"},{"chave":"art-351","sequencia":377,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 351.","conteudo":"A citação inicial far-se-á por mandado, quando o réu estiver no território sujeito à jurisdição do juiz que a houver ordenado."},{"chave":"art-352","sequencia":378,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 352.","conteudo":"O mandado de citação indicará:\n\nI - o nome do juiz;\n\nII - o nome do querelante nas ações iniciadas por queixa;\n\nIII - o nome do réu, ou, se for desconhecido, os seus sinais característicos;\n\nIV - a residência do réu, se for conhecida;\n\nV - o fim para que é feita a citação;\n\nVI - o juízo e o lugar, o dia e a hora em que o réu deverá comparecer;\n\nVII - a subscrição do escrivão e a rubrica do juiz."},{"chave":"art-353","sequencia":379,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 353.","conteudo":"Quando o réu estiver fora do território da jurisdição do juiz processante, será citado mediante precatória."},{"chave":"art-354","sequencia":380,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 354.","conteudo":"A precatória indicará:\n\nI - o juiz deprecado e o juiz deprecante;\n\nII - a sede da jurisdição de um e de outro;\n\nIll - o fim para que é feita a citação, com todas as especificações;\n\nIV - o juízo do lugar, o dia e a hora em que o réu deverá comparecer."},{"chave":"art-355","sequencia":381,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 355.","conteudo":"A precatória será devolvida ao juiz deprecante, independentemente de traslado, depois de lançado o \"cumpra-se\" e de feita a citação por mandado do juiz deprecado.\n\n§ 1 o Verificado que o réu se encontra em território sujeito à jurisdição de outro juiz, a este remeterá o juiz deprecado os autos para efetivação da diligência, desde que haja tempo para fazer-se a citação.\n\n§ 2 o Certificado pelo oficial de justiça que o réu se oculta para não ser citado, a precatória será imediatamente devolvida, para o fim previsto no art. 362 ."},{"chave":"art-356","sequencia":382,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 356.","conteudo":"Se houver urgência, a precatória, que conterá em resumo os requisitos enumerados no art. 354, poderá ser expedida por via telegráfica, depois de reconhecida a firma do juiz, o que a estação expedidora mencionará."},{"chave":"art-357","sequencia":383,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 357.","conteudo":"São requisitos da citação por mandado:\n\nI - leitura do mandado ao citando pelo oficial e entrega da contrafé, na qual se mencionarão dia e hora da citação;\n\nII - declaração do oficial, na certidão, da entrega da contrafé, e sua aceitação ou recusa."},{"chave":"art-358","sequencia":384,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 358.","conteudo":"A citação do militar far-se-á por intermédio do chefe do respectivo serviço."},{"chave":"art-359","sequencia":385,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 359.","conteudo":"O dia designado para funcionário público comparecer em juízo, como acusado, será notificado assim a ele como ao chefe de sua repartição."},{"chave":"art-360","sequencia":386,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 360.","conteudo":"Se o réu estiver preso, será pessoalmente citado. (Redação dada pela Lei nº 10.792, de 1º.12.2003)"},{"chave":"art-361","sequencia":387,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 361.","conteudo":"Se o réu não for encontrado, será citado por edital, com o prazo de 15 (quinze) dias."},{"chave":"art-362","sequencia":388,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 362.","conteudo":"Verificando que o réu se oculta para não ser citado, o oficial de justiça certificará a ocorrência e procederá à citação com hora certa, na forma estabelecida nos arts. 227 a 229 da Lei n o 5.869, de 11 de janeiro de 1973 - Código de Processo Civil . (Redação dada pela Lei nº 11.719, de 2008).\n\nParágrafo único. Completada a citação com hora certa, se o acusado não comparecer, ser-lhe-á nomeado defensor dativo. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-363","sequencia":389,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 363.","conteudo":"O processo terá completada a sua formação quando realizada a citação do acusado. (Redação dada pela Lei nº 11.719, de 2008).\n\nI - (revogado); (Redação dada pela Lei nº 11.719, de 2008).\n\nII - (revogado). (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o Não sendo encontrado o acusado, será procedida a citação por edital. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 2 o (VETADO) (Incluído pela Lei nº 11.719, de 2008).\n\n§ 3 o (VETADO) (Incluído pela Lei nº 11.719, de 2008).\n\n§ 4 o Comparecendo o acusado citado por edital, em qualquer tempo, o processo observará o disposto nos arts. 394 e seguintes deste Código. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-364","sequencia":390,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 364.","conteudo":"No caso do artigo anterior, n o I, o prazo será fixado pelo juiz entre 15 (quinze) e 90 (noventa) dias, de acordo com as circunstâncias, e, no caso de n o II, o prazo será de trinta dias."},{"chave":"art-365","sequencia":391,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 365.","conteudo":"O edital de citação indicará:\n\nI - o nome do juiz que a determinar;\n\nII - o nome do réu, ou, se não for conhecido, os seus sinais característicos, bem como sua residência e profissão, se constarem do processo;\n\nIII - o fim para que é feita a citação;\n\nIV - o juízo e o dia, a hora e o lugar em que o réu deverá comparecer;\n\nV - o prazo, que será contado do dia da publicação do edital na imprensa, se houver, ou da sua afixação.\n\nParágrafo único. O edital será afixado à porta do edifício onde funcionar o juízo e será publicado pela imprensa, onde houver, devendo a afixação ser certificada pelo oficial que a tiver feito e a publicação provada por exemplar do jornal ou certidão do escrivão, da qual conste a página do jornal com a data da publicação."},{"chave":"art-366","sequencia":392,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 366.","conteudo":"Se o acusado, citado por edital, não comparecer, nem constituir advogado, ficarão suspensos o processo e o curso do prazo prescricional, podendo o juiz determinar a produção antecipada das provas consideradas urgentes e, se for o caso, decretar prisão preventiva, nos termos do disposto no art. 312 . (Redação dada pela Lei nº 9.271, de 17.4.1996)\n\n§ 1 o (Revogado pela Lei nº 11.719, de 2008).\n\n§ 2 o (Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-367","sequencia":393,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 367.","conteudo":"O processo seguirá sem a presença do acusado que, citado ou intimado pessoalmente para qualquer ato, deixar de comparecer sem motivo justificado, ou, no caso de mudança de residência, não comunicar o novo endereço ao juízo. (Redação dada pela Lei nº 9.271, de 17.4.1996)"},{"chave":"art-368","sequencia":394,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 368.","conteudo":"Estando o acusado no estrangeiro, em lugar sabido, será citado mediante carta rogatória, suspendendo-se o curso do prazo de prescrição até o seu cumprimento. (Redação dada pela Lei nº 9.271, de 17.4.1996)"},{"chave":"art-369","sequencia":395,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO I — DAS CITAÇÕES"],"titulo":"CAPÍTULO I — DAS CITAÇÕES","rotulo":"Art. 369.","conteudo":"As citações que houverem de ser feitas em legações estrangeiras serão efetuadas mediante carta rogatória. (Redação dada pela Lei nº 9.271, de 17.4.1996)"},{"chave":"art-370","sequencia":396,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO II — DAS INTIMAÇÕES"],"titulo":"CAPÍTULO II — DAS INTIMAÇÕES","rotulo":"Art. 370.","conteudo":"Nas intimações dos acusados, das testemunhas e demais pessoas que devam tomar conhecimento de qualquer ato, será observado, no que for aplicável, o disposto no Capítulo anterior. (Redação dada pela Lei nº 9.271, de 17.4.1996)\n\n§ 1 o A intimação do defensor constituído, do advogado do querelante e do assistente far-se-á por publicação no órgão incumbido da publicidade dos atos judiciais da comarca, incluindo, sob pena de nulidade, o nome do acusado. (Incluído Lei nº 9.271, de 17.4.1996)\n\n§ 2 o Caso não haja órgão de publicação dos atos judiciais na comarca, a intimação far-se-á diretamente pelo escrivão, por mandado, ou via postal com comprovante de recebimento, ou por qualquer outro meio idôneo. (Redação dada pela Lei nº 9.271, de 17.4.1996)\n\n§ 3 o A intimação pessoal, feita pelo escrivão, dispensará a aplicação a que alude o § 1 o . (Incluído pela Lei nº 9.271, de 17.4.1996)\n\n§ 4 o A intimação do Ministério Público e do defensor nomeado será pessoal. (Incluído pela Lei nº 9.271, de 17.4.1996)"},{"chave":"art-371","sequencia":397,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO II — DAS INTIMAÇÕES"],"titulo":"CAPÍTULO II — DAS INTIMAÇÕES","rotulo":"Art. 371.","conteudo":"Será admissível a intimação por despacho na petição em que for requerida, observado o disposto no art. 357 ."},{"chave":"art-372","sequencia":398,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO X — DAS CITAÇÕES E INTIMAÇÕES","CAPÍTULO II — DAS INTIMAÇÕES"],"titulo":"CAPÍTULO II — DAS INTIMAÇÕES","rotulo":"Art. 372.","conteudo":"Adiada, por qualquer motivo, a instrução criminal, o juiz marcará desde logo, na presença das partes e testemunhas, dia e hora para seu prosseguimento, do que se lavrará termo nos autos."},{"chave":"art-373","sequencia":399,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA","rotulo":"Art. 373.","conteudo":"A aplicação provisória de interdições de direitos poderá ser determinada pelo juiz, de ofício, ou a requerimento do Ministério Público, do querelante, do assistente, do ofendido, ou de seu representante legal, ainda que este não se tenha constituído como assistente:\n\nI - durante a instrução criminal após a apresentação da defesa ou do prazo concedido para esse fim;\n\nII - na sentença de pronúncia;\n\nIII - na decisão confirmatória da pronúncia ou na que, em grau de recurso, pronunciar o réu;\n\nIV - na sentença condenatória recorrível.\n\n§ 1 o No caso do n o I, havendo requerimento de aplicação da medida, o réu ou seu defensor será ouvido no prazo de 2 (dois) dias.\n\n§ 2 o Decretada a medida, serão feitas as comunicações necessárias para a sua execução, na forma do disposto no Capítulo III do Título II do Livro IV ."},{"chave":"art-374","sequencia":400,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA","rotulo":"Art. 374.","conteudo":"Não caberá recurso do despacho ou da parte da sentença que decretar ou denegar a aplicação provisória de interdições de direitos, mas estas poderão ser substituídas ou revogadas:\n\nI - se aplicadas no curso da instrução criminal, durante esta ou pelas sentenças a que se referem os ns. II, III e IV do artigo anterior;\n\nII - se aplicadas na sentença de pronúncia, pela decisão que, em grau de recurso, a confirmar, total ou parcialmente, ou pela sentença condenatória recorrível;\n\nIII - se aplicadas na decisão a que se refere o n o III do artigo anterior, pela sentença condenatória recorrível."},{"chave":"art-375","sequencia":401,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA","rotulo":"Art. 375.","conteudo":"O despacho que aplicar, provisoriamente, substituir ou revogar interdição de direito, será fundamentado."},{"chave":"art-376","sequencia":402,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA","rotulo":"Art. 376.","conteudo":"A decisão que impronunciar ou absolver o réu fará cessar a aplicação provisória da interdição anteriormente determinada."},{"chave":"art-377","sequencia":403,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA","rotulo":"Art. 377.","conteudo":"Transitando em julgado a sentença condenatória, serão executadas somente as interdições nela aplicadas ou que derivarem da imposição da pena principal."},{"chave":"art-378","sequencia":404,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA","rotulo":"Art. 378.","conteudo":"A aplicação provisória de medida de segurança obedecerá ao disposto nos artigos anteriores, com as modificações seguintes:\n\nI - o juiz poderá aplicar, provisoriamente, a medida de segurança, de ofício, ou a requerimento do Ministério Público;\n\nII - a aplicação poderá ser determinada ainda no curso do inquérito, mediante representação da autoridade policial;\n\nIII - a aplicação provisória de medida de segurança, a substituição ou a revogação da anteriormente aplicada poderão ser determinadas, também, na sentença absolutória;\n\nIV - decretada a medida, atender-se-á ao disposto no Título V do Livro IV , no que for aplicável."},{"chave":"art-379","sequencia":405,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA","rotulo":"Art. 379.","conteudo":"Transitando em julgado a sentença, observar-se-á, quanto à execução das medidas de segurança definitivamente aplicadas, o disposto no Título V do Livro IV ."},{"chave":"art-380","sequencia":406,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO XI — DA APLICAÇÃO PROVISÓRIA DE INTERDIÇÕES DE DIREITOS E MEDIDAS DE SEGURANÇA","rotulo":"Art. 380.","conteudo":"A aplicação provisória de medida de segurança obstará a concessão de fiança, e tornará sem efeito a anteriormente concedida."},{"chave":"art-381","sequencia":407,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 381.","conteudo":"A sentença conterá:\n\nI - os nomes das partes ou, quando não possível, as indicações necessárias para identificá-las;\n\nII - a exposição sucinta da acusação e da defesa;\n\nIII - a indicação dos motivos de fato e de direito em que se fundar a decisão;\n\nIV - a indicação dos artigos de lei aplicados;\n\nV - o dispositivo;\n\nVI - a data e a assinatura do juiz."},{"chave":"art-382","sequencia":408,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 382.","conteudo":"Qualquer das partes poderá, no prazo de 2 (dois) dias, pedir ao juiz que declare a sentença, sempre que nela houver obscuridade, ambigüidade, contradição ou omissão."},{"chave":"art-383","sequencia":409,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 383.","conteudo":"O juiz, sem modificar a descrição do fato contida na denúncia ou queixa, poderá atribuir-lhe definição jurídica diversa, ainda que, em conseqüência, tenha de aplicar pena mais grave. (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o Se, em conseqüência de definição jurídica diversa, houver possibilidade de proposta de suspensão condicional do processo, o juiz procederá de acordo com o disposto na lei. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 2 o Tratando-se de infração da competência de outro juízo, a este serão encaminhados os autos. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-384","sequencia":410,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 384.","conteudo":"Encerrada a instrução probatória, se entender cabível nova definição jurídica do fato, em conseqüência de prova existente nos autos de elemento ou circunstância da infração penal não contida na acusação, o Ministério Público deverá aditar a denúncia ou queixa, no prazo de 5 (cinco) dias, se em virtude desta houver sido instaurado o processo em crime de ação pública, reduzindo-se a termo o aditamento, quando feito oralmente. (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o Não procedendo o órgão do Ministério Público ao aditamento, aplica-se o art. 28 deste Código. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 2 o Ouvido o defensor do acusado no prazo de 5 (cinco) dias e admitido o aditamento, o juiz, a requerimento de qualquer das partes, designará dia e hora para continuação da audiência, com inquirição de testemunhas, novo interrogatório do acusado, realização de debates e julgamento. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 3 o Aplicam-se as disposições dos §§ 1 o e 2 o do art. 383 ao caput deste artigo. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 4 o Havendo aditamento, cada parte poderá arrolar até 3 (três) testemunhas, no prazo de 5 (cinco) dias, ficando o juiz, na sentença, adstrito aos termos do aditamento. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 5 o Não recebido o aditamento, o processo prosseguirá. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-385","sequencia":411,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 385.","conteudo":"Nos crimes de ação pública, o juiz poderá proferir sentença condenatória, ainda que o Ministério Público tenha opinado pela absolvição, bem como reconhecer agravantes, embora nenhuma tenha sido alegada."},{"chave":"art-386","sequencia":412,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 386.","conteudo":"O juiz absolverá o réu, mencionando a causa na parte dispositiva, desde que reconheça:\n\nI - estar provada a inexistência do fato;\n\nII - não haver prova da existência do fato;\n\nIII - não constituir o fato infração penal;\n\nIV – estar provado que o réu não concorreu para a infração penal; (Redação dada pela Lei nº 11.690, de 2008)\n\nV – não existir prova de ter o réu concorrido para a infração penal; (Redação dada pela Lei nº 11.690, de 2008)\n\nVI – existirem circunstâncias que excluam o crime ou isentem o réu de pena ( arts. 20, 21, 22, 23 , 26 e § 1º do art. 28, todos do Código Penal) , ou mesmo se houver fundada dúvida sobre sua existência; (Redação dada pela Lei nº 11.690, de 2008)\n\nVII – não existir prova suficiente para a condenação. (Incluído pela Lei nº 11.690, de 2008)\n\nParágrafo único. Na sentença absolutória, o juiz:\n\nI - mandará, se for o caso, pôr o réu em liberdade;\n\nII – ordenará a cessação das medidas cautelares e provisoriamente aplicadas; (Redação dada pela Lei nº 11.690, de 2008)\n\nIII - aplicará medida de segurança, se cabível."},{"chave":"art-387","sequencia":413,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 387.","conteudo":"O juiz, ao proferir sentença condenatória: (Vide Lei nº 11.719, de 2008)\n\nI - mencionará as circunstâncias agravantes ou atenuantes definidas no Código Penal , e cuja existência reconhecer;\n\nII - mencionará as outras circunstâncias apuradas e tudo o mais que deva ser levado em conta na aplicação da pena, de acordo com o disposto nos arts. 59 e 60 do Decreto-Lei n o 2.848, de 7 de dezembro de 1940 - Código Penal ; (Redação dada pela Lei nº 11.719, de 2008).\n\nIII - aplicará as penas de acordo com essas conclusões; (Redação dada pela Lei nº 11.719, de 2008).\n\nIV - fixará valor mínimo para reparação dos danos causados pela infração, considerando os prejuízos sofridos pelo ofendido; (Redação dada pela Lei nº 11.719, de 2008).\n\nV - atenderá, quanto à aplicação provisória de interdições de direitos e medidas de segurança, ao disposto no Título Xl deste Livro ;\n\nVI - determinará se a sentença deverá ser publicada na íntegra ou em resumo e designará o jornal em que será feita a publicação ( art. 73, § 1 o , do Código Penal ).\n\n§ 1 o O juiz decidirá, fundamentadamente, sobre a manutenção ou, se for o caso, a imposição de prisão preventiva ou de outra medida cautelar, sem prejuízo do conhecimento de apelação que vier a ser interposta. (Incluído pela Lei nº 12.736, de 2012)\n\n§ 2 o O tempo de prisão provisória, de prisão administrativa ou de internação, no Brasil ou no estrangeiro, será computado para fins de determinação do regime inicial de pena privativa de liberdade. (Incluído pela Lei nº 12.736, de 2012)"},{"chave":"art-388","sequencia":414,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 388.","conteudo":"A sentença poderá ser datilografada e neste caso o juiz a rubricará em todas as folhas."},{"chave":"art-389","sequencia":415,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 389.","conteudo":"A sentença será publicada em mão do escrivão, que lavrará nos autos o respectivo termo, registrando-a em livro especialmente destinado a esse fim."},{"chave":"art-390","sequencia":416,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 390.","conteudo":"O escrivão, dentro de três dias após a publicação, e sob pena de suspensão de cinco dias, dará conhecimento da sentença ao órgão do Ministério Público."},{"chave":"art-391","sequencia":417,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 391.","conteudo":"O querelante ou o assistente será intimado da sentença, pessoalmente ou na pessoa de seu advogado. Se nenhum deles for encontrado no lugar da sede do juízo, a intimação será feita mediante edital com o prazo de 10 dias, afixado no lugar de costume."},{"chave":"art-392","sequencia":418,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 392.","conteudo":"A intimação da sentença será feita:\n\nI - ao réu, pessoalmente, se estiver preso;\n\nII - ao réu, pessoalmente, ou ao defensor por ele constituído, quando se livrar solto, ou, sendo afiançável a infração, tiver prestado fiança;\n\nIII - ao defensor constituído pelo réu, se este, afiançável, ou não, a infração, expedido o mandado de prisão, não tiver sido encontrado, e assim o certificar o oficial de justiça;\n\nIV - mediante edital, nos casos do n o II, se o réu e o defensor que houver constituído não forem encontrados, e assim o certificar o oficial de justiça;\n\nV - mediante edital, nos casos do n o III, se o defensor que o réu houver constituído também não for encontrado, e assim o certificar o oficial de justiça;\n\nVI - mediante edital, se o réu, não tendo constituído defensor, não for encontrado, e assim o certificar o oficial de justiça.\n\n§ 1 o O prazo do edital será de 90 dias, se tiver sido imposta pena privativa de liberdade por tempo igual ou superior a um ano, e de 60 dias, nos outros casos.\n\n§ 2 o O prazo para apelação correrá após o término do fixado no edital, salvo se, no curso deste, for feita a intimação por qualquer das outras formas estabelecidas neste artigo."},{"chave":"art-393","sequencia":419,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO I — DO PROCESSO EM GERAL","TÍTULO XII — DA SENTENÇA"],"titulo":"TÍTULO XII — DA SENTENÇA","rotulo":"Art. 393.","conteudo":"(Revogado pela Lei nº 12.403, de 2011)."},{"chave":"art-394","sequencia":420,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 394.","conteudo":"O procedimento será comum ou especial. (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o O procedimento comum será ordinário, sumário ou sumaríssimo: (Incluído pela Lei nº 11.719, de 2008).\n\nI - ordinário, quando tiver por objeto crime cuja sanção máxima cominada for igual ou superior a 4 (quatro) anos de pena privativa de liberdade; (Incluído pela Lei nº 11.719, de 2008).\n\nII - sumário, quando tiver por objeto crime cuja sanção máxima cominada seja inferior a 4 (quatro) anos de pena privativa de liberdade; (Incluído pela Lei nº 11.719, de 2008).\n\nIII - sumaríssimo, para as infrações penais de menor potencial ofensivo, na forma da lei. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 2 o Aplica-se a todos os processos o procedimento comum, salvo disposições em contrário deste Código ou de lei especial. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 3 o Nos processos de competência do Tribunal do Júri, o procedimento observará as disposições estabelecidas nos arts. 406 a 497 deste Código . (Incluído pela Lei nº 11.719, de 2008).\n\n§ 4 o As disposições dos arts. 395 a 398 deste Código aplicam-se a todos os procedimentos penais de primeiro grau, ainda que não regulados neste Código. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 5 o Aplicam-se subsidiariamente aos procedimentos especial, sumário e sumaríssimo as disposições do procedimento ordinário. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-394-a","sequencia":421,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 394º-A","conteudo":"Os processos que apurem a prática de crime hediondo ou violência contra a mulher terão prioridade de tramitação em todas as instâncias. (Redação dada pela Lei nº 14.994, de 2024)\n\n§ 1º Os processos que apurem violência contra a mulher independerão do pagamento de custas, taxas ou despesas processuais, salvo em caso de má-fé. (Incluído pela Lei nº 14.994, de 2024)\n\n§ 2º As isenções de que trata o § 1º deste artigo aplicam-se apenas à vítima e, em caso de morte, ao cônjuge, ascendente, descendente ou irmão, quando a estes couber o direito de representação ou de oferecer queixa ou prosseguir com a ação. (Incluído pela Lei nº 14.994, de 2024)"},{"chave":"art-395","sequencia":422,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 395.","conteudo":"A denúncia ou queixa será rejeitada quando: (Redação dada pela Lei nº 11.719, de 2008).\n\nI - for manifestamente inepta; (Incluído pela Lei nº 11.719, de 2008).\n\nII - faltar pressuposto processual ou condição para o exercício da ação penal; ou (Incluído pela Lei nº 11.719, de 2008).\n\nIII - faltar justa causa para o exercício da ação penal. (Incluído pela Lei nº 11.719, de 2008).\n\nParágrafo único. (Revogado). (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-396","sequencia":423,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 396.","conteudo":"Nos procedimentos ordinário e sumário, oferecida a denúncia ou queixa, o juiz, se não a rejeitar liminarmente, recebê-la-á e ordenará a citação do acusado para responder à acusação, por escrito, no prazo de 10 (dez) dias. (Redação dada pela Lei nº 11.719, de 2008).\n\nParágrafo único. No caso de citação por edital, o prazo para a defesa começará a fluir a partir do comparecimento pessoal do acusado ou do defensor constituído. (Redação dada pela Lei nº 11.719, de 2008)."},{"chave":"art-396-a","sequencia":424,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 396º-A","conteudo":"Na resposta, o acusado poderá argüir preliminares e alegar tudo o que interesse à sua defesa, oferecer documentos e justificações, especificar as provas pretendidas e arrolar testemunhas, qualificando-as e requerendo sua intimação, quando necessário. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 1 o A exceção será processada em apartado, nos termos dos arts. 95 a 112 deste Código . (Incluído pela Lei nº 11.719, de 2008).\n\n§ 2 o Não apresentada a resposta no prazo legal, ou se o acusado, citado, não constituir defensor, o juiz nomeará defensor para oferecê-la, concedendo-lhe vista dos autos por 10 (dez) dias. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-397","sequencia":425,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 397.","conteudo":"Após o cumprimento do disposto no art. 396-A , e parágrafos, deste Código, o juiz deverá absolver sumariamente o acusado quando verificar: (Redação dada pela Lei nº 11.719, de 2008).\n\nI - a existência manifesta de causa excludente da ilicitude do fato; (Incluído pela Lei nº 11.719, de 2008).\n\nII - a existência manifesta de causa excludente da culpabilidade do agente, salvo inimputabilidade; (Incluído pela Lei nº 11.719, de 2008).\n\nIII - que o fato narrado evidentemente não constitui crime; ou (Incluído pela Lei nº 11.719, de 2008).\n\nIV - extinta a punibilidade do agente. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-398","sequencia":426,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 398.","conteudo":"(Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-399","sequencia":427,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 399.","conteudo":"Recebida a denúncia ou queixa, o juiz designará dia e hora para a audiência, ordenando a intimação do acusado, de seu defensor, do Ministério Público e, se for o caso, do querelante e do assistente. (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o O acusado preso será requisitado para comparecer ao interrogatório, devendo o poder público providenciar sua apresentação. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 2 o O juiz que presidiu a instrução deverá proferir a sentença. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-400","sequencia":428,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 400.","conteudo":"Na audiência de instrução e julgamento, a ser realizada no prazo máximo de 60 (sessenta) dias, proceder-se-á à tomada de declarações do ofendido, à inquirição das testemunhas arroladas pela acusação e pela defesa, nesta ordem, ressalvado o disposto no art. 222 deste Código , bem como aos esclarecimentos dos peritos, às acareações e ao reconhecimento de pessoas e coisas, interrogando-se, em seguida, o acusado. (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o As provas serão produzidas numa só audiência, podendo o juiz indeferir as consideradas irrelevantes, impertinentes ou protelatórias. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 2 o Os esclarecimentos dos peritos dependerão de prévio requerimento das partes. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-400-a","sequencia":429,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 400º-A","conteudo":"Na audiência de instrução e julgamento, e, em especial, nas que apurem crimes contra a dignidade sexual, todas as partes e demais sujeitos processuais presentes no ato deverão zelar pela integridade física e psicológica da vítima, sob pena de responsabilização civil, penal e administrativa, cabendo ao juiz garantir o cumprimento do disposto neste artigo, vedadas: (Incluído pela Lei nº 14.245, de 2021) (Vide ADPF 1107)\n\nI - a manifestação sobre circunstâncias ou elementos alheios aos fatos objeto de apuração nos autos; (Incluído pela Lei nº 14.245, de 2021)\n\nII - a utilização de linguagem, de informações ou de material que ofendam a dignidade da vítima ou de testemunhas. (Incluído pela Lei nº 14.245, de 2021)"},{"chave":"art-401","sequencia":430,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 401.","conteudo":"Na instrução poderão ser inquiridas até 8 (oito) testemunhas arroladas pela acusação e 8 (oito) pela defesa. (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o Nesse número não se compreendem as que não prestem compromisso e as referidas. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 2 o A parte poderá desistir da inquirição de qualquer das testemunhas arroladas, ressalvado o disposto no art. 209 deste Código . (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-402","sequencia":431,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 402.","conteudo":"Produzidas as provas, ao final da audiência, o Ministério Público, o querelante e o assistente e, a seguir, o acusado poderão requerer diligências cuja necessidade se origine de circunstâncias ou fatos apurados na instrução. (Redação dada pela Lei nº 11.719, de 2008)."},{"chave":"art-403","sequencia":432,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 403.","conteudo":"Não havendo requerimento de diligências, ou sendo indeferido, serão oferecidas alegações finais orais por 20 (vinte) minutos, respectivamente, pela acusação e pela defesa, prorrogáveis por mais 10 (dez), proferindo o juiz, a seguir, sentença. (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o Havendo mais de um acusado, o tempo previsto para a defesa de cada um será individual. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 2 o Ao assistente do Ministério Público, após a manifestação desse, serão concedidos 10 (dez) minutos, prorrogando-se por igual período o tempo de manifestação da defesa. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 3 o O juiz poderá, considerada a complexidade do caso ou o número de acusados, conceder às partes o prazo de 5 (cinco) dias sucessivamente para a apresentação de memoriais. Nesse caso, terá o prazo de 10 (dez) dias para proferir a sentença. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-404","sequencia":433,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO I — DA INSTRUÇÃO CRIMINAL"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO CRIMINAL","rotulo":"Art. 404.","conteudo":"Ordenado diligência considerada imprescindível, de ofício ou a requerimento da parte, a audiência será concluída sem as alegações finais. (Redação dada pela Lei nº 11.719, de 2008).\n\nParágrafo único. Realizada, em seguida, a diligência determinada, as partes apresentarão, no prazo sucessivo de 5 (cinco) dias, suas alegações finais, por memorial, e, no prazo de 10 (dez) dias, o juiz proferirá a sentença. (Incluído pela Lei nº 11.719, de 2008).\n\nA rt. 405. Do ocorrido em audiência será lavrado termo em livro próprio, assinado pelo juiz e pelas partes, contendo breve resumo dos fatos relevantes nela ocorridos. (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o Sempre que possível, o registro dos depoimentos do investigado, indiciado, ofendido e testemunhas será feito pelos meios ou recursos de gravação magnética, estenotipia, digital ou técnica similar, inclusive audiovisual, destinada a obter maior fidelidade das informações . (Incluído pela Lei nº 11.719, de 2008).\n\n§ 2 o No caso de registro por meio audiovisual, será encaminhado às partes cópia do registro original, sem necessidade de transcrição. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-406","sequencia":434,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR"],"titulo":"SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR","rotulo":"Art. 406.","conteudo":"O juiz, ao receber a denúncia ou a queixa, ordenará a citação do acusado para responder a acusação, por escrito, no prazo de 10 (dez) dias. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o O prazo previsto no caput deste artigo será contado a partir do efetivo cumprimento do mandado ou do comparecimento, em juízo, do acusado ou de defensor constituído, no caso de citação inválida ou por edital. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 2 o A acusação deverá arrolar testemunhas, até o máximo de 8 (oito), na denúncia ou na queixa.\n\n§ 3 o Na resposta, o acusado poderá argüir preliminares e alegar tudo que interesse a sua defesa, oferecer documentos e justificações, especificar as provas pretendidas e arrolar testemunhas, até o máximo de 8 (oito), qualificando-as e requerendo sua intimação, quando necessário. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-407","sequencia":435,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR"],"titulo":"SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR","rotulo":"Art. 407.","conteudo":"As exceções serão processadas em apartado, nos termos dos arts. 95 a 112 deste Código . (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-408","sequencia":436,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR"],"titulo":"SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR","rotulo":"Art. 408.","conteudo":"Não apresentada a resposta no prazo legal, o juiz nomeará defensor para oferecê-la em até 10 (dez) dias, concedendo-lhe vista dos autos. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-409","sequencia":437,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR"],"titulo":"SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR","rotulo":"Art. 409.","conteudo":"Apresentada a defesa, o juiz ouvirá o Ministério Público ou o querelante sobre preliminares e documentos, em 5 (cinco) dias. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-410","sequencia":438,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR"],"titulo":"SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR","rotulo":"Art. 410.","conteudo":"O juiz determinará a inquirição das testemunhas e a realização das diligências requeridas pelas partes, no prazo máximo de 10 (dez) dias. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-411","sequencia":439,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR"],"titulo":"SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR","rotulo":"Art. 411.","conteudo":"Na audiência de instrução, proceder-se-á à tomada de declarações do ofendido, se possível, à inquirição das testemunhas arroladas pela acusação e pela defesa, nesta ordem, bem como aos esclarecimentos dos peritos, às acareações e ao reconhecimento de pessoas e coisas, interrogando-se, em seguida, o acusado e procedendo-se o debate. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Os esclarecimentos dos peritos dependerão de prévio requerimento e de deferimento pelo juiz. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o As provas serão produzidas em uma só audiência, podendo o juiz indeferir as consideradas irrelevantes, impertinentes ou protelatórias. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 3 o Encerrada a instrução probatória, observar-se-á, se for o caso, o disposto no art. 384 deste Código . (Incluído pela Lei nº 11.689, de 2008)\n\n§ 4 o As alegações serão orais, concedendo-se a palavra, respectivamente, à acusação e à defesa, pelo prazo de 20 (vinte) minutos, prorrogáveis por mais 10 (dez). (Incluído pela Lei nº 11.689, de 2008)\n\n§ 5 o Havendo mais de 1 (um) acusado, o tempo previsto para a acusação e a defesa de cada um deles será individual. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 6 o Ao assistente do Ministério Público, após a manifestação deste, serão concedidos 10 (dez) minutos, prorrogando-se por igual período o tempo de manifestação da defesa. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 7 o Nenhum ato será adiado, salvo quando imprescindível à prova faltante, determinando o juiz a condução coercitiva de quem deva comparecer. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 8 o A testemunha que comparecer será inquirida, independentemente da suspensão da audiência, observada em qualquer caso a ordem estabelecida no caput deste artigo. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 9 o Encerrados os debates, o juiz proferirá a sua decisão, ou o fará em 10 (dez) dias, ordenando que os autos para isso lhe sejam conclusos. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-412","sequencia":440,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR"],"titulo":"SEÇÃO I — DA ACUSAÇÃO E DA INSTRUÇÃO PRELIMINAR","rotulo":"Art. 412.","conteudo":"O procedimento será concluído no prazo máximo de 90 (noventa) dias. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-413","sequencia":441,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA"],"titulo":"SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA","rotulo":"Art. 413.","conteudo":"O juiz, fundamentadamente, pronunciará o acusado, se convencido da materialidade do fato e da existência de indícios suficientes de autoria ou de participação. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o A fundamentação da pronúncia limitar-se-á à indicação da materialidade do fato e da existência de indícios suficientes de autoria ou de participação, devendo o juiz declarar o dispositivo legal em que julgar incurso o acusado e especificar as circunstâncias qualificadoras e as causas de aumento de pena. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Se o crime for afiançável, o juiz arbitrará o valor da fiança para a concessão ou manutenção da liberdade provisória. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 3 o O juiz decidirá, motivadamente, no caso de manutenção, revogação ou substituição da prisão ou medida restritiva de liberdade anteriormente decretada e, tratando-se de acusado solto, sobre a necessidade da decretação da prisão ou imposição de quaisquer das medidas previstas no Título IX do Livro I deste Código . (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-414","sequencia":442,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA"],"titulo":"SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA","rotulo":"Art. 414.","conteudo":"Não se convencendo da materialidade do fato ou da existência de indícios suficientes de autoria ou de participação, o juiz, fundamentadamente, impronunciará o acusado. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. Enquanto não ocorrer a extinção da punibilidade, poderá ser formulada nova denúncia ou queixa se houver prova nova. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-415","sequencia":443,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA"],"titulo":"SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA","rotulo":"Art. 415.","conteudo":"O juiz, fundamentadamente, absolverá desde logo o acusado, quando: (Redação dada pela Lei nº 11.689, de 2008)\n\nI – provada a inexistência do fato; (Redação dada pela Lei nº 11.689, de 2008)\n\nII – provado não ser ele autor ou partícipe do fato; (Redação dada pela Lei nº 11.689, de 2008)\n\nIII – o fato não constituir infração penal; (Redação dada pela Lei nº 11.689, de 2008)\n\nIV – demonstrada causa de isenção de pena ou de exclusão do crime. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. Não se aplica o disposto no inciso IV do caput deste artigo ao caso de inimputabilidade prevista no caput do art. 26 do Decreto-Lei n o 2.848, de 7 de dezembro de 1940 – Código Penal , salvo quando esta for a única tese defensiva. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-416","sequencia":444,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA"],"titulo":"SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA","rotulo":"Art. 416.","conteudo":"Contra a sentença de impronúncia ou de absolvição sumária caberá apelação. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-417","sequencia":445,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA"],"titulo":"SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA","rotulo":"Art. 417.","conteudo":"Se houver indícios de autoria ou de participação de outras pessoas não incluídas na acusação, o juiz, ao pronunciar ou impronunciar o acusado, determinará o retorno dos autos ao Ministério Público, por 15 (quinze) dias, aplicável, no que couber, o art. 80 deste Código . (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-418","sequencia":446,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA"],"titulo":"SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA","rotulo":"Art. 418.","conteudo":"O juiz poderá dar ao fato definição jurídica diversa da constante da acusação, embora o acusado fique sujeito a pena mais grave. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-419","sequencia":447,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA"],"titulo":"SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA","rotulo":"Art. 419.","conteudo":"Quando o juiz se convencer, em discordância com a acusação, da existência de crime diverso dos referidos no § 1 o do art. 74 deste Código e não for competente para o julgamento, remeterá os autos ao juiz que o seja. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. Remetidos os autos do processo a outro juiz, à disposição deste ficará o acusado preso. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-420","sequencia":448,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA"],"titulo":"SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA","rotulo":"Art. 420.","conteudo":"A intimação da decisão de pronúncia será feita: (Redação dada pela Lei nº 11.689, de 2008)\n\nI – pessoalmente ao acusado, ao defensor nomeado e ao Ministério Público; (Incluído pela Lei nº 11.689, de 2008)\n\nII – ao defensor constituído, ao querelante e ao assistente do Ministério Público, na forma do disposto no § 1 o do art. 370 deste Código . (Incluído pela Lei nº 11.689, de 2008)\n\nParágrafo único. Será intimado por edital o acusado solto que não for encontrado. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-421","sequencia":449,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA"],"titulo":"SEÇÃO II — DA PRONÚNCIA, DA IMPRONÚNCIA E DA ABSOLVIÇÃO SUMÁRIA","rotulo":"Art. 421.","conteudo":"Preclusa a decisão de pronúncia, os autos serão encaminhados ao juiz presidente do Tribunal do Júri. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Ainda que preclusa a decisão de pronúncia, havendo circunstância superveniente que altere a classificação do crime, o juiz ordenará a remessa dos autos ao Ministério Público. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Em seguida, os autos serão conclusos ao juiz para decisão. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-422","sequencia":450,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO III — DA PREPARAÇÃO DO PROCESSO PARA JULGAMENTO EM PLENÁRIO"],"titulo":"SEÇÃO III — DA PREPARAÇÃO DO PROCESSO PARA JULGAMENTO EM PLENÁRIO","rotulo":"Art. 422.","conteudo":"Ao receber os autos, o presidente do Tribunal do Júri determinará a intimação do órgão do Ministério Público ou do querelante, no caso de queixa, e do defensor, para, no prazo de 5 (cinco) dias, apresentarem rol de testemunhas que irão depor em plenário, até o máximo de 5 (cinco), oportunidade em que poderão juntar documentos e requerer diligência. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-423","sequencia":451,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO III — DA PREPARAÇÃO DO PROCESSO PARA JULGAMENTO EM PLENÁRIO"],"titulo":"SEÇÃO III — DA PREPARAÇÃO DO PROCESSO PARA JULGAMENTO EM PLENÁRIO","rotulo":"Art. 423.","conteudo":"Deliberando sobre os requerimentos de provas a serem produzidas ou exibidas no plenário do júri, e adotadas as providências devidas, o juiz presidente: (Redação dada pela Lei nº 11.689, de 2008)\n\nI – ordenará as diligências necessárias para sanar qualquer nulidade ou esclarecer fato que interesse ao julgamento da causa; (Incluído pela Lei nº 11.689, de 2008)\n\nII – fará relatório sucinto do processo, determinando sua inclusão em pauta da reunião do Tribunal do Júri. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-424","sequencia":452,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO III — DA PREPARAÇÃO DO PROCESSO PARA JULGAMENTO EM PLENÁRIO"],"titulo":"SEÇÃO III — DA PREPARAÇÃO DO PROCESSO PARA JULGAMENTO EM PLENÁRIO","rotulo":"Art. 424.","conteudo":"Quando a lei local de organização judiciária não atribuir ao presidente do Tribunal do Júri o preparo para julgamento, o juiz competente remeter-lhe-á os autos do processo preparado até 5 (cinco) dias antes do sorteio a que se refere o art. 433 deste Código . (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. Deverão ser remetidos, também, os processos preparados até o encerramento da reunião, para a realização de julgamento. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-425","sequencia":453,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO IV — DO ALISTAMENTO DOS JURADOS"],"titulo":"SEÇÃO IV — DO ALISTAMENTO DOS JURADOS","rotulo":"Art. 425.","conteudo":"Anualmente, serão alistados pelo presidente do Tribunal do Júri de 800 (oitocentos) a 1.500 (um mil e quinhentos) jurados nas comarcas de mais de 1.000.000 (um milhão) de habitantes, de 300 (trezentos) a 700 (setecentos) nas comarcas de mais de 100.000 (cem mil) habitantes e de 80 (oitenta) a 400 (quatrocentos) nas comarcas de menor população. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Nas comarcas onde for necessário, poderá ser aumentado o número de jurados e, ainda, organizada lista de suplentes, depositadas as cédulas em urna especial, com as cautelas mencionadas na parte final do § 3 o do art. 426 deste Código . (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o O juiz presidente requisitará às autoridades locais, associações de classe e de bairro, entidades associativas e culturais, instituições de ensino em geral, universidades, sindicatos, repartições públicas e outros núcleos comunitários a indicação de pessoas que reúnam as condições para exercer a função de jurado. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-426","sequencia":454,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO IV — DO ALISTAMENTO DOS JURADOS"],"titulo":"SEÇÃO IV — DO ALISTAMENTO DOS JURADOS","rotulo":"Art. 426.","conteudo":"A lista geral dos jurados, com indicação das respectivas profissões, será publicada pela imprensa até o dia 10 de outubro de cada ano e divulgada em editais afixados à porta do Tribunal do Júri. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o A lista poderá ser alterada, de ofício ou mediante reclamação de qualquer do povo ao juiz presidente até o dia 10 de novembro, data de sua publicação definitiva. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Juntamente com a lista, serão transcritos os arts. 436 a 446 deste Código . (Incluído pela Lei nº 11.689, de 2008)\n\n§ 3 o Os nomes e endereços dos alistados, em cartões iguais, após serem verificados na presença do Ministério Público, de advogado indicado pela Seção local da Ordem dos Advogados do Brasil e de defensor indicado pelas Defensorias Públicas competentes, permanecerão guardados em urna fechada a chave, sob a responsabilidade do juiz presidente. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 4 o O jurado que tiver integrado o Conselho de Sentença nos 12 (doze) meses que antecederem à publicação da lista geral fica dela excluído. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 5 o Anualmente, a lista geral de jurados será, obrigatoriamente, completada. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-427","sequencia":455,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO V — DO DESAFORAMENTO"],"titulo":"SEÇÃO V — DO DESAFORAMENTO","rotulo":"Art. 427.","conteudo":"Se o interesse da ordem pública o reclamar ou houver dúvida sobre a imparcialidade do júri ou a segurança pessoal do acusado, o Tribunal, a requerimento do Ministério Público, do assistente, do querelante ou do acusado ou mediante representação do juiz competente, poderá determinar o desaforamento do julgamento para outra comarca da mesma região, onde não existam aqueles motivos, preferindo-se as mais próximas. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o O pedido de desaforamento será distribuído imediatamente e terá preferência de julgamento na Câmara ou Turma competente. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Sendo relevantes os motivos alegados, o relator poderá determinar, fundamentadamente, a suspensão do julgamento pelo júri. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 3 o Será ouvido o juiz presidente, quando a medida não tiver sido por ele solicitada. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 4 o Na pendência de recurso contra a decisão de pronúncia ou quando efetivado o julgamento, não se admitirá o pedido de desaforamento, salvo, nesta última hipótese, quanto a fato ocorrido durante ou após a realização de julgamento anulado. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-428","sequencia":456,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO V — DO DESAFORAMENTO"],"titulo":"SEÇÃO V — DO DESAFORAMENTO","rotulo":"Art. 428.","conteudo":"O desaforamento também poderá ser determinado, em razão do comprovado excesso de serviço, ouvidos o juiz presidente e a parte contrária, se o julgamento não puder ser realizado no prazo de 6 (seis) meses, contado do trânsito em julgado da decisão de pronúncia. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Para a contagem do prazo referido neste artigo, não se computará o tempo de adiamentos, diligências ou incidentes de interesse da defesa. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Não havendo excesso de serviço ou existência de processos aguardando julgamento em quantidade que ultrapasse a possibilidade de apreciação pelo Tribunal do Júri, nas reuniões periódicas previstas para o exercício, o acusado poderá requerer ao Tribunal que determine a imediata realização do julgamento. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-429","sequencia":457,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VI — DA ORGANIZAÇÃO DA PAUTA"],"titulo":"SEÇÃO VI — DA ORGANIZAÇÃO DA PAUTA","rotulo":"Art. 429.","conteudo":"Salvo motivo relevante que autorize alteração na ordem dos julgamentos, terão preferência: (Redação dada pela Lei nº 11.689, de 2008)\n\nI – os acusados presos; (Incluído pela Lei nº 11.689, de 2008)\n\nII – dentre os acusados presos, aqueles que estiverem há mais tempo na prisão; (Incluído pela Lei nº 11.689, de 2008)\n\nIII – em igualdade de condições, os precedentemente pronunciados. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 1 o Antes do dia designado para o primeiro julgamento da reunião periódica, será afixada na porta do edifício do Tribunal do Júri a lista dos processos a serem julgados, obedecida a ordem prevista no caput deste artigo. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 2 o O juiz presidente reservará datas na mesma reunião periódica para a inclusão de processo que tiver o julgamento adiado. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-430","sequencia":458,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VI — DA ORGANIZAÇÃO DA PAUTA"],"titulo":"SEÇÃO VI — DA ORGANIZAÇÃO DA PAUTA","rotulo":"Art. 430.","conteudo":"O assistente somente será admitido se tiver requerido sua habilitação até 5 (cinco) dias antes da data da sessão na qual pretenda atuar. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-431","sequencia":459,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VI — DA ORGANIZAÇÃO DA PAUTA"],"titulo":"SEÇÃO VI — DA ORGANIZAÇÃO DA PAUTA","rotulo":"Art. 431.","conteudo":"Estando o processo em ordem, o juiz presidente mandará intimar as partes, o ofendido, se for possível, as testemunhas e os peritos, quando houver requerimento, para a sessão de instrução e julgamento, observando, no que couber, o disposto no art. 420 deste Código. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-432","sequencia":460,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VII — DO SORTEIO E DA CONVOCAÇÃO DOS JURADOS"],"titulo":"SEÇÃO VII — DO SORTEIO E DA CONVOCAÇÃO DOS JURADOS","rotulo":"Art. 432.","conteudo":"Em seguida à organização da pauta, o juiz presidente determinará a intimação do Ministério Público, da Ordem dos Advogados do Brasil e da Defensoria Pública para acompanharem, em dia e hora designados, o sorteio dos jurados que atuarão na reunião periódica. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-433","sequencia":461,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VII — DO SORTEIO E DA CONVOCAÇÃO DOS JURADOS"],"titulo":"SEÇÃO VII — DO SORTEIO E DA CONVOCAÇÃO DOS JURADOS","rotulo":"Art. 433.","conteudo":"O sorteio, presidido pelo juiz, far-se-á a portas abertas, cabendo-lhe retirar as cédulas até completar o número de 25 (vinte e cinco) jurados, para a reunião periódica ou extraordinária. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o O sorteio será realizado entre o 15 o (décimo quinto) e o 10 o (décimo) dia útil antecedente à instalação da reunião. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o A audiência de sorteio não será adiada pelo não comparecimento das partes. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 3 o O jurado não sorteado poderá ter o seu nome novamente incluído para as reuniões futuras. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-434","sequencia":462,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VII — DO SORTEIO E DA CONVOCAÇÃO DOS JURADOS"],"titulo":"SEÇÃO VII — DO SORTEIO E DA CONVOCAÇÃO DOS JURADOS","rotulo":"Art. 434.","conteudo":"Os jurados sorteados serão convocados pelo correio ou por qualquer outro meio hábil para comparecer no dia e hora designados para a reunião, sob as penas da lei. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. No mesmo expediente de convocação serão transcritos os arts. 436 a 446 deste Código . (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-435","sequencia":463,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VII — DO SORTEIO E DA CONVOCAÇÃO DOS JURADOS"],"titulo":"SEÇÃO VII — DO SORTEIO E DA CONVOCAÇÃO DOS JURADOS","rotulo":"Art. 435.","conteudo":"Serão afixados na porta do edifício do Tribunal do Júri a relação dos jurados convocados, os nomes do acusado e dos procuradores das partes, além do dia, hora e local das sessões de instrução e julgamento. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-436","sequencia":464,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VIII — DA FUNÇÃO DO JURADO"],"titulo":"SEÇÃO VIII — DA FUNÇÃO DO JURADO","rotulo":"Art. 436.","conteudo":"O serviço do júri é obrigatório. O alistamento compreenderá os cidadãos maiores de 18 (dezoito) anos de notória idoneidade. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Nenhum cidadão poderá ser excluído dos trabalhos do júri ou deixar de ser alistado em razão de cor ou etnia, raça, credo, sexo, profissão, classe social ou econômica, origem ou grau de instrução. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o A recusa injustificada ao serviço do júri acarretará multa no valor de 1 (um) a 10 (dez) salários mínimos, a critério do juiz, de acordo com a condição econômica do jurado. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-437","sequencia":465,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VIII — DA FUNÇÃO DO JURADO"],"titulo":"SEÇÃO VIII — DA FUNÇÃO DO JURADO","rotulo":"Art. 437.","conteudo":"Estão isentos do serviço do júri: (Redação dada pela Lei nº 11.689, de 2008)\n\nI – o Presidente da República e os Ministros de Estado; (Incluído pela Lei nº 11.689, de 2008)\n\nII – os Governadores e seus respectivos Secretários; (Incluído pela Lei nº 11.689, de 2008)\n\nIII – os membros do Congresso Nacional, das Assembléias Legislativas e das Câmaras Distrital e Municipais; (Incluído pela Lei nº 11.689, de 2008)\n\nIV – os Prefeitos Municipais; (Incluído pela Lei nº 11.689, de 2008)\n\nV – os Magistrados e membros do Ministério Público e da Defensoria Pública; (Incluído pela Lei nº 11.689, de 2008)\n\nVI – os servidores do Poder Judiciário, do Ministério Público e da Defensoria Pública; (Incluído pela Lei nº 11.689, de 2008)\n\nVII – as autoridades e os servidores da polícia e da segurança pública; (Incluído pela Lei nº 11.689, de 2008)\n\nVIII – os militares em serviço ativo; (Incluído pela Lei nº 11.689, de 2008)\n\nIX – os cidadãos maiores de 70 (setenta) anos que requeiram sua dispensa; (Incluído pela Lei nº 11.689, de 2008)\n\nX – aqueles que o requererem, demonstrando justo impedimento. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-438","sequencia":466,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VIII — DA FUNÇÃO DO JURADO"],"titulo":"SEÇÃO VIII — DA FUNÇÃO DO JURADO","rotulo":"Art. 438.","conteudo":"A recusa ao serviço do júri fundada em convicção religiosa, filosófica ou política importará no dever de prestar serviço alternativo, sob pena de suspensão dos direitos políticos, enquanto não prestar o serviço imposto. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Entende-se por serviço alternativo o exercício de atividades de caráter administrativo, assistencial, filantrópico ou mesmo produtivo, no Poder Judiciário, na Defensoria Pública, no Ministério Público ou em entidade conveniada para esses fins. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o O juiz fixará o serviço alternativo atendendo aos princípios da proporcionalidade e da razoabilidade. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-439","sequencia":467,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VIII — DA FUNÇÃO DO JURADO"],"titulo":"SEÇÃO VIII — DA FUNÇÃO DO JURADO","rotulo":"Art. 439.","conteudo":"O exercício efetivo da função de jurado constituirá serviço público relevante e estabelecerá presunção de idoneidade moral. (Redação dada pela Lei nº 12.403, de 2011)."},{"chave":"art-440","sequencia":468,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VIII — DA FUNÇÃO DO JURADO"],"titulo":"SEÇÃO VIII — DA FUNÇÃO DO JURADO","rotulo":"Art. 440.","conteudo":"Constitui também direito do jurado, na condição do art. 439 deste Código , preferência, em igualdade de condições, nas licitações públicas e no provimento, mediante concurso, de cargo ou função pública, bem como nos casos de promoção funcional ou remoção voluntária. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-441","sequencia":469,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VIII — DA FUNÇÃO DO JURADO"],"titulo":"SEÇÃO VIII — DA FUNÇÃO DO JURADO","rotulo":"Art. 441.","conteudo":"Nenhum desconto será feito nos vencimentos ou salário do jurado sorteado que comparecer à sessão do júri. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-442","sequencia":470,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VIII — DA FUNÇÃO DO JURADO"],"titulo":"SEÇÃO VIII — DA FUNÇÃO DO JURADO","rotulo":"Art. 442.","conteudo":"Ao jurado que, sem causa legítima, deixar de comparecer no dia marcado para a sessão ou retirar-se antes de ser dispensado pelo presidente será aplicada multa de 1 (um) a 10 (dez) salários mínimos, a critério do juiz, de acordo com a sua condição econômica. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-443","sequencia":471,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VIII — DA FUNÇÃO DO JURADO"],"titulo":"SEÇÃO VIII — DA FUNÇÃO DO JURADO","rotulo":"Art. 443.","conteudo":"Somente será aceita escusa fundada em motivo relevante devidamente comprovado e apresentada, ressalvadas as hipóteses de força maior, até o momento da chamada dos jurados. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-444","sequencia":472,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VIII — DA FUNÇÃO DO JURADO"],"titulo":"SEÇÃO VIII — DA FUNÇÃO DO JURADO","rotulo":"Art. 444.","conteudo":"O jurado somente será dispensado por decisão motivada do juiz presidente, consignada na ata dos trabalhos. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-445","sequencia":473,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VIII — DA FUNÇÃO DO JURADO"],"titulo":"SEÇÃO VIII — DA FUNÇÃO DO JURADO","rotulo":"Art. 445.","conteudo":"O jurado, no exercício da função ou a pretexto de exercê-la, será responsável criminalmente nos mesmos termos em que o são os juízes togados. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-446","sequencia":474,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO VIII — DA FUNÇÃO DO JURADO"],"titulo":"SEÇÃO VIII — DA FUNÇÃO DO JURADO","rotulo":"Art. 446.","conteudo":"Aos suplentes, quando convocados, serão aplicáveis os dispositivos referentes às dispensas, faltas e escusas e à equiparação de responsabilidade penal prevista no art. 445 deste Código . (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-447","sequencia":475,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO IX — DA COMPOSIÇÃO DO TRIBUNAL DO JÚRI E DA FORMAÇÃO DO CONSELHO DE SENTENÇA"],"titulo":"SEÇÃO IX — DA COMPOSIÇÃO DO TRIBUNAL DO JÚRI E DA FORMAÇÃO DO CONSELHO DE SENTENÇA","rotulo":"Art. 447.","conteudo":"O Tribunal do Júri é composto por 1 (um) juiz togado, seu presidente e por 25 (vinte e cinco) jurados que serão sorteados dentre os alistados, 7 (sete) dos quais constituirão o Conselho de Sentença em cada sessão de julgamento. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-448","sequencia":476,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO IX — DA COMPOSIÇÃO DO TRIBUNAL DO JÚRI E DA FORMAÇÃO DO CONSELHO DE SENTENÇA"],"titulo":"SEÇÃO IX — DA COMPOSIÇÃO DO TRIBUNAL DO JÚRI E DA FORMAÇÃO DO CONSELHO DE SENTENÇA","rotulo":"Art. 448.","conteudo":"São impedidos de servir no mesmo Conselho: (Redação dada pela Lei nº 11.689, de 2008)\n\nI – marido e mulher; (Incluído pela Lei nº 11.689, de 2008)\n\nII – ascendente e descendente; (Incluído pela Lei nº 11.689, de 2008)\n\nIII – sogro e genro ou nora; (Incluído pela Lei nº 11.689, de 2008)\n\nIV – irmãos e cunhados, durante o cunhadio; (Incluído pela Lei nº 11.689, de 2008)\n\nV – tio e sobrinho; (Incluído pela Lei nº 11.689, de 2008)\n\nVI – padrasto, madrasta ou enteado. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 1 o O mesmo impedimento ocorrerá em relação às pessoas que mantenham união estável reconhecida como entidade familiar. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Aplicar-se-á aos jurados o disposto sobre os impedimentos, a suspeição e as incompatibilidades dos juízes togados. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-449","sequencia":477,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO IX — DA COMPOSIÇÃO DO TRIBUNAL DO JÚRI E DA FORMAÇÃO DO CONSELHO DE SENTENÇA"],"titulo":"SEÇÃO IX — DA COMPOSIÇÃO DO TRIBUNAL DO JÚRI E DA FORMAÇÃO DO CONSELHO DE SENTENÇA","rotulo":"Art. 449.","conteudo":"Não poderá servir o jurado que: (Redação dada pela Lei nº 11.689, de 2008)\n\nI – tiver funcionado em julgamento anterior do mesmo processo, independentemente da causa determinante do julgamento posterior; (Incluído pela Lei nº 11.689, de 2008)\n\nII – no caso do concurso de pessoas, houver integrado o Conselho de Sentença que julgou o outro acusado; (Incluído pela Lei nº 11.689, de 2008)\n\nIII – tiver manifestado prévia disposição para condenar ou absolver o acusado . (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-450","sequencia":478,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO IX — DA COMPOSIÇÃO DO TRIBUNAL DO JÚRI E DA FORMAÇÃO DO CONSELHO DE SENTENÇA"],"titulo":"SEÇÃO IX — DA COMPOSIÇÃO DO TRIBUNAL DO JÚRI E DA FORMAÇÃO DO CONSELHO DE SENTENÇA","rotulo":"Art. 450.","conteudo":"Dos impedidos entre si por parentesco ou relação de convivência, servirá o que houver sido sorteado em primeiro lugar. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-451","sequencia":479,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO IX — DA COMPOSIÇÃO DO TRIBUNAL DO JÚRI E DA FORMAÇÃO DO CONSELHO DE SENTENÇA"],"titulo":"SEÇÃO IX — DA COMPOSIÇÃO DO TRIBUNAL DO JÚRI E DA FORMAÇÃO DO CONSELHO DE SENTENÇA","rotulo":"Art. 451.","conteudo":"Os jurados excluídos por impedimento, suspeição ou incompatibilidade serão considerados para a constituição do número legal exigível para a realização da sessão. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-452","sequencia":480,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO IX — DA COMPOSIÇÃO DO TRIBUNAL DO JÚRI E DA FORMAÇÃO DO CONSELHO DE SENTENÇA"],"titulo":"SEÇÃO IX — DA COMPOSIÇÃO DO TRIBUNAL DO JÚRI E DA FORMAÇÃO DO CONSELHO DE SENTENÇA","rotulo":"Art. 452.","conteudo":"O mesmo Conselho de Sentença poderá conhecer de mais de um processo, no mesmo dia, se as partes o aceitarem, hipótese em que seus integrantes deverão prestar novo compromisso. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-453","sequencia":481,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 453.","conteudo":"O Tribunal do Júri reunir-se -á para as sessões de instrução e julgamento nos períodos e na forma estabelecida pela lei local de organização judiciária. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-454","sequencia":482,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 454.","conteudo":"Até o momento de abertura dos trabalhos da sessão, o juiz presidente decidirá os casos de isenção e dispensa de jurados e o pedido de adiamento de julgamento, mandando consignar em ata as deliberações. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-455","sequencia":483,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 455.","conteudo":"Se o Ministério Público não comparecer, o juiz presidente adiará o julgamento para o primeiro dia desimpedido da mesma reunião, cientificadas as partes e as testemunhas. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. Se a ausência não for justificada, o fato será imediatamente comunicado ao Procurador-Geral de Justiça com a data designada para a nova sessão. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-456","sequencia":484,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 456.","conteudo":"Se a falta, sem escusa legítima, for do advogado do acusado, e se outro não for por este constituído, o fato será imediatamente comunicado ao presidente da seccional da Ordem dos Advogados do Brasil, com a data designada para a nova sessão. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Não havendo escusa legítima, o julgamento será adiado somente uma vez, devendo o acusado ser julgado quando chamado novamente. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Na hipótese do § 1 o deste artigo, o juiz intimará a Defensoria Pública para o novo julgamento, que será adiado para o primeiro dia desimpedido, observado o prazo mínimo de 10 (dez) dias. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-457","sequencia":485,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 457.","conteudo":"O julgamento não será adiado pelo não comparecimento do acusado solto, do assistente ou do advogado do querelante, que tiver sido regularmente intimado. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Os pedidos de adiamento e as justificações de não comparecimento deverão ser, salvo comprovado motivo de força maior, previamente submetidos à apreciação do juiz presidente do Tribunal do Júri. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Se o acusado preso não for conduzido, o julgamento será adiado para o primeiro dia desimpedido da mesma reunião, salvo se houver pedido de dispensa de comparecimento subscrito por ele e seu defensor. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-458","sequencia":486,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 458.","conteudo":"Se a testemunha, sem justa causa, deixar de comparecer, o juiz presidente, sem prejuízo da ação penal pela desobediência, aplicar-lhe-á a multa prevista no § 2 o do art. 436 deste Código . (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-459","sequencia":487,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 459.","conteudo":"Aplicar-se-á às testemunhas a serviço do Tribunal do Júri o disposto no art. 441 deste Código . (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-460","sequencia":488,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 460.","conteudo":"Antes de constituído o Conselho de Sentença, as testemunhas serão recolhidas a lugar onde umas não possam ouvir os depoimentos das outras. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-461","sequencia":489,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 461.","conteudo":"O julgamento não será adiado se a testemunha deixar de comparecer, salvo se uma das partes tiver requerido a sua intimação por mandado, na oportunidade de que trata o art. 422 deste Código , declarando não prescindir do depoimento e indicando a sua localização. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Se, intimada, a testemunha não comparecer, o juiz presidente suspenderá os trabalhos e mandará conduzi-la ou adiará o julgamento para o primeiro dia desimpedido, ordenando a sua condução. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o O julgamento será realizado mesmo na hipótese de a testemunha não ser encontrada no local indicado, se assim for certificado por oficial de justiça. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-462","sequencia":490,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 462.","conteudo":"Realizadas as diligências referidas nos arts. 454 a 461 deste Código , o juiz presidente verificará se a urna contém as cédulas dos 25 (vinte e cinco) jurados sorteados, mandando que o escrivão proceda à chamada deles. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-463","sequencia":491,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 463.","conteudo":"Comparecendo, pelo menos, 15 (quinze) jurados, o juiz presidente declarará instalados os trabalhos, anunciando o processo que será submetido a julgamento. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o O oficial de justiça fará o pregão, certificando a diligência nos autos. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Os jurados excluídos por impedimento ou suspeição serão computados para a constituição do número legal. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-464","sequencia":492,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 464.","conteudo":"Não havendo o número referido no art. 463 deste Código , proceder-se-á ao sorteio de tantos suplentes quantos necessários, e designar-se-á nova data para a sessão do júri. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-465","sequencia":493,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 465.","conteudo":"Os nomes dos suplentes serão consignados em ata, remetendo-se o expediente de convocação, com observância do disposto nos arts. 434 e 435 deste Código . (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-466","sequencia":494,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 466.","conteudo":"Antes do sorteio dos membros do Conselho de Sentença, o juiz presidente esclarecerá sobre os impedimentos, a suspeição e as incompatibilidades constantes dos arts. 448 e 449 deste Código . (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o O juiz presidente também advertirá os jurados de que, uma vez sorteados, não poderão comunicar-se entre si e com outrem, nem manifestar sua opinião sobre o processo, sob pena de exclusão do Conselho e multa, na forma do § 2 o do art. 436 deste Código . (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 2 o A incomunicabilidade será certificada nos autos pelo oficial de justiça. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-467","sequencia":495,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 467.","conteudo":"Verificando que se encontram na urna as cédulas relativas aos jurados presentes, o juiz presidente sorteará 7 (sete) dentre eles para a formação do Conselho de Sentença. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-468","sequencia":496,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 468.","conteudo":"À medida que as cédulas forem sendo retiradas da urna, o juiz presidente as lerá, e a defesa e, depois dela, o Ministério Público poderão recusar os jurados sorteados, até 3 (três) cada parte, sem motivar a recusa. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. O jurado recusado imotivadamente por qualquer das partes será excluído daquela sessão de instrução e julgamento, prosseguindo-se o sorteio para a composição do Conselho de Sentença com os jurados remanescentes. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-469","sequencia":497,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 469.","conteudo":"Se forem 2 (dois) ou mais os acusados, as recusas poderão ser feitas por um só defensor. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o A separação dos julgamentos somente ocorrerá se, em razão das recusas, não for obtido o número mínimo de 7 (sete) jurados para compor o Conselho de Sentença. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Determinada a separação dos julgamentos, será julgado em primeiro lugar o acusado a quem foi atribuída a autoria do fato ou, em caso de co-autoria, aplicar-se-á o critério de preferência disposto no art. 429 deste Código . (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-470","sequencia":498,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 470.","conteudo":"Desacolhida a argüição de impedimento, de suspeição ou de incompatibilidade contra o juiz presidente do Tribunal do Júri, órgão do Ministério Público, jurado ou qualquer funcionário, o julgamento não será suspenso, devendo, entretanto, constar da ata o seu fundamento e a decisão. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-471","sequencia":499,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 471.","conteudo":"Se, em conseqüência do impedimento, suspeição, incompatibilidade, dispensa ou recusa, não houver número para a formação do Conselho, o julgamento será adiado para o primeiro dia desimpedido, após sorteados os suplentes, com observância do disposto no art. 464 deste Código . (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-472","sequencia":500,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO X — DA REUNIÃO E DAS SESSÕES DO TRIBUNAL DO JÚRI","rotulo":"Art. 472.","conteudo":"Formado o Conselho de Sentença, o presidente, levantando-se, e, com ele, todos os presentes, fará aos jurados a seguinte exortação: (Redação dada pela Lei nº 11.689, de 2008)\n\nEm nome da lei, concito-vos a examinar esta causa com imparcialidade e a proferir a vossa decisão de acordo com a vossa consciência e os ditames da justiça.\n\nOs jurados, nominalmente chamados pelo presidente, responderão:\n\nAssim o prometo.\n\nParágrafo único. O jurado, em seguida, receber á cópias da pronúncia ou, se for o caso, das decisões posteriores que julgaram admissível a acusação e do relatório do processo. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-473","sequencia":501,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XI — DA INSTRUÇÃO EM PLENÁRIO"],"titulo":"SEÇÃO XI — DA INSTRUÇÃO EM PLENÁRIO","rotulo":"Art. 473.","conteudo":"Prestado o compromisso pelos jurados, será iniciada a instrução plenária quando o juiz presidente, o Ministério Público, o assistente, o querelante e o defensor do acusado tomarão, sucessiva e diretamente, as declarações do ofendido, se possível, e inquirirão as testemunhas arroladas pela acusação. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Para a inquirição das testemunhas arroladas pela defesa, o defensor do acusado formulará as perguntas antes do Ministério Público e do assistente, mantidos no mais a ordem e os critérios estabelecidos neste artigo. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Os jurados poderão formular perguntas ao ofendido e às testemunhas, por intermédio do juiz presidente. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 3 o As partes e os jurados poderão requerer acareações, reconhecimento de pessoas e coisas e esclarecimento dos peritos, bem como a leitura de peças que se refiram, exclusivamente, às provas colhidas por carta precatória e às provas cautelares, antecipadas ou não repetíveis. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-474","sequencia":502,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XI — DA INSTRUÇÃO EM PLENÁRIO"],"titulo":"SEÇÃO XI — DA INSTRUÇÃO EM PLENÁRIO","rotulo":"Art. 474.","conteudo":"A seguir será o acusado interrogado, se estiver presente, na forma estabelecida no Capítulo III do Título VII do Livro I deste Código , com as alterações introduzidas nesta Seção. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o O Ministério Público, o assistente, o querelante e o defensor, nessa ordem, poderão formular, diretamente, perguntas ao acusado. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 2 o Os jurados formularão perguntas por intermédio do juiz presidente. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 3 o Não se permitirá o uso de algemas no acusado durante o período em que permanecer no plenário do júri, salvo se absolutamente necessário à ordem dos trabalhos, à segurança das testemunhas ou à garantia da integridade física dos presentes. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-474-a","sequencia":503,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XI — DA INSTRUÇÃO EM PLENÁRIO"],"titulo":"SEÇÃO XI — DA INSTRUÇÃO EM PLENÁRIO","rotulo":"Art. 474º-A","conteudo":"Durante a instrução em plenário, todas as partes e demais sujeitos processuais presentes no ato deverão respeitar a dignidade da vítima, sob pena de responsabilização civil, penal e administrativa, cabendo ao juiz presidente garantir o cumprimento do disposto neste artigo, vedadas: (Incluído pela Lei nº 14.245, de 2021)\n\nI - a manifestação sobre circunstâncias ou elementos alheios aos fatos objeto de apuração nos autos; (Incluído pela Lei nº 14.245, de 2021)\n\nII - a utilização de linguagem, de informações ou de material que ofendam a dignidade da vítima ou de testemunhas. (Incluído pela Lei nº 14.245, de 2021)"},{"chave":"art-475","sequencia":504,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XI — DA INSTRUÇÃO EM PLENÁRIO"],"titulo":"SEÇÃO XI — DA INSTRUÇÃO EM PLENÁRIO","rotulo":"Art. 475.","conteudo":"O registro dos depoimentos e do interrogatório será feito pelos meios ou recursos de gravação magnética, eletrônica, estenotipia ou técnica similar, destinada a obter maior fidelidade e celeridade na colheita da prova. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. A transcrição do registro, após feita a degravação, constará dos autos. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-476","sequencia":505,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XII — DOS DEBATES"],"titulo":"SEÇÃO XII — DOS DEBATES","rotulo":"Art. 476.","conteudo":"Encerrada a instrução, será concedida a palavra ao Ministério Público, que fará a acusação, nos limites da pronúncia ou das decisões posteriores que julgaram admissível a acusação, sustentando, se for o caso, a existência de circunstância agravante. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o O assistente falará depois do Ministério Público. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Tratando-se de ação penal de iniciativa privada, falará em primeiro lugar o querelante e, em seguida, o Ministério Público, salvo se este houver retomado a titularidade da ação, na forma do art. 29 deste Código . (Incluído pela Lei nº 11.689, de 2008)\n\n§ 3 o Finda a acusação, terá a palavra a defesa. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 4 o A acusação poderá replicar e a defesa treplicar, sendo admitida a reinquirição de testemunha já ouvida em plenário. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-477","sequencia":506,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XII — DOS DEBATES"],"titulo":"SEÇÃO XII — DOS DEBATES","rotulo":"Art. 477.","conteudo":"O tempo destinado à acusação e à defesa será de uma hora e meia para cada, e de uma hora para a réplica e outro tanto para a tréplica. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Havendo mais de um acusador ou mais de um defensor, combinarão entre si a distribuição do tempo, que, na falta de acordo, será dividido pelo juiz presidente, de forma a não exceder o determinado neste artigo. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Havendo mais de 1 (um) acusado, o tempo para a acusação e a defesa será acrescido de 1 (uma) hora e elevado ao dobro o da réplica e da tréplica, observado o disposto no § 1 o deste artigo. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-478","sequencia":507,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XII — DOS DEBATES"],"titulo":"SEÇÃO XII — DOS DEBATES","rotulo":"Art. 478.","conteudo":"Durante os debates as partes não poderão, sob pena de nulidade, fazer referências: (Redação dada pela Lei nº 11.689, de 2008)\n\nI – à decisão de pronúncia, às decisões posteriores que julgaram admissível a acusação ou à determinação do uso de algemas como argumento de autoridade que beneficiem ou prejudiquem o acusado; (Incluído pela Lei nº 11.689, de 2008)\n\nII – ao silêncio do acusado ou à ausência de interrogatório por falta de requerimento, em seu prejuízo. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-479","sequencia":508,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XII — DOS DEBATES"],"titulo":"SEÇÃO XII — DOS DEBATES","rotulo":"Art. 479.","conteudo":"Durante o julgamento não será permitida a leitura de documento ou a exibição de objeto que não tiver sido juntado aos autos com a antecedência mínima de 3 (três) dias úteis, dando-se ciência à outra parte. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. Compreende-se na proibição deste artigo a leitura de jornais ou qualquer outro escrito, bem como a exibição de vídeos, gravações, fotografias, laudos, quadros, croqui ou qualquer outro meio assemelhado, cujo conteúdo versar sobre a matéria de fato submetida à apreciação e julgamento dos jurados. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-480","sequencia":509,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XII — DOS DEBATES"],"titulo":"SEÇÃO XII — DOS DEBATES","rotulo":"Art. 480.","conteudo":"A acusação, a defesa e os jurados poderão, a qualquer momento e por intermédio do juiz presidente, pedir ao orador que indique a folha dos autos onde se encontra a peça por ele lida ou citada, facultando-se, ainda, aos jurados solicitar-lhe, pelo mesmo meio, o esclarecimento de fato por ele alegado. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Concluídos os debates, o presidente indagará dos jurados se estão habilitados a julgar ou se necessitam de outros esclarecimentos. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Se houver dúvida sobre questão de fato, o presidente prestará esclarecimentos à vista dos autos. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 3 o Os jurados, nesta fase do procedimento, terão acesso aos autos e aos instrumentos do crime se solicitarem ao juiz presidente. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-481","sequencia":510,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XII — DOS DEBATES"],"titulo":"SEÇÃO XII — DOS DEBATES","rotulo":"Art. 481.","conteudo":"Se a verificação de qualquer fato, reconhecida como essencial para o julgamento da causa, não puder ser realizada imediatamente, o juiz presidente dissolverá o Conselho, ordenando a realização das diligências entendidas necessárias. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. Se a diligência consistir na produção de prova pericial, o juiz presidente, desde logo, nomeará perito e formulará quesitos, facultando às partes também formulá-los e indicar assistentes técnicos, no prazo de 5 (cinco) dias. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-482","sequencia":511,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO"],"titulo":"SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO","rotulo":"Art. 482.","conteudo":"O Conselho de Sentença será questionado sobre matéria de fato e se o acusado deve ser absolvido. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. Os quesitos serão redigidos em proposições afirmativas, simples e distintas, de modo que cada um deles possa ser respondido com suficiente clareza e necessária precisão. Na sua elaboração, o presidente levará em conta os termos da pronúncia ou das decisões posteriores que julgaram admissível a acusação, do interrogatório e das alegações das partes. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-483","sequencia":512,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO"],"titulo":"SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO","rotulo":"Art. 483.","conteudo":"Os quesitos serão formulados na seguinte ordem, indagando sobre: (Redação dada pela Lei nº 11.689, de 2008)\n\nI – a materialidade do fato; (Incluído pela Lei nº 11.689, de 2008)\n\nII – a autoria ou participação; (Incluído pela Lei nº 11.689, de 2008)\n\nIII – se o acusado deve ser absolvido; (Incluído pela Lei nº 11.689, de 2008) (Vide ADPF 779)\n\nIV – se existe causa de diminuição de pena alegada pela defesa; (Incluído pela Lei nº 11.689, de 2008)\n\nV – se existe circunstância qualificadora ou causa de aumento de pena reconhecidas na pronúncia ou em decisões posteriores que julgaram admissível a acusação. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 1 o A resposta negativa, de mais de 3 (três) jurados, a qualquer dos quesitos referidos nos incisos I e II do caput deste artigo encerra a votação e implica a absolvição do acusado. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o Respondidos afirmativamente por mais de 3 (três) jurados os quesitos relativos aos incisos I e II do caput deste artigo será formulado quesito com a seguinte redação: (Incluído pela Lei nº 11.689, de 2008) (Vide ADPF 779)\n\nO jurado absolve o acusado?\n\n§ 3 o Decidindo os jurados pela condenação, o julgamento prossegue, devendo ser formulados quesitos sobre: (Incluído pela Lei nº 11.689, de 2008)\n\nI – causa de diminuição de pena alegada pela defesa; (Incluído pela Lei nº 11.689, de 2008)\n\nII – circunstância qualificadora ou causa de aumento de pena, reconhecidas na pronúncia ou em decisões posteriores que julgaram admissível a acusação. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 4 o Sustentada a desclassificação da infração para outra de competência do juiz singular, será formulado quesito a respeito, para ser respondido após o 2 o (segundo) ou 3 o (terceiro) quesito, conforme o caso. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 5 o Sustentada a tese de ocorrência do crime na sua forma tentada ou havendo divergência sobre a tipificação do delito, sendo este da competência do Tribunal do Júri, o juiz formulará quesito acerca destas questões, para ser respondido após o segundo quesito. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 6 o Havendo mais de um crime ou mais de um acusado, os quesitos serão formulados em séries distintas. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-484","sequencia":513,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO"],"titulo":"SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO","rotulo":"Art. 484.","conteudo":"A seguir, o presidente lerá os quesitos e indagará das partes se têm requerimento ou reclamação a fazer, devendo qualquer deles, bem como a decisão, constar da ata. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. Ainda em plenário, o juiz presidente explicará aos jurados o significado de cada quesito. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-485","sequencia":514,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO"],"titulo":"SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO","rotulo":"Art. 485.","conteudo":"Não havendo dúvida a ser esclarecida, o juiz presidente, os jurados, o Ministério Público, o assistente, o querelante, o defensor do acusado, o escrivão e o oficial de justiça dirigir-se-ão à sala especial a fim de ser procedida a votação. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Na falta de sala especial, o juiz presidente determinará que o público se retire, permanecendo somente as pessoas mencionadas no caput deste artigo. (Incluído pela Lei nº 11.689, de 2008)\n\n§ 2 o O juiz presidente advertirá as partes de que não será permitida qualquer intervenção que possa perturbar a livre manifestação do Conselho e fará retirar da sala quem se portar inconvenientemente. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-486","sequencia":515,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO"],"titulo":"SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO","rotulo":"Art. 486.","conteudo":"Antes de proceder-se à votação de cada quesito, o juiz presidente mandará distribuir aos jurados pequenas cédulas, feitas de papel opaco e facilmente dobráveis, contendo 7 (sete) delas a palavra sim , 7 (sete) a palavra não . (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-487","sequencia":516,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO"],"titulo":"SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO","rotulo":"Art. 487.","conteudo":"Para assegurar o sigilo do voto, o oficial de justiça recolherá em urnas separadas as cédulas correspondentes aos votos e as não utilizadas. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-488","sequencia":517,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO"],"titulo":"SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO","rotulo":"Art. 488.","conteudo":"Após a resposta, verificados os votos e as cédulas não utilizadas, o presidente determinará que o escrivão registre no termo a votação de cada quesito, bem como o resultado do julgamento. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. Do termo também constará a conferência das cédulas não utilizadas. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-489","sequencia":518,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO"],"titulo":"SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO","rotulo":"Art. 489.","conteudo":"As decisões do Tribunal do Júri serão tomadas por maioria de votos. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-490","sequencia":519,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO"],"titulo":"SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO","rotulo":"Art. 490.","conteudo":"Se a resposta a qualquer dos quesitos estiver em contradição com outra ou outras já dadas, o presidente, explicando aos jurados em que consiste a contradição, submeterá novamente à votação os quesitos a que se referirem tais respostas. (Redação dada pela Lei nº 11.689, de 2008)\n\nParágrafo único. Se, pela resposta dada a um dos quesitos, o presidente verificar que ficam prejudicados os seguintes, assim o declarará, dando por finda a votação. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-491","sequencia":520,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO"],"titulo":"SEÇÃO XIII — DO QUESTIONÁRIO E SUA VOTAÇÃO","rotulo":"Art. 491.","conteudo":"Encerrada a votação, será o termo a que se refere o art. 488 deste Código assinado pelo presidente, pelos jurados e pelas partes. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-492","sequencia":521,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XIV — DA SENTENÇA"],"titulo":"SEÇÃO XIV — DA SENTENÇA","rotulo":"Art. 492.","conteudo":"Em seguida, o presidente proferirá sentença que: (Redação dada pela Lei nº 11.689, de 2008)\n\nI – no caso de condenação: (Redação dada pela Lei nº 11.689, de 2008)\n\na) fixará a pena-base; (Incluído pela Lei nº 11.689, de 2008)\n\nb) considerará as circunstâncias agravantes ou atenuantes alegadas nos debates; (Incluído pela Lei nº 11.689, de 2008)\n\nc) imporá os aumentos ou diminuições da pena, em atenção às causas admitidas pelo júri; (Incluído pela Lei nº 11.689, de 2008)\n\nd) observará as demais disposições do art. 387 deste Código ; (Incluído pela Lei nº 11.689, de 2008)\n\ne) mandará o acusado recolher-se ou recomendá-lo-á à prisão em que se encontra, se presentes os requisitos da prisão preventiva, ou, no caso de condenação a uma pena igual ou superior a 15 (quinze) anos de reclusão, determinará a execução provisória das penas, com expedição do mandado de prisão, se for o caso, sem prejuízo do conhecimento de recursos que vierem a ser interpostos; (Redação dada pela Lei nº 13.964, de 2019)\n\nf) estabelecerá os efeitos genéricos e específicos da condenação; (Incluído pela Lei nº 11.689, de 2008)\n\nII – no caso de absolvição: (Redação dada pela Lei nº 11.689, de 2008)\n\na) mandará colocar em liberdade o acusado se por outro motivo não estiver preso; (Redação dada pela Lei nº 11.689, de 2008)\n\nb) revogará as medidas restritivas provisoriamente decretadas; (Redação dada pela Lei nº 11.689, de 2008)\n\nc) imporá, se for o caso, a medida de segurança cabível. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 1 o Se houver desclassificação da infração para outra, de competência do juiz singular, ao presidente do Tribunal do Júri caberá proferir sentença em seguida, aplicando-se, quando o delito resultante da nova tipificação for considerado pela lei como infração penal de menor potencial ofensivo, o disposto nos arts. 69 e seguintes da Lei n o 9.099, de 26 de setembro de 1995 . (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 2 o Em caso de desclassificação, o crime conexo que não seja doloso contra a vida será julgado pelo juiz presidente do Tribunal do Júri, aplicando-se, no que couber, o disposto no § 1 o deste artigo. (Redação dada pela Lei nº 11.689, de 2008)\n\n§ 3º O presidente poderá, excepcionalmente, deixar de autorizar a execução provisória das penas de que trata a alínea e do inciso I do caput deste artigo, se houver questão substancial cuja resolução pelo tribunal ao qual competir o julgamento possa plausivelmente levar à revisão da condenação. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 4º A apelação interposta contra decisão condenatória do Tribunal do Júri a uma pena igual ou superior a 15 (quinze) anos de reclusão não terá efeito suspensivo. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 5º Excepcionalmente, poderá o tribunal atribuir efeito suspensivo à apelação de que trata o § 4º deste artigo, quando verificado cumulativamente que o recurso: (Incluído pela Lei nº 13.964, de 2019)\n\nI - não tem propósito meramente protelatório; e (Incluído pela Lei nº 13.964, de 2019)\n\nII - levanta questão substancial e que pode resultar em absolvição, anulação da sentença, novo julgamento ou redução da pena para patamar inferior a 15 (quinze) anos de reclusão.\n\n§ 6º O pedido de concessão de efeito suspensivo poderá ser feito incidentemente na apelação ou por meio de petição em separado dirigida diretamente ao relator, instruída com cópias da sentença condenatória, das razões da apelação e de prova da tempestividade, das contrarrazões e das demais peças necessárias à compreensão da controvérsia. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-493","sequencia":522,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XIV — DA SENTENÇA"],"titulo":"SEÇÃO XIV — DA SENTENÇA","rotulo":"Art. 493.","conteudo":"A sentença será lida em plenário pelo presidente antes de encerrada a sessão de instrução e julgamento. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-494","sequencia":523,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XV — DA ATA DOS TRABALHOS"],"titulo":"SEÇÃO XV — DA ATA DOS TRABALHOS","rotulo":"Art. 494.","conteudo":"De cada sessão de julgamento o escrivão lavrará ata, assinada pelo presidente e pelas partes. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-495","sequencia":524,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XV — DA ATA DOS TRABALHOS"],"titulo":"SEÇÃO XV — DA ATA DOS TRABALHOS","rotulo":"Art. 495.","conteudo":"A ata descreverá fielmente todas as ocorrências, mencionando obrigatoriamente: (Redação dada pela Lei nº 11.689, de 2008)\n\nI – a data e a hora da instalação dos trabalhos; (Redação dada pela Lei nº 11.689, de 2008)\n\nII – o magistrado que presidiu a sessão e os jurados presentes; (Redação dada pela Lei nº 11.689, de 2008)\n\nIII – os jurados que deixaram de comparecer, com escusa ou sem ela, e as sanções aplicadas; (Redação dada pela Lei nº 11.689, de 2008)\n\nIV – o ofício ou requerimento de isenção ou dispensa ; (Redação dada pela Lei nº 11.689, de 2008)\n\nV – o sorteio dos jurados suplentes; (Redação dada pela Lei nº 11.689, de 2008)\n\nVI – o adiamento da sessão, se houver ocorrido, com a indicação do motivo; (Redação dada pela Lei nº 11.689, de 2008)\n\nVII – a abertura da sessão e a presença do Ministério Público, do querelante e do assistente, se houver, e a do defensor do acusado; (Redação dada pela Lei nº 11.689, de 2008)\n\nVIII – o pregão e a sanção imposta, no caso de não comparecimento; (Redação dada pela Lei nº 11.689, de 2008)\n\nIX – as testemunhas dispensadas de depor; (Redação dada pela Lei nº 11.689, de 2008)\n\nX – o recolhimento das testemunhas a lugar de onde umas não pudessem ouvir o depoimento das outras; (Redação dada pela Lei nº 11.689, de 2008)\n\nXI – a verificação das cédulas pelo juiz presidente; (Redação dada pela Lei nº 11.689, de 2008)\n\nXII – a formação do Conselho de Sentença, com o registro dos nomes dos jurados sorteados e recusas; (Redação dada pela Lei nº 11.689, de 2008)\n\nXIII – o compromisso e o interrogatório, com simples referência ao termo; (Redação dada pela Lei nº 11.689, de 2008)\n\nXIV – os debates e as alegações das partes com os respectivos fundamentos; (Redação dada pela Lei nº 11.689, de 2008)\n\nXV – os incidentes; (Redação dada pela Lei nº 11.689, de 2008)\n\nXVI – o julgamento da causa; (Redação dada pela Lei nº 11.689, de 2008)\n\nXVII – a publicidade dos atos da instrução plenária, das diligências e da sentença. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-496","sequencia":525,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XV — DA ATA DOS TRABALHOS"],"titulo":"SEÇÃO XV — DA ATA DOS TRABALHOS","rotulo":"Art. 496.","conteudo":"A falta da ata sujeitará o responsável a sanções administrativa e penal. (Redação dada pela Lei nº 11.689, de 2008)"},{"chave":"art-497","sequencia":526,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO II — DO PROCEDIMENTO RELATIVO AOS PROCESSOS DA COMPETÊNCIA DO TRIBUNAL DO JÚRI","SEÇÃO XVI — DAS ATRIBUIÇÕES DO PRESIDENTE DO TRIBUNAL DO JÚRI"],"titulo":"SEÇÃO XVI — DAS ATRIBUIÇÕES DO PRESIDENTE DO TRIBUNAL DO JÚRI","rotulo":"Art. 497.","conteudo":"São atribuições do juiz presidente do Tribunal do Júri, além de outras expressamente referidas neste Código: (Redação dada pela Lei nº 11.689, de 2008)\n\nI – regular a polícia das sessões e prender os desobedientes; (Redação dada pela Lei nº 11.689, de 2008)\n\nII – requisitar o auxílio da força pública, que ficará sob sua exclusiva autoridade; (Redação dada pela Lei nº 11.689, de 2008)\n\nIII – dirigir os debates, intervindo em caso de abuso, excesso de linguagem ou mediante requerimento de uma das partes; (Redação dada pela Lei nº 11.689, de 2008)\n\nIV – resolver as questões incidentes que não dependam de pronunciamento do júri; (Redação dada pela Lei nº 11.689, de 2008)\n\nV – nomear defensor ao acusado, quando considerá-lo indefeso, podendo, neste caso, dissolver o Conselho e designar novo dia para o julgamento, com a nomeação ou a constituição de novo defensor; (Redação dada pela Lei nº 11.689, de 2008)\n\nVI – mandar retirar da sala o acusado que dificultar a realização do julgamento, o qual prosseguirá sem a sua presença; (Redação dada pela Lei nº 11.689, de 2008)\n\nVII – suspender a sessão pelo tempo indispensável à realização das diligências requeridas ou entendidas necessárias, mantida a incomunicabilidade dos jurados; (Redação dada pela Lei nº 11.689, de 2008)\n\nVIII – interromper a sessão por tempo razoável, para proferir sentença e para repouso ou refeição dos jurados; (Redação dada pela Lei nº 11.689, de 2008)\n\nIX – decidir, de ofício, ouvidos o Ministério Público e a defesa, ou a requerimento de qualquer destes, a argüição de extinção de punibilidade; (Redação dada pela Lei nº 11.689, de 2008)\n\nX – resolver as questões de direito suscitadas no curso do julgamento; (Redação dada pela Lei nº 11.689, de 2008)\n\nXI – determinar, de ofício ou a requerimento das partes ou de qualquer jurado, as diligências destinadas a sanar nulidade ou a suprir falta que prejudique o esclarecimento da verdade; (Redação dada pela Lei nº 11.689, de 2008)\n\nXII – regulamentar, durante os debates, a intervenção de uma das partes, quando a outra estiver com a palavra, podendo conceder até 3 (três) minutos para cada aparte requerido, que serão acrescidos ao tempo desta última. (Incluído pela Lei nº 11.689, de 2008)"},{"chave":"art-498","sequencia":527,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DA COMPETÊNCIA DO JUIZ SINGULAR"],"titulo":"CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DA COMPETÊNCIA DO JUIZ SINGULAR","rotulo":"Art. 498.","conteudo":"(Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-499","sequencia":528,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DA COMPETÊNCIA DO JUIZ SINGULAR"],"titulo":"CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DA COMPETÊNCIA DO JUIZ SINGULAR","rotulo":"Art. 499.","conteudo":"(Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-500","sequencia":529,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DA COMPETÊNCIA DO JUIZ SINGULAR"],"titulo":"CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DA COMPETÊNCIA DO JUIZ SINGULAR","rotulo":"Art. 500.","conteudo":"(Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-501","sequencia":530,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DA COMPETÊNCIA DO JUIZ SINGULAR"],"titulo":"CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DA COMPETÊNCIA DO JUIZ SINGULAR","rotulo":"Art. 501.","conteudo":"(Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-502","sequencia":531,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO I — DO PROCESSO COMUM","CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DA COMPETÊNCIA DO JUIZ SINGULAR"],"titulo":"CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DA COMPETÊNCIA DO JUIZ SINGULAR","rotulo":"Art. 502.","conteudo":"(Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-503","sequencia":532,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA"],"titulo":"CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA","rotulo":"Art. 503.","conteudo":"(Revogado pela Lei nº 11.101, de 2005)"},{"chave":"art-504","sequencia":533,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA"],"titulo":"CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA","rotulo":"Art. 504.","conteudo":"(Revogado pela Lei nº 11.101, de 2005)"},{"chave":"art-505","sequencia":534,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA"],"titulo":"CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA","rotulo":"Art. 505.","conteudo":"(Revogado pela Lei nº 11.101, de 2005)"},{"chave":"art-506","sequencia":535,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA"],"titulo":"CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA","rotulo":"Art. 506.","conteudo":"(Revogado pela Lei nº 11.101, de 2005)"},{"chave":"art-507","sequencia":536,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA"],"titulo":"CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA","rotulo":"Art. 507.","conteudo":"(Revogado pela Lei nº 11.101, de 2005)"},{"chave":"art-508","sequencia":537,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA"],"titulo":"CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA","rotulo":"Art. 508.","conteudo":"(Revogado pela Lei nº 11.101, de 2005)"},{"chave":"art-509","sequencia":538,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA"],"titulo":"CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA","rotulo":"Art. 509.","conteudo":"(Revogado pela Lei nº 11.101, de 2005)"},{"chave":"art-510","sequencia":539,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA"],"titulo":"CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA","rotulo":"Art. 510.","conteudo":"(Revogado pela Lei nº 11.101, de 2005)"},{"chave":"art-511","sequencia":540,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA"],"titulo":"CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA","rotulo":"Art. 511.","conteudo":"(Revogado pela Lei nº 11.101, de 2005)"},{"chave":"art-512","sequencia":541,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA"],"titulo":"CAPÍTULO I — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE FALÊNCIA","rotulo":"Art. 512.","conteudo":"(Revogado pela Lei nº 11.101, de 2005)"},{"chave":"art-513","sequencia":542,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO II — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE RESPONSABILIDADE DOS FUNCIONÁRIOS PÚBLICOS"],"titulo":"CAPÍTULO II — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE RESPONSABILIDADE DOS FUNCIONÁRIOS PÚBLICOS","rotulo":"Art. 513.","conteudo":"Os crimes de responsabilidade dos funcionários públicos, cujo processo e julgamento competirão aos juízes de direito, a queixa ou a denúncia será instruída com documentos ou justificação que façam presumir a existência do delito ou com declaração fundamentada da impossibilidade de apresentação de qualquer dessas provas."},{"chave":"art-514","sequencia":543,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO II — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE RESPONSABILIDADE DOS FUNCIONÁRIOS PÚBLICOS"],"titulo":"CAPÍTULO II — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE RESPONSABILIDADE DOS FUNCIONÁRIOS PÚBLICOS","rotulo":"Art. 514.","conteudo":"Nos crimes afiançáveis, estando a denúncia ou queixa em devida forma, o juiz mandará autuá-la e ordenará a notificação do acusado, para responder por escrito, dentro do prazo de quinze dias.\n\nParágrafo único. Se não for conhecida a residência do acusado, ou este se achar fora da jurisdição do juiz, ser-lhe-á nomeado defensor, a quem caberá apresentar a resposta preliminar."},{"chave":"art-515","sequencia":544,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO II — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE RESPONSABILIDADE DOS FUNCIONÁRIOS PÚBLICOS"],"titulo":"CAPÍTULO II — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE RESPONSABILIDADE DOS FUNCIONÁRIOS PÚBLICOS","rotulo":"Art. 515.","conteudo":"No caso previsto no artigo anterior, durante o prazo concedido para a resposta, os autos permanecerão em cartório, onde poderão ser examinados pelo acusado ou por seu defensor.\n\nParágrafo único. A resposta poderá ser instruída com documentos e justificações."},{"chave":"art-516","sequencia":545,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO II — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE RESPONSABILIDADE DOS FUNCIONÁRIOS PÚBLICOS"],"titulo":"CAPÍTULO II — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE RESPONSABILIDADE DOS FUNCIONÁRIOS PÚBLICOS","rotulo":"Art. 516.","conteudo":"O juiz rejeitará a queixa ou denúncia, em despacho fundamentado, se convencido, pela resposta do acusado ou do seu defensor, da inexistência do crime ou da improcedência da ação."},{"chave":"art-517","sequencia":546,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO II — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE RESPONSABILIDADE DOS FUNCIONÁRIOS PÚBLICOS"],"titulo":"CAPÍTULO II — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE RESPONSABILIDADE DOS FUNCIONÁRIOS PÚBLICOS","rotulo":"Art. 517.","conteudo":"Recebida a denúncia ou a queixa, será o acusado citado, na forma estabelecida no Capítulo I do Título X do Livro I ."},{"chave":"art-518","sequencia":547,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO II — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE RESPONSABILIDADE DOS FUNCIONÁRIOS PÚBLICOS"],"titulo":"CAPÍTULO II — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE RESPONSABILIDADE DOS FUNCIONÁRIOS PÚBLICOS","rotulo":"Art. 518.","conteudo":"Na instrução criminal e nos demais termos do processo, observar-se-á o disposto nos Capítulos I e III, Título I, deste Livro ."},{"chave":"art-519","sequencia":548,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE CALÚNIA E INJÚRIA, DE COMPETÊNCIA DO JUIZ SINGULAR"],"titulo":"CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE CALÚNIA E INJÚRIA, DE COMPETÊNCIA DO JUIZ SINGULAR","rotulo":"Art. 519.","conteudo":"No processo por crime de calúnia ou injúria, para o qual não haja outra forma estabelecida em lei especial, observar-se-á o disposto nos Capítulos I e III, Titulo I, deste Livro , com as modificações constantes dos artigos seguintes."},{"chave":"art-520","sequencia":549,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE CALÚNIA E INJÚRIA, DE COMPETÊNCIA DO JUIZ SINGULAR"],"titulo":"CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE CALÚNIA E INJÚRIA, DE COMPETÊNCIA DO JUIZ SINGULAR","rotulo":"Art. 520.","conteudo":"Antes de receber a queixa, o juiz oferecerá às partes oportunidade para se reconciliarem, fazendo-as comparecer em juízo e ouvindo-as, separadamente, sem a presença dos seus advogados, não se lavrando termo."},{"chave":"art-521","sequencia":550,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE CALÚNIA E INJÚRIA, DE COMPETÊNCIA DO JUIZ SINGULAR"],"titulo":"CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE CALÚNIA E INJÚRIA, DE COMPETÊNCIA DO JUIZ SINGULAR","rotulo":"Art. 521.","conteudo":"Se depois de ouvir o querelante e o querelado, o juiz achar provável a reconciliação, promoverá entendimento entre eles, na sua presença."},{"chave":"art-522","sequencia":551,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE CALÚNIA E INJÚRIA, DE COMPETÊNCIA DO JUIZ SINGULAR"],"titulo":"CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE CALÚNIA E INJÚRIA, DE COMPETÊNCIA DO JUIZ SINGULAR","rotulo":"Art. 522.","conteudo":"No caso de reconciliação, depois de assinado pelo querelante o termo da desistência, a queixa será arquivada."},{"chave":"art-523","sequencia":552,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE CALÚNIA E INJÚRIA, DE COMPETÊNCIA DO JUIZ SINGULAR"],"titulo":"CAPÍTULO III — DO PROCESSO E DO JULGAMENTO DOS CRIMES DE CALÚNIA E INJÚRIA, DE COMPETÊNCIA DO JUIZ SINGULAR","rotulo":"Art. 523.","conteudo":"Quando for oferecida a exceção da verdade ou da notoriedade do fato imputado, o querelante poderá contestar a exceção no prazo de dois dias, podendo ser inquiridas as testemunhas arroladas na queixa, ou outras indicadas naquele prazo, em substituição às primeiras, ou para completar o máximo legal."},{"chave":"art-524","sequencia":553,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 524.","conteudo":"No processo e julgamento dos crimes contra a propriedade imaterial, observar-se-á o disposto nos Capítulos I e III do Título I deste Livro , com as modificações constantes dos artigos seguintes."},{"chave":"art-525","sequencia":554,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 525.","conteudo":"No caso de haver o crime deixado vestígio, a queixa ou a denúncia não será recebida se não for instruída com o exame pericial dos objetos que constituam o corpo de delito."},{"chave":"art-526","sequencia":555,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 526.","conteudo":"Sem a prova de direito à ação, não será recebida a queixa, nem ordenada qualquer diligência preliminarmente requerida pelo ofendido."},{"chave":"art-527","sequencia":556,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 527.","conteudo":"A diligência de busca ou de apreensão será realizada por dois peritos nomeados pelo juiz, que verificarão a existência de fundamento para a apreensão, e quer esta se realize, quer não, o laudo pericial será apresentado dentro de 3 (três) dias após o encerramento da diligência.\n\nParágrafo único. O requerente da diligência poderá impugnar o laudo contrário à apreensão, e o juiz ordenará que esta se efetue, se reconhecer a improcedência das razões aduzidas pelos peritos."},{"chave":"art-528","sequencia":557,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 528.","conteudo":"Encerradas as diligências, os autos serão conclusos ao juiz para homologação do laudo."},{"chave":"art-529","sequencia":558,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 529.","conteudo":"Nos crimes de ação privativa do ofendido, não será admitida queixa com fundamento em apreensão e em perícia, se decorrido o prazo de 30 dias, após a homologação do laudo.\n\nParágrafo único. Será dada vista ao Ministério Público dos autos de busca e apreensão requeridas pelo ofendido, se o crime for de ação pública e não tiver sido oferecida queixa no prazo fixado neste artigo."},{"chave":"art-530","sequencia":559,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 530.","conteudo":"Se ocorrer prisão em flagrante e o réu não for posto em liberdade, o prazo a que se refere o artigo anterior será de 8 (oito) dias."},{"chave":"art-530-a","sequencia":560,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 530º-A","conteudo":"O disposto nos arts. 524 a 530 será aplicável aos crimes em que se proceda mediante queixa. (Incluído pela Lei nº 10.695, de 1º.7.2003)"},{"chave":"art-530-b","sequencia":561,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 530º-B","conteudo":"Nos casos das infrações previstas nos §§ 1 o , 2 o e 3 o do art. 184 do Código Penal , a autoridade policial procederá à apreensão dos bens ilicitamente produzidos ou reproduzidos, em sua totalidade, juntamente com os equipamentos, suportes e materiais que possibilitaram a sua existência, desde que estes se destinem precipuamente à prática do ilícito . (Incluído pela Lei nº 10.695, de 1º.7.2003)"},{"chave":"art-530-c","sequencia":562,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 530º-C","conteudo":"Na ocasião da apreensão será lavrado termo, assinado por 2 (duas) ou mais testemunhas, com a descrição de todos os bens apreendidos e informações sobre suas origens, o qual deverá integrar o inquérito policial ou o processo. (Incluído pela Lei nº 10.695, de 1º.7.2003)"},{"chave":"art-530-d","sequencia":563,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 530º-D","conteudo":"Subseqüente à apreensão, será realizada, por perito oficial, ou, na falta deste, por pessoa tecnicamente habilitada, perícia sobre todos os bens apreendidos e elaborado o laudo que deverá integrar o inquérito policial ou o processo. (Incluído pela Lei nº 10.695, de 1º.7.2003)"},{"chave":"art-530-e","sequencia":564,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 530º-E","conteudo":"Os titulares de direito de autor e os que lhe são conexos serão os fiéis depositários de todos os bens apreendidos, devendo colocá-los à disposição do juiz quando do ajuizamento da ação. (Incluído pela Lei nº 10.695, de 1º.7.2003)"},{"chave":"art-530-f","sequencia":565,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 530º-F","conteudo":"Ressalvada a possibilidade de se preservar o corpo de delito, o juiz poderá determinar, a requerimento da vítima, a destruição da produção ou reprodução apreendida quando não houver impugnação quanto à sua ilicitude ou quando a ação penal não puder ser iniciada por falta de determinação de quem seja o autor do ilícito. (Incluído pela Lei nº 10.695, de 1º.7.2003)"},{"chave":"art-530-g","sequencia":566,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 530º-G","conteudo":"O juiz, ao prolatar a sentença condenatória, poderá determinar a destruição dos bens ilicitamente produzidos ou reproduzidos e o perdimento dos equipamentos apreendidos, desde que precipuamente destinados à produção e reprodução dos bens, em favor da Fazenda Nacional, que deverá destruí-los ou doá-los aos Estados, Municípios e Distrito Federal, a instituições públicas de ensino e pesquisa ou de assistência social, bem como incorporá-los, por economia ou interesse público, ao patrimônio da União, que não poderão retorná-los aos canais de comércio. (Incluído pela Lei nº 10.695, de 1º.7.2003)"},{"chave":"art-530-h","sequencia":567,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 530º-H","conteudo":"As associações de titulares de direitos de autor e os que lhes são conexos poderão, em seu próprio nome, funcionar como assistente da acusação nos crimes previstos no art. 184 do Código Penal , quando praticado em detrimento de qualquer de seus associados. (Incluído pela Lei nº 10.695, de 1º.7.2003)"},{"chave":"art-530-i","sequencia":568,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL"],"titulo":"CAPÍTULO IV — DO PROCESSO E DO JULGAMENTO DOS CRIMES CONTRA A PROPRIEDADE IMATERIAL","rotulo":"Art. 530º-I","conteudo":"Nos crimes em que caiba ação penal pública incondicionada ou condicionada, observar-se-ão as normas constantes dos arts. 530-B, 530-C, 530-D, 530-E, 530-F, 530-G e 530-H . (Incluído pela Lei nº 10.695, de 1º.7.2003)"},{"chave":"art-531","sequencia":569,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO V — DO PROCESSO SUMÁRIO"],"titulo":"CAPÍTULO V — DO PROCESSO SUMÁRIO","rotulo":"Art. 531.","conteudo":"Na audiência de instrução e julgamento, a ser realizada no prazo máximo de 30 (trinta) dias, proceder-se-á à tomada de declarações do ofendido, se possível, à inquirição das testemunhas arroladas pela acusação e pela defesa, nesta ordem, ressalvado o disposto no art. 222 deste Código , bem como aos esclarecimentos dos peritos, às acareações e ao reconhecimento de pessoas e coisas, interrogando-se, em seguida, o acusado e procedendo-se, finalmente, ao debate. (Redação dada pela Lei nº 11.719, de 2008)."},{"chave":"art-532","sequencia":570,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO V — DO PROCESSO SUMÁRIO"],"titulo":"CAPÍTULO V — DO PROCESSO SUMÁRIO","rotulo":"Art. 532.","conteudo":"Na instrução, poderão ser inquiridas até 5 (cinco) testemunhas arroladas pela acusação e 5 (cinco) pela defesa. (Redação dada pela Lei nº 11.719, de 2008)."},{"chave":"art-533","sequencia":571,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO V — DO PROCESSO SUMÁRIO"],"titulo":"CAPÍTULO V — DO PROCESSO SUMÁRIO","rotulo":"Art. 533.","conteudo":"Aplica-se ao procedimento sumário o disposto nos parágrafos do art. 400 deste Código . (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o (Revogado pela Lei nº 11.719, de 2008).\n\n§ 2 o (Revogado pela Lei nº 11.719, de 2008).\n\n§ 3 o (Revogado pela Lei nº 11.719, de 2008).\n\n§ 4 o (Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-534","sequencia":572,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO V — DO PROCESSO SUMÁRIO"],"titulo":"CAPÍTULO V — DO PROCESSO SUMÁRIO","rotulo":"Art. 534.","conteudo":"As alegações finais serão orais, concedendo-se a palavra, respectivamente, à acusação e à defesa, pelo prazo de 20 (vinte) minutos, prorrogáveis por mais 10 (dez), proferindo o juiz, a seguir, sentença. (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o Havendo mais de um acusado, o tempo previsto para a defesa de cada um será individual. (Incluído pela Lei nº 11.719, de 2008).\n\n§ 2 o Ao assistente do Ministério Público, após a manifestação deste, serão concedidos 10 (dez) minutos, prorrogando-se por igual período o tempo de manifestação da defesa. (Incluído pela Lei nº 11.719, de 2008)."},{"chave":"art-535","sequencia":573,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO V — DO PROCESSO SUMÁRIO"],"titulo":"CAPÍTULO V — DO PROCESSO SUMÁRIO","rotulo":"Art. 535.","conteudo":"Nenhum ato será adiado, salvo quando imprescindível a prova faltante, determinando o juiz a condução coercitiva de quem deva comparecer. (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o (Revogado pela Lei nº 11.719, de 2008).\n\n§ 2 o (Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-536","sequencia":574,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO V — DO PROCESSO SUMÁRIO"],"titulo":"CAPÍTULO V — DO PROCESSO SUMÁRIO","rotulo":"Art. 536.","conteudo":"A testemunha que comparecer será inquirida, independentemente da suspensão da audiência, observada em qualquer caso a ordem estabelecida no art. 531 deste Código . (Redação dada pela Lei nº 11.719, de 2008)."},{"chave":"art-537","sequencia":575,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO V — DO PROCESSO SUMÁRIO"],"titulo":"CAPÍTULO V — DO PROCESSO SUMÁRIO","rotulo":"Art. 537.","conteudo":"(Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-538","sequencia":576,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO V — DO PROCESSO SUMÁRIO"],"titulo":"CAPÍTULO V — DO PROCESSO SUMÁRIO","rotulo":"Art. 538.","conteudo":"Nas infrações penais de menor potencial ofensivo, quando o juizado especial criminal encaminhar ao juízo comum as peças existentes para a adoção de outro procedimento, observar-se-á o procedimento sumário previsto neste Capítulo. (Redação dada pela Lei nº 11.719, de 2008).\n\n§ 1 o (Revogado pela Lei nº 11.719, de 2008).\n\n§ 2 o (Revogado pela Lei nº 11.719, de 2008).\n\n§ 3 o (Revogado pela Lei nº 11.719, de 2008).\n\n§ 4 o (Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-539","sequencia":577,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO V — DO PROCESSO SUMÁRIO"],"titulo":"CAPÍTULO V — DO PROCESSO SUMÁRIO","rotulo":"Art. 539.","conteudo":"(Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-540","sequencia":578,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO V — DO PROCESSO SUMÁRIO"],"titulo":"CAPÍTULO V — DO PROCESSO SUMÁRIO","rotulo":"Art. 540.","conteudo":"(Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-541","sequencia":579,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS"],"titulo":"CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS","rotulo":"Art. 541.","conteudo":"Os autos originais de processo penal extraviados ou destruídos, em primeira ou segunda instância, serão restaurados.\n\n§ 1 o Se existir e for exibida cópia autêntica ou certidão do processo, será uma ou outra considerada como original.\n\n§ 2 o Na falta de cópia autêntica ou certidão do processo, o juiz mandará, de ofício, ou a requerimento de qualquer das partes, que:\n\na) o escrivão certifique o estado do processo, segundo a sua lembrança, e reproduza o que houver a respeito em seus protocolos e registros;\n\nb) sejam requisitadas cópias do que constar a respeito no Instituto Médico-Legal, no Instituto de Identificação e Estatística ou em estabelecimentos congêneres, repartições públicas, penitenciárias ou cadeias;\n\nc) as partes sejam citadas pessoalmente, ou, se não forem encontradas, por edital, com o prazo de dez dias, para o processo de restauração dos autos.\n\n§ 3 o Proceder-se-á à restauração na primeira instância, ainda que os autos se tenham extraviado na segunda."},{"chave":"art-542","sequencia":580,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS"],"titulo":"CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS","rotulo":"Art. 542.","conteudo":"No dia designado, as partes serão ouvidas, mencionando-se em termo circunstanciado os pontos em que estiverem acordes e a exibição e a conferência das certidões e mais reproduções do processo apresentadas e conferidas."},{"chave":"art-543","sequencia":581,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS"],"titulo":"CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS","rotulo":"Art. 543.","conteudo":"O juiz determinará as diligências necessárias para a restauração, observando-se o seguinte:\n\nI - caso ainda não tenha sido proferida a sentença, reinquirir-se-ão as testemunhas podendo ser substituídas as que tiverem falecido ou se encontrarem em lugar não sabido;\n\nII - os exames periciais, quando possível, serão repetidos, e de preferência pelos mesmos peritos;\n\nIII - a prova documental será reproduzida por meio de cópia autêntica ou, quando impossível, por meio de testemunhas;\n\nIV - poderão também ser inquiridas sobre os atos do processo, que deverá ser restaurado, as autoridades, os serventuários, os peritos e mais pessoas que tenham nele funcionado;\n\nV - o Ministério Público e as partes poderão oferecer testemunhas e produzir documentos, para provar o teor do processo extraviado ou destruído."},{"chave":"art-544","sequencia":582,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS"],"titulo":"CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS","rotulo":"Art. 544.","conteudo":"Realizadas as diligências que, salvo motivo de força maior, deverão concluir-se dentro de vinte dias, serão os autos conclusos para julgamento.\n\nParágrafo único. No curso do processo, e depois de subirem os autos conclusos para sentença, o juiz poderá, dentro em cinco dias, requisitar de autoridades ou de repartições todos os esclarecimentos para a restauração."},{"chave":"art-545","sequencia":583,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS"],"titulo":"CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS","rotulo":"Art. 545.","conteudo":"Os selos e as taxas judiciárias, já pagos nos autos originais, não serão novamente cobrados."},{"chave":"art-546","sequencia":584,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS"],"titulo":"CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS","rotulo":"Art. 546.","conteudo":"Os causadores de extravio de autos responderão pelas custas, em dobro, sem prejuízo da responsabilidade criminal."},{"chave":"art-547","sequencia":585,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS"],"titulo":"CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS","rotulo":"Art. 547.","conteudo":"Julgada a restauração, os autos respectivos valerão pelos originais.\n\nParágrafo único. Se no curso da restauração aparecerem os autos originais, nestes continuará o processo, apensos a eles os autos da restauração."},{"chave":"art-548","sequencia":586,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS"],"titulo":"CAPÍTULO VI — DO PROCESSO DE RESTAURAÇÃO DE AUTOS EXTRAVIADOS OU DESTRUÍDOS","rotulo":"Art. 548.","conteudo":"Até à decisão que julgue restaurados os autos, a sentença condenatória em execução continuará a produzir efeito, desde que conste da respectiva guia arquivada na cadeia ou na penitenciária, onde o réu estiver cumprindo a pena, ou de registro que torne a sua existência inequívoca."},{"chave":"art-549","sequencia":587,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO"],"titulo":"CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO","rotulo":"Art. 549.","conteudo":"Se a autoridade policial tiver conhecimento de fato que, embora não constituindo infração penal, possa determinar a aplicação de medida de segurança ( Código Penal, arts. 14 e 27 ), deverá proceder a inquérito, a fim de apurá-lo e averiguar todos os elementos que possam interessar à verificação da periculosidade do agente."},{"chave":"art-550","sequencia":588,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO"],"titulo":"CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO","rotulo":"Art. 550.","conteudo":"O processo será promovido pelo Ministério Público, mediante requerimento que conterá a exposição sucinta do fato, as suas circunstâncias e todos os elementos em que se fundar o pedido."},{"chave":"art-551","sequencia":589,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO"],"titulo":"CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO","rotulo":"Art. 551.","conteudo":"O juiz, ao deferir o requerimento, ordenará a intimação do interessado para comparecer em juízo, a fim de ser interrogado."},{"chave":"art-552","sequencia":590,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO"],"titulo":"CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO","rotulo":"Art. 552.","conteudo":"Após o interrogatório ou dentro do prazo de dois dias, o interessado ou seu defensor poderá oferecer alegações.\n\nParágrafo único. O juiz nomeará defensor ao interessado que não o tiver."},{"chave":"art-553","sequencia":591,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO"],"titulo":"CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO","rotulo":"Art. 553.","conteudo":"O Ministério Público, ao fazer o requerimento inicial, e a defesa, no prazo estabelecido no artigo anterior, poderão requerer exames, diligências e arrolar até três testemunhas."},{"chave":"art-554","sequencia":592,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO"],"titulo":"CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO","rotulo":"Art. 554.","conteudo":"Após o prazo de defesa ou a realização dos exames e diligências ordenados pelo juiz, de ofício ou a requerimento das partes, será marcada audiência, em que, inquiridas as testemunhas e produzidas alegações orais pelo órgão do Ministério Público e pelo defensor, dentro de dez minutos para cada um, o juiz proferirá sentença.\n\nParágrafo único. Se o juiz não se julgar habilitado a proferir a decisão, designará, desde logo, outra audiência, que se realizará dentro de cinco dias, para publicar a sentença."},{"chave":"art-555","sequencia":593,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO II — DOS PROCESSOS ESPECIAIS","CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO"],"titulo":"CAPÍTULO VII — DO PROCESSO DE APLICAÇÃO DE MEDIDA DE SEGURANÇA POR FATO NÃO CRIMINOSO","rotulo":"Art. 555.","conteudo":"Quando, instaurado processo por infração penal, o juiz, absolvendo ou impronunciando o réu, reconhecer a existência de qualquer dos fatos previstos no art. 14 ou no art. 27 do Código Penal , aplicar-lhe-á, se for caso, medida de segurança."},{"chave":"art-556","sequencia":594,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO III — DOS PROCESSOS DE COMPETÊNCIA DO SUPREMO TRIBUNAL FEDERAL E DOS TRIBUNAIS DE APELAÇÃO","CAPÍTULO I — DA INSTRUÇÃO"],"titulo":"CAPÍTULO I — DA INSTRUÇÃO","rotulo":"Art. 556.","conteudo":"a Art. 560 (Revogado pela Lei nº 8.658, de 26.5.1993)"},{"chave":"art-561","sequencia":595,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO II — DOS PROCESSOS EM ESPÉCIE","TÍTULO III — DOS PROCESSOS DE COMPETÊNCIA DO SUPREMO TRIBUNAL FEDERAL E DOS TRIBUNAIS DE APELAÇÃO","CAPÍTULO II — DO JULGAMENTO"],"titulo":"CAPÍTULO II — DO JULGAMENTO","rotulo":"Art. 561.","conteudo":"e Art. 562. (Revogado pela Lei nº 8.658, de 26.5.1993)"},{"chave":"art-563","sequencia":596,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO I — DAS NULIDADES"],"titulo":"TÍTULO I — DAS NULIDADES","rotulo":"Art. 563.","conteudo":"Nenhum ato será declarado nulo, se da nulidade não resultar prejuízo para a acusação ou para a defesa."},{"chave":"art-564","sequencia":597,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO I — DAS NULIDADES"],"titulo":"TÍTULO I — DAS NULIDADES","rotulo":"Art. 564.","conteudo":"A nulidade ocorrerá nos seguintes casos:\n\nI - por incompetência, suspeição ou suborno do juiz;\n\nII - por ilegitimidade de parte;\n\nIII - por falta das fórmulas ou dos termos seguintes:\n\na) a denúncia ou a queixa e a representação e, nos processos de contravenções penais, a portaria ou o auto de prisão em flagrante;\n\nb) o exame do corpo de delito nos crimes que deixam vestígios, ressalvado o disposto no Art. 167 ;\n\nc) a nomeação de defensor ao réu presente, que o não tiver, ou ao ausente, e de curador ao menor de 21 anos;\n\nd) a intervenção do Ministério Público em todos os termos da ação por ele intentada e nos da intentada pela parte ofendida, quando se tratar de crime de ação pública;\n\ne) a citação do réu para ver-se processar, o seu interrogatório, quando presente, e os prazos concedidos à acusação e à defesa;\n\nf) a sentença de pronúncia, o libelo e a entrega da respectiva cópia, com o rol de testemunhas, nos processos perante o Tribunal do Júri;\n\ng) a intimação do réu para a sessão de julgamento, pelo Tribunal do Júri, quando a lei não permitir o julgamento à revelia;\n\nh) a intimação das testemunhas arroladas no libelo e na contrariedade, nos termos estabelecidos pela lei;\n\ni) a presença pelo menos de 15 jurados para a constituição do júri;\n\nj) o sorteio dos jurados do conselho de sentença em número legal e sua incomunicabilidade;\n\nk) os quesitos e as respectivas respostas;\n\nl) a acusação e a defesa, na sessão de julgamento;\n\nm) a sentença;\n\nn) o recurso de oficio, nos casos em que a lei o tenha estabelecido;\n\no) a intimação, nas condições estabelecidas pela lei, para ciência de sentenças e despachos de que caiba recurso;\n\np) no Supremo Tribunal Federal e nos Tribunais de Apelação, o quorum legal para o julgamento;\n\nIV - por omissão de formalidade que constitua elemento essencial do ato.\n\nV - em decorrência de decisão carente de fundamentação. (Incluído pela Lei nº 13.964, de 2019)\n\nParágrafo único. Ocorrerá ainda a nulidade, por deficiência dos quesitos ou das suas respostas, e contradição entre estas. (Incluído pela Lei nº 263, de 23.2.1948)"},{"chave":"art-565","sequencia":598,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO I — DAS NULIDADES"],"titulo":"TÍTULO I — DAS NULIDADES","rotulo":"Art. 565.","conteudo":"Nenhuma das partes poderá argüir nulidade a que haja dado causa, ou para que tenha concorrido, ou referente a formalidade cuja observância só à parte contrária interesse."},{"chave":"art-566","sequencia":599,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO I — DAS NULIDADES"],"titulo":"TÍTULO I — DAS NULIDADES","rotulo":"Art. 566.","conteudo":"Não será declarada a nulidade de ato processual que não houver influído na apuração da verdade substancial ou na decisão da causa."},{"chave":"art-567","sequencia":600,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO I — DAS NULIDADES"],"titulo":"TÍTULO I — DAS NULIDADES","rotulo":"Art. 567.","conteudo":"A incompetência do juízo anula somente os atos decisórios, devendo o processo, quando for declarada a nulidade, ser remetido ao juiz competente."},{"chave":"art-568","sequencia":601,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO I — DAS NULIDADES"],"titulo":"TÍTULO I — DAS NULIDADES","rotulo":"Art. 568.","conteudo":"A nulidade por ilegitimidade do representante da parte poderá ser a todo tempo sanada, mediante ratificação dos atos processuais."},{"chave":"art-569","sequencia":602,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO I — DAS NULIDADES"],"titulo":"TÍTULO I — DAS NULIDADES","rotulo":"Art. 569.","conteudo":"As omissões da denúncia ou da queixa, da representação, ou, nos processos das contravenções penais, da portaria ou do auto de prisão em flagrante, poderão ser supridas a todo o tempo, antes da sentença final."},{"chave":"art-570","sequencia":603,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO I — DAS NULIDADES"],"titulo":"TÍTULO I — DAS NULIDADES","rotulo":"Art. 570.","conteudo":"A falta ou a nulidade da citação, da intimação ou notificação estará sanada, desde que o interessado compareça, antes de o ato consumar-se, embora declare que o faz para o único fim de argüi-la. O juiz ordenará, todavia, a suspensão ou o adiamento do ato, quando reconhecer que a irregularidade poderá prejudicar direito da parte."},{"chave":"art-571","sequencia":604,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO I — DAS NULIDADES"],"titulo":"TÍTULO I — DAS NULIDADES","rotulo":"Art. 571.","conteudo":"As nulidades deverão ser argüidas:\n\nI - as da instrução criminal dos processos da competência do júri, nos prazos a que se refere o art. 406 ;\n\nII - as da instrução criminal dos processos de competência do juiz singular e dos processos especiais, salvo os dos Capítulos V e Vll do Título II do Livro II , nos prazos a que se refere o art. 500 ;\n\nIII - as do processo sumário, no prazo a que se refere o art. 537 , ou, se verificadas depois desse prazo, logo depois de aberta a audiência e apregoadas as partes;\n\nIV - as do processo regulado no Capítulo VII do Título II do Livro II , logo depois de aberta a audiência;\n\nV - as ocorridas posteriormente à pronúncia, logo depois de anunciado o julgamento e apregoadas as partes ( art. 447 );\n\nVI - as de instrução criminal dos processos de competência do Supremo Tribunal Federal e dos Tribunais de Apelação, nos prazos a que se refere o art. 500 ;\n\nVII - se verificadas após a decisão da primeira instância, nas razões de recurso ou logo depois de anunciado o julgamento do recurso e apregoadas as partes;\n\nVIII - as do julgamento em plenário, em audiência ou em sessão do tribunal, logo depois de ocorrerem."},{"chave":"art-572","sequencia":605,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO I — DAS NULIDADES"],"titulo":"TÍTULO I — DAS NULIDADES","rotulo":"Art. 572.","conteudo":"As nulidades previstas no art. 564, Ill, d e e , segunda parte, g e h , e IV, considerar-se-ão sanadas:\n\nI - se não forem argüidas, em tempo oportuno, de acordo com o disposto no artigo anterior;\n\nII - se, praticado por outra forma, o ato tiver atingido o seu fim;\n\nIII - se a parte, ainda que tacitamente, tiver aceito os seus efeitos."},{"chave":"art-573","sequencia":606,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO I — DAS NULIDADES"],"titulo":"TÍTULO I — DAS NULIDADES","rotulo":"Art. 573.","conteudo":"Os atos, cuja nulidade não tiver sido sanada, na forma dos artigos anteriores, serão renovados ou retificados.\n\n§ 1 o A nulidade de um ato, uma vez declarada, causará a dos atos que dele diretamente dependam ou sejam conseqüência.\n\n§ 2 o O juiz que pronunciar a nulidade declarará os atos a que ela se estende."},{"chave":"art-574","sequencia":607,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 574.","conteudo":"Os recursos serão voluntários, excetuando-se os seguintes casos, em que deverão ser interpostos, de ofício, pelo juiz:\n\nI - da sentença que conceder habeas corpus ;\n\nII - da que absolver desde logo o réu com fundamento na existência de circunstância que exclua o crime ou isente o réu de pena, nos termos do art. 411 ."},{"chave":"art-575","sequencia":608,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 575.","conteudo":"Não serão prejudicados os recursos que, por erro, falta ou omissão dos funcionários, não tiverem seguimento ou não forem apresentados dentro do prazo."},{"chave":"art-576","sequencia":609,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 576.","conteudo":"O Ministério Público não poderá desistir de recurso que haja interposto."},{"chave":"art-577","sequencia":610,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 577.","conteudo":"O recurso poderá ser interposto pelo Ministério Público, ou pelo querelante, ou pelo réu, seu procurador ou seu defensor.\n\nParágrafo único. Não se admitirá, entretanto, recurso da parte que não tiver interesse na reforma ou modificação da decisão."},{"chave":"art-578","sequencia":611,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 578.","conteudo":"O recurso será interposto por petição ou por termo nos autos, assinado pelo recorrente ou por seu representante.\n\n§ 1 o Não sabendo ou não podendo o réu assinar o nome, o termo será assinado por alguém, a seu rogo, na presença de duas testemunhas.\n\n§ 2 o A petição de interposição de recurso, com o despacho do juiz, será, até o dia seguinte ao último do prazo, entregue ao escrivão, que certificará no termo da juntada a data da entrega.\n\n§ 3 o Interposto por termo o recurso, o escrivão, sob pena de suspensão por dez a trinta dias, fará conclusos os autos ao juiz, até o dia seguinte ao último do prazo."},{"chave":"art-579","sequencia":612,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 579.","conteudo":"Salvo a hipótese de má-fé, a parte não será prejudicada pela interposição de um recurso por outro.\n\nParágrafo único. Se o juiz, desde logo, reconhecer a impropriedade do recurso interposto pela parte, mandará processá-lo de acordo com o rito do recurso cabível."},{"chave":"art-580","sequencia":613,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 580.","conteudo":"No caso de concurso de agentes ( Código Penal, art. 25 ), a decisão do recurso interposto por um dos réus, se fundado em motivos que não sejam de caráter exclusivamente pessoal, aproveitará aos outros."},{"chave":"art-581","sequencia":614,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO"],"titulo":"CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO","rotulo":"Art. 581.","conteudo":"Caberá recurso, no sentido estrito, da decisão, despacho ou sentença:\n\nI - que não receber a denúncia ou a queixa;\n\nII - que concluir pela incompetência do juízo;\n\nIII - que julgar procedentes as exceções, salvo a de suspeição;\n\nIV – que pronunciar o réu; (Redação dada pela Lei nº 11.689, de 2008)\n\nV - que conceder, negar, arbitrar, cassar ou julgar inidônea a fiança, indeferir requerimento de prisão preventiva ou revogá-la, conceder liberdade provisória ou relaxar a prisão em flagrante; (Redação dada pela Lei nº 7.780, de 22.6.1989)\n\nVI - (Revogado pela Lei nº 11.689, de 2008)\n\nVII - que julgar quebrada a fiança ou perdido o seu valor;\n\nVIII - que decretar a prescrição ou julgar, por outro modo, extinta a punibilidade;\n\nIX - que indeferir o pedido de reconhecimento da prescrição ou de outra causa extintiva da punibilidade;\n\nX - que conceder ou negar a ordem de habeas corpus ;\n\nXI - que conceder, negar ou revogar a suspensão condicional da pena;\n\nXII - que conceder, negar ou revogar livramento condicional;\n\nXIII - que anular o processo da instrução criminal, no todo ou em parte;\n\nXIV - que incluir jurado na lista geral ou desta o excluir;\n\nXV - que denegar a apelação ou a julgar deserta;\n\nXVI - que ordenar a suspensão do processo, em virtude de questão prejudicial;\n\nXVII - que decidir sobre a unificação de penas;\n\nXVIII - que decidir o incidente de falsidade;\n\nXIX - que decretar medida de segurança, depois de transitar a sentença em julgado;\n\nXX - que impuser medida de segurança por transgressão de outra;\n\nXXI - que mantiver ou substituir a medida de segurança, nos casos do art. 774 ;\n\nXXII - que revogar a medida de segurança;\n\nXXIII - que deixar de revogar a medida de segurança, nos casos em que a lei admita a revogação;\n\nXXIV - que converter a multa em detenção ou em prisão simples.\n\nXXV - que recusar homologação à proposta de acordo de não persecução penal, previsto no art. 28-A desta Lei. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-582-o","sequencia":615,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO"],"titulo":"CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO","rotulo":"Art. 582º-O","conteudo":"s recursos serão sempre para o Tribunal de Apelação, salvo nos casos dos ns. V, X e XIV.\n\nParágrafo único. O recurso, no caso do n o XIV, será para o presidente do Tribunal de Apelação."},{"chave":"art-583","sequencia":616,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO"],"titulo":"CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO","rotulo":"Art. 583.","conteudo":"Subirão nos próprios autos os recursos:\n\nI - quando interpostos de oficio;\n\nII - nos casos do art. 581, I, III, IV, VI, VIII e X ;\n\nIII - quando o recurso não prejudicar o andamento do processo.\n\nParágrafo único. O recurso da pronúncia subirá em traslado, quando, havendo dois ou mais réus, qualquer deles se conformar com a decisão ou todos não tiverem sido ainda intimados da pronúncia."},{"chave":"art-584","sequencia":617,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO"],"titulo":"CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO","rotulo":"Art. 584.","conteudo":"Os recursos terão efeito suspensivo nos casos de perda da fiança, de concessão de livramento condicional e dos ns. XV, XVII e XXIV do art. 581 .\n\n§ 1 o Ao recurso interposto de sentença de impronúncia ou no caso do no VIII do art. 581 , aplicar-se-á o disposto nos arts. 596 e 598 .\n\n§ 2 o O recurso da pronúncia suspenderá tão-somente o julgamento.\n\n§ 3 o O recurso do despacho que julgar quebrada a fiança suspenderá unicamente o efeito de perda da metade do seu valor.\n\n§ 4º No caso previsto no inciso V do caput do art. 581, sem prejuízo do disposto no art. 589 deste Código, a qualquer tempo, até o julgamento, o recorrente poderá pedir ao Tribunal ad quem concessão de efeito suspensivo ou ativo ao recurso interposto, demonstrando a relevância dos motivos, a plausibilidade do direito alegado e a probabilidade de dano irreparável ou de difícil reparação, durante a tramitação. (Incluído pela Lei nº 15.358, de 2026)"},{"chave":"art-585","sequencia":618,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO"],"titulo":"CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO","rotulo":"Art. 585.","conteudo":"O réu não poderá recorrer da pronúncia senão depois de preso, salvo se prestar fiança, nos casos em que a lei a admitir."},{"chave":"art-586","sequencia":619,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO"],"titulo":"CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO","rotulo":"Art. 586.","conteudo":"O recurso voluntário poderá ser interposto no prazo de cinco dias.\n\nParágrafo único. No caso do art. 581, XIV , o prazo será de vinte dias, contado da data da publicação definitiva da lista de jurados."},{"chave":"art-587","sequencia":620,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO"],"titulo":"CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO","rotulo":"Art. 587.","conteudo":"Quando o recurso houver de subir por instrumento, a parte indicará, no respectivo termo, ou em requerimento avulso, as peças dos autos de que pretenda traslado.\n\nParágrafo único. O traslado será extraído, conferido e concertado no prazo de cinco dias, e dele constarão sempre a decisão recorrida, a certidão de sua intimação, se por outra forma não for possível verificar-se a oportunidade do recurso, e o termo de interposição."},{"chave":"art-588","sequencia":621,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO"],"titulo":"CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO","rotulo":"Art. 588.","conteudo":"Dentro de dois dias, contados da interposição do recurso, ou do dia em que o escrivão, extraído o traslado, o fizer com vista ao recorrente, este oferecerá as razões e, em seguida, será aberta vista ao recorrido por igual prazo.\n\nParágrafo único. Se o recorrido for o réu, será intimado do prazo na pessoa do defensor."},{"chave":"art-589","sequencia":622,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO"],"titulo":"CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO","rotulo":"Art. 589.","conteudo":"Com a resposta do recorrido ou sem ela, será o recurso concluso ao juiz, que, dentro de dois dias, reformará ou sustentará o seu despacho, mandando instruir o recurso com os traslados que Ihe parecerem necessários.\n\nParágrafo único. Se o juiz reformar o despacho recorrido, a parte contrária, por simples petição, poderá recorrer da nova decisão, se couber recurso, não sendo mais lícito ao juiz modificá-la. Neste caso, independentemente de novos arrazoados, subirá o recurso nos próprios autos ou em traslado."},{"chave":"art-590","sequencia":623,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO"],"titulo":"CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO","rotulo":"Art. 590.","conteudo":"Quando for impossível ao escrivão extrair o traslado no prazo da lei, poderá o juiz prorrogá-lo até o dobro."},{"chave":"art-591","sequencia":624,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO"],"titulo":"CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO","rotulo":"Art. 591.","conteudo":"Os recursos serão apresentados ao juiz ou tribunal ad quem , dentro de cinco dias da publicação da resposta do juiz a quo , ou entregues ao Correio dentro do mesmo prazo."},{"chave":"art-592","sequencia":625,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO"],"titulo":"CAPÍTULO II — DO RECURSO EM SENTIDO ESTRITO","rotulo":"Art. 592.","conteudo":"Publicada a decisão do juiz ou do tribunal ad quem , deverão os autos ser devolvidos, dentro de cinco dias, ao juiz a quo ."},{"chave":"art-593","sequencia":626,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 593.","conteudo":"Caberá apelação no prazo de 5 (cinco) dias: (Redação dada pela Lei nº 263, de 23.2.1948)\n\nI - das sentenças definitivas de condenação ou absolvição proferidas por juiz singular; (Redação dada pela Lei nº 263, de 23.2.1948)\n\nII - das decisões definitivas, ou com força de definitivas, proferidas por juiz singular nos casos não previstos no Capítulo anterior; (Redação dada pela Lei nº 263, de 23.2.1948)\n\nIII - das decisões do Tribunal do Júri, quando: (Redação dada pela Lei nº 263, de 23.2.1948)\n\na) ocorrer nulidade posterior à pronúncia; (Redação dada pela Lei nº 263, de 23.2.1948)\n\nb) for a sentença do juiz-presidente contrária à lei expressa ou à decisão dos jurados; (Redação dada pela Lei nº 263, de 23.2.1948)\n\nc) houver erro ou injustiça no tocante à aplicação da pena ou da medida de segurança; (Redação dada pela Lei nº 263, de 23.2.1948)\n\nd) for a decisão dos jurados manifestamente contrária à prova dos autos. (Incluído pela Lei nº 263, de 23.2.1948)\n\n§ 1 o Se a sentença do juiz-presidente for contrária à lei expressa ou divergir das respostas dos jurados aos quesitos, o tribunal ad quem fará a devida retificação. (Incluído pela Lei nº 263, de 23.2.1948)\n\n§ 2 o Interposta a apelação com fundamento no n o III, c , deste artigo, o tribunal ad quem , se Ihe der provimento, retificará a aplicação da pena ou da medida de segurança. (Incluído pela Lei nº 263, de 23.2.1948)\n\n§ 3 o Se a apelação se fundar no n o III, d , deste artigo, e o tribunal ad quem se convencer de que a decisão dos jurados é manifestamente contrária à prova dos autos, dar-lhe-á provimento para sujeitar o réu a novo julgamento; não se admite, porém, pelo mesmo motivo, segunda apelação. (Incluído pela Lei nº 263, de 23.2.1948)\n\n§ 4 o Quando cabível a apelação, não poderá ser usado o recurso em sentido estrito, ainda que somente de parte da decisão se recorra. (Parágrafo único renumerado pela Lei nº 263, de 23.2.1948)"},{"chave":"art-594","sequencia":627,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 594.","conteudo":"(Revogado pela Lei nº 11.719, de 2008)."},{"chave":"art-595","sequencia":628,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 595.","conteudo":"(Revogado pela Lei nº 12.403, de 2011)."},{"chave":"art-596","sequencia":629,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 596.","conteudo":"A apelação da sentença absolutória não impedirá que o réu seja posto imediatamente em liberdade. (Redação dada pela Lei nº 5.941, de 22.11.1973)\n\nParágrafo único. A apelação não suspenderá a execução da medida de segurança aplicada provisoriamente. (Redação dada pela Lei nº 5.941, de 22.11.1973)"},{"chave":"art-597","sequencia":630,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 597.","conteudo":"A apelação de sentença condenatória terá efeito suspensivo, salvo o disposto no art. 393 , a aplicação provisória de interdições de direitos e de medidas de segurança ( arts. 374 e 378 ), e o caso de suspensão condicional de pena."},{"chave":"art-598","sequencia":631,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 598.","conteudo":"Nos crimes de competência do Tribunal do Júri, ou do juiz singular, se da sentença não for interposta apelação pelo Ministério Público no prazo legal, o ofendido ou qualquer das pessoas enumeradas no art. 31, ainda que não se tenha habilitado como assistente, poderá interpor apelação, que não terá, porém, efeito suspensivo.\n\nParágrafo único. O prazo para interposição desse recurso será de quinze dias e correrá do dia em que terminar o do Ministério Público."},{"chave":"art-599","sequencia":632,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 599.","conteudo":"As apelações poderão ser interpostas quer em relação a todo o julgado, quer em relação a parte dele."},{"chave":"art-600","sequencia":633,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 600.","conteudo":"Assinado o termo de apelação, o apelante e, depois dele, o apelado terão o prazo de oito dias cada um para oferecer razões, salvo nos processos de contravenção, em que o prazo será de três dias.\n\n§ 1 o Se houver assistente, este arrazoará, no prazo de três dias, após o Ministério Público.\n\n§ 2 o Se a ação penal for movida pela parte ofendida, o Ministério Público terá vista dos autos, no prazo do parágrafo anterior.\n\n§ 3 o Quando forem dois ou mais os apelantes ou apelados, os prazos serão comuns.\n\n§ 4 o Se o apelante declarar, na petição ou no termo, ao interpor a apelação, que deseja arrazoar na superior instância serão os autos remetidos ao tribunal ad quem onde será aberta vista às partes, observados os prazos legais, notificadas as partes pela publicação oficial. (Incluído pela Lei nº 4.336, de 1º.6.1964)"},{"chave":"art-601","sequencia":634,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 601.","conteudo":"Findos os prazos para razões, os autos serão remetidos à instância superior, com as razões ou sem elas, no prazo de 5 (cinco) dias, salvo no caso do art. 603 , segunda parte, em que o prazo será de trinta dias.\n\n§ 1 o Se houver mais de um réu, e não houverem todos sido julgados, ou não tiverem todos apelado, caberá ao apelante promover extração do traslado dos autos, o qual deverá ser remetido à instância superior no prazo de trinta dias, contado da data da entrega das últimas razões de apelação, ou do vencimento do prazo para a apresentação das do apelado.\n\n§ 2 o As despesas do traslado correrão por conta de quem o solicitar, salvo se o pedido for de réu pobre ou do Ministério Público."},{"chave":"art-602","sequencia":635,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 602.","conteudo":"Os autos serão, dentro dos prazos do artigo anterior, apresentados ao tribunal ad quem ou entregues ao Correio, sob registro."},{"chave":"art-603","sequencia":636,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 603.","conteudo":"A apelação subirá nos autos originais e, a não ser no Distrito Federal e nas comarcas que forem sede de Tribunal de Apelação, ficará em cartório traslado dos termos essenciais do processo referidos no art. 564, n. III ."},{"chave":"art-604","sequencia":637,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 604.","conteudo":"(Revogado pela Lei nº 263, de 23.2.1948)"},{"chave":"art-605","sequencia":638,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 605.","conteudo":"(Revogado pela Lei nº 263, de 23.2.1948)"},{"chave":"art-606","sequencia":639,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO III — DA APELAÇÃO"],"titulo":"CAPÍTULO III — DA APELAÇÃO","rotulo":"Art. 606.","conteudo":"(Revogado pela Lei nº 263, de 23.2.1948)"},{"chave":"art-607","sequencia":640,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO IV — DO PROTESTO POR NOVO JÚRI"],"titulo":"CAPÍTULO IV — DO PROTESTO POR NOVO JÚRI","rotulo":"Art. 607.","conteudo":"(Revogado pela Lei nº 11.689, de 2008)"},{"chave":"art-608","sequencia":641,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO IV — DO PROTESTO POR NOVO JÚRI"],"titulo":"CAPÍTULO IV — DO PROTESTO POR NOVO JÚRI","rotulo":"Art. 608.","conteudo":"(Revogado pela Lei nº 11.689, de 2008)"},{"chave":"art-609","sequencia":642,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO"],"titulo":"CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO","rotulo":"Art. 609.","conteudo":"Os recursos, apelações e embargos serão julgados pelos Tribunais de Justiça, câmaras ou turmas criminais, de acordo com a competência estabelecida nas leis de organização judiciária. (Redação dada pela Lei nº 1.720-B, de 3.11.1952)\n\nParágrafo único. Quando não for unânime a decisão de segunda instância, desfavorável ao réu, admitem-se embargos infringentes e de nulidade, que poderão ser opostos dentro de 10 (dez) dias, a contar da publicação de acórdão, na forma do art. 613 . Se o desacordo for parcial, os embargos serão restritos à matéria objeto de divergência. (Incluído pela Lei nº 1.720-B, de 3.11.1952)"},{"chave":"art-610","sequencia":643,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO"],"titulo":"CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO","rotulo":"Art. 610.","conteudo":"Nos recursos em sentido estrito, com exceção do de habeas corpus , e nas apelações interpostas das sentenças em processo de contravenção ou de crime a que a lei comine pena de detenção, os autos irão imediatamente com vista ao procurador-geral pelo prazo de cinco dias, e, em seguida, passarão, por igual prazo, ao relator, que pedirá designação de dia para o julgamento.\n\nParágrafo único. Anunciado o julgamento pelo presidente, e apregoadas as partes, com a presença destas ou à sua revelia, o relator fará a exposição do feito e, em seguida, o presidente concederá, pelo prazo de 10 (dez) minutos, a palavra aos advogados ou às partes que a solicitarem e ao procurador-geral, quando o requerer, por igual prazo."},{"chave":"art-612","sequencia":644,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO"],"titulo":"CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO","rotulo":"Art. 612.","conteudo":"Os recursos de habeas corpus , designado o relator, serão julgados na primeira sessão."},{"chave":"art-613","sequencia":645,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO"],"titulo":"CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO","rotulo":"Art. 613.","conteudo":"As apelações interpostas das sentenças proferidas em processos por crime a que a lei comine pena de reclusão, deverão ser processadas e julgadas pela forma estabelecida no Art. 610 , com as seguintes modificações:\n\nI - exarado o relatório nos autos, passarão estes ao revisor, que terá igual prazo para o exame do processo e pedirá designação de dia para o julgamento;\n\nII - os prazos serão ampliados ao dobro;\n\nIII - o tempo para os debates será de um quarto de hora."},{"chave":"art-614","sequencia":646,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO"],"titulo":"CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO","rotulo":"Art. 614.","conteudo":"No caso de impossibilidade de observância de qualquer dos prazos marcados nos arts. 610 e 613 , os motivos da demora serão declarados nos autos."},{"chave":"art-615","sequencia":647,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO"],"titulo":"CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO","rotulo":"Art. 615.","conteudo":"O tribunal decidirá por maioria de votos.\n\n§ 1º Em todos os julgamentos em matéria penal ou processual penal em órgãos colegiados, havendo empate, prevalecerá a decisão mais favorável ao indivíduo imputado, proclamando-se de imediato esse resultado, ainda que, nas hipóteses de vaga aberta a ser preenchida, de impedimento, de suspeição ou de ausência, tenha sido o julgamento tomado sem a totalidade dos integrantes do colegiado. (Redação dada pela Lei nº 14.836, de 2024)\n\n§ 2 o O acórdão será apresentado à conferência na primeira sessão seguinte à do julgamento, ou no prazo de duas sessões, pelo juiz incumbido de lavrá-lo."},{"chave":"art-616","sequencia":648,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO"],"titulo":"CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO","rotulo":"Art. 616.","conteudo":"No julgamento das apelações poderá o tribunal, câmara ou turma proceder a novo interrogatório do acusado, reinquirir testemunhas ou determinar outras diligências."},{"chave":"art-617","sequencia":649,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO"],"titulo":"CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO","rotulo":"Art. 617.","conteudo":"O tribunal, câmara ou turma atenderá nas suas decisões ao disposto nos arts. 383 , 386 e 387 , no que for aplicável, não podendo, porém, ser agravada a pena, quando somente o réu houver apelado da sentença."},{"chave":"art-618","sequencia":650,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO"],"titulo":"CAPÍTULO V — DO PROCESSO E DO JULGAMENTO DOS RECURSOS EM SENTIDO ESTRITO E DAS APELAÇÕES, NOS TRIBUNAIS DE APELAÇÃO","rotulo":"Art. 618.","conteudo":"Os regimentos dos Tribunais de Apelação estabelecerão as normas complementares para o processo e julgamento dos recursos e apelações."},{"chave":"art-619","sequencia":651,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VI — DOS EMBARGOS"],"titulo":"CAPÍTULO VI — DOS EMBARGOS","rotulo":"Art. 619.","conteudo":"Aos acórdãos proferidos pelos Tribunais de Apelação, câmaras ou turmas, poderão ser opostos embargos de declaração, no prazo de dois dias contados da sua publicação, quando houver na sentença ambiguidade, obscuridade, contradição ou omissão."},{"chave":"art-620","sequencia":652,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VI — DOS EMBARGOS"],"titulo":"CAPÍTULO VI — DOS EMBARGOS","rotulo":"Art. 620.","conteudo":"Os embargos de declaração serão deduzidos em requerimento de que constem os pontos em que o acórdão é ambíguo, obscuro, contraditório ou omisso.\n\n§ 1 o O requerimento será apresentado pelo relator e julgado, independentemente de revisão, na primeira sessão.\n\n§ 2 o Se não preenchidas as condições enumeradas neste artigo, o relator indeferirá desde logo o requerimento."},{"chave":"art-621","sequencia":653,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VII — DA REVISÃO"],"titulo":"CAPÍTULO VII — DA REVISÃO","rotulo":"Art. 621.","conteudo":"A revisão dos processos findos será admitida:\n\nI - quando a sentença condenatória for contrária ao texto expresso da lei penal ou à evidência dos autos;\n\nII - quando a sentença condenatória se fundar em depoimentos, exames ou documentos comprovadamente falsos;\n\nIII - quando, após a sentença, se descobrirem novas provas de inocência do condenado ou de circunstância que determine ou autorize diminuição especial da pena."},{"chave":"art-622","sequencia":654,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VII — DA REVISÃO"],"titulo":"CAPÍTULO VII — DA REVISÃO","rotulo":"Art. 622.","conteudo":"A revisão poderá ser requerida em qualquer tempo, antes da extinção da pena ou após.\n\nParágrafo único. Não será admissível a reiteração do pedido, salvo se fundado em novas provas."},{"chave":"art-623","sequencia":655,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VII — DA REVISÃO"],"titulo":"CAPÍTULO VII — DA REVISÃO","rotulo":"Art. 623.","conteudo":"A revisão poderá ser pedida pelo próprio réu ou por procurador legalmente habilitado ou, no caso de morte do réu, pelo cônjuge, ascendente, descendente ou irmão."},{"chave":"art-624","sequencia":656,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VII — DA REVISÃO"],"titulo":"CAPÍTULO VII — DA REVISÃO","rotulo":"Art. 624.","conteudo":"As revisões criminais serão processadas e julgadas: (Redação dada pelo Decreto-lei nº 504, de 18.3.1969)\n\nI - pelo Supremo Tribunal Federal, quanto às condenações por ele proferidas; (Redação dada pelo Decreto-lei nº 504, de 18.3.1969)\n\nII - pelo Tribunal Federal de Recursos, Tribunais de Justiça ou de Alçada, nos demais casos. (Redação dada pelo Decreto-lei nº 504, de 18.3.1969)\n\n§ 1 o No Supremo Tribunal Federal e no Tribunal Federal de Recursos o processo e julgamento obedecerão ao que for estabelecido no respectivo regimento interno. (Incluído pelo Decreto-lei nº 504, de 18.3.1969)\n\n§ 2 o Nos Tribunais de Justiça ou de Alçada, o julgamento será efetuado pelas câmaras ou turmas criminais, reunidas em sessão conjunta, quando houver mais de uma, e, no caso contrário, pelo tribunal pleno. (Incluído pelo Decreto-lei nº 504, de 18.3.1969)\n\n§ 3 o Nos tribunais onde houver quatro ou mais câmaras ou turmas criminais, poderão ser constituídos dois ou mais grupos de câmaras ou turmas para o julgamento de revisão, obedecido o que for estabelecido no respectivo regimento interno. (Incluído pelo Decreto-lei nº 504, de 18.3.1969)"},{"chave":"art-625","sequencia":657,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VII — DA REVISÃO"],"titulo":"CAPÍTULO VII — DA REVISÃO","rotulo":"Art. 625.","conteudo":"O requerimento será distribuído a um relator e a um revisor, devendo funcionar como relator um desembargador que não tenha pronunciado decisão em qualquer fase do processo.\n\n§ 1 o O requerimento será instruído com a certidão de haver passado em julgado a sentença condenatória e com as peças necessárias à comprovação dos fatos argüidos.\n\n§ 2 o O relator poderá determinar que se apensem os autos originais, se daí não advier dificuldade à execução normal da sentença.\n\n§ 3 o Se o relator julgar insuficientemente instruído o pedido e inconveniente ao interesse da justiça que se apensem os autos originais, indeferi-lo-á in limine , dando recurso para as câmaras reunidas ou para o tribunal, conforme o caso ( art. 624, parágrafo único ).\n\n§ 4 o Interposto o recurso por petição e independentemente de termo, o relator apresentará o processo em mesa para o julgamento e o relatará, sem tomar parte na discussão.\n\n§ 5 o Se o requerimento não for indeferido in limine , abrir-se-á vista dos autos ao procurador-geral, que dará parecer no prazo de dez dias. Em seguida, examinados os autos, sucessivamente, em igual prazo, pelo relator e revisor, julgar-se-á o pedido na sessão que o presidente designar."},{"chave":"art-626","sequencia":658,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VII — DA REVISÃO"],"titulo":"CAPÍTULO VII — DA REVISÃO","rotulo":"Art. 626.","conteudo":"Julgando procedente a revisão, o tribunal poderá alterar a classificação da infração, absolver o réu, modificar a pena ou anular o processo.\n\nParágrafo único. De qualquer maneira, não poderá ser agravada a pena imposta pela decisão revista."},{"chave":"art-627","sequencia":659,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VII — DA REVISÃO"],"titulo":"CAPÍTULO VII — DA REVISÃO","rotulo":"Art. 627.","conteudo":"A absolvição implicará o restabelecimento de todos os direitos perdidos em virtude da condenação, devendo o tribunal, se for caso, impor a medida de segurança cabível."},{"chave":"art-628","sequencia":660,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VII — DA REVISÃO"],"titulo":"CAPÍTULO VII — DA REVISÃO","rotulo":"Art. 628.","conteudo":"Os regimentos internos dos Tribunais de Apelação estabelecerão as normas complementares para o processo e julgamento das revisões criminais."},{"chave":"art-629","sequencia":661,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VII — DA REVISÃO"],"titulo":"CAPÍTULO VII — DA REVISÃO","rotulo":"Art. 629.","conteudo":"À vista da certidão do acórdão que cassar a sentença condenatória, o juiz mandará juntá-la imediatamente aos autos, para inteiro cumprimento da decisão."},{"chave":"art-630","sequencia":662,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VII — DA REVISÃO"],"titulo":"CAPÍTULO VII — DA REVISÃO","rotulo":"Art. 630.","conteudo":"O tribunal, se o interessado o requerer, poderá reconhecer o direito a uma justa indenização pelos prejuízos sofridos.\n\n§ 1 o Por essa indenização, que será liquidada no juízo cível, responderá a União, se a condenação tiver sido proferida pela justiça do Distrito Federal ou de Território, ou o Estado, se o tiver sido pela respectiva justiça.\n\n§ 2 o A indenização não será devida:\n\na) se o erro ou a injustiça da condenação proceder de ato ou falta imputável ao próprio impetrante, como a confissão ou a ocultação de prova em seu poder;\n\nb) se a acusação houver sido meramente privada."},{"chave":"art-631","sequencia":663,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VII — DA REVISÃO"],"titulo":"CAPÍTULO VII — DA REVISÃO","rotulo":"Art. 631.","conteudo":"Quando, no curso da revisão, falecer a pessoa, cuja condenação tiver de ser revista, o presidente do tribunal nomeará curador para a defesa."},{"chave":"art-632","sequencia":664,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO"],"titulo":"CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO","rotulo":"Art. 632.","conteudo":"(Revogado pela Lei nº 3.396, de 2.6.1958):"},{"chave":"art-633","sequencia":665,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO"],"titulo":"CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO","rotulo":"Art. 633.","conteudo":"(Revogado pela Lei nº 3.396, de 2.6.1958):"},{"chave":"art-634","sequencia":666,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO"],"titulo":"CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO","rotulo":"Art. 634.","conteudo":"(Revogado pela Lei nº 3.396, de 2.6.1958):"},{"chave":"art-635","sequencia":667,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO"],"titulo":"CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO","rotulo":"Art. 635.","conteudo":"(Revogado pela Lei nº 3.396, de 2.6.1958):"},{"chave":"art-636","sequencia":668,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO"],"titulo":"CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO","rotulo":"Art. 636.","conteudo":"(Revogado pela Lei nº 3.396, de 2.6.1958):"},{"chave":"art-637","sequencia":669,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO"],"titulo":"CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO","rotulo":"Art. 637.","conteudo":"O recurso extraordinário não tem efeito suspensivo, e uma vez arrazoados pelo recorrido os autos do traslado, os originais baixarão à primeira instância, para a execução da sentença."},{"chave":"art-638","sequencia":670,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO"],"titulo":"CAPÍTULO VIII — DO RECURSO EXTRAORDINÁRIO","rotulo":"Art. 638.","conteudo":"O recurso extraordinário e o recurso especial serão processados e julgados no Supremo Tribunal Federal e no Superior Tribunal de Justiça na forma estabelecida por leis especiais, pela lei processual civil e pelos respectivos regimentos internos. (Redação dada pela Lei nº 13.964, de 2019)"},{"chave":"art-639","sequencia":671,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL"],"titulo":"CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL","rotulo":"Art. 639.","conteudo":"Dar-se-á carta testemunhável:\n\nI - da decisão que denegar o recurso;\n\nII - da que, admitindo embora o recurso, obstar à sua expedição e seguimento para o juízo ad quem ."},{"chave":"art-640","sequencia":672,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL"],"titulo":"CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL","rotulo":"Art. 640.","conteudo":"A carta testemunhável será requerida ao escrivão, ou ao secretário do tribunal, conforme o caso, nas quarenta e oito horas seguintes ao despacho que denegar o recurso, indicando o requerente as peças do processo que deverão ser trasladadas."},{"chave":"art-641","sequencia":673,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL"],"titulo":"CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL","rotulo":"Art. 641.","conteudo":"O escrivão, ou o secretário do tribunal, dará recibo da petição à parte e, no prazo máximo de cinco dias, no caso de recurso no sentido estrito, ou de sessenta dias, no caso de recurso extraordinário, fará entrega da carta, devidamente conferida e concertada."},{"chave":"art-642","sequencia":674,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL"],"titulo":"CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL","rotulo":"Art. 642.","conteudo":"O escrivão, ou o secretário do tribunal, que se negar a dar o recibo, ou deixar de entregar, sob qualquer pretexto, o instrumento, será suspenso por trinta dias. O juiz, ou o presidente do Tribunal de Apelação, em face de representação do testemunhante, imporá a pena e mandará que seja extraído o instrumento, sob a mesma sanção, pelo substituto do escrivão ou do secretário do tribunal. Se o testemunhante não for atendido, poderá reclamar ao presidente do tribunal ad quem , que avocará os autos, para o efeito do julgamento do recurso e imposição da pena."},{"chave":"art-643","sequencia":675,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL"],"titulo":"CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL","rotulo":"Art. 643.","conteudo":"Extraído e autuado o instrumento, observar-se-á o disposto nos arts. 588 a 592 , no caso de recurso em sentido estrito, ou o processo estabelecido para o recurso extraordinário, se deste se tratar."},{"chave":"art-644","sequencia":676,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL"],"titulo":"CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL","rotulo":"Art. 644.","conteudo":"O tribunal, câmara ou turma a que competir o julgamento da carta, se desta tomar conhecimento, mandará processar o recurso, ou, se estiver suficientemente instruída, decidirá logo, de meritis ."},{"chave":"art-645","sequencia":677,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL"],"titulo":"CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL","rotulo":"Art. 645.","conteudo":"O processo da carta testemunhável na instância superior seguirá o processo do recurso denegado."},{"chave":"art-646","sequencia":678,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL"],"titulo":"CAPÍTULO IX — DA CARTA TESTEMUNHÁVEL","rotulo":"Art. 646.","conteudo":"A carta testemunhável não terá efeito suspensivo."},{"chave":"art-647","sequencia":679,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 647.","conteudo":"Dar-se-á habeas corpus sempre que alguém sofrer ou se achar na iminência de sofrer violência ou coação ilegal na sua liberdade de ir e vir, salvo nos casos de punição disciplinar."},{"chave":"art-647-a","sequencia":680,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 647º-A","conteudo":"No âmbito de sua competência jurisdicional, qualquer autoridade judicial poderá expedir de ofício ordem de habeas corpus , individual ou coletivo, quando, no curso de qualquer processo judicial, verificar que, por violação ao ordenamento jurídico, alguém sofre ou se acha ameaçado de sofrer violência ou coação em sua liberdade de locomoção. (Incluído pela Lei nº 14.836, de 2024)\n\nParágrafo único. A ordem de habeas corpus poderá ser concedida de ofício pelo juiz ou pelo tribunal em processo de competência originária ou recursal, ainda que não conhecidos a ação ou o recurso em que veiculado o pedido de cessação de coação ilegal. (Incluído pela Lei nº 14.836, de 2024)"},{"chave":"art-648","sequencia":681,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 648.","conteudo":"A coação considerar-se-á ilegal:\n\nI - quando não houver justa causa;\n\nII - quando alguém estiver preso por mais tempo do que determina a lei;\n\nIII - quando quem ordenar a coação não tiver competência para fazê-lo;\n\nIV - quando houver cessado o motivo que autorizou a coação;\n\nV - quando não for alguém admitido a prestar fiança, nos casos em que a lei a autoriza;\n\nVI - quando o processo for manifestamente nulo;\n\nVII - quando extinta a punibilidade."},{"chave":"art-649","sequencia":682,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 649.","conteudo":"O juiz ou o tribunal, dentro dos limites da sua jurisdição, fará passar imediatamente a ordem impetrada, nos casos em que tenha cabimento, seja qual for a autoridade coatora."},{"chave":"art-650","sequencia":683,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 650.","conteudo":"Competirá conhecer, originariamente, do pedido de habeas corpus :\n\nI - ao Supremo Tribunal Federal, nos casos previstos no Art. 101, I, g , da Constituição ;\n\nII - aos Tribunais de Apelação, sempre que os atos de violência ou coação forem atribuídos aos governadores ou interventores dos Estados ou Territórios e ao prefeito do Distrito Federal, ou a seus secretários, ou aos chefes de Polícia.\n\n§ 1 o A competência do juiz cessará sempre que a violência ou coação provier de autoridade judiciária de igual ou superior jurisdição.\n\n§ 2 o Não cabe o habeas corpus contra a prisão administrativa, atual ou iminente, dos responsáveis por dinheiro ou valor pertencente à Fazenda Pública, alcançados ou omissos em fazer o seu recolhimento nos prazos legais, salvo se o pedido for acompanhado de prova de quitação ou de depósito do alcance verificado, ou se a prisão exceder o prazo legal."},{"chave":"art-651","sequencia":684,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 651.","conteudo":"A concessão do habeas corpus não obstará, nem porá termo ao processo, desde que este não esteja em conflito com os fundamentos daquela."},{"chave":"art-652","sequencia":685,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 652.","conteudo":"Se o habeas corpus for concedido em virtude de nulidade do processo, este será renovado."},{"chave":"art-653","sequencia":686,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 653.","conteudo":"Ordenada a soltura do paciente em virtude de habeas corpus , será condenada nas custas a autoridade que, por má-fé ou evidente abuso de poder, tiver determinado a coação.\n\nParágrafo único. Neste caso, será remetida ao Ministério Público cópia das peças necessárias para ser promovida a responsabilidade da autoridade."},{"chave":"art-654","sequencia":687,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 654.","conteudo":"O habeas corpus poderá ser impetrado por qualquer pessoa, em seu favor ou de outrem, bem como pelo Ministério Público.\n\n§ 1 o A petição de habeas corpus conterá:\n\na) o nome da pessoa que sofre ou está ameaçada de sofrer violência ou coação e o de quem exercer a violência, coação ou ameaça;\n\nb) a declaração da espécie de constrangimento ou, em caso de simples ameaça de coação, as razões em que funda o seu temor;\n\nc) a assinatura do impetrante, ou de alguém a seu rogo, quando não souber ou não puder escrever, e a designação das respectivas residências.\n\n§ 2 o Os juízes e os tribunais têm competência para expedir de ofício ordem de habeas corpus , quando no curso de processo verificarem que alguém sofre ou está na iminência de sofrer coação ilegal."},{"chave":"art-655","sequencia":688,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 655.","conteudo":"O carcereiro ou o diretor da prisão, o escrivão, o oficial de justiça ou a autoridade judiciária ou policial que embaraçar ou procrastinar a expedição de ordem de habeas corpus , as informações sobre a causa da prisão, a condução e apresentação do paciente, ou a sua soltura, será multado na quantia de duzentos mil-réis a um conto de réis, sem prejuízo das penas em que incorrer. As multas serão impostas pelo juiz do tribunal que julgar o habeas corpus , salvo quando se tratar de autoridade judiciária, caso em que caberá ao Supremo Tribunal Federal ou ao Tribunal de Apelação impor as multas."},{"chave":"art-656","sequencia":689,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 656.","conteudo":"Recebida a petição de habeas corpus , o juiz, se julgar necessário, e estiver preso o paciente, mandará que este Ihe seja imediatamente apresentado em dia e hora que designar.\n\nParágrafo único. Em caso de desobediência, será expedido mandado de prisão contra o detentor, que será processado na forma da lei, e o juiz providenciará para que o paciente seja tirado da prisão e apresentado em juízo."},{"chave":"art-657","sequencia":690,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 657.","conteudo":"Se o paciente estiver preso, nenhum motivo escusará a sua apresentação, salvo:\n\nI - grave enfermidade do paciente;\n\nIl - não estar ele sob a guarda da pessoa a quem se atribui a detenção;\n\nIII - se o comparecimento não tiver sido determinado pelo juiz ou pelo tribunal.\n\nParágrafo único. O juiz poderá ir ao local em que o paciente se encontrar, se este não puder ser apresentado por motivo de doença."},{"chave":"art-658","sequencia":691,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 658.","conteudo":"O detentor declarará à ordem de quem o paciente estiver preso."},{"chave":"art-659","sequencia":692,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 659.","conteudo":"Se o juiz ou o tribunal verificar que já cessou a violência ou coação ilegal, julgará prejudicado o pedido."},{"chave":"art-660","sequencia":693,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 660.","conteudo":"Efetuadas as diligências, e interrogado o paciente, o juiz decidirá, fundamentadamente, dentro de 24 (vinte e quatro) horas.\n\n§ 1 o Se a decisão for favorável ao paciente, será logo posto em liberdade, salvo se por outro motivo dever ser mantido na prisão.\n\n§ 2 o Se os documentos que instruírem a petição evidenciarem a ilegalidade da coação, o juiz ou o tribunal ordenará que cesse imediatamente o constrangimento.\n\n§ 3 o Se a ilegalidade decorrer do fato de não ter sido o paciente admitido a prestar fiança, o juiz arbitrará o valor desta, que poderá ser prestada perante ele, remetendo, neste caso, à autoridade os respectivos autos, para serem anexados aos do inquérito policial ou aos do processo judicial.\n\n§ 4 o Se a ordem de habeas corpus for concedida para evitar ameaça de violência ou coação ilegal, dar-se-á ao paciente salvo-conduto assinado pelo juiz.\n\n§ 5 o Será incontinenti enviada cópia da decisão à autoridade que tiver ordenado a prisão ou tiver o paciente à sua disposição, a fim de juntar-se aos autos do processo.\n\n§ 6 o Quando o paciente estiver preso em lugar que não seja o da sede do juízo ou do tribunal que conceder a ordem, o alvará de soltura será expedido pelo telégrafo, se houver, observadas as formalidades estabelecidas no art. 289, parágrafo único , in fine , ou por via postal."},{"chave":"art-661","sequencia":694,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 661.","conteudo":"Em caso de competência originária do Tribunal de Apelação, a petição de habeas corpus será apresentada ao secretário, que a enviará imediatamente ao presidente do tribunal, ou da câmara criminal, ou da turma, que estiver reunida, ou primeiro tiver de reunir-se."},{"chave":"art-662","sequencia":695,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 662.","conteudo":"Se a petição contiver os requisitos do art. 654, § 1 o , o presidente, se necessário, requisitará da autoridade indicada como coatora informações por escrito. Faltando, porém, qualquer daqueles requisitos, o presidente mandará preenchê-lo, logo que Ihe for apresentada a petição."},{"chave":"art-663","sequencia":696,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 663.","conteudo":"As diligências do artigo anterior não serão ordenadas, se o presidente entender que o habeas corpus deva ser indeferido in limine . Nesse caso, levará a petição ao tribunal, câmara ou turma, para que delibere a respeito."},{"chave":"art-664","sequencia":697,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 664.","conteudo":"Recebidas as informações, ou dispensadas, o habeas corpus será julgado na primeira sessão, podendo, entretanto, adiar-se o julgamento para a sessão seguinte.\n\nParágrafo único. A decisão será tomada por maioria de votos. Havendo empate, se o presidente não tiver tomado parte na votação, proferirá voto de desempate; no caso contrário, prevalecerá a decisão mais favorável ao paciente."},{"chave":"art-665","sequencia":698,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 665.","conteudo":"O secretário do tribunal lavrará a ordem que, assinada pelo presidente do tribunal, câmara ou turma, será dirigida, por ofício ou telegrama, ao detentor, ao carcereiro ou autoridade que exercer ou ameaçar exercer o constrangimento.\n\nParágrafo único. A ordem transmitida por telegrama obedecerá ao disposto no art. 289, parágrafo único, in fine ."},{"chave":"art-666","sequencia":699,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 666.","conteudo":"Os regimentos dos Tribunais de Apelação estabelecerão as normas complementares para o processo e julgamento do pedido de habeas corpus de sua competência originária."},{"chave":"art-667","sequencia":700,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO III — DAS NULIDADES E DOS RECURSOS EM GERAL","TÍTULO II — DOS RECURSOS EM GERAL","CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO"],"titulo":"CAPÍTULO X — DO HABEAS CORPUS E SEU PROCESSO","rotulo":"Art. 667.","conteudo":"No processo e julgamento do habeas corpus de competência originária do Supremo Tribunal Federal, bem como nos de recurso das decisões de última ou única instância, denegatórias de habeas corpus , observar-se-á, no que Ihes for aplicável, o disposto nos artigos anteriores, devendo o regimento interno do tribunal estabelecer as regras complementares."},{"chave":"art-668","sequencia":701,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"TÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 668.","conteudo":"A execução, onde não houver juiz especial, incumbirá ao juiz da sentença, ou, se a decisão for do Tribunal do Júri, ao seu presidente.\n\nParágrafo único. Se a decisão for de tribunal superior, nos casos de sua competência originária, caberá ao respectivo presidente prover-lhe a execução."},{"chave":"art-669","sequencia":702,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"TÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 669.","conteudo":"Só depois de passar em julgado, será exeqüível a sentença, salvo:\n\nI - quando condenatória, para o efeito de sujeitar o réu a prisão, ainda no caso de crime afiançável, enquanto não for prestada a fiança;\n\nII - quando absolutória, para o fim de imediata soltura do réu, desde que não proferida em processo por crime a que a lei comine pena de reclusão, no máximo, por tempo igual ou superior a oito anos."},{"chave":"art-670","sequencia":703,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"TÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 670.","conteudo":"No caso de decisão absolutória confirmada ou proferida em grau de apelação, incumbirá ao relator fazer expedir o alvará de soltura, de que dará imediatamente conhecimento ao juiz de primeira instância."},{"chave":"art-671","sequencia":704,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"TÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 671.","conteudo":"Os incidentes da execução serão resolvidos pelo respectivo juiz."},{"chave":"art-672","sequencia":705,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"TÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 672.","conteudo":"Computar-se-á na pena privativa da liberdade o tempo:\n\nI - de prisão preventiva no Brasil ou no estrangeiro;\n\nII - de prisão provisória no Brasil ou no estrangeiro;\n\nIII - de internação em hospital ou manicômio."},{"chave":"art-673","sequencia":706,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"TÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 673.","conteudo":"Verificado que o réu, pendente a apelação por ele interposta, já sofreu prisão por tempo igual ao da pena a que foi condenado, o relator do feito mandará pô-lo imediatamente em liberdade, sem prejuízo do julgamento do recurso, salvo se, no caso de crime a que a lei comine pena de reclusão, no máximo, por tempo igual ou superior a 8 anos, o querelante ou o Ministério Público também houver apelado da sentença condenatória."},{"chave":"art-674","sequencia":707,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE"],"titulo":"CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE","rotulo":"Art. 674.","conteudo":"Transitando em julgado a sentença que impuser pena privativa de liberdade, se o réu já estiver preso, ou vier a ser preso, o juiz ordenará a expedição de carta de guia para o cumprimento da pena.\n\nParágrafo único. Na hipótese do art. 82 , última parte, a expedição da carta de guia será ordenada pelo juiz competente para a soma ou unificação das penas."},{"chave":"art-675","sequencia":708,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE"],"titulo":"CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE","rotulo":"Art. 675.","conteudo":"No caso de ainda não ter sido expedido mandado de prisão, por tratar-se de infração penal em que o réu se livra solto ou por estar afiançado, o juiz, ou o presidente da câmara ou tribunal, se tiver havido recurso, fará expedir o mandado de prisão, logo que transite em julgado a sentença condenatória.\n\n§ 1 o No caso de reformada pela superior instância, em grau de recurso, a sentença absolutória, estando o réu solto, o presidente da câmara ou do tribunal fará, logo após a sessão de julgamento, remeter ao chefe de Polícia o mandado de prisão do condenado.\n\n§ 2 o Se o réu estiver em prisão especial, deverá, ressalvado o disposto na legislação relativa aos militares, ser expedida ordem para sua imediata remoção para prisão comum, até que se verifique a expedição de carta de guia para o cumprimento da pena."},{"chave":"art-676","sequencia":709,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE"],"titulo":"CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE","rotulo":"Art. 676.","conteudo":"A carta de guia, extraída pelo escrivão e assinada pelo juiz, que a rubricará em todas as folhas, será remetida ao diretor do estabelecimento em que tenha de ser cumprida a sentença condenatória, e conterá:\n\nI - o nome do réu e a alcunha por que for conhecido;\n\nIl - a sua qualificação civil (naturalidade, filiação, idade, estado, profissão), instrução e, se constar, número do registro geral do Instituto de Identificação e Estatística ou de repartição congênere;\n\nIII - o teor integral da sentença condenatória e a data da terminação da pena.\n\nParágrafo único. Expedida carta de guia para cumprimento de uma pena, se o réu estiver cumprindo outra, só depois de terminada a execução desta será aquela executada. Retificar-se-á a carta de guia sempre que sobrevenha modificação quanto ao início da execução ou ao tempo de duração da pena."},{"chave":"art-677","sequencia":710,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE"],"titulo":"CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE","rotulo":"Art. 677.","conteudo":"Da carta de guia e seus aditamentos se remeterá cópia ao Conselho Penitenciário."},{"chave":"art-678","sequencia":711,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE"],"titulo":"CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE","rotulo":"Art. 678.","conteudo":"O diretor do estabelecimento, em que o réu tiver de cumprir a pena, passará recibo da carta de guia para juntar-se aos autos do processo."},{"chave":"art-679","sequencia":712,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE"],"titulo":"CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE","rotulo":"Art. 679.","conteudo":"As cartas de guia serão registradas em livro especial, segundo a ordem cronológica do recebimento, fazendo-se no curso da execução as anotações necessárias."},{"chave":"art-680","sequencia":713,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE"],"titulo":"CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE","rotulo":"Art. 680.","conteudo":"Computar-se-á no tempo da pena o período em que o condenado, por sentença irrecorrível, permanecer preso em estabelecimento diverso do destinado ao cumprimento dela."},{"chave":"art-681","sequencia":714,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE"],"titulo":"CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE","rotulo":"Art. 681.","conteudo":"Se impostas cumulativamente penas privativas da liberdade, será executada primeiro a de reclusão, depois a de detenção e por último a de prisão simples."},{"chave":"art-682","sequencia":715,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE"],"titulo":"CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE","rotulo":"Art. 682.","conteudo":"O sentenciado a que sobrevier doença mental, verificada por perícia médica, será internado em manicômio judiciário, ou, à falta, em outro estabelecimento adequado, onde Ihe seja assegurada a custódia.\n\n§ 1 o Em caso de urgência, o diretor do estabelecimento penal poderá determinar a remoção do sentenciado, comunicando imediatamente a providência ao juiz, que, em face da perícia médica, ratificará ou revogará a medida.\n\n§ 2 o Se a internação se prolongar até o término do prazo restante da pena e não houver sido imposta medida de segurança detentiva, o indivíduo terá o destino aconselhado pela sua enfermidade, feita a devida comunicação ao juiz de incapazes."},{"chave":"art-683","sequencia":716,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE"],"titulo":"CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE","rotulo":"Art. 683.","conteudo":"O diretor da prisão a que o réu tiver sido recolhido provisoriamente ou em cumprimento de pena comunicará imediatamente ao juiz o óbito, a fuga ou a soltura do detido ou sentenciado para que fique constando dos autos.\n\nParágrafo único. A certidão de óbito acompanhará a comunicação."},{"chave":"art-684","sequencia":717,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE"],"titulo":"CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE","rotulo":"Art. 684.","conteudo":"A recaptura do réu evadido não depende de prévia ordem judicial e poderá ser efetuada por qualquer pessoa."},{"chave":"art-685","sequencia":718,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE"],"titulo":"CAPÍTULO I — DAS PENAS PRIVATIVAS DE LIBERDADE","rotulo":"Art. 685.","conteudo":"Cumprida ou extinta a pena, o condenado será posto, imediatamente, em liberdade, mediante alvará do juiz, no qual se ressalvará a hipótese de dever o condenado continuar na prisão por outro motivo legal.\n\nParágrafo único. Se tiver sido imposta medida de segurança detentiva, o condenado será removido para estabelecimento adequado ( art. 762 )."},{"chave":"art-686","sequencia":719,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO II — DAS PENAS PECUNIÁRIAS"],"titulo":"CAPÍTULO II — DAS PENAS PECUNIÁRIAS","rotulo":"Art. 686.","conteudo":"A pena de multa será paga dentro em 10 dias após haver transitado em julgado a sentença que a impuser.\n\nParágrafo único. Se interposto recurso da sentença, esse prazo será contado do dia em que o juiz ordenar o cumprimento da decisão da superior instância."},{"chave":"art-687","sequencia":720,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO II — DAS PENAS PECUNIÁRIAS"],"titulo":"CAPÍTULO II — DAS PENAS PECUNIÁRIAS","rotulo":"Art. 687.","conteudo":"O juiz poderá, desde que o condenado o requeira:\n\nI - prorrogar o prazo do pagamento da multa até três meses, se as circunstâncias justificarem essa prorrogação;\n\nII - permitir, nas mesmas circunstâncias, que o pagamento se faça em parcelas mensais, no prazo que fixar, mediante caução real ou fidejussória, quando necessário. (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\n§ 1 o O requerimento, tanto no caso do n o I, como no do n o II, será feito dentro do decêndio concedido para o pagamento da multa.\n\n§ 2º A permissão para o pagamento em parcelas será revogada, se o juiz verificar que o condenado dela se vale para fraudar a execução da pena. Nesse caso, a caução resolver-se-á em valor monetário, devolvendo-se ao condenado o que exceder à satisfação da multa e das custas processuais. (Redação dada pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-688","sequencia":721,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO II — DAS PENAS PECUNIÁRIAS"],"titulo":"CAPÍTULO II — DAS PENAS PECUNIÁRIAS","rotulo":"Art. 688.","conteudo":"Findo o decêndio ou a prorrogação sem que o condenado efetue o pagamento, ou ocorrendo a hipótese prevista no § 2 o do artigo anterior, observar-se-á o seguinte:\n\nI - possuindo o condenado bens sobre os quais possa recair a execução, será extraída certidão da sentença condenatória, a fim de que o Ministério Público proceda à cobrança judicial;\n\nII - sendo o condenado insolvente, far-se-á a cobrança:\n\na) mediante desconto de quarta parte de sua remuneração ( arts. 29, § 1 o , e 37 do Código Penal ), quando cumprir pena privativa da liberdade, cumulativamente imposta com a de multa;\n\nb) mediante desconto em seu vencimento ou salário, se, cumprida a pena privativa da liberdade, ou concedido o livramento condicional, a multa não houver sido resgatada;\n\nc) mediante esse desconto, se a multa for a única pena imposta ou no caso de suspensão condicional da pena.\n\n§ 1 o O desconto, nos casos das letras b e c , será feito mediante ordem ao empregador, à repartição competente ou à administração da entidade paraestatal, e, antes de fixá-lo, o juiz requisitará informações e ordenará diligências, inclusive arbitramento, quando necessário, para observância do art. 37, § 3 o , do Código Penal .\n\n§ 2 o Sob pena de desobediência e sem prejuízo da execução a que ficará sujeito, o empregador será intimado a recolher mensalmente, até o dia fixado pelo juiz, a importância correspondente ao desconto, em selo penitenciário, que será inutilizado nos autos pelo juiz.\n\n§ 3 o Se o condenado for funcionário estadual ou municipal ou empregado de entidade paraestatal, a importância do desconto será, semestralmente, recolhida ao Tesouro Nacional, delegacia fiscal ou coletoria federal, como receita do selo penitenciário.\n\n§ 4 o As quantias descontadas em folha de pagamento de funcionário federal constituirão renda do selo penitenciário."},{"chave":"art-689","sequencia":722,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO II — DAS PENAS PECUNIÁRIAS"],"titulo":"CAPÍTULO II — DAS PENAS PECUNIÁRIAS","rotulo":"Art. 689.","conteudo":"A multa será convertida, à razão de dez mil-réis por dia, em detenção ou prisão simples, no caso de crime ou de contravenção:\n\nI - se o condenado solvente frustrar o pagamento da multa;\n\nII - se não forem pagas pelo condenado solvente as parcelas mensais autorizadas sem garantia. (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\n§ 1 o Se o juiz reconhecer desde logo a existência de causa para a conversão, a ela procederá de ofício ou a requerimento do Ministério Público, independentemente de audiência do condenado; caso contrário, depois de ouvir o condenado, se encontrado no lugar da sede do juízo, poderá admitir a apresentação de prova pelas partes, inclusive testemunhal, no prazo de três dias.\n\n§ 2 o O juiz, desde que transite em julgado a decisão, ordenará a expedição de mandado de prisão ou aditamento à carta de guia, conforme esteja o condenado solto ou em cumprimento de pena privativa da liberdade.\n\n§ 3 o Na hipótese do inciso II deste artigo, a conversão será feita pelo valor das parcelas não pagas. (Incluído pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-690","sequencia":723,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO II — DAS PENAS PECUNIÁRIAS"],"titulo":"CAPÍTULO II — DAS PENAS PECUNIÁRIAS","rotulo":"Art. 690.","conteudo":"O juiz tornará sem efeito a conversão, expedindo alvará de soltura ou cassando a ordem de prisão, se o condenado, em qualquer tempo:\n\nI - pagar a multa;\n\nII - prestar caução real ou fidejussória que Ihe assegure o pagamento.\n\nParágrafo único. No caso do n o II, antes de homologada a caução, será ouvido o Ministério Público dentro do prazo de dois dias."},{"chave":"art-691","sequencia":724,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO III — DAS PENAS ACESSÓRIAS"],"titulo":"CAPÍTULO III — DAS PENAS ACESSÓRIAS","rotulo":"Art. 691.","conteudo":"O juiz dará à autoridade administrativa competente conhecimento da sentença transitada em julgado, que impuser ou de que resultar a perda da função pública ou a incapacidade temporária para investidura em função pública ou para exercício de profissão ou atividade."},{"chave":"art-692","sequencia":725,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO III — DAS PENAS ACESSÓRIAS"],"titulo":"CAPÍTULO III — DAS PENAS ACESSÓRIAS","rotulo":"Art. 692.","conteudo":"No caso de incapacidade temporária ou permanente para o exercício do pátrio poder, da tutela ou da curatela, o juiz providenciará para que sejam acautelados, no juízo competente, a pessoa e os bens do menor ou do interdito."},{"chave":"art-693","sequencia":726,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO III — DAS PENAS ACESSÓRIAS"],"titulo":"CAPÍTULO III — DAS PENAS ACESSÓRIAS","rotulo":"Art. 693.","conteudo":"A incapacidade permanente ou temporária para o exercício da autoridade marital ou do pátrio poder será averbada no registro civil."},{"chave":"art-694","sequencia":727,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO III — DAS PENAS ACESSÓRIAS"],"titulo":"CAPÍTULO III — DAS PENAS ACESSÓRIAS","rotulo":"Art. 694.","conteudo":"As penas acessórias consistentes em interdições de direitos serão comunicadas ao Instituto de Identificação e Estatística ou estabelecimento congênere, figurarão na folha de antecedentes do condenado e serão mencionadas no rol de culpados."},{"chave":"art-695","sequencia":728,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO II — DA EXECUÇÃO DAS PENAS EM ESPÉCIE","CAPÍTULO III — DAS PENAS ACESSÓRIAS"],"titulo":"CAPÍTULO III — DAS PENAS ACESSÓRIAS","rotulo":"Art. 695.","conteudo":"Iniciada a execução das interdições temporárias ( art. 72, a e b , do Código Penal ), o juiz, de ofício, a requerimento do Ministério Público ou do condenado, fixará o seu termo final, completando as providências determinadas nos artigos anteriores."},{"chave":"art-696","sequencia":729,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 696.","conteudo":"O juiz poderá suspender, por tempo não inferior a 2 (dois) nem superior a 6 (seis) anos, a execução das penas de reclusão e de detenção que não excedam a 2 (dois) anos, ou, por tempo não inferior a 1 (um) nem superior a 3 (três) anos, a execução da pena de prisão simples, desde que o sentenciado: (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\nI - não haja sofrido, no País ou no estrangeiro, condenação irrecorrível por outro crime a pena privativa da liberdade, salvo o disposto no parágrafo único do art. 46 do Código Penal ; (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\nII - os antecedentes e a personalidade do sentenciado, os motivos e as circunstâncias do crime autorizem a presunção de que não tornará a delinqüir.\n\nParágrafo único. Processado o beneficiário por outro crime ou contravenção, considerar-se-á prorrogado o prazo da suspensão da pena até o julgamento definitivo."},{"chave":"art-697","sequencia":730,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 697.","conteudo":"O juiz ou tribunal, na decisão que aplicar pena privativa da liberdade não superior a 2 (dois) anos, deverá pronunciar-se, motivadamente, sobre a suspensão condicional, quer a conceda quer a denegue. (Redação dada pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-698","sequencia":731,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 698.","conteudo":"Concedida a suspensão, o juiz especificará as condições a que fica sujeito o condenado, pelo prazo previsto, começando este a correr da audiência em que se der conhecimento da sentença ao beneficiário e Ihe for entregue documento similar ao descrito no art. 724. (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\n§ 1 o As condições serão adequadas ao delito e à personalidade do condenado. (Incluído pela Lei nº 6.416, de 24.5.1977)\n\n§ 2 o Poderão ser impostas, além das estabelecidas no art. 767 , como normas de conduta e obrigações, as seguintes condições: (Incluído pela Lei nº 6.416, de 24.5.1977)\n\nI - freqüentar curso de habilitação profissional ou de instrução escolar; (Incluído pela Lei nº 6.416, de 24.5.1977)\n\nII - prestar serviços em favor da comunidade; (Incluído pela Lei nº 6.416, de 24.5.1977)\n\nIII - atender aos encargos de família; (Incluído pela Lei nº 6.416, de 24.5.1977)\n\nIV - submeter-se a tratamento de desintoxicação. (Incluído pela Lei nº 6.416, de 24.5.1977)\n\n§ 3 o O juiz poderá fixar, a qualquer tempo, de ofício ou a requerimento do Ministério Público, outras condições além das especificadas na sentença e das referidas no parágrafo anterior, desde que as circunstâncias o aconselhem. (Incluído pela Lei nº 6.416, de 24.5.1977)\n\n§ 4 o A fiscalização do cumprimento das condições deverá ser regulada, nos Estados, Territórios e Distrito Federal, por normas supletivas e atribuída a serviço social penitenciário, patronato, conselho de comunidade ou entidades similares, inspecionadas pelo Conselho Penitenciário, pelo Ministério Público ou ambos, devendo o juiz da execução na comarca suprir, por ato, a falta das normas supletivas. (Incluído pela Lei nº 6.416, de 24.5.1977)\n\n§ 5 o O beneficiário deverá comparecer periodicamente à entidade fiscalizadora, para comprovar a observância das condições a que está sujeito, comunicando, também, a sua ocupação, os salários ou proventos de que vive, as economias que conseguiu realizar e as dificuldades materiais ou sociais que enfrenta. (Incluído pela Lei nº 6.416, de 24.5.1977)\n\n§ 6 o A entidade fiscalizadora deverá comunicar imediatamente ao órgão de inspeção, para os fins legais ( arts. 730 e 731 ), qualquer fato capaz de acarretar a revogação do benefício, a prorrogação do prazo ou a modificação das condições. (Incluído pela Lei nº 6.416, de 24.5.1977)\n\n§ 7 o Se for permitido ao beneficiário mudar-se, será feita comunicação ao juiz e à entidade fiscalizadora do local da nova residência, aos quais deverá apresentar-se imediatamente. (Incluído pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-699","sequencia":732,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 699.","conteudo":"No caso de condenação pelo Tribunal do Júri, a suspensão condicional da pena competirá ao seu presidente."},{"chave":"art-700","sequencia":733,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 700.","conteudo":"A suspensão não compreende a multa, as penas acessórias, os efeitos da condenação nem as custas."},{"chave":"art-701","sequencia":734,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 701.","conteudo":"O juiz, ao conceder a suspensão, fixará, tendo em conta as condições econômicas ou profissionais do réu, o prazo para o pagamento, integral ou em prestações, das custas do processo e taxa penitenciária."},{"chave":"art-702","sequencia":735,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 702.","conteudo":"Em caso de co-autoria, a suspensão poderá ser concedida a uns e negada a outros réus."},{"chave":"art-703","sequencia":736,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 703.","conteudo":"O juiz que conceder a suspensão lerá ao réu, em audiência, a sentença respectiva, e o advertirá das conseqüências de nova infração penal e da transgressão das obrigações impostas."},{"chave":"art-704","sequencia":737,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 704.","conteudo":"Quando for concedida a suspensão pela superior instância, a esta caberá estabelecer-lhe as condições, podendo a audiência ser presidida por qualquer membro do tribunal ou câmara, pelo juiz do processo ou por outro designado pelo presidente do tribunal ou câmara."},{"chave":"art-705","sequencia":738,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 705.","conteudo":"Se, intimado pessoalmente ou por edital com prazo de 20 dias, o réu não comparecer à audiência a que se refere o art. 703 , a suspensão ficará sem efeito e será executada imediatamente a pena, salvo prova de justo impedimento, caso em que será marcada nova audiência."},{"chave":"art-706","sequencia":739,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 706.","conteudo":"A suspensão também ficará sem efeito se, em virtude de recurso, for aumentada a pena de modo que exclua a concessão do benefício. (Redação dada pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-707","sequencia":740,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 707.","conteudo":"A suspensão será revogada se o beneficiário: (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\nI - é condenado, por sentença irrecorrível, a pena privativa da liberdade; (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\nII - frustra, embora solvente, o pagamento da multa, ou não efetua, sem motivo justificado, a reparação do dano. (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\nParágrafo único. O juiz poderá revogar a suspensão, se o beneficiário deixa de cumprir qualquer das obrigações constantes da sentença, de observar proibições inerentes à pena acessória, ou é irrecorrivelmente condenado a pena que não seja privativa da liberdade; se não a revogar, deverá advertir o beneficiário, ou exacerbar as condições ou, ainda, prorrogar o período da suspensão até o máximo, se esse limite não foi o fixado. (Redação dada pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-708","sequencia":741,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 708.","conteudo":"Expirado o prazo de suspensão ou a prorrogação, sem que tenha ocorrido motivo de revogação, a pena privativa de liberdade será declarada extinta.\n\nParágrafo único. O juiz, quando julgar necessário, requisitará, antes do julgamento, nova folha de antecedentes do beneficiário."},{"chave":"art-709","sequencia":742,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA"],"titulo":"CAPÍTULO I — DA SUSPENSÃO CONDICIONAL DA PENA","rotulo":"Art. 709.","conteudo":"A condenação será inscrita, com a nota de suspensão, em livros especiais do Instituto de Identificação e Estatística, ou repartição congênere, averbando-se, mediante comunicação do juiz ou do tribunal, a revogação da suspensão ou a extinção da pena. Em caso de revogação, será feita a averbação definitiva no registro geral.\n\n§ 1 o Nos lugares onde não houver Instituto de Identificação e Estatística ou repartição congênere, o registro e a averbação serão feitos em livro próprio no juízo ou no tribunal.\n\n§ 2 o O registro será secreto, salvo para efeito de informações requisitadas por autoridade judiciária, no caso de novo processo.\n\n§ 3 o Não se aplicará o disposto no § 2 o , quando houver sido imposta ou resultar de condenação pena acessória consistente em interdição de direitos."},{"chave":"art-710","sequencia":743,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 710.","conteudo":"O livramento condicional poderá ser concedido ao condenado a pena privativa da liberdade igual ou superior a 2 (dois) anos, desde que se verifiquem as condições seguintes: (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\nI - cumprimento de mais da metade da pena, ou mais de três quartos, se reincidente o sentenciado; (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\nII - ausência ou cessação de periculosidade;\n\nIII - bom comportamento durante a vida carcerária;\n\nIV - aptidão para prover à própria subsistência mediante trabalho honesto;\n\nV - reparação do dano causado pela infração, salvo impossibilidade de fazê-lo. (Redação dada pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-711","sequencia":744,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 711.","conteudo":"As penas que correspondem a infrações diversas podem somar-se, para efeito do livramento. (Redação dada pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-712","sequencia":745,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 712.","conteudo":"O livramento condicional poderá ser concedido mediante requerimento do sentenciado, de seu cônjuge ou de parente em linha reta, ou por proposta do diretor do estabelecimento penal, ou por iniciativa do Conselho Penitenciário. (Redação dada pelo Decreto-lei nº 6.109, de 16.12.1943)"},{"chave":"art-713","sequencia":746,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 713.","conteudo":"As condições de admissibilidade, conveniência e oportunidade da concessão do livramento serão verificadas pelo Conselho Penitenciário, a cujo parecer não ficará, entretanto, adstrito o juiz."},{"chave":"art-714","sequencia":747,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 714.","conteudo":"O diretor do estabelecimento penal remeterá ao Conselho Penitenciário minucioso relatório sobre:\n\nI - o caráter do sentenciado, revelado pelos seus antecedentes e conduta na prisão;\n\nII - o procedimento do liberando na prisão, sua aplicação ao trabalho e seu trato com os companheiros e funcionários do estabelecimento;\n\nIII - suas relações, quer com a família, quer com estranhos;\n\nIV - seu grau de instrução e aptidão profissional, com a indicação dos serviços em que haja sido empregado e da especialização anterior ou adquirida na prisão;\n\nV - sua situação financeira, e seus propósitos quanto ao seu futuro meio de vida, juntando o diretor, quando dada por pessoa idônea, promessa escrita de colocação do liberando, com indicação do serviço e do salário.\n\nParágrafo único. O relatório será, dentro do prazo de quinze dias, remetido ao Conselho, com o prontuário do sentenciado, e, na falta, o Conselho opinará livremente, comunicando à autoridade competente a omissão do diretor da prisão."},{"chave":"art-715","sequencia":748,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 715.","conteudo":"Se tiver sido imposta medida de segurança detentiva, o livramento não poderá ser concedido sem que se verifique, mediante exame das condições do sentenciado, a cessação da periculosidade.\n\nParágrafo único. Consistindo a medida de segurança em internação em casa de custódia e tratamento, proceder-se-á a exame mental do sentenciado."},{"chave":"art-716","sequencia":749,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 716.","conteudo":"A petição ou a proposta de livramento será remetida ao juiz ou ao tribunal por ofício do presidente do Conselho Penitenciário, com a cópia do respectivo parecer e do relatório do diretor da prisão.\n\n§ 1 o Para emitir parecer, o Conselho poderá determinar diligências e requisitar os autos do processo.\n\n§ 2 o O juiz ou o tribunal mandará juntar a petição ou a proposta, com o ofício ou documento que a acompanhar, aos autos do processo, e proferirá sua decisão, previamente ouvido o Ministério Público."},{"chave":"art-717","sequencia":750,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 717.","conteudo":"Na ausência da condição prevista no art. 710, I , o requerimento será liminarmente indeferido. (Redação dada pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-718","sequencia":751,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 718.","conteudo":"Deferido o pedido, o juiz, ao especificar as condições a que ficará subordinado o livramento, atenderá ao disposto no art. 698, §§ 1 o , 2 o e 5 o . (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\n§ 1 o Se for permitido ao liberado residir fora da jurisdição do juiz da execução, remeter-se-á cópia da sentença do livramento à autoridade judiciária do lugar para onde ele se houver transferido, e à entidade de observação cautelar e proteção. (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\n§ 2 o O liberado será advertido da obrigação de apresentar-se imediatamente à autoridade judiciária e à entidade de observação cautelar e proteção. Redação dada pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-719","sequencia":752,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 719.","conteudo":"O livramento ficará também subordinado à obrigação de pagamento das custas do processo e da taxa penitenciária, salvo caso de insolvência comprovada.\n\nParágrafo único. O juiz poderá fixar o prazo para o pagamento integral ou em prestações, tendo em consideração as condições econômicas ou profissionais do liberado."},{"chave":"art-720","sequencia":753,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 720.","conteudo":"A forma de pagamento da multa, ainda não paga pelo liberando, será determinada de acordo com o disposto no art. 688 ."},{"chave":"art-721","sequencia":754,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 721.","conteudo":"Reformada a sentença denegatória do livramento, os autos baixarão ao juiz da primeira instância, a fim de que determine as condições que devam ser impostas ao liberando."},{"chave":"art-722","sequencia":755,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 722.","conteudo":"Concedido o livramento, será expedida carta de guia, com a cópia integral da sentença em duas vias, remetendo-se uma ao diretor do estabelecimento penal e outra ao presidente do Conselho Penitenciário."},{"chave":"art-723","sequencia":756,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 723.","conteudo":"A cerimônia do livramento condicional será realizada solenemente, em dia marcado pela autoridade que deva presidi-la, observando-se o seguinte:\n\nI - a sentença será lida ao liberando, na presença dos demais presos, salvo motivo relevante, pelo presidente do Conselho Penitenciário, ou pelo seu representante junto ao estabelecimento penal, ou, na falta, pela autoridade judiciária local;\n\nII - o diretor do estabelecimento penal chamará a atenção do liberando para as condições impostas na sentença de livramento;\n\nIII - o preso declarará se aceita as condições.\n\n§ 1 o De tudo, em livro próprio, se lavrará termo, subscrito por quem presidir a cerimônia, e pelo liberando, ou alguém a seu rogo, se não souber ou não puder escrever.\n\n§ 2 o Desse termo, se remeterá cópia ao juiz do processo."},{"chave":"art-724","sequencia":757,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 724.","conteudo":"Ao sair da prisão o liberado, ser-lhe-á entregue, além do saldo do seu pecúlio e do que Ihe pertencer, uma caderneta que exibirá à autoridade judiciária ou administrativa sempre que Ihe for exigido. Essa caderneta conterá:\n\nI - a reprodução da ficha de identidade, ou o retrato do liberado, sua qualificação e sinais característicos;\n\nII - o texto impresso dos artigos do presente capítulo;\n\nIII - as condições impostas ao liberado;\n\nIV - a pena acessória a que esteja sujeito. (Incluído pela Lei nº 6.416, de 24.5.1977)\n\n§ 1 o Na falta de caderneta, será entregue ao liberado um salvo-conduto, em que constem as condições do livramento e a pena acessória, podendo substituir-se a ficha de identidade ou o retrato do liberado pela descrição dos sinais que possam identificá-lo. (Incluído pela Lei nº 6.416, de 24.5.1977)\n\n§ 2 o Na caderneta e no salvo-conduto deve haver espaço para consignar o cumprimento das condições referidas no art. 718 . (Incluído pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-725","sequencia":758,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 725.","conteudo":"A observação cautelar e proteção realizadas por serviço social penitenciário, patronato, conselho de comunidade ou entidades similares, terá a finalidade de: (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\nI - fazer observar o cumprimento da pena acessória, bem como das condições especificadas na sentença concessiva do benefício; (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\nII - proteger o beneficiário, orientando-o na execução de suas obrigações e auxiliando-o na obtenção de atividade laborativa. (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\nParágrafo único. As entidades encarregadas de observação cautelar e proteção do liberado apresentarão relatório ao Conselho Penitenciário, para efeito da representação prevista nos arts. 730 e 731 . (Redação dada pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-726","sequencia":759,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 726.","conteudo":"Revogar-se-á o livramento condicional, se o liberado vier, por crime ou contravenção, a ser condenado por sentença irrecorrível a pena privativa de liberdade."},{"chave":"art-727","sequencia":760,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 727.","conteudo":"O juiz pode, também, revogar o livramento, se o liberado deixar de cumprir qualquer das obrigações constantes da sentença, de observar proibições inerentes à pena acessória ou for irrecorrivelmente condenado, por crime, à pena que não seja privativa da liberdade. (Redação dada pela Lei nº 6.416, de 24.5.1977)\n\nParágrafo único. Se o juiz não revogar o livramento, deverá advertir o liberado ou exacerbar as condições. (Incluído pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-728","sequencia":761,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 728.","conteudo":"Se a revogação for motivada por infração penal anterior à vigência do livramento, computar-se-á no tempo da pena o período em que esteve solto o liberado, sendo permitida, para a concessão de novo livramento, a soma do tempo das duas penas."},{"chave":"art-729","sequencia":762,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 729.","conteudo":"No caso de revogação por outro motivo, não se computará na pena o tempo em que esteve solto o liberado, e tampouco se concederá, em relação à mesma pena, novo livramento."},{"chave":"art-730","sequencia":763,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 730.","conteudo":"A revogação do livramento será decretada mediante representação do Conselho Penitenciário, ou a requerimento do Ministério Público, ou de ofício, pelo juiz, que, antes, ouvirá o liberado, podendo ordenar diligências e permitir a produção de prova, no prazo de cinco dias. (Redação dada pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-731","sequencia":764,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 731.","conteudo":"O juiz, de ofício, a requerimento do Ministério Público, ou mediante representação do Conselho Penitenciário, poderá modificar as condições ou normas de conduta especificadas na sentença, devendo a respectiva decisão ser lida ao liberado por uma das autoridades ou por um dos funcionários indicados no inciso I do art. 723 , observado o disposto nos incisos II e III, e §§ 1o e 2o do mesmo artigo . (Redação dada pela Lei nº 6.416, de 24.5.1977)"},{"chave":"art-732","sequencia":765,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 732.","conteudo":"Praticada pelo liberado nova infração, o juiz ou o tribunal poderá ordenar a sua prisão, ouvido o Conselho Penitenciário, suspendendo o curso do livramento condicional, cuja revogação ficará, entretanto, dependendo da decisão final no novo processo."},{"chave":"art-733","sequencia":766,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO III — DOS INCIDENTES DA EXECUÇÃO","CAPÍTULO II — DO LIVRAMENTO CONDICIONAL"],"titulo":"CAPÍTULO II — DO LIVRAMENTO CONDICIONAL","rotulo":"Art. 733.","conteudo":"O juiz, de ofício, ou a requerimento do interessado, do Ministério Público, ou do Conselho Penitenciário, julgará extinta a pena privativa de liberdade, se expirar o prazo do livramento sem revogação, ou na hipótese do artigo anterior, for o liberado absolvido por sentença irrecorrível."},{"chave":"art-734","sequencia":767,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA"],"titulo":"CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA","rotulo":"Art. 734.","conteudo":"A graça poderá ser provocada por petição do condenado, de qualquer pessoa do povo, do Conselho Penitenciário, ou do Ministério Público, ressalvada, entretanto, ao Presidente da República, a faculdade de concedê-la espontaneamente."},{"chave":"art-735","sequencia":768,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA"],"titulo":"CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA","rotulo":"Art. 735.","conteudo":"A petição de graça, acompanhada dos documentos com que o impetrante a instruir, será remetida ao ministro da Justiça por intermédio do Conselho Penitenciário."},{"chave":"art-736","sequencia":769,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA"],"titulo":"CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA","rotulo":"Art. 736.","conteudo":"O Conselho Penitenciário, à vista dos autos do processo, e depois de ouvir o diretor do estabelecimento penal a que estiver recolhido o condenado, fará, em relatório, a narração do fato criminoso, examinará as provas, mencionará qualquer formalidade ou circunstância omitida na petição e exporá os antecedentes do condenado e seu procedimento depois de preso, opinando sobre o mérito do pedido. (Vide Lei nº 7.417, de 1985)"},{"chave":"art-737","sequencia":770,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA"],"titulo":"CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA","rotulo":"Art. 737.","conteudo":"Processada no Ministério da Justiça, com os documentos e o relatório do Conselho Penitenciário, a petição subirá a despacho do Presidente da República, a quem serão presentes os autos do processo ou a certidão de qualquer de suas peças, se ele o determinar."},{"chave":"art-738","sequencia":771,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA"],"titulo":"CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA","rotulo":"Art. 738.","conteudo":"Concedida a graça e junta aos autos cópia do decreto, o juiz declarará extinta a pena ou penas, ou ajustará a execução aos termos do decreto, no caso de redução ou comutação de pena."},{"chave":"art-739","sequencia":772,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA"],"titulo":"CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA","rotulo":"Art. 739.","conteudo":"O condenado poderá recusar a comutação da pena."},{"chave":"art-740","sequencia":773,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA"],"titulo":"CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA","rotulo":"Art. 740.","conteudo":"Os autos da petição de graça serão arquivados no Ministério da Justiça."},{"chave":"art-741","sequencia":774,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA"],"titulo":"CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA","rotulo":"Art. 741.","conteudo":"Se o réu for beneficiado por indulto, o juiz, de ofício ou a requerimento do interessado, do Ministério Público ou por iniciativa do Conselho Penitenciário, providenciará de acordo com o disposto no art. 738 ."},{"chave":"art-742","sequencia":775,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA"],"titulo":"CAPÍTULO I — DA GRAÇA, DO INDULTO E DA ANISTIA","rotulo":"Art. 742.","conteudo":"Concedida a anistia após transitar em julgado a sentença condenatória, o juiz, de ofício ou a requerimento do interessado, do Ministério Público ou por iniciativa do Conselho Penitenciário, declarará extinta a pena."},{"chave":"art-743","sequencia":776,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO II — DA REABILITAÇÃO"],"titulo":"CAPÍTULO II — DA REABILITAÇÃO","rotulo":"Art. 743.","conteudo":"A reabilitação será requerida ao juiz da condenação, após o decurso de quatro ou oito anos, pelo menos, conforme se trate de condenado ou reincidente, contados do dia em que houver terminado a execução da pena principal ou da medida de segurança detentiva, devendo o requerente indicar as comarcas em que haja residido durante aquele tempo."},{"chave":"art-744","sequencia":777,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO II — DA REABILITAÇÃO"],"titulo":"CAPÍTULO II — DA REABILITAÇÃO","rotulo":"Art. 744.","conteudo":"O requerimento será instruído com:\n\nI - certidões comprobatórias de não ter o requerente respondido, nem estar respondendo a processo penal, em qualquer das comarcas em que houver residido durante o prazo a que se refere o artigo anterior;\n\nII - atestados de autoridades policiais ou outros documentos que comprovem ter residido nas comarcas indicadas e mantido, efetivamente, bom comportamento;\n\nIII - atestados de bom comportamento fornecidos por pessoas a cujo serviço tenha estado;\n\nIV - quaisquer outros documentos que sirvam como prova de sua regeneração;\n\nV - prova de haver ressarcido o dano causado pelo crime ou persistir a impossibilidade de fazê-lo."},{"chave":"art-745","sequencia":778,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO II — DA REABILITAÇÃO"],"titulo":"CAPÍTULO II — DA REABILITAÇÃO","rotulo":"Art. 745.","conteudo":"O juiz poderá ordenar as diligências necessárias para apreciação do pedido, cercando-as do sigilo possível e, antes da decisão final, ouvirá o Ministério Público."},{"chave":"art-746","sequencia":779,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO II — DA REABILITAÇÃO"],"titulo":"CAPÍTULO II — DA REABILITAÇÃO","rotulo":"Art. 746.","conteudo":"Da decisão que conceder a reabilitação haverá recurso de ofício."},{"chave":"art-747","sequencia":780,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO II — DA REABILITAÇÃO"],"titulo":"CAPÍTULO II — DA REABILITAÇÃO","rotulo":"Art. 747.","conteudo":"A reabilitação, depois de sentença irrecorrível, será comunicada ao Instituto de Identificação e Estatística ou repartição congênere."},{"chave":"art-748","sequencia":781,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO II — DA REABILITAÇÃO"],"titulo":"CAPÍTULO II — DA REABILITAÇÃO","rotulo":"Art. 748.","conteudo":"A condenação ou condenações anteriores não serão mencionadas na folha de antecedentes do reabilitado, nem em certidão extraída dos livros do juízo, salvo quando requisitadas por juiz criminal."},{"chave":"art-749","sequencia":782,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO II — DA REABILITAÇÃO"],"titulo":"CAPÍTULO II — DA REABILITAÇÃO","rotulo":"Art. 749.","conteudo":"Indeferida a reabilitação, o condenado não poderá renovar o pedido senão após o decurso de dois anos, salvo se o indeferimento tiver resultado de falta ou insuficiência de documentos."},{"chave":"art-750","sequencia":783,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO IV — DA GRAÇA, DO INDULTO, DA ANISTIA E DA REHABILITAÇÃO","CAPÍTULO II — DA REABILITAÇÃO"],"titulo":"CAPÍTULO II — DA REABILITAÇÃO","rotulo":"Art. 750.","conteudo":"A revogação de reabilitação ( Código Penal, art. 120 ) será decretada pelo juiz, de ofício ou a requerimento do Ministério Público."},{"chave":"art-751","sequencia":784,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 751.","conteudo":"Durante a execução da pena ou durante o tempo em que a ela se furtar o condenado, poderá ser imposta medida de segurança, se:\n\nI - o juiz ou o tribunal, na sentença:\n\na) omitir sua decretação, nos casos de periculosidade presumida;\n\nb) deixar de aplicá-la ou de excluí-la expressamente;\n\nc) declarar os elementos constantes do processo insuficientes para a imposição ou exclusão da medida e ordenar indagações para a verificação da periculosidade do condenado;\n\nII - tendo sido, expressamente, excluída na sentença a periculosidade do condenado, novos fatos demonstrarem ser ele perigoso."},{"chave":"art-752","sequencia":785,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 752.","conteudo":"Poderá ser imposta medida de segurança, depois de transitar em julgado a sentença, ainda quando não iniciada a execução da pena, por motivo diverso de fuga ou ocultação do condenado:\n\nI - no caso da letra a do n o I do artigo anterior, bem como no da letra b , se tiver sido alegada a periculosidade;\n\nII - no caso da letra c do n o I do mesmo artigo."},{"chave":"art-753","sequencia":786,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 753.","conteudo":"Ainda depois de transitar em julgado a sentença absolutória, poderá ser imposta a medida de segurança, enquanto não decorrido tempo equivalente ao da sua duração mínima, a indivíduo que a lei presuma perigoso."},{"chave":"art-754","sequencia":787,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 754.","conteudo":"A aplicação da medida de segurança, nos casos previstos nos arts. 751 e 752 , competirá ao juiz da execução da pena, e, no caso do art. 753 , ao juiz da sentença."},{"chave":"art-755","sequencia":788,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 755.","conteudo":"A imposição da medida de segurança, nos casos dos arts. 751 a 753 , poderá ser decretada de ofício ou a requerimento do Ministério Público.\n\nParágrafo único. O diretor do estabelecimento penal, que tiver conhecimento de fatos indicativos da periculosidade do condenado a quem não tenha sido imposta medida de segurança, deverá logo comunicá-los ao juiz."},{"chave":"art-756","sequencia":789,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 756.","conteudo":"Nos casos do no I, a e b, do art. 751 , e n o I do art. 752 , poderá ser dispensada nova audiência do condenado."},{"chave":"art-757","sequencia":790,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 757.","conteudo":"Nos casos do no I, c, e no II do art. 751 e no II do art. 752 , o juiz, depois de proceder às diligências que julgar convenientes, ouvirá o Ministério Público e concederá ao condenado o prazo de três dias para alegações, devendo a prova requerida ou reputada necessária pelo juiz ser produzida dentro em dez dias.\n\n§ 1 o O juiz nomeará defensor ao condenado que o requerer.\n\n§ 2 o Se o réu estiver foragido, o juiz procederá às diligências que julgar convenientes, concedendo o prazo de provas, quando requerido pelo Ministério Público.\n\n§ 3 o Findo o prazo de provas, o juiz proferirá a sentença dentro de três dias."},{"chave":"art-758","sequencia":791,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 758.","conteudo":"A execução da medida de segurança incumbirá ao juiz da execução da sentença."},{"chave":"art-759","sequencia":792,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 759.","conteudo":"No caso do art. 753 , o juiz ouvirá o curador já nomeado ou que então nomear, podendo mandar submeter o condenado a exame mental, internando-o, desde logo, em estabelecimento adequado."},{"chave":"art-760","sequencia":793,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 760.","conteudo":"Para a verificação da periculosidade, no caso do § 3 o do art. 78 do Código Penal , observar-se-á o disposto no art. 757 , no que for aplicável."},{"chave":"art-761","sequencia":794,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 761.","conteudo":"Para a providência determinada no art. 84, § 2 o , do Código Penal , se as sentenças forem proferidas por juízes diferentes, será competente o juiz que tiver sentenciado por último ou a autoridade de jurisdição prevalente no caso do art. 82 ."},{"chave":"art-762","sequencia":795,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 762.","conteudo":"A ordem de internação, expedida para executar-se medida de segurança detentiva, conterá:\n\nI - a qualificação do internando;\n\nII - o teor da decisão que tiver imposto a medida de segurança;\n\nIII - a data em que terminará o prazo mínimo da internação."},{"chave":"art-763","sequencia":796,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 763.","conteudo":"Se estiver solto o internando, expedir-se-á mandado de captura, que será cumprido por oficial de justiça ou por autoridade policial."},{"chave":"art-764","sequencia":797,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 764.","conteudo":"O trabalho nos estabelecimentos referidos no art. 88, § 1 o , III, do Código Penal , será educativo e remunerado, de modo que assegure ao internado meios de subsistência, quando cessar a internação.\n\n§ 1 o O trabalho poderá ser praticado ao ar livre.\n\n§ 2 o Nos outros estabelecimentos, o trabalho dependerá das condições pessoais do internado."},{"chave":"art-765","sequencia":798,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 765.","conteudo":"A quarta parte do salário caberá ao Estado ou, no Distrito Federal e nos Territórios, à União, e o restante será depositado em nome do internado ou, se este preferir, entregue à sua família."},{"chave":"art-766","sequencia":799,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 766.","conteudo":"A internação das mulheres será feita em estabelecimento próprio ou em seção especial."},{"chave":"art-767","sequencia":800,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 767.","conteudo":"O juiz fixará as normas de conduta que serão observadas durante a liberdade vigiada.\n\n§ 1 o Serão normas obrigatórias, impostas ao indivíduo sujeito à liberdade vigiada:\n\na) tomar ocupação, dentro de prazo razoável, se for apto para o trabalho;\n\nb) não mudar do território da jurisdição do juiz, sem prévia autorização deste.\n\n§ 2 o Poderão ser impostas ao indivíduo sujeito à liberdade vigiada, entre outras obrigações, as seguintes:\n\na) não mudar de habitação sem aviso prévio ao juiz, ou à autoridade incumbida da vigilância;\n\nb) recolher-se cedo à habitação;\n\nc) não trazer consigo armas ofensivas ou instrumentos capazes de ofender;\n\nd) não freqüentar casas de bebidas ou de tavolagem, nem certas reuniões, espetáculos ou diversões públicas.\n\n§ 3 o Será entregue ao indivíduo sujeito à liberdade vigiada uma caderneta, de que constarão as obrigações impostas."},{"chave":"art-768","sequencia":801,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 768.","conteudo":"As obrigações estabelecidas na sentença serão comunicadas à autoridade policial."},{"chave":"art-769","sequencia":802,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 769.","conteudo":"A vigilância será exercida discretamente, de modo que não prejudique o indivíduo a ela sujeito."},{"chave":"art-770","sequencia":803,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 770.","conteudo":"Mediante representação da autoridade incumbida da vigilância, a requerimento do Ministério Público ou de ofício, poderá o juiz modificar as normas fixadas ou estabelecer outras."},{"chave":"art-771","sequencia":804,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 771.","conteudo":"Para execução do exílio local, o juiz comunicará sua decisão à autoridade policial do lugar ou dos lugares onde o exilado está proibido de permanecer ou de residir.\n\n§ 1 o O infrator da medida será conduzido à presença do juiz que poderá mantê-lo detido até proferir decisão.\n\n§ 2 o Se for reconhecida a transgressão e imposta, conseqüentemente, a liberdade vigiada, determinará o juiz que a autoridade policial providencie a fim de que o infrator siga imediatamente para o lugar de residência por ele escolhido, e oficiará à autoridade policial desse lugar, observando-se o disposto no art. 768 ."},{"chave":"art-772","sequencia":805,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 772.","conteudo":"A proibição de freqüentar determinados lugares será comunicada pelo juiz à autoridade policial, que Ihe dará conhecimento de qualquer transgressão."},{"chave":"art-773","sequencia":806,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 773.","conteudo":"A medida de fechamento de estabelecimento ou de interdição de associação será comunicada pelo juiz à autoridade policial, para que a execute."},{"chave":"art-774","sequencia":807,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 774.","conteudo":"Nos casos do parágrafo único do art. 83 do Código Penal , ou quando a transgressão de uma medida de segurança importar a imposição de outra, observar-se-á o disposto no art. 757 , no que for aplicável."},{"chave":"art-775","sequencia":808,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 775.","conteudo":"A cessação ou não da periculosidade se verificará ao fim do prazo mínimo de duração da medida de segurança pelo exame das condições da pessoa a que tiver sido imposta, observando-se o seguinte:\n\nI - o diretor do estabelecimento de internação ou a autoridade policial incumbida da vigilância, até um mês antes de expirado o prazo de duração mínima da medida, se não for inferior a um ano, ou até quinze dias nos outros casos, remeterá ao juiz da execução minucioso relatório, que o habilite a resolver sobre a cessação ou permanência da medida;\n\nII - se o indivíduo estiver internado em manicômio judiciário ou em casa de custódia e tratamento, o relatório será acompanhado do laudo de exame pericial feito por dois médicos designados pelo diretor do estabelecimento;\n\nIII - o diretor do estabelecimento de internação ou a autoridade policial deverá, no relatório, concluir pela conveniência da revogação, ou não, da medida de segurança;\n\nIV - se a medida de segurança for o exílio local ou a proibição de freqüentar determinados lugares, o juiz, até um mês ou quinze dias antes de expirado o prazo mínimo de duração, ordenará as diligências necessárias, para verificar se desapareceram as causas da aplicação da medida;\n\nV - junto aos autos o relatório, ou realizadas as diligências, serão ouvidos sucessivamente o Ministério Público e o curador ou o defensor, no prazo de três dias para cada um;\n\nVI - o juiz nomeará curador ou defensor ao interessado que o não tiver;\n\nVII - o juiz, de ofício, ou a requerimento de qualquer das partes, poderá determinar novas diligências, ainda que já expirado o prazo de duração mínima da medida de segurança;\n\nVIII - ouvidas as partes ou realizadas as diligências a que se refere o número anterior o juiz proferirá a sua decisão, no prazo de três dias."},{"chave":"art-776","sequencia":809,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 776.","conteudo":"Nos exames sucessivos a que se referem o § 1º, II, e § 2 o do art. 81 do Código Penal , observar-se-á, no que Ihes for aplicável, o disposto no artigo anterior."},{"chave":"art-777","sequencia":810,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 777.","conteudo":"Em qualquer tempo, ainda durante o prazo mínimo de duração da medida de segurança, poderá o tribunal, câmara ou turma, a requerimento do Ministério Público ou do interessado, seu defensor ou curador, ordenar o exame, para a verificação da cessação da periculosidade.\n\n§ 1 o Designado o relator e ouvido o procurador-geral, se a medida não tiver sido por ele requerida, o pedido será julgado na primeira sessão.\n\n§ 2 o Deferido o pedido, a decisão será imediatamente comunicada ao juiz, que requisitará, marcando prazo, o relatório e o exame a que se referem os ns. I e II do art. 775 ou ordenará as diligências mencionadas no no IV do mesmo artigo , prosseguindo de acordo com o disposto nos outros incisos do citado artigo."},{"chave":"art-778","sequencia":811,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 778.","conteudo":"Transitando em julgado a sentença de revogação, o juiz expedirá ordem para a desinternação, quando se tratar de medida detentiva, ou para que cesse a vigilância ou a proibição, nos outros casos."},{"chave":"art-779","sequencia":812,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO IV — DA EXECUÇÃO","TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA"],"titulo":"TÍTULO V — DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA","rotulo":"Art. 779.","conteudo":"O confisco dos instrumentos e produtos do crime, no caso previsto no art. 100 do Código Penal , será decretado no despacho de arquivamento do inquérito, na sentença de impronúncia ou na sentença absolutória."},{"chave":"art-780","sequencia":813,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO V — DAS RELAÇÕES JURISDICIONAIS COM AUTORIDADE ESTRANGEIRA","TÍTULO ÚNICO","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 780.","conteudo":"Sem prejuízo de convenções ou tratados, aplicar-se-á o disposto neste Título à homologação de sentenças penais estrangeiras e à expedição e ao cumprimento de cartas rogatórias para citações, inquirições e outras diligências necessárias à instrução de processo penal."},{"chave":"art-781","sequencia":814,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO V — DAS RELAÇÕES JURISDICIONAIS COM AUTORIDADE ESTRANGEIRA","TÍTULO ÚNICO","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 781.","conteudo":"As sentenças estrangeiras não serão homologadas, nem as cartas rogatórias cumpridas, se contrárias à ordem pública e aos bons costumes."},{"chave":"art-782","sequencia":815,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO V — DAS RELAÇÕES JURISDICIONAIS COM AUTORIDADE ESTRANGEIRA","TÍTULO ÚNICO","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 782.","conteudo":"O trânsito, por via diplomática, dos documentos apresentados constituirá prova bastante de sua autenticidade."},{"chave":"art-783","sequencia":816,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO V — DAS RELAÇÕES JURISDICIONAIS COM AUTORIDADE ESTRANGEIRA","TÍTULO ÚNICO","CAPÍTULO II — DAS CARTAS ROGATÓRIAS"],"titulo":"CAPÍTULO II — DAS CARTAS ROGATÓRIAS","rotulo":"Art. 783.","conteudo":"As cartas rogatórias serão, pelo respectivo juiz, remetidas ao Ministro da Justiça, a fim de ser pedido o seu cumprimento, por via diplomática, às autoridades estrangeiras competentes."},{"chave":"art-784","sequencia":817,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO V — DAS RELAÇÕES JURISDICIONAIS COM AUTORIDADE ESTRANGEIRA","TÍTULO ÚNICO","CAPÍTULO II — DAS CARTAS ROGATÓRIAS"],"titulo":"CAPÍTULO II — DAS CARTAS ROGATÓRIAS","rotulo":"Art. 784.","conteudo":"As cartas rogatórias emanadas de autoridades estrangeiras competentes não dependem de homologação e serão atendidas se encaminhadas por via diplomática e desde que o crime, segundo a lei brasileira, não exclua a extradição.\n\n§ 1 o As rogatórias, acompanhadas de tradução em língua nacional, feita por tradutor oficial ou juramentado, serão, após exequatur do presidente do Supremo Tribunal Federal, cumpridas pelo juiz criminal do lugar onde as diligências tenham de efetuar-se, observadas as formalidades prescritas neste Código.\n\n§ 2 o A carta rogatória será pelo presidente do Supremo Tribunal Federal remetida ao presidente do Tribunal de Apelação do Estado, do Distrito Federal, ou do Território, a fim de ser encaminhada ao juiz competente.\n\n§ 3 o Versando sobre crime de ação privada, segundo a lei brasileira, o andamento, após o exequatur , dependerá do interessado, a quem incumbirá o pagamento das despesas.\n\n§ 4 o Ficará sempre na secretaria do Supremo Tribunal Federal cópia da carta rogatória."},{"chave":"art-785","sequencia":818,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO V — DAS RELAÇÕES JURISDICIONAIS COM AUTORIDADE ESTRANGEIRA","TÍTULO ÚNICO","CAPÍTULO II — DAS CARTAS ROGATÓRIAS"],"titulo":"CAPÍTULO II — DAS CARTAS ROGATÓRIAS","rotulo":"Art. 785.","conteudo":"Concluídas as diligências, a carta rogatória será devolvida ao presidente do Supremo Tribunal Federal, por intermédio do presidente do Tribunal de Apelação, o qual, antes de devolvê-la, mandará completar qualquer diligência ou sanar qualquer nulidade."},{"chave":"art-786","sequencia":819,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO V — DAS RELAÇÕES JURISDICIONAIS COM AUTORIDADE ESTRANGEIRA","TÍTULO ÚNICO","CAPÍTULO II — DAS CARTAS ROGATÓRIAS"],"titulo":"CAPÍTULO II — DAS CARTAS ROGATÓRIAS","rotulo":"Art. 786.","conteudo":"O despacho que conceder o exequatur marcará, para o cumprimento da diligência, prazo razoável, que poderá ser excedido, havendo justa causa, ficando esta consignada em ofício dirigido ao presidente do Supremo Tribunal Federal, juntamente com a carta rogatória."},{"chave":"art-787","sequencia":820,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO V — DAS RELAÇÕES JURISDICIONAIS COM AUTORIDADE ESTRANGEIRA","TÍTULO ÚNICO","CAPÍTULO III — DA HOMOLOGAÇÃO DAS SENTENÇAS ESTRANGEIRAS"],"titulo":"CAPÍTULO III — DA HOMOLOGAÇÃO DAS SENTENÇAS ESTRANGEIRAS","rotulo":"Art. 787.","conteudo":"As sentenças estrangeiras deverão ser previamente homologadas pelo Supremo Tribunal Federal para que produzam os efeitos do art. 7 o do Código Penal ."},{"chave":"art-788","sequencia":821,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO V — DAS RELAÇÕES JURISDICIONAIS COM AUTORIDADE ESTRANGEIRA","TÍTULO ÚNICO","CAPÍTULO III — DA HOMOLOGAÇÃO DAS SENTENÇAS ESTRANGEIRAS"],"titulo":"CAPÍTULO III — DA HOMOLOGAÇÃO DAS SENTENÇAS ESTRANGEIRAS","rotulo":"Art. 788.","conteudo":"A sentença penal estrangeira será homologada, quando a aplicação da lei brasileira produzir na espécie as mesmas conseqüências e concorrem os seguintes requisitos:\n\nI - estar revestida das formalidades externas necessárias, segundo a legislação do país de origem;\n\nII - haver sido proferida por juiz competente, mediante citação regular, segundo a mesma legislação;\n\nIII - ter passado em julgado;\n\nIV - estar devidamente autenticada por cônsul brasileiro;\n\nV - estar acompanhada de tradução, feita por tradutor público."},{"chave":"art-789","sequencia":822,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO V — DAS RELAÇÕES JURISDICIONAIS COM AUTORIDADE ESTRANGEIRA","TÍTULO ÚNICO","CAPÍTULO III — DA HOMOLOGAÇÃO DAS SENTENÇAS ESTRANGEIRAS"],"titulo":"CAPÍTULO III — DA HOMOLOGAÇÃO DAS SENTENÇAS ESTRANGEIRAS","rotulo":"Art. 789.","conteudo":"O procurador-geral da República, sempre que tiver conhecimento da existência de sentença penal estrangeira, emanada de Estado que tenha com o Brasil tratado de extradição e que haja imposto medida de segurança pessoal ou pena acessória que deva ser cumprida no Brasil, pedirá ao Ministro da Justiça providências para obtenção de elementos que o habilitem a requerer a homologação da sentença.\n\n§ 1 o A homologação de sentença emanada de autoridade judiciária de Estado, que não tiver tratado de extradição com o Brasil, dependerá de requisição do Ministro da Justiça.\n\n§ 2 o Distribuído o requerimento de homologação, o relator mandará citar o interessado para deduzir embargos, dentro de dez dias, se residir no Distrito Federal, de trinta dias, no caso contrário.\n\n§ 3 o Se nesse prazo o interessado não deduzir os embargos, ser-lhe-á pelo relator nomeado defensor, o qual dentro de dez dias produzirá a defesa.\n\n§ 4 o Os embargos somente poderão fundar-se em dúvida sobre a autenticidade do documento, sobre a inteligência da sentença, ou sobre a falta de qualquer dos requisitos enumerados nos arts. 781 e 788 .\n\n§ 5 o Contestados os embargos dentro de dez dias, pelo procurador-geral, irá o processo ao relator e ao revisor, observando-se no seu julgamento o Regimento Interno do Supremo Tribunal Federal.\n\n§ 6 o Homologada a sentença, a respectiva carta será remetida ao presidente do Tribunal de Apelação do Distrito Federal, do Estado, ou do Território.\n\n§ 7 o Recebida a carta de sentença, o presidente do Tribunal de Apelação a remeterá ao juiz do lugar de residência do condenado, para a aplicação da medida de segurança ou da pena acessória, observadas as disposições do Título II, Capítulo III , e Título V do Livro IV deste Código ."},{"chave":"art-790","sequencia":823,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO V — DAS RELAÇÕES JURISDICIONAIS COM AUTORIDADE ESTRANGEIRA","TÍTULO ÚNICO","CAPÍTULO III — DA HOMOLOGAÇÃO DAS SENTENÇAS ESTRANGEIRAS"],"titulo":"CAPÍTULO III — DA HOMOLOGAÇÃO DAS SENTENÇAS ESTRANGEIRAS","rotulo":"Art. 790.","conteudo":"O interessado na execução de sentença penal estrangeira, para a reparação do dano, restituição e outros efeitos civis, poderá requerer ao Supremo Tribunal Federal a sua homologação, observando-se o que a respeito prescreve o Código de Processo Civil."},{"chave":"art-791","sequencia":824,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 791.","conteudo":"Em todos os juízos e tribunais do crime, além das audiências e sessões ordinárias, haverá as extraordinárias, de acordo com as necessidades do rápido andamento dos feitos."},{"chave":"art-792","sequencia":825,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 792.","conteudo":"As audiências, sessões e os atos processuais serão, em regra, públicos e se realizarão nas sedes dos juízos e tribunais, com assistência dos escrivães, do secretário, do oficial de justiça que servir de porteiro, em dia e hora certos, ou previamente designados.\n\n§ 1 o Se da publicidade da audiência, da sessão ou do ato processual, puder resultar escândalo, inconveniente grave ou perigo de perturbação da ordem, o juiz, ou o tribunal, câmara, ou turma, poderá, de ofício ou a requerimento da parte ou do Ministério Público, determinar que o ato seja realizado a portas fechadas, limitando o número de pessoas que possam estar presentes.\n\n§ 2 o As audiências, as sessões e os atos processuais, em caso de necessidade, poderão realizar-se na residência do juiz, ou em outra casa por ele especialmente designada."},{"chave":"art-793","sequencia":826,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 793.","conteudo":"Nas audiências e nas sessões, os advogados, as partes, os escrivães e os espectadores poderão estar sentados. Todos, porém, se levantarão quando se dirigirem aos juízes ou quando estes se levantarem para qualquer ato do processo.\n\nParágrafo único. Nos atos da instrução criminal, perante os juízes singulares, os advogados poderão requerer sentados."},{"chave":"art-794","sequencia":827,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 794.","conteudo":"A polícia das audiências e das sessões compete aos respectivos juízes ou ao presidente do tribunal, câmara, ou turma, que poderão determinar o que for conveniente à manutenção da ordem. Para tal fim, requisitarão força pública, que ficará exclusivamente à sua disposição."},{"chave":"art-795","sequencia":828,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 795.","conteudo":"Os espectadores das audiências ou das sessões não poderão manifestar-se.\n\nParágrafo único. O juiz ou o presidente fará retirar da sala os desobedientes, que, em caso de resistência, serão presos e autuados."},{"chave":"art-796","sequencia":829,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 796.","conteudo":"Os atos de instrução ou julgamento prosseguirão com a assistência do defensor, se o réu se portar inconvenientemente."},{"chave":"art-797","sequencia":830,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 797.","conteudo":"Excetuadas as sessões de julgamento, que não serão marcadas para domingo ou dia feriado, os demais atos do processo poderão ser praticados em período de férias, em domingos e dias feriados. Todavia, os julgamentos iniciados em dia útil não se interromperão pela superveniência de feriado ou domingo."},{"chave":"art-798","sequencia":831,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 798.","conteudo":"Todos os prazos correrão em cartório e serão contínuos e peremptórios, não se interrompendo por férias, domingo ou dia feriado.\n\n§ 1 o Não se computará no prazo o dia do começo, incluindo-se, porém, o do vencimento.\n\n§ 2 o A terminação dos prazos será certificada nos autos pelo escrivão; será, porém, considerado findo o prazo, ainda que omitida aquela formalidade, se feita a prova do dia em que começou a correr.\n\n§ 3 o O prazo que terminar em domingo ou dia feriado considerar-se-á prorrogado até o dia útil imediato.\n\n§ 4 o Não correrão os prazos, se houver impedimento do juiz, força maior, ou obstáculo judicial oposto pela parte contrária.\n\n§ 5 o Salvo os casos expressos, os prazos correrão:\n\na) da intimação;\n\nb) da audiência ou sessão em que for proferida a decisão, se a ela estiver presente a parte;\n\nc) do dia em que a parte manifestar nos autos ciência inequívoca da sentença ou despacho."},{"chave":"art-798-a","sequencia":832,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 798º-A","conteudo":"Suspende-se o curso do prazo processual nos dias compreendidos entre 20 de dezembro e 20 de janeiro, inclusive, salvo nos seguintes casos: (Incluído pela Lei nº 14.365, de 2022)\n\nI - que envolvam réus presos, nos processos vinculados a essas prisões; (Incluído pela Lei nº 14.365, de 2022)\n\nII - nos procedimentos regidos pela Lei nº 11.340, de 7 de agosto de 2006 (Lei Maria da Penha); (Incluído pela Lei nº 14.365, de 2022)\n\nIII - nas medidas consideradas urgentes, mediante despacho fundamentado do juízo competente. (Incluído pela Lei nº 14.365, de 2022)\n\nParágrafo único. Durante o período a que se refere o caput deste artigo, fica vedada a realização de audiências e de sessões de julgamento, salvo nas hipóteses dos incisos I, II e III do caput deste artigo. (Incluído pela Lei nº 14.365, de 2022)"},{"chave":"art-799","sequencia":833,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 799.","conteudo":"O escrivão, sob pena de multa de cinqüenta a quinhentos mil-réis e, na reincidência, suspensão até 30 (trinta) dias, executará dentro do prazo de dois dias os atos determinados em lei ou ordenados pelo juiz."},{"chave":"art-800","sequencia":834,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 800.","conteudo":"Os juízes singulares darão seus despachos e decisões dentro dos prazos seguintes, quando outros não estiverem estabelecidos:\n\nI - de dez dias, se a decisão for definitiva, ou interlocutória mista;\n\nII - de cinco dias, se for interlocutória simples;\n\nIII - de um dia, se se tratar de despacho de expediente.\n\n§ 1 o Os prazos para o juiz contar-se-ão do termo de conclusão.\n\n§ 2 o Os prazos do Ministério Público contar-se-ão do termo de vista, salvo para a interposição do recurso ( art. 798, § 5 o ).\n\n§ 3 o Em qualquer instância, declarando motivo justo, poderá o juiz exceder por igual tempo os prazos a ele fixados neste Código.\n\n§ 4 o O escrivão que não enviar os autos ao juiz ou ao órgão do Ministério Público no dia em que assinar termo de conclusão ou de vista estará sujeito à sanção estabelecida no art. 799 ."},{"chave":"art-801","sequencia":835,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 801.","conteudo":"Findos os respectivos prazos, os juízes e os órgãos do Ministério Público, responsáveis pelo retardamento, perderão tantos dias de vencimentos quantos forem os excedidos. Na contagem do tempo de serviço, para o efeito de promoção e aposentadoria, a perda será do dobro dos dias excedidos."},{"chave":"art-802","sequencia":836,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 802.","conteudo":"O desconto referido no artigo antecedente far-se-á à vista da certidão do escrivão do processo ou do secretário do tribunal, que deverão, de ofício, ou a requerimento de qualquer interessado, remetê-la às repartições encarregadas do pagamento e da contagem do tempo de serviço, sob pena de incorrerem, de pleno direito, na multa de quinhentos mil-réis, imposta por autoridade fiscal."},{"chave":"art-803","sequencia":837,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 803.","conteudo":"Salvo nos casos expressos em lei, é proibida a retirada de autos do cartório, ainda que em confiança, sob pena de responsabilidade do escrivão."},{"chave":"art-804","sequencia":838,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 804.","conteudo":"A sentença ou o acórdão, que julgar a ação, qualquer incidente ou recurso, condenará nas custas o vencido."},{"chave":"art-805","sequencia":839,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 805.","conteudo":"As custas serão contadas e cobradas de acordo com os regulamentos expedidos pela União e pelos Estados."},{"chave":"art-806","sequencia":840,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 806.","conteudo":"Salvo o caso do art. 32 , nas ações intentadas mediante queixa, nenhum ato ou diligência se realizará, sem que seja depositada em cartório a importância das custas.\n\n§ 1 o Igualmente, nenhum ato requerido no interesse da defesa será realizado, sem o prévio pagamento das custas, salvo se o acusado for pobre.\n\n§ 2 o A falta do pagamento das custas, nos prazos fixados em lei, ou marcados pelo juiz, importará renúncia à diligência requerida ou deserção do recurso interposto.\n\n§ 3 o A falta de qualquer prova ou diligência que deixe de realizar-se em virtude do não-pagamento de custas não implicará a nulidade do processo, se a prova de pobreza do acusado só posteriormente foi feita."},{"chave":"art-807","sequencia":841,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 807.","conteudo":"O disposto no artigo anterior não obstará à faculdade atribuída ao juiz de determinar de ofício inquirição de testemunhas ou outras diligências."},{"chave":"art-808","sequencia":842,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 808.","conteudo":"Na falta ou impedimento do escrivão e seu substituto, servirá pessoa idônea, nomeada pela autoridade, perante quem prestará compromisso, lavrando o respectivo termo."},{"chave":"art-809","sequencia":843,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 809.","conteudo":"A estatística judiciária criminal, a cargo do Instituto de Identificação e Estatística ou repartições congêneres, terá por base o boletim individual , que é parte integrante dos processos e versará sobre:\n\nI - os crimes e as contravenções praticados durante o trimestre, com especificação da natureza de cada um, meios utilizados e circunstâncias de tempo e lugar;\n\nII - as armas proibidas que tenham sido apreendidas;\n\nIII - o número de delinqüentes, mencionadas as infrações que praticaram, sua nacionalidade, sexo, idade, filiação, estado civil, prole, residência, meios de vida e condições econômicas, grau de instrução, religião, e condições de saúde física e psíquica;\n\nIV - o número dos casos de co-delinqüência;\n\nV - a reincidência e os antecedentes judiciários;\n\nVI - as sentenças condenatórias ou absolutórias, bem como as de pronúncia ou de impronúncia;\n\nVII - a natureza das penas impostas;\n\nVIII - a natureza das medidas de segurança aplicadas;\n\nIX - a suspensão condicional da execução da pena, quando concedida;\n\nX - as concessões ou denegações de habeas corpus .\n\n§ 1 o Os dados acima enumerados constituem o mínimo exigível, podendo ser acrescidos de outros elementos úteis ao serviço da estatística criminal.\n\n§ 2 o Esses dados serão lançados semestralmente em mapa e remetidos ao Serviço de Estatística Demográfica Moral e Política do Ministério da Justiça. (Redação dada pela Lei nº 9.061, de 14.6.1995)\n\n§ 3 o O boletim individual a que se refere este artigo é dividido em três partes destacáveis, conforme modelo anexo a este Código , e será adotado nos Estados, no Distrito Federal e nos Territórios. A primeira parte ficará arquivada no cartório policial; a segunda será remetida ao Instituto de Identificação e Estatística, ou repartição congênere; e a terceira acompanhará o processo, e, depois de passar em julgado a sentença definitiva, lançados os dados finais, será enviada ao referido Instituto ou repartição congênere."},{"chave":"art-810","sequencia":844,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 810.","conteudo":"Este Código entrará em vigor no dia 1 o de janeiro de 1942."},{"chave":"art-811","sequencia":845,"caminho":["CÓDIGO DE PROCESSO PENAL","LIVRO VI — DISPOSIÇÕES GERAIS"],"titulo":"LIVRO VI — DISPOSIÇÕES GERAIS","rotulo":"Art. 811.","conteudo":"Revogam-se as disposições em contrário."}]$dados$::jsonb)
    as item(chave text, sequencia integer, caminho text[], titulo text, rotulo text, conteudo text);

