insert into public.legal_provisions (
    version_id, provision_key, sequence, heading_path, heading, label, content
)
select
    '21000000-0000-4000-8000-000000000007', item.chave, item.sequencia, item.caminho, item.titulo, item.rotulo, item.conteudo
from jsonb_to_recordset($dados$[{"chave":"art-1","sequencia":1,"caminho":["LEI DE PRISÃO TEMPORÁRIA"],"titulo":"O PRESIDENTE DA REPÚBLICA , faço saber que o Congresso Nacional decreta e eu sanciono a seguinte Lei:","rotulo":"Art. 1º","conteudo":"Caberá prisão temporária: (Vide ADI 3360) (Vide ADI 4109)\n\nI - quando imprescindível para as investigações do inquérito policial;\n\nII - quando o indicado não tiver residência fixa ou não fornecer elementos necessários ao esclarecimento de sua identidade;\n\nIII - quando houver fundadas razões, de acordo com qualquer prova admitida na legislação penal, de autoria ou participação do indiciado nos seguintes crimes:\n\na) homicídio doloso (art. 121, caput, e seu § 2°) ;\n\nb) seqüestro ou cárcere privado (art. 148, caput, e seus §§ 1° e 2°);\n\nc) roubo (art. 157, caput, e seus §§ 1°, 2° e 3°);\n\nd) extorsão (art. 158, caput, e seus §§ 1° e 2°);\n\ne) extorsão mediante seqüestro (art. 159, caput, e seus §§ 1°, 2° e 3°) ;\n\nf) estupro (art. 213, caput , e sua combinação com o art. 223, caput, e parágrafo único) ; (Vide Decreto-Lei nº 2.848, de 1940)\n\ng) atentado violento ao pudor (art. 214, caput , e sua combinação com o art. 223, caput, e parágrafo único) ; (Vide Decreto-Lei nº 2.848, de 1940)\n\nh) rapto violento (art. 219 , e sua combinação com o art. 223 caput, e parágrafo único) ; (Vide Decreto-Lei nº 2.848, de 1940)\n\ni) epidemia com resultado de morte (art. 267, § 1°) ;\n\nj) envenenamento de água potável ou substância alimentícia ou medicinal qualificado pela morte ( art. 270, caput , combinado com art. 285 );\n\nl) quadrilha ou bando (art. 288) , todos do Código Penal;\n\nm) genocídio (arts. 1° , 2° e 3° da Lei n° 2.889, de 1° de outubro de 1956 ), em qualquer de sua formas típicas;\n\nn) tráfico de drogas (art. 12 da Lei n° 6.368, de 21 de outubro de 1976) ;\n\no) crimes contra o sistema financeiro ( Lei n° 7.492, de 16 de junho de 1986 ).\n\np) crimes previstos na Lei de Terrorismo. (Incluído pela Lei nº 13.260, de 2016)"},{"chave":"art-2","sequencia":2,"caminho":["LEI DE PRISÃO TEMPORÁRIA"],"titulo":"LEI DE PRISÃO TEMPORÁRIA","rotulo":"Art. 2º","conteudo":"A prisão temporária será decretada pelo Juiz, em face da representação da autoridade policial ou de requerimento do Ministério Público, e terá o prazo de 5 (cinco) dias, prorrogável por igual período em caso de extrema e comprovada necessidade.\n\n§ 1° Na hipótese de representação da autoridade policial, o Juiz, antes de decidir, ouvirá o Ministério Público.\n\n§ 2° O despacho que decretar a prisão temporária deverá ser fundamentado e prolatado dentro do prazo de 24 (vinte e quatro) horas, contadas a partir do recebimento da representação ou do requerimento.\n\n§ 3° O Juiz poderá, de ofício, ou a requerimento do Ministério Público e do Advogado, determinar que o preso lhe seja apresentado, solicitar informações e esclarecimentos da autoridade policial e submetê-lo a exame de corpo de delito.\n\n§ 4° Decretada a prisão temporária, expedir-se-á mandado de prisão, em duas vias, uma das quais será entregue ao indiciado e servirá como nota de culpa.\n\n§ 4º-A O mandado de prisão conterá necessariamente o período de duração da prisão temporária estabelecido no caput deste artigo, bem como o dia em que o preso deverá ser libertado. (Incluído pela Lei nº 13.869. de 2019)\n\n§ 5° A prisão somente poderá ser executada depois da expedição de mandado judicial.\n\n§ 6° Efetuada a prisão, a autoridade policial informará o preso dos direitos previstos no art. 5° da Constituição Federal.\n\n§ 7º Decorrido o prazo contido no mandado de prisão, a autoridade responsável pela custódia deverá, independentemente de nova ordem da autoridade judicial, pôr imediatamente o preso em liberdade, salvo se já tiver sido comunicada da prorrogação da prisão temporária ou da decretação da prisão preventiva. (Redação dada pela Lei nº 13.869. de 2019)\n\n§ 8º Inclui-se o dia do cumprimento do mandado de prisão no cômputo do prazo de prisão temporária. (Incluído pela Lei nº 13.869. de 2019)"},{"chave":"art-3","sequencia":3,"caminho":["LEI DE PRISÃO TEMPORÁRIA"],"titulo":"LEI DE PRISÃO TEMPORÁRIA","rotulo":"Art. 3º","conteudo":"Os presos temporários deverão permanecer, obrigatoriamente, separados dos demais detentos."},{"chave":"art-4","sequencia":4,"caminho":["LEI DE PRISÃO TEMPORÁRIA"],"titulo":"LEI DE PRISÃO TEMPORÁRIA","rotulo":"Art. 4º","conteudo":"O art. 4° da Lei n° 4.898, de 9 de dezembro de 1965, fica acrescido da alínea i, com a seguinte redação:\n\n\"Art. 4° ...............................................................\n\ni) prolongar a execução de prisão temporária, de pena ou de medida de segurança, deixando de expedir em tempo oportuno ou de cumprir imediatamente ordem de liberdade;\""},{"chave":"art-5","sequencia":5,"caminho":["LEI DE PRISÃO TEMPORÁRIA"],"titulo":"LEI DE PRISÃO TEMPORÁRIA","rotulo":"Art. 5º","conteudo":"Em todas as comarcas e seções judiciárias haverá um plantão permanente de vinte e quatro horas do Poder Judiciário e do Ministério Público para apreciação dos pedidos de prisão temporária."},{"chave":"art-6","sequencia":6,"caminho":["LEI DE PRISÃO TEMPORÁRIA"],"titulo":"LEI DE PRISÃO TEMPORÁRIA","rotulo":"Art. 6º","conteudo":"Esta Lei entra em vigor na data de sua publicação."},{"chave":"art-7","sequencia":7,"caminho":["LEI DE PRISÃO TEMPORÁRIA"],"titulo":"LEI DE PRISÃO TEMPORÁRIA","rotulo":"Art. 7º","conteudo":"Revogam-se as disposições em contrário."}]$dados$::jsonb)
    as item(chave text, sequencia integer, caminho text[], titulo text, rotulo text, conteudo text);

